  const bs=el('acctBtnSec'); if(bs){ bs.textContent='🔐 '+T('امنیت'); bs.style.display = viewing ? 'none' : ''; }
  const bo=el('acctBtnOut'); if(bo) bo.textContent='🚪 '+T('خروج');
