function accItemResource(it){
  if(!it) return null;
  if(it.access) return it.access;
  if(typeof accResourceForNav==='function') return accResourceForNav(it.id);
  return null;
}
function filterAccNavItem(it){
  if(!it) return false;
  if(it.id==='exit-acc-shell' || it.id==='help') return true;
  const key=ACC_MODULE_MAP[it.id];
  const flags=CACHE.moduleFlags||{};
  if(key && flags[key]==='0') return false;
  /* «اصلاح تفکیک رنگ و سایز»: مشاهده با acc_variant_reclass.view یا همان دسترسی ابطال اصلاحی کاردکس (acc_warehouse_ops.delete) */
  if(it.id==='acc-variant-reclass' && typeof canVariantReclassView==='function' && canVariantReclassView()){
    return typeof showAccountingTab==='function' ? !!showAccountingTab() : true;
  }
  if(ME?.role==='admin') return true;
  if(typeof showAccountingTab==='function' && !showAccountingTab()) return false;
  const resource=accItemResource(it);
  if(!resource) return ME?.role==='accounting';
  return typeof canPerm==='function' && canPerm(resource, 'view');
}
function accNavForRole(){
  return accNavFlat().filter(filterAccNavItem);
}
function firstAllowedAccPage(){
  const hit=(accNavForRole()||[]).find(it=>String(it.id||'').startsWith('acc-'));
  return hit?hit.id:null;
}
function withAccountingTab(items){
  const show=typeof showAccountingTab==='function' && showAccountingTab();
  const has=items.some(it=>it.id==='accounting');
  if(show && !has){
    const idx=items.findIndex(it=>it.id==='messages');
    const entry={id:'accounting', icon:'💰', label:'حسابداری'};
    items=idx>=0?[...items.slice(0,idx), entry, ...items.slice(idx)]:[...items, entry];
  }
  if(!show && has) items=items.filter(it=>it.id!=='accounting');
  return items;
}
/** نرمال‌سازی پاسخ لیست Wave1: آرایه خام یا {data,pagination} */
function listRows(resp){
  if(Array.isArray(resp)) return resp;
  if(resp && Array.isArray(resp.data)) return resp.data;
  if(resp && Array.isArray(resp.rows)) return resp.rows;
  return [];
}
function listTotal(resp, rows){
  const t = resp && resp.pagination && resp.pagination.total;
  if(t != null && Number.isFinite(Number(t))) return Number(t);
  return (rows || listRows(resp)).length;
}
/** کاتالوگ کامل: اگر سرور صفحه برید، بقیه صفحات را هم می‌گیرد. شمارنده = total نه length صفحه. */
async function fetchCatalogList(path, extra){
  const base = new URLSearchParams(extra || '');
  base.set('page', '1');
  base.set('pageSize', '500');
  const sep = path.indexOf('?') >= 0 ? '&' : '?';
  const first = await api('GET', path + sep + base.toString()) || {};
  if(Array.isArray(first)) return { rows: first, total: first.length };
  const rows = listRows(first);
  const total = listTotal(first, rows);
  if(!total || rows.length >= total) return { rows, total: total || rows.length };
  const out = rows.slice();
  const pageSize = Number(first.pagination && first.pagination.pageSize) || 500;
  const pages = Math.ceil(total / pageSize);
  for(let p = 2; p <= pages; p++){
    base.set('page', String(p));
    const resp = await api('GET', path + sep + base.toString()) || {};
    out.push.apply(out, listRows(resp));
  }
  return { rows: out, total };
}
function navItems(){
  if(IN_ACC_SHELL){
    return accNavForRole();
  }
  // B2B portal is central-only — hide its admin menu on offline device builds
  if(ME.role==='admin'){
    let items = (APP_INFO&&APP_INFO.role==='device') ? NAV_ADMIN.filter(it=>it.id!=='b2bOrders') : NAV_ADMIN;
    items = items.filter(filterMainNavItem);
    if(isDeviceClient() && !items.some(it=>it.id==='desktop-settings')){
      const hi=items.findIndex(it=>it.id==='help');
      const entry={ id:'desktop-settings', icon:'⚙️', label:'تنظیمات برنامه' };
      items = hi>=0 ? [...items.slice(0,hi), entry, ...items.slice(hi)] : [...items, entry];
    }
    return withAccountingTab(items);
  }
  if(ME.role==='accounting' || ME.role==='sales_manager'){
    let items = NAV_ACCOUNTING.filter(filterMainNavItem);
    if(isDeviceClient()){
      items = [...items.slice(0, -1), { id:'desktop-settings', icon:'⚙️', label:'تنظیمات برنامه' }, items[items.length - 1]];
    }
    return withAccountingTab(items);
  }
  if(ME.role==='store_retail'){
    let items = NAV_STORE.filter(filterMainNavItem);
    if(isDeviceClient()){
      items = [...items.slice(0, -1), { id:'desktop-settings', icon:'⚙️', label:'تنظیمات برنامه' }, items[items.length - 1]];
    }
    return items;
  }
  let items = NAV_SALES.filter(filterMainNavItem);
  if(isRepRole(ME?.role)){
    items = [{id:'my-rep', icon:'💼', label:'حساب من'}, ...items.slice(0, -1), items[items.length - 1]];
  }
  if(isDeviceClient()){
    items = [...items.slice(0, -1), { id:'desktop-settings', icon:'⚙️', label:'تنظیمات برنامه' }, items[items.length - 1]];
  }
  return withAccountingTab(items);
}
function isDeviceClient(){
  const p = detectClientPlatform();
  return p==='desktop' || p==='android';
}
function isDesktopApp(){ return detectClientPlatform()==='desktop'; }
function isOfflineDevice(){ return !!(APP_INFO && APP_INFO.role==='device'); }
function showBackupAccessDenied(){
  openModal(`<div class="modal-head"><h3>⛔ دسترسی محدود</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body">
      <div class="warn" data-csp-style="${CSP.style(`margin-bottom:12px;line-height:1.8`)}"><strong>Access Denied:</strong> Backup operations are strictly restricted to the Central Server environment.</div>
      <p data-csp-style="${CSP.style(`font-size:13px;line-height:1.9;color:var(--muted)`)}">پشتیبان‌گیری فقط روی <strong>سرور مرکزی</strong> (نسخه وب) انجام می‌شود. نسخه دسکتاپ و اندروید فقط داده را همگام‌سازی می‌کنند و نمی‌توانند از اینجا dump دیتابیس بگیرند.</p>
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">متوجه شدم</button>
    </div>`);
}
function guardBackupAccess(){
  // Server dump فقط روی وب مرکزی؛ دسکتاپ/اندروید از همگام‌سازی استفاده می‌کنند
  if(!isOfflineDevice()) return true;
  if(isDesktopApp()){
    // دسکتاپ: بقیه تنظیمات آزاد است؛ فقط dump سرور محدود می‌ماند
    showBackupAccessDenied();
    return false;
  }
  showBackupAccessDenied();
  return false;
}
function isRepRole(r){ return r==='field_sales'||r==='inside_sales'; }
function isSalesProformaOnlyRole(r){ return isRepRole(r) || r==='salesperson'; }
/** Keep in sync with server/lib/sales-experts.js — who may appear as «کارشناس» on invoices. */
const SALES_EXPERT_ROLES = ['admin','accounting','field_sales','inside_sales','salesperson','sales_manager','distribution_office','store_retail'];
function isSalesExpertRole(r){ return SALES_EXPERT_ROLES.includes(String(r||'')); }
function listSalesExpertUsers(users, includeIds){
  const keep = new Set((includeIds||[]).map(Number).filter(n=>n>0));
  const byId = new Map();
  for(const u of (users||[])){
    if(!u) continue;
    const id = Number(u.id);
    if(!id) continue;
    // Keep current invoice/customer expert even if inactive or outside role set.
    if(keep.has(id)){ byId.set(id, u); continue; }
    if(u.active===0 || u.active==='0') continue;
    if(!isSalesExpertRole(u.role)) continue;
    byId.set(id, u);
  }
  return [...byId.values()].sort((a,b)=>String(a.name||a.username||'').localeCompare(String(b.name||b.username||''),'fa'));
}
async function ensureExpertUsersCache(force, includeId){
  if(!force && Array.isArray(CACHE.expertUsers) && CACHE.expertUsers.length) return CACHE.expertUsers;
  const q = includeId ? ('?include_id='+encodeURIComponent(includeId)) : '';
  try{
    const rows = await api('GET','/auth/expert-options'+q);
    CACHE.expertUsers = Array.isArray(rows) ? rows : [];
  }catch(_){
    if(!(CACHE.users||[]).length){
      try{ CACHE.users = await api('GET','/auth/users')||[]; }catch(__){ CACHE.users=[]; }
    }
    CACHE.expertUsers = listSalesExpertUsers(CACHE.users, includeId ? [includeId] : []);
  }
  return CACHE.expertUsers;
}
function canConvertProforma(){
  const r=ME&&ME.role;
  if(isSalesProformaOnlyRole(r)) return false;
  return r==='admin'||r==='accounting'||r==='sales_manager';
}
const REP_EXPENSE_CATS_FALLBACK={
  transport:'حمل‌ونقل', fuel:'سوخت', hotel:'هتل', meals:'پذیرایی',
  gifts:'هدایا', advertising:'تبلیغات', entertainment:'پذیرایی مشتری',
  office:'اداری', other:'سایر'
};
function normalizeRepExpenseCats(cats){
  if(cats && typeof cats==='object' && !Array.isArray(cats)){
    if(cats.transport) return cats;
    if(cats.data && cats.data.transport) return cats.data;
  }
  return REP_EXPENSE_CATS_FALLBACK;
}
function defaultVatExemptForType(type){
  const t=String(type||'').toLowerCase();
  return t==='normal' || t==='proforma';
}

function ensureModuleFlags(){
  if(CACHE._moduleFlagsLoading) return;
  if(CACHE.moduleFlags && Object.keys(CACHE.moduleFlags).length) return;
  CACHE._moduleFlagsLoading=true;
  api('GET','/settings/modules').then(f=>{
    CACHE.moduleFlags=f||{};
    CACHE._moduleFlagsLoading=false;
    buildNav();
  }).catch(()=>{ CACHE._moduleFlagsLoading=false; });
}
function buildNav(){
  ensureModuleFlags();
  const linkHtml = it=>`
    <a href="#" data-page="${it.id}" data-csp-click="${CSP.bind('click',function(event){go(`${String((it.id) ?? '')}`);return false;})}">
      <span class="ico">${navIcon(it)}</span><span>${T(it.label)}</span>
      ${it.id==='messages'?'<span class="badge hide" id="msgBadge">0</span>':''}
      ${it.id==='reminders'?'<span class="badge hide" id="remBadge">0</span>':''}
    </a>`;
  if(IN_ACC_SHELL){
    el('nav').innerHTML = ACC_NAV_SECTIONS.map((sec, secIdx)=>{
      const secItems = sec.items || (sec.subgroups||[]).flatMap(sg=>sg.items||[]);
      const items = secItems.filter(filterAccNavItem);
      if(!items.length) return '';
      const collapsed = ACC_NAV_COLLAPSED.has(secIdx);
      let bodyHtml='';
      if(sec.subgroups && sec.subgroups.length){
        bodyHtml = sec.subgroups.map((sg)=>{
          const sgItems=(sg.items||[]).filter(filterAccNavItem);
          if(!sgItems.length) return '';
          return `<div class="nav-acc-sub">
            <div class="nav-acc-sub-title">${T(sg.title)}</div>
            ${sgItems.map(linkHtml).join('')}
          </div>`;
        }).join('');
      } else {
        bodyHtml = items.map(linkHtml).join('');
      }
      return `<div class="nav-section">
        <div class="nav-section-title nav-acc-head ${collapsed?'':'open'}" data-csp-click="${CSP.bind('click',function(event){toggleAccNavSection((secIdx))})}">${T(sec.title)}<span class="chev">▾</span></div>
        <div class="nav-acc-items" data-csp-style="${CSP.style(`display:${collapsed?'none':'block'}`)}">${bodyHtml}</div>
      </div>`;
    }).join('');
    return;
  }
  const items = navItems();
  el('nav').innerHTML = items.map(linkHtml).join('');
}

// Dashboard "View Statement" quick action — jumps straight into the
// Accounting shell's Persons Statement page, preselected on this customer.
async function viewCustStatementFromDash(custId){
  stmtCustId = String(custId);
  enterAccountingShell('acc-statement');
}
async function enterAccountingShell(nextPage){
  if(typeof showAccountingTab==='function' && !showAccountingTab()){
    showToast('دسترسی به تب حسابداری ندارید','error');
    return;
  }
  IN_ACC_SHELL = true;
  collapseAllAccNav();
  el('brandRole').textContent = '🧮 '+T('ماژول حسابداری');
  buildNav();
  let target = nextPage || 'acc-dash';
  const spec = accNavFlat().find(x=>x.id===target);
  if(!spec || !filterAccNavItem(spec)) target = firstAllowedAccPage();
  if(!target){
    const view=el('view');
    if(view) view.innerHTML='<div class="empty">تب حسابداری روشن است، ولی هنوز بخشی داخل آن برای شما باز نشده. در دسترسی‌های کاربر، مشاهدهٔ همان بخش را تیک بزنید.</div>';
    return;
  }
  go(target);
  if(!CACHE.moduleFlags){
    api('GET','/settings/modules').then(f=>{ CACHE.moduleFlags=f||{}; buildNav(); }).catch(()=>{});
  }
}
function exitAccountingShell(){
  IN_ACC_SHELL = false;
  if(window.WinMgr) WinMgr.closeAll();
  el('brandRole').textContent = shellBrand();
  buildNav();
  go(ME.role==='accounting'||ME.role==='sales_manager'?'customers':'dash');
}

function mdiPageTitle(page){
  const it = navItems().find(x=>x.id===page) || (typeof ACC_NAV_SECTIONS!=='undefined' && accNavFlat().find(x=>x.id===page));
  if(it && it.label) return T(it.label);
  if(page==='help') return 'راهنما';
  if(page==='dash') return 'داشبورد';
  if(page==='acc-dash') return 'داشبورد حسابداری';
  return page;
}
function syncChromeForPage(page, title){
  CURRENT_PAGE = page;
  document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active', a.dataset.page===page));
  const titleEl = el('pageTitle');
  if(titleEl) titleEl.textContent = title || mdiPageTitle(page) || '';
  if(window.innerWidth<=900) closeSidebar();
  updateBackBtn();
  try{ expandAccNavForPage(page); }catch(_){}
}
function hookWinMgrNav(){
  if(!window.WinMgr || WinMgr._navHooked) return;
  WinMgr._navHooked = true;
  WinMgr.onFocus = function(w){
    if(!w || !w.key) return;
    syncChromeForPage(w.key, w.title);
  };
}
async function renderPageIntoMdiBody(page, body){
  body.innerHTML = '';
  const mainView = el('view');
  const placeholder = document.createElement('div');
  placeholder.id = 'view';
  placeholder.style.display = 'none';
  const realId = mainView ? mainView.id : 'view';
  if(mainView) mainView.id = 'view-main-backup';
  body.appendChild(placeholder);
  try{
    CURRENT_PAGE = page;
    if(ROUTES[page]) await ROUTES[page]();
    while(placeholder.firstChild) body.appendChild(placeholder.firstChild);
    if(typeof enhanceAccTables==='function') enhanceAccTables(body);
  } finally {
    placeholder.remove();
    const bak = document.getElementById('view-main-backup');
    if(bak) bak.id = realId || 'view';
  }
}

function go(page){
  if(typeof pcsConfirmLeaveDraft==='function' && !pcsConfirmLeaveDraft()) return;
  // ACC-CRM-UNIFY — redirects for legacy/duplicate routes
  const ROUTE_REDIRECTS = {
    'kardex': 'acc-item-kardex',
    'item-kardex': 'acc-item-kardex',
    'acc-kardex': 'acc-item-kardex',
    'products-kardex': 'acc-item-kardex',
    'acc-products-kardex': 'acc-item-kardex',
    'normal-invoices': 'acc-normal-invoices',
    'final-invoices': 'acc-final-invoices',
    'crm': 'crm-dashboard',
    'crm-reports': 'crm-dashboard',
  };
  if (ROUTE_REDIRECTS[page]) page = ROUTE_REDIRECTS[page];
  if(page==='accounting'){ enterAccountingShell(); return; }
  if(page==='exit-acc-shell'){ exitAccountingShell(); return; }
  if(String(page||'').startsWith('acc-')){
    const spec=typeof accNavFlat==='function'?accNavFlat().find(x=>x.id===page):null;
    const allowed=spec?filterAccNavItem(spec):(ME&&(ME.role==='admin'||ME.role==='accounting'));
    if((typeof showAccountingTab==='function' && !showAccountingTab()) || !allowed){
      showToast('به این بخش حسابداری دسترسی ندارید','error');
      return;
    }
    if(!IN_ACC_SHELL){
      IN_ACC_SHELL=true;
      collapseAllAccNav();
      if(el('brandRole')) el('brandRole').textContent='🧮 '+T('ماژول حسابداری');
      buildNav();
    }
  }
  if(page!=='messages' && typeof stopMsgPoll==='function') stopMsgPoll();
  if(page!=='store-quick-sale' && typeof storeQsLeave==='function'){ try{ storeQsLeave(); }catch(_){} }
  // تاریخچهٔ ناوبری برای دکمه بازگشت (به‌جز حرکت برگشتی)
  if(!_navGoingBack && CURRENT_PAGE && CURRENT_PAGE!==page){
    PAGE_HISTORY.push(CURRENT_PAGE);
    if(PAGE_HISTORY.length>60) PAGE_HISTORY.shift();
  }
  hookWinMgrNav();
  // بستن مودال‌های باز هنگام تعویض صفحه — جلوگیری از پنل گیرکرده روی سایدبار
  try{
    if(typeof closeNestedModal==='function') closeNestedModal();
    if(el('modalRoot') && el('modalRoot').querySelector('.overlay.open') && typeof closeModal==='function'){
      el('modalRoot').innerHTML='';
      if(typeof syncOverlayBodyClass==='function') syncOverlayBodyClass();
    }
  }catch(_){}
  // صفحات سراسری (تنظیمات، راهنما، …) روی #view اصلی — پنجره MDI حسابداری را ببند
  if(IN_ACC_SHELL && page!=='exit-acc-shell' && !String(page).startsWith('acc-') && window.WinMgr && typeof WinMgr.closeAll==='function'){
    WinMgr.closeAll();
  }
  // چندپنجره‌ای فقط داخل حسابداری — نه داشبورد CRM و نه داشبورد حسابداری
  const openAsMdi = IN_ACC_SHELL && String(page).startsWith('acc-') && page!=='acc-dash'
    && window.WinMgr && WinMgr.enabled() && typeof ROUTES[page]==='function';
  if(openAsMdi){
    const title = mdiPageTitle(page);
    const opened = WinMgr.open(page, title, (body)=>renderPageIntoMdiBody(page, body));
    if(opened){
      syncChromeForPage(page, title);
      return;
    }
  }
  syncChromeForPage(page);
  const runRoute = ROUTES[page];
  if(runRoute){
    Promise.resolve(runRoute()).catch(e=>{
      console.error('route', page, e);
      const v=el('view');
      if(v) v.innerHTML=`<div class="empty" data-csp-style="${CSP.style(`padding:24px`)}">خطا در بارگذاری صفحه: ${esc(e.message||e.code||'نامشخص')}</div>`;
      showToast(e.message||'خطا در بارگذاری','error');
    }).finally(()=>{ setTimeout(fitStatNums,60); if(typeof enhanceAccTables==='function') enhanceAccTables(el('view')); });
  } else {
    el('view').innerHTML='';
  }
}
/** والد صفحه — رفتار شبیه دکمه Up اکسپلورر ویندوز (نه Back تاریخچه) */
function pageParent(page){
  if(!page) return null;
  if(IN_ACC_SHELL){
    if(page==='acc-dash' || page==='exit-acc-shell') return 'exit-acc-shell';
    if(String(page).startsWith('acc-')) return 'acc-dash';
  }
  if(page==='dash') return null;
  return 'dash';
}
function updateBackBtn(){
  const btn=el('navBackBtn');
  if(!btn) return;
  const parent=pageParent(CURRENT_PAGE);
  const show=!!parent;
  btn.classList.toggle('show', show);
  btn.disabled=!show;
  btn.title = show ? 'بالا — سطح والد (مثل Up ویندوز)' : '';
}
function goUp(){
  const parent=pageParent(CURRENT_PAGE);
  if(!parent) return;
  // بستن پنجره MDI فعلی قبل از رفتن به والد
  if(window.WinMgr && IN_ACC_SHELL && CURRENT_PAGE && CURRENT_PAGE!=='acc-dash'){
    const w=typeof WinMgr.findByKey==='function' ? WinMgr.findByKey(CURRENT_PAGE) : null;
    if(w) WinMgr.close(w.id);
  }
  if(parent==='exit-acc-shell'){ exitAccountingShell(); updateBackBtn(); return; }
  _navGoingBack=true;
  try{ go(parent); } finally { _navGoingBack=false; updateBackBtn(); }
}
function goBack(){
  // سازگاری: تاریخچهٔ اختیاری (Alt+←) — دکمهٔ UI از goUp استفاده می‌کند
  if(!PAGE_HISTORY.length){ goUp(); return; }
  const prev=PAGE_HISTORY.pop();
  _navGoingBack=true;
  try{ go(prev); } finally { _navGoingBack=false; updateBackBtn(); }
}
function toggleSidebar(){
  if(window.innerWidth<=900){
    const open = el('sidebar').classList.toggle('open');
    el('sidebarBackdrop').classList.toggle('show', open);
  } else {
    el('sidebar').classList.toggle('collapsed');
    document.querySelector('.main').classList.toggle('expanded');
  }
}
function closeSidebar(){
  el('sidebar').classList.remove('open');
  el('sidebarBackdrop').classList.remove('show');
}

document.addEventListener('keydown',(e)=>{
  if(e.key==='F10'){
    e.preventDefault();
    const s=el('partySearch')||el('pSearch')||el('cSearch')||el('iSearch')||document.querySelector('.search');
    if(s){ s.focus(); s.select?.(); }
  }
  if((e.altKey && e.key==='ArrowLeft') || (e.altKey && (e.key==='Backspace' || e.code==='Backspace'))){
    if(!document.querySelector('.overlay.open') && PAGE_HISTORY.length){
      e.preventDefault();
      goBack();
    }
  }
  if(e.key==='F4' && IN_ACC_SHELL && accTab==='parties'){
    e.preventDefault();
    if(PARTY_GROUP_FILTER) partyModal();
  }
});

/* ============================================================
   BOOT
============================================================ */
function roleLabel(r){
  if(r==='admin') return T('مدیر سیستم');
  if(r==='accounting') return T('حسابدار');
  if(r==='sales_manager') return T('مدیر فروش');
  if(r==='inside_sales') return T('کارشناس داخلی');
  if(r==='field_sales'||r==='salesperson') return T('کارشناس میدانی');
  if(r==='distribution_office') return T('دفتر پخش');
  if(r==='store_retail') return T('فروشگاهی');
  if(r==='production_manager') return T('مدیر تولید');
  if(r==='production_operator') return T('اپراتور تولید');
  if(r==='unit_manager') return T('مدیر واحد عملیاتی');
  if(r==='department_manager') return T('مدیر بخش');
  return T('کارشناس فروش');
}
function roleTag(r){
  const cls = r==='admin'?'t-vip':r==='accounting'?'t-proposal':r==='inside_sales'?'t-inside':(r==='field_sales'||r==='salesperson')?'t-field':'t-proposal';
  return `<span class="tag ${cls}">${esc(roleLabel(r))}</span>`;
}
function shellBrand(){
  if(isAdmin()) return T('پنل مدیریت');
  if(ME&&(ME.role==='accounting'||ME.role==='sales_manager')) return T('پنل حسابداری');
  if(ME&&ME.role==='store_retail') return T('صندوق فروشگاهی');
  if(ME&&(ME.role==='production_manager'||ME.role==='production_operator'||ME.role==='unit_manager'||ME.role==='department_manager')) return T('پنل تولید');
  return T('پنل فروش');
}
/* Render a contextual help tooltip icon */
function hlp(tip){ return `<span class="hlp" data-tip="${tip.replace(/"/g,'&quot;')}">?</span>`; }
function isAdmin(){ return ME && ME.role==='admin'; }
function isManager(){ return ME && (ME.role==='admin' || ME.role==='sales_manager'); }
/** Customer edit/delete: admin or original creator (created_by). Assigned-only = view. */
function canEditCustomer(c){
  if(!c || !ME) return false;
  if(ME.role==='admin') return true;
  const creator = c.created_by != null ? c.created_by : c.user_id;
  return creator === ME.id;
}
let USER_PERMS = null;
const SALES_MANAGER_ACC_RESOURCES=new Set(['acc_dash','acc_reps','acc_commissions','acc_receivables','acc_sales_invoices','acc_statement','acc_settlements']);
function canPerm(resource, action){
  if(!ME) return false;
  if(ME.role==='admin') return true;
  if(!USER_PERMS){
    if(ME.role==='accounting' && (resource==='accounting' || String(resource).startsWith('acc_'))) return true;
    if(ME.role==='accounting' && ['invoices','customers','products','stocktaking','opening_stock'].includes(resource)) return true;
    if(ME.role==='sales_manager' && action==='view' && (resource==='accounting' || SALES_MANAGER_ACC_RESOURCES.has(resource))) return true;
    return false;
  }
  return !!(USER_PERMS[resource] && USER_PERMS[resource][action]);
}
function showAccountingTab(){
  if(!ME) return false;
  if(ME.role==='admin') return true;
  if(!USER_PERMS) return ME.role==='accounting' || ME.role==='sales_manager';
  return !!(USER_PERMS.accounting && USER_PERMS.accounting.view);
}
function canAccounting(){ return ME && (ME.role==='admin' || ME.role==='accounting' || ME.role==='sales_manager'); }
/* v567: فروش از انبار دیگر — admin همیشه؛ بقیه فقط با sales_cross_warehouse.create (ماتریس USER_PERMS) */
function canSalesCrossWarehouse(){
  if(!ME) return false;
  if(ME.role==='admin') return true;
  return !!(USER_PERMS && USER_PERMS.sales_cross_warehouse && USER_PERMS.sales_cross_warehouse.create);
}
function canRepAdmin(){
  return canAccounting() || canPerm('reps','view') || canPerm('acc_reps','view');
}

function disarmLoginAutofill(){
  const u=el('loginUser'), p=el('loginPass'), f=el('loginForm');
  if(p){ p.value=''; p.setAttribute('autocomplete','off'); p.setAttribute('name','erp_disarmed_pass'); }
  if(u){ u.setAttribute('autocomplete','off'); }
  if(f) f.setAttribute('autocomplete','off');
}
function armLoginAutofill(){
  const u=el('loginUser'), p=el('loginPass'), f=el('loginForm');
  if(p){ p.setAttribute('autocomplete','current-password'); p.removeAttribute('name'); }
  if(u){ u.setAttribute('autocomplete','username'); }
  if(f) f.removeAttribute('autocomplete');
}
function markNoFieldHistory(inp){
  if(!inp || inp.dataset.noHist==='1') return;
  const type=(inp.getAttribute('type')||'text').toLowerCase();
  if(['password','hidden','checkbox','radio','file','submit','button','range','color'].includes(type)) return;
  const ac=inp.getAttribute('autocomplete')||'';
  if(ac==='current-password'||ac==='new-password'||ac==='username'||ac==='one-time-code') return;
  inp.dataset.noHist='1';
  inp.setAttribute('autocomplete','off');
  inp.setAttribute('autocapitalize','off');
  inp.setAttribute('autocorrect','off');
  inp.setAttribute('spellcheck','false');
  if(!inp.getAttribute('name')) inp.setAttribute('name','nofill_'+Math.random().toString(36).slice(2,9));
  inp.addEventListener('pointerdown', function(){
    if(this.readOnly || this.dataset.dpBound) return;
    this.setAttribute('readonly','readonly');
    const self=this;
    setTimeout(function(){ if(!self.dataset.dpBound) self.removeAttribute('readonly'); }, 40);
  });
}
function disarmFieldHistory(root){
  const scope=root&&root.querySelectorAll?root:document;
  scope.querySelectorAll('input,textarea').forEach(markNoFieldHistory);
  scope.querySelectorAll('form').forEach(f=>{
    if((f.getAttribute('autocomplete')||'')==='on' || !f.getAttribute('autocomplete')) f.setAttribute('autocomplete','off');
  });
}
let _noHistObs=null;
function watchFieldHistory(){
  disarmFieldHistory(document);
  if(_noHistObs || typeof MutationObserver==='undefined') return;
  _noHistObs=new MutationObserver(function(list){
    list.forEach(function(m){
      m.addedNodes&&m.addedNodes.forEach(function(n){
        if(!n||n.nodeType!==1) return;
        if(n.matches&&n.matches('input,textarea')) markNoFieldHistory(n);
        if(n.querySelectorAll) disarmFieldHistory(n);
      });
    });
  });
  _noHistObs.observe(document.body||document.documentElement,{childList:true,subtree:true});
}
async function boot(){
  el('login').style.display='none';
  el('app').style.display='block';
  disarmLoginAutofill();
  try{ watchFieldHistory(); }catch(_){}
  let stored = JSON.parse(localStorage.getItem('crm_user')||'null');
  setME(stored);
  try{
    const fresh = await api('GET','/auth/me');
    if(fresh && (fresh.id||fresh.username)){
      stored = Object.assign({}, stored||{}, fresh);
      if(!fresh.impersonation){
        delete stored.impersonation;
        localStorage.removeItem('crm_admin_token');
        localStorage.removeItem('crm_admin_user');
      }
      localStorage.setItem('crm_user', JSON.stringify(stored));
      setME(stored);
    }
  }catch(_){}
  renderImpersonationBanner();
  syncServerTime(); // refresh offset after login (non-blocking)
  el('userName').textContent = ME.name;
  el('userRole').textContent = roleLabel(ME.role);
  el('brandRole').textContent = shellBrand();
  el('avatar').textContent = (ME.name||'؟').trim().charAt(0);
  syncAcctDrawerUser();
  try{ USER_PERMS = await api('GET','/rbac/me')||{}; }catch{ USER_PERMS=null; }
  buildNav();
  await loadInitial();
  go(ME.role==='store_retail' ? 'store-quick-sale'
    : ((ME.role==='accounting'||ME.role==='sales_manager') && showAccountingTab() ? 'accounting' : 'dash'));
  refreshMsgBadge();
  refreshRemBadge();
  setInterval(refreshMsgBadge, 30000);
  setInterval(refreshRemBadge, 60000);
  initSyncUI();
  initAppUpdate();
  bindBarcodeWedgeListener();
  window.__canSeeCost = !!(ME.role==='admin' || ME.role==='accounting' || canPerm('production_cost','view'));
  /* P4: بهای خرید/میانگین/سود در انبار، کاردکس و کالاها — فقط با cost_visibility:view (admin/حسابداری پیش‌فرض) */
  window.__canSeeCostVis = !!(ME.role==='admin' || canPerm('cost_visibility','view'));
  initOmnibox();
  initNotifications();
  if(typeof applyAppLanguage==='function') applyAppLanguage();
  if(isAdmin()) refreshWorkspaceBadge();
}

/* ===== Command Palette (Ctrl+K) ===== */
let _omniboxIdx = 0, _omniboxResults = [];
function initOmnibox(){
  document.addEventListener('keydown', e=>{
    if((e.ctrlKey||e.metaKey) && e.key==='k'){ e.preventDefault(); openOmnibox(); }
    if(e.key==='Escape') closeOmnibox();
  });
  const inp = el('omniboxInput');
  if(inp) inp.addEventListener('input', debounceOmnibox);
  if(inp) inp.addEventListener('keydown', omniboxKeyNav);
}
let _omniboxTimer;
function debounceOmnibox(){ clearTimeout(_omniboxTimer); _omniboxTimer=setTimeout(runOmniboxSearch,200); }
function openOmnibox(){
  el('omniboxOverlay').classList.add('open');
  const inp=el('omniboxInput'); if(inp){ inp.value=''; inp.focus(); }
  el('omniboxResults').innerHTML=`<div class="muted" data-csp-style="${CSP.style(`padding:12px 16px`)}">حداقل ۲ حرف تایپ کنید...</div>`;
  _omniboxResults=[]; _omniboxIdx=0;
}
function closeOmnibox(){ el('omniboxOverlay').classList.remove('open'); }
// Normalize Persian text for tolerant matching (Arabic ي/ك, ZWNJ, punctuation, digits).
function _omniNorm(s){
  return String(s||'')
    .replace(/\u200c/g,' ')
    .replace(/[\u200B-\u200F\u202A-\u202E\u2060\uFEFF]/g,'')
    .replace(/ي/g,'ی').replace(/ى/g,'ی').replace(/ك/g,'ک')
    .replace(/ۀ/g,'ه').replace(/ة/g,'ه').replace(/ؤ/g,'و').replace(/[أإآ]/g,'ا')
    .replace(/[\u064B-\u065F\u0670]/g,'')
    .replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d))
    .replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d))
    .replace(/[()[\]{}«»""''،,.;:!?؟\-_/\\|+*=<>@#$%^&~`]/g,' ')
    .toLowerCase().replace(/\s+/g,' ').trim();
}
function textMatchesQuery(haystack, query){
  const q=_omniNorm(query);
  if(!q) return true;
  const hay=_omniNorm(haystack);
  const tokens=q.split(/\s+/).filter(Boolean);
  if(tokens.every(t=>hay.includes(t))) return true;
  return String(haystack||'').toLowerCase().includes(String(query||'').trim().toLowerCase());
}
function _omniScore(text,q){
  const t=_omniNorm(text), n=_omniNorm(q);
  if(!t||!n) return 0;
  if(t===n) return 100;
  if(t.startsWith(n)) return 85;
  if(t.includes(n)) return 65;
  const words=n.split(' ').filter(Boolean);
  if(words.length>1 && words.every(w=>t.includes(w))) return 50;
  return 0;
}
// Build a navigable index of EVERY section/subsection/group the current user can
// reach: main sidebar pages + all accounting sub-modules (respecting module flags).
function buildOmniboxPageIndex(){
  const idx=[];
  try{
    (navItems()||[]).forEach(it=>{ if(it&&it.id&&it.id!=='exit-acc-shell') idx.push({type:'page',label:it.label,sub:'صفحه',route:it.id}); });
  }catch(_){}
  try{
    const secs=(typeof ACC_NAV_SECTIONS!=='undefined')?ACC_NAV_SECTIONS:[];
    secs.forEach(sec=>{
      const items=sec.items||(sec.subgroups||[]).flatMap(sg=>sg.items||[]);
      items.forEach(it=>{
      if(!it||!it.id||it.id==='exit-acc-shell') return;
      if(typeof filterAccNavItem==='function' && !filterAccNavItem(it)) return;
      idx.push({type:'page',label:it.label,sub:'حسابداری › '+(sec.title||''),route:it.id});
    });});
  }catch(_){}
  return idx;
}
async function runOmniboxSearch(){
  const q=(el('omniboxInput')?.value||'').trim();
  const box=el('omniboxResults');
  if(q.length<2){ box.innerHTML=`<div class="muted" data-csp-style="${CSP.style(`padding:12px 16px`)}">حداقل ۲ حرف...</div>`; return; }
  box.innerHTML=`<div class="muted" data-csp-style="${CSP.style(`padding:12px 16px`)}">جستجو...</div>`;
  let server=[]; try{ server=await api('GET','/search?q='+encodeURIComponent(q))||[]; }catch(_){ server=[]; }
  // Keep entity hits (customers/products/invoices…) from the server; replace its
  // limited hard-coded page list with the full client-side navigation index.
  const entities=(server||[]).filter(r=>r.type!=='page').map(e=>({...e,score:e.score||60}));
  const pages=buildOmniboxPageIndex().map(p=>({...p,score:_omniScore(p.label,q)})).filter(p=>p.score>0);
  const merged=[...pages,...entities].sort((a,b)=>(b.score||0)-(a.score||0)).slice(0,40);
  _omniboxResults=merged;
  _omniboxIdx=0;
  renderOmniboxResults();
}
function renderOmniboxResults(){
  const box=el('omniboxResults');
  if(!_omniboxResults.length){ box.innerHTML=`<div class="empty" data-csp-style="${CSP.style(`padding:16px`)}">نتیجه‌ای یافت نشد</div>`; return; }
  box.innerHTML=_omniboxResults.map((r,i)=>`<div class="omnibox-item ${i===_omniboxIdx?'active':''}" data-csp-click="${CSP.bind('click',function(event){pickOmnibox((i))})}">
    <span>${esc(r.label)}</span><span class="sub">${esc(r.sub||r.type||'')}</span></div>`).join('');
}
function omniboxKeyNav(e){
  if(!_omniboxResults.length) return;
  if(e.key==='ArrowDown'){ e.preventDefault(); _omniboxIdx=(_omniboxIdx+1)%_omniboxResults.length; renderOmniboxResults(); }
  if(e.key==='ArrowUp'){ e.preventDefault(); _omniboxIdx=(_omniboxIdx-1+_omniboxResults.length)%_omniboxResults.length; renderOmniboxResults(); }
  if(e.key==='Enter'){ e.preventDefault(); pickOmnibox(_omniboxIdx); }
}
function pickOmnibox(i){
  const r=_omniboxResults[i]; if(!r) return;
  closeOmnibox();
  if(r.type==='customer'){ go('customers'); setTimeout(()=>{ const s=el('cSearch'); if(s){ s.value=r.label; s.dispatchEvent(new Event('input')); }},300); }
  else if(r.type==='product'){
    // P5: open accounting products with group filter + highlight search
    PRODUCT_CAT_FILTER=r.category_id?String(r.category_id):'';
    PRODUCT_ACC_SEARCH=r.label||'';
    enterAccountingShell().then(()=>{
      go('acc-products');
      setTimeout(()=>{
        const btn=document.querySelector(`#accProdCatFilter button[data-product-category-id="${CSS.escape(String(PRODUCT_CAT_FILTER))}"]`);
        if(btn) btn.scrollIntoView({block:'nearest',behavior:'smooth'});
        const row=document.querySelector(`#accProductsTbl tr[data-id="${r.id}"]`);
        if(row){ row.style.outline='2px solid var(--purple)'; row.scrollIntoView({block:'center',behavior:'smooth'}); }
      },400);
    });
  }
  else if(r.type==='person'){
    enterAccountingShell().then(()=>{
      go('acc-parties');
      setTimeout(()=>{
        const rows=[...document.querySelectorAll('table.tbl tbody tr')];
        const hit=rows.find(tr=>tr.textContent&&tr.textContent.includes(r.label));
        if(hit){ hit.style.outline='2px solid var(--purple)'; hit.scrollIntoView({block:'center',behavior:'smooth'}); }
      },400);
    });
  }
  else if(r.type==='invoice'){ go('invoices'); setTimeout(()=>openInvBuilder(r.id),300); }
  else if(r.route==='accounting'||String(r.route||'').startsWith('acc-')){ enterAccountingShell().then(()=>go(r.route)); }
  else if(r.route){ go(r.route); }
  if(r.entity_type&&r.entity_id) api('POST','/notifications/entity-viewed',{entity_type:r.entity_type,entity_id:r.entity_id}).catch(()=>{});
}

/* ===== Notifications (polling + optional SSE) ===== */
function initNotifications(){
  const bell=el('notifBell');
  if(!bell) return;
  // همه کاربران اعلان می‌بینند (حداقل برای آپدیت نرم‌افزار)
  bell.style.display='block';
  refreshPendingBadge();
  pollNotifications();
  setInterval(pollNotifications, 45000);
}
async function pollNotifications(){
  try{
    const d=await api('GET','/notifications/pending-actions', null, false, true)||{};
    const n=(d.notifications||[]).length;
    const badge=el('notifBadge');
    if(badge){ badge.textContent=n; badge.classList.toggle('hide',!n); }
    window._pendingActions=d.actions||[];
    window._notifications=d.notifications||[];
  }catch{}
}
function refreshPendingBadge(){ pollNotifications(); }
function toggleNotifPanel(){
  const items=(window._notifications||[]);
  openModal(`<div class="modal-head"><h3>🔔 اعلان‌ها</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body">${items.length?items.map(n=>`<div class="pending-action-item" data-csp-click="${CSP.bind('click',function(event){notifClick((n.id),`${String((CSP.htmlDecode(String(esc(n.entity_type||'')))) ?? '')}`,`${String((n.entity_id||0) ?? '')}`,`${String((CSP.htmlDecode(String(esc(n.kind||'')))) ?? '')}`)})}">
      <b>${esc(n.title)}</b><div class="muted" data-csp-style="${CSP.style(`font-size:12px`)}">${esc(n.body||'')}</div></div>`).join(''):'<div class="empty">اعلان جدیدی نیست</div>'}
    </div><div class="modal-foot"><button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">بستن</button></div>`);
}
async function notifClick(id, entityType, entityId, kind){
  await api('POST','/notifications/'+id+'/resolve').catch(()=>{});
  closeModal(); refreshPendingBadge();
  if(kind==='app_update' || entityType==='app_update'){
    if(isDesktopApp()||detectClientPlatform()==='android') go(isAdmin()?'settings':'desktop-settings');
    else if(typeof go==='function') go(isAdmin()?'settings':'dash');
    return;
  }
  // v537: nightly subledger recon bell → open report (loads last run with ردیف/ریز)
  if(kind==='subledger_recon_nightly' || entityType==='subledger_recon_run'){
    enterAccountingShell().then(()=>{
      go('acc-subledger-recon');
      showToast('آخرین نتیجهٔ تطبیق شبانه — روی «ریز» هر هشدار جزئیات را ببینید');
    });
    return;
  }
  if(entityType==='invoice'&&entityId){ enterAccountingShell().then(()=>go('acc-sales-invoices')); }
  else if(entityType==='followup'&&entityId) go('followups');
  else if(kind==='invoice_approval') enterAccountingShell().then(()=>go('acc-commissions'));
  else if(entityType==='op_parameter'||entityType==='op_department'||String(kind||'').startsWith('portal_')){
    enterAccountingShell().then(()=>{
      if(ME?.role==='department_manager') go('acc-portal-my-dept');
      else go('acc-portal-units');
    });
  }
}

async function loadInitial(){
  try{
    CACHE.reminders = [];
    // Defer heavy lists: customers/products load on first page that needs them (invoice, CRM, …).
    // Previously admin/sales blocked boot on full /products + /customers payloads.
    CACHE.customers=[]; CACHE.products=[]; CACHE.allProducts=[]; CACHE.users=[];
    CACHE._allProductsIsFull=false;
    invalidateMasterCaches();
    if(ME.role==='admin'){
      CACHE.settings = {};
      api('GET','/settings',null,false,true).then(s=>{ CACHE.settings=s||{}; }).catch(()=>{});
      api('GET','/auth/users').then(u=>{ CACHE.users=u||[]; }).catch(()=>{});
    }
  }catch(e){ console.error(e); }
}
async function ensureCustomersCache(){
  if(Array.isArray(CACHE.customers) && CACHE.customers.length) return CACHE.customers;
  const resp = await api('GET','/customers');
  CACHE.customers = listRows(resp);
  return CACHE.customers;
}
async function ensureProductsCache(){
  // Only trust allProducts when marked as a complete (unfiltered) catalog.
  if(CACHE._allProductsIsFull && CACHE.allProducts?.length) return CACHE.allProducts;
  const catalog = await fetchCatalogList('/products');
  return setFullProductsCatalog(catalog.rows || []);
}

async function reloadCustomers(){ CACHE.customers = listRows(await api('GET','/customers')); }
async function reloadProducts(q=''){ CACHE.products = await api('GET','/products'+q)||[]; }

/* ============================================================
   OFFLINE SYNC UI (device builds only)
   The desktop/mobile apps run an embedded local server (SYNC_ROLE=device)
   that exposes /api/sync/status. On the central web server that endpoint
   doesn't exist, so this whole UI stays dormant there.
============================================================ */
let SYNC_MODE = false, SYNC_STATUS = null;

async function fetchSyncStatus(){
  const token = localStorage.getItem('crm_token');
  const r = await fetch('/api/sync/status',{headers:{'Authorization':'Bearer '+token}});
  if(!r.ok) return null;
  return await r.json();
}

let _lastDataVersion = null;
async function initSyncUI(){
  try{
    SYNC_STATUS = await fetchSyncStatus();
    if(!SYNC_STATUS || SYNC_STATUS.role!=='device') return;
    SYNC_MODE = true;
    try{ ivalInstallOnlineGuard(); }catch(_){}
    _lastDataVersion = SYNC_STATUS.data_version;
    renderSyncBadge();
    bindOnlineFirstSync();
    setInterval(async ()=>{ try{
      SYNC_STATUS=await fetchSyncStatus(); renderSyncBadge();
      maybeRefreshAfterSync();
      // Online-First: اگر قبلاً آفلاین بودیم و الان آنلاین شدیم، فوری همگام کن
      if(SYNC_STATUS && SYNC_STATUS.online && window._syncWasOffline){
        window._syncWasOffline=false;
        bgSyncSilent();
      }
      if(SYNC_STATUS && !SYNC_STATUS.online) window._syncWasOffline=true;
    }catch(e){} }, 10000);
    if(SYNC_STATUS.pairing_broken && isAdmin()) openSyncPairModal({repair:true});
    else if(!SYNC_STATUS.paired && isAdmin()) openSyncPairModal();
    else if(SYNC_STATUS.paired && SYNC_STATUS.initial_sync_running) openSyncPairProgressModal();
    else if(SYNC_STATUS.paired && SYNC_STATUS.files_missing>0) pullProductImages(true);
  }catch(e){ /* central server — no sync UI */ }
}

/** Online-First: بمحض وصل اینترنت / برگشت به تب، همگام خودکار */
function bindOnlineFirstSync(){
  if(window._onlineFirstBound) return;
  window._onlineFirstBound = true;
  window.addEventListener('online', ()=>{
    window._syncWasOffline = false;
    try{ showToast('اینترنت وصل شد — همگام‌سازی خودکار…'); }catch(_){}
    bgSyncSilent();
    setTimeout(bgSyncSilent, 2500);
  });
  window.addEventListener('offline', ()=>{
    window._syncWasOffline = true;
    if(SYNC_STATUS){ SYNC_STATUS.online=false; SYNC_STATUS.connection_mode='offline'; }
    try{ renderSyncBadge(); }catch(_){}
  });
  document.addEventListener('visibilitychange', ()=>{
    if(document.visibilityState==='visible' && SYNC_MODE) bgSyncSilent();
  });
}

async function pullProductImages(silent){
  const token = localStorage.getItem('crm_token');
  const r = await fetch('/api/sync/pull-files',{method:'POST',headers:{'Authorization':'Bearer '+token}});
  const j = await r.json().catch(()=>({}));
  if(j.ok && j.pulled>0){
    if(!silent) showToast(`${fmt(j.pulled)} فایل از سرور مرکزی دریافت شد`);
    SYNC_STATUS=await fetchSyncStatus(); renderSyncBadge();
    maybeRefreshAfterSync();
  } else if(j.ok && j.failed>0){
    if(!silent) showToast(`${fmt(j.failed)} فایل روی سرور مرکزی یافت نشد — از پنل همگام‌سازی جزئیات را ببینید`,'error');
    SYNC_STATUS=await fetchSyncStatus(); renderSyncBadge();
  } else if(!silent && !j.ok) showToast(j.error||'دریافت تصاویر ناموفق بود','error');
  else if(!silent && j.ok && !j.pulled) showToast('همه فایل‌های موجود همگام شدند');
}
async function skipSyncMissingFile(subdir,name){
  if(!confirm('این فایل روی سرور مرکزی موجود نیست. از لیست انتظار حذف شود؟ (تصویر شکسته می‌ماند)')) return;
  const token=localStorage.getItem('crm_token');
  const r=await fetch('/api/sync/skip-file',{method:'POST',headers:{'Authorization':'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify({subdir,name})});
  const j=await r.json().catch(()=>({}));
  if(r.ok){ showToast('از لیست انتظار حذف شد'); SYNC_STATUS=await fetchSyncStatus(); renderSyncBadge(); openSyncPanel(); }
  else showToast(j.error||'خطا','error');
}

// When a background sync changed local data (id remap, pulled rows/deletes),
// drop stale caches and re-render the current view — otherwise the browser
// keeps showing old ids (delete → "یافت نشد") or already-deleted rows.
function maybeRefreshAfterSync(){
  if(!SYNC_STATUS || SYNC_STATUS.data_version==null) return;
  if(_lastDataVersion===null){ _lastDataVersion=SYNC_STATUS.data_version; return; }
  if(SYNC_STATUS.data_version===_lastDataVersion) return;
  _lastDataVersion = SYNC_STATUS.data_version;
  // invalidate cached lists so the next render re-fetches from the local DB
  CACHE.customers=[]; CACHE.products=[]; CACHE.allProducts=[]; CACHE.invoices=[];
  CACHE.followups=[]; _followupsFetched=false; _invoicesFetched=false; _accRecvCache=null;
  invalidateMasterCaches();
  if(document.querySelector('.overlay.open')) return; // don't yank a modal the user is filling
  if(IN_ACC_SHELL){ if(typeof accTab!=='undefined' && accTab) loadAccTab(accTab); }
  else { reloadCustomers().then(()=>{ if(CURRENT_PAGE) go(CURRENT_PAGE); }).catch(()=>{ if(CURRENT_PAGE) go(CURRENT_PAGE); }); }
}

function isNarrowUI(){ return window.matchMedia('(max-width:900px)').matches; }
function renderSyncBadge(){
  const b = el('syncBadge'); if(!b || !SYNC_STATUS) return;
  b.style.display='inline-block';
  const s = SYNC_STATUS;
  const m = isNarrowUI();
  if(s.pairing_broken){
    b.textContent=m?'⚠️ خراب':'⚠️ اتصال خراب — لمس کنید'; b.style.background='#fee2e2'; b.style.color='#b91c1c';
  } else if(!s.paired){
    b.textContent=m?'🔗 اتصال':'🔗 اتصال به سرور مرکزی'; b.style.background='#fef3c7'; b.style.color='#b45309';
  } else if(s.initial_sync_running || (s.syncing && !s.initial_sync_done)){
    b.textContent=m?'⬇️ دریافت...':'⬇️ دریافت اولیه از مرکز...'; b.style.background='#dbeafe'; b.style.color='#1d4ed8';
  } else if(s.conflicts>0){
    b.textContent=`⚠️ ${fmt(s.conflicts)}`; b.style.background='#fee2e2'; b.style.color='#b91c1c';
  } else if(s.syncing){
    b.textContent=m?'🔄…':'🔄 در حال همگام‌سازی...'; b.style.background='#dbeafe'; b.style.color='#1d4ed8';
  } else if(!s.online){
    b.textContent=m?`📡 آفلاین`:`📡 حالت آفلاین${s.pending?` · ${fmt(s.pending)} در صف`:''}`; b.style.background='#f3f4f6'; b.style.color='#6b7280';
  } else if(s.pending>0){
    b.textContent=m?`🔄 ${fmt(s.pending)}`:`🔄 ${fmt(s.pending)} در انتظار ارسال`; b.style.background='#fef3c7'; b.style.color='#b45309';
  } else if(s.files_missing>0){
    b.textContent=m?`🖼️ ${fmt(s.files_missing)}`:`🖼️ ${fmt(s.files_missing)} تصویر در انتظار`; b.style.background='#fef3c7'; b.style.color='#b45309';
  } else {
    b.textContent=m?'● آنلاین':'🟢 آنلاین — همگام با مرکز'; b.style.background='#dcfce7'; b.style.color='#15803d';
  }
}

async function openSyncPanel(){
  SYNC_STATUS = await fetchSyncStatus() || SYNC_STATUS;
  renderSyncBadge();
  const s = SYNC_STATUS || {};
  if(s.pairing_broken){ if(isAdmin()) openSyncPairModal({repair:true}); else showToast('اتصال دستگاه خراب است — از مدیر بخواهید قطع و اتصال مجدد کند','error'); return; }
  if(!s.paired){ if(isAdmin()) openSyncPairModal(); else showToast('دستگاه هنوز متصل نشده — از مدیر سیستم بخواهید اتصال را انجام دهد','error'); return; }
  if(s.initial_sync_running || (s.syncing && !s.initial_sync_done)){ openSyncPairProgressModal(); return; }
  const token = localStorage.getItem('crm_token');
  const [pending, conflicts, missingFiles] = await Promise.all([
    fetch('/api/sync/pending',{headers:{'Authorization':'Bearer '+token}}).then(r=>r.ok?r.json():[]),
    fetch('/api/sync/conflicts',{headers:{'Authorization':'Bearer '+token}}).then(r=>r.ok?r.json():[]),
    fetch('/api/sync/missing-files',{headers:{'Authorization':'Bearer '+token}}).then(r=>r.ok?r.json():[])
  ]);
  const opLabel = o=>{
    const act = o.method==='POST'?'ثبت':o.method==='DELETE'?'حذف':'ویرایش';
    const ent = {invoices:'فاکتور',customers:'مشتری',settlements:'تسویه',sales_returns:'برگشت از فروش',purchase_invoices:'فاکتور خرید',purchase_returns:'برگشت از خرید',supplier_payments:'پرداخت تأمین‌کننده',expense_payments:'هزینه',account_transfers:'انتقال وجه',followups:'پیگیری',products:'کالا',suppliers:'تأمین‌کننده',persons:'شخص',journal_entries:'سند دستی',payroll_records:'حقوق'}[o.entity_table]||o.entity_table||o.path;
    return `${act} ${ent}`;
  };
  openModal(`
    <div class="modal-head"><h3>🔄 همگام‌سازی با سرور مرکزی</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body">
      <div data-csp-style="${CSP.style(`display:flex;gap:10px;flex-wrap:wrap;margin-bottom:14px`)}">
        <span class="tag ${s.online?'t-done':'t-cancel'}">${s.online?'🟢 متصل به مرکز':'📡 آفلاین'}</span>
        <span class="tag">${fmt(s.pending)} عملیات در صف</span>
        <span class="tag ${s.conflicts?'t-cancel':'t-done'}">${fmt(s.conflicts)} تعارض</span>
        ${s.files_missing?`<span class="tag t-pending">🖼️ ${fmt(s.files_missing)} تصویر محلی نیست</span>`:''}
        ${s.last_sync_at?`<span class="tag">آخرین همگام‌سازی: ${new Date(s.last_sync_at*1000).toLocaleTimeString('fa-IR')}</span>`:''}
      </div>
      <div data-csp-style="${CSP.style(`background:var(--bg2,#f9fafb);border:1px solid var(--border);border-radius:8px;padding:10px 12px;font-size:12px;margin-bottom:12px;line-height:1.8`)}">
        <div><b>آدرس سرور:</b> <span class="mono" dir="ltr">${esc(s.central_url||'—')}</span></div>
        <div><b>شناسه دستگاه:</b> <span class="mono" dir="ltr">${esc(String(s.device_id||'—'))}</span></div>
      </div>
      ${s.last_error?`<div data-csp-style="${CSP.style(`background:#fee2e2;color:#b91c1c;border-radius:8px;padding:8px 12px;font-size:12px;margin-bottom:12px`)}">${esc(s.last_error)}</div>`:''}
      <div data-csp-style="${CSP.style(`display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px`)}">
        <button class="btn" data-csp-click="${CSP.bind('click',function(event){syncNowUI()})}">🔄 همگام‌سازی اکنون</button>
        ${s.files_missing?`<button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){pullProductImages()})}">🖼️ دریافت فایل‌ها</button>`:''}
        ${isAdmin()?`<button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){editCentralUrlUI()})}">✏️ تغییر آدرس سرور</button>`:''}
        ${isAdmin()?`<button class="btn red" data-csp-click="${CSP.bind('click',function(event){resetPairingUI()})}">🔌 قطع اتصال و اتصال مجدد</button>`:''}
      </div>
      ${(missingFiles||[]).length?`
        <h4 data-csp-style="${CSP.style(`margin:10px 0 6px`)}">🖼️ فایل‌های محلی نیست (${fmt(missingFiles.length)})</h4>
        <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:8px`)}">اگر فایل روی سرور مرکزی وجود ندارد، می‌توانید آن را از لیست انتظار حذف کنید.</p>
        <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr><th>نوع</th><th>نام فایل</th><th></th></tr></thead><tbody>
          ${missingFiles.map(f=>`<tr>
            <td>${esc(f.subdir)}</td><td class="mono">${esc(f.name)}</td>
            <td><button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){skipSyncMissingFile((f.subdir), (f.name))})}">✕ حذف از لیست</button></td>
          </tr>`).join('')}
        </tbody></table></div>`:''}
      ${pending.filter(p=>p.status==='pending').length?`
        <h4 data-csp-style="${CSP.style(`margin:10px 0 6px`)}">⏳ در صف ارسال</h4>
        <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><tbody>
          ${pending.filter(p=>p.status==='pending').map(o=>`<tr><td>${esc(opLabel(o))}</td><td class="mono muted">${new Date((o.created_at||0)*1000).toLocaleString('fa-IR')}</td></tr>`).join('')}
        </tbody></table></div>`:''}
      ${conflicts.length?`
        <h4 data-csp-style="${CSP.style(`margin:14px 0 6px;color:var(--red)`)}">⚠️ تعارض‌ها — نیاز به تصمیم شما</h4>
        <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:8px`)}">این عملیات‌ها روی سرور مرکزی پذیرفته نشدند (مثلاً موجودی کافی نبود). می‌توانید آن‌ها را «لغو» کنید تا اثر محلی‌شان برگردد، و در صورت نیاز عملیات را با شرایط جدید دوباره ثبت کنید.</p>
        <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr><th>عملیات</th><th>علت رد شدن</th><th></th></tr></thead><tbody>
          ${conflicts.map(c=>`<tr>
            <td>${esc(opLabel(c))}</td>
            <td data-csp-style="${CSP.style(`color:var(--red)`)}">${esc(c.reason||'-')}</td>
            <td><button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){discardSyncConflict((c.id))})}">🗑️ لغو عملیات</button></td>
          </tr>`).join('')}
        </tbody></table></div>`:''}
    </div>`, true);
}

async function syncNowUI(){
  const token = localStorage.getItem('crm_token');
  showToast('همگام‌سازی شروع شد...');
  const r = await fetch('/api/sync/now',{method:'POST',headers:{'Authorization':'Bearer '+token}});
  const j = await r.json().catch(()=>({}));
  if(j.ok){
    const extra = j.pulled ? ` · ${fmt(j.pulled)} فایل` : '';
    showToast(`همگام‌سازی انجام شد (${fmt(j.confirmed||0)} عملیات تأیید شد${extra})`);
  }
  else showToast(j.error||'همگام‌سازی ناموفق بود','error');
  SYNC_STATUS = await fetchSyncStatus(); renderSyncBadge();
  closeModal();
  // Always drop master caches after explicit sync — version may be unchanged on no-op pulls
  // but warehouses/groups might still have been updated locally from another path.
  invalidateMasterCaches();
  CACHE.customers=[]; CACHE.products=[]; CACHE.allProducts=[]; CACHE.invoices=[];
  CACHE.followups=[]; _followupsFetched=false; _invoicesFetched=false; _accRecvCache=null;
  if(SYNC_STATUS?.data_version!=null) _lastDataVersion=SYNC_STATUS.data_version;
  if(!document.querySelector('.overlay.open')){
    if(IN_ACC_SHELL && typeof accTab!=='undefined' && accTab) loadAccTab(accTab);
    else if(CURRENT_PAGE) go(CURRENT_PAGE);
  }
}

let _bgSyncTimer=null;
async function bgSyncSilent(){
  if(!SYNC_MODE) return;
  const token=localStorage.getItem('crm_token');
  try{
    const r=await fetch('/api/sync/now',{method:'POST',headers:{'Authorization':'Bearer '+token}});
    const j=await r.json().catch(()=>({}));
    if(j.ok){ SYNC_STATUS=await fetchSyncStatus(); renderSyncBadge(); maybeRefreshAfterSync(); }
  }catch(e){}
}
function scheduleBgSync(){
  if(!SYNC_MODE) return;
  clearTimeout(_bgSyncTimer);
  // Online-First: flush outbox quickly after local mutations
  _bgSyncTimer=setTimeout(bgSyncSilent, 800);
}

async function discardSyncConflict(outboxId){
  if(!confirm('این عملیات به‌طور کامل لغو و اثر محلی آن برگردانده شود؟')) return;
  const token = localStorage.getItem('crm_token');
  const r = await fetch('/api/sync/conflicts/'+outboxId+'/discard',{method:'POST',headers:{'Authorization':'Bearer '+token}});
  const j = await r.json().catch(()=>({}));
  if(j.ok){ showToast('عملیات لغو شد'); SYNC_STATUS=await fetchSyncStatus(); renderSyncBadge(); closeModal(); openSyncPanel(); }
  else showToast(j.error||'لغو ناموفق بود','error');
}

