let fupFilter={q:'',status:'',stage:'',view:''};
let _followupsFetched=false, _invoicesFetched=false, _msgsFetched=false, _remindersFetched=false;
let _accRecvCache=null;
let custTimer, fupTimer, invTimer, remTimer, msgTimer;
