function bindProductImageInstantUpload(productId){
  const inp=el('p-image');
  const box=el('p-img-preview');
  if(!inp||!box) return;
  inp.addEventListener('change', async ()=>{
    const files=[...inp.files||[]];
    if(!files.length) return;
    // Instant local previews
    const frag=document.createDocumentFragment();
    for(const f of files){
      const url=URL.createObjectURL(f);
      const wrap=document.createElement('div');
      wrap.style.cssText='position:relative;width:72px;height:72px;border:1px dashed var(--purple);border-radius:8px;overflow:hidden';
      wrap.innerHTML=`<img src="${url}" class="prod-thumb" data-csp-style="${CSP.style(`width:100%;height:100%;object-fit:cover`)}"><div class="img-upload-prog" data-csp-style="${CSP.style(`position:absolute;bottom:0;left:0;right:0;height:4px;background:#ddd`)}"><div data-csp-style="${CSP.style(`height:100%;width:30%;background:var(--purple);animation:pulse 1s infinite`)}"></div></div>`;
      frag.appendChild(wrap);
    }
    const muted=box.querySelector('.muted');
    if(muted) muted.remove();
    box.appendChild(frag);
    // If editing existing product, upload via image-only endpoint (never touch stock/pack)
    if(productId){
      try{
        const fd=new FormData();
        for(const f of files){ fd.append('images', await compressProductImageFile(f)); }
        const saved=await api('POST','/products/'+productId+'/images',fd,true,true);
        if(saved){
          window._prodModalProduct=saved;
          showToast('تصاویر آپلود شد');
          // refresh preview from server
          const gallery=productImageList(saved);
          box.innerHTML=gallery.length?gallery.map((fn,i)=>{
            const row=(saved.images||[]).find(im=>(im.filename||im)===fn);
            const iid=row&&row.id?row.id:0;
            return `<div data-csp-style="${CSP.style(`position:relative;cursor:zoom-in`)}" data-csp-click="${CSP.bind('click',function(event){openProductAlbumFromCard((productId))})}">
              ${prodImgTag(fn,'class=\"prod-thumb\"')}
              ${(iid||fn)?`<button type="button" class="btn sm red" data-csp-style="${CSP.style(`position:absolute;top:2px;inset-inline-start:2px;z-index:2`)}" data-csp-click="${CSP.bind('click',function(event){event.stopPropagation();deleteProductImage(iid,productId,fn)})}">×</button>`:''}
              ${i===0?`<span class="img-badge" data-csp-style="${CSP.style(`bottom:4px;inset-inline-start:4px`)}">اصلی</span>`:''}
            </div>`;
          }).join(''):'<span class="muted">تصویری ثبت نشده</span>';
          inp.value='';
        }
      }catch(e){
        showToast((e&&e.message)||'خطا در آپلود تصویر','error');
      }
    }
  });
}
async function compressProductImageFile(file){
  if(!file || !String(file.type||'').startsWith('image/')) return file;
  if((file.size||0) < 350*1024) return file;
  try{
    const bmp = await createImageBitmap(file);
    const max=1200;
    let w=bmp.width, h=bmp.height;
    if(w>max||h>max){ const sc=Math.min(max/w, max/h); w=Math.round(w*sc); h=Math.round(h*sc); }
    const canvas=document.createElement('canvas');
    canvas.width=w; canvas.height=h;
    canvas.getContext('2d').drawImage(bmp,0,0,w,h);
    try{ bmp.close(); }catch(_){}
    const blob=await new Promise(res=>canvas.toBlob(res,'image/webp',0.72));
    if(!blob || blob.size >= file.size) return file;
    const base=String(file.name||'photo').replace(/\.[^.]+$/,'');
    return new File([blob], base+'.webp', { type:'image/webp', lastModified:Date.now() });
  }catch(_){ return file; }
}
async function saveProduct(id){
  const name = el('p-name').value.trim();
  if(!name){ showToast('نام کالا الزامی است','error'); return; }
  const fd = new FormData();
  fd.append('name',name);
  fd.append('category',el('p-cat').value.trim());
  fd.append('category_id',el('p-cat-id')?.value||'');
  fd.append('code',el('p-code').value);
  fd.append('price',moneyVal('p-price'));
  fd.append('retail_price',moneyVal('p-retail'));
  if(el('p-min-price')) fd.append('min_price_rial',moneyVal('p-min-price')||0);
  if(window.__canSeeCostVis!==false) fd.append('cost',moneyVal('p-cost')); /* P4: بدون مجوز، بها ارسال/بازنویسی نشود */
  // موجودی هرگز از فرم کالا ارسال نمی‌شود: POST با stock>0 → ۴۲۲ E_STOCK_VIA_OPENING، PUT → ۴۰۹ E_STOCK_VIA_DOCUMENT
  fd.append('stock_alert',el('p-alert').value||5);
  const picked=uomPayload('p-unit-id');
  fd.append('unit_id', picked.unit_id||'');
  fd.append('unit', picked.unit||'عدد');
  fd.append('item_type',el('p-item_type')?.value||'finished');
  fd.append('is_manufactured', el('p-is-manufactured')?.checked ? '1' : '0');
  const websitePushEl = el('p-website-stock-push');
  if(websitePushEl) fd.append('website_stock_push', websitePushEl.checked ? '1' : '0');
  fd.append('colors',el('p-colors')?.value||1);
  fd.append('pack_size',el('p-pack_size')?.value||1);
  if(el('p-full_pack_mode')) fd.append('full_pack_mode', el('p-full_pack_mode').value||'');
  fd.append('barcode',el('p-barcode')?.value||'');
  fd.append('warehouse_id',el('p-warehouse')?.value||'');
  fd.append('costing_method',el('p-costing')?.value||'');
  if(el('p-val-level')) fd.append('valuation_level',el('p-val-level').value||'');
  fd.append('note',el('p-note').value);
  if(usesExtendedCoa()){
    fd.append('full_name',el('p-full_name')?.value||'');
    fd.append('product_type',el('p-product_type')?.value||'');
    fd.append('product_index',el('p-product_index')?.value||'');
    fd.append('tax_id',el('p-tax_id')?.value||'');
    fd.append('tax_stuff_id',el('p-tax_stuff_id')?.value||'');
    fd.append('consumer_price',moneyVal('p-consumer_price'));
    fd.append('opening_price',moneyVal('p-opening_price'));
    fd.append('location',el('p-location')?.value||'');
    fd.append('sms_code',el('p-sms_code')?.value||'');
  }
  // فقط فیلد images — ارسال همزمان image+images باعث دوباره‌سازی و حذف عکس قبلی می‌شد
  const files = el('p-image').files || [];
  const hadNewImages = files.length > 0;
  const beforeImgCount = id ? productImageList(window._prodModalProduct||{}).length : 0;
  for(let i=0;i<files.length;i++){
    fd.append('images', await compressProductImageFile(files[i]));
  }
  let saved = null;
  try{
    // silent=true تا toast خطا را خودمان کنترل کنیم (گاهی پاسخ قطع می‌شود ولی ذخیره موفق است)
    saved = id ? await api('PUT','/products/'+id,fd,true,true) : await api('POST','/products',fd,true,true);
  }catch(e){
    // آپلود گاهی روی سرور تمام می‌شود ولی پاسخ قطع می‌شود (timeout/پروکسی) —
    // اگر عکس جدید ثبت شده باشد، ذخیره را موفق حساب کن.
    if(id && hadNewImages){
      try{
        const check = await api('GET','/products/'+id, null, false, true);
        const imgs = (check && (check.images||[])) || [];
        if(imgs.length > beforeImgCount){ saved = check; }
      }catch(_){}
    }
    if(!saved){
      showToast((e && ((e.payload&&e.payload.error)||e.message)) || 'خطا در ذخیره کالا','error');
      return;
    }
  }
  const savedId = (saved && (saved.id || saved.product_id)) || id || 0;
  const chips=typeof selectedProdChips==='function'?selectedProdChips():{colors:[],sizes:[]};
  const color_ids=[...new Set([
    ...(chips.colors||[]).map(c=>Number(c.id)).filter(Boolean),
    ...(window._prodPreserveColorIds||[]).map(Number).filter(Boolean)
  ])];
  // ترتیب سایز از نوار ترتیب مودال (product_style_sizes.sort_order)
  const size_ids=(chips.sizes||[]).map(s=>Number(s.id)).filter(Boolean);
  let zeroColorHint='';
  if(savedId && color_ids.length && size_ids.length){
    try{
      const gm=await api('POST','/product-variants/generate-matrix',{ product_id:Number(savedId), color_ids, size_ids, auto_barcode:true });
      if(gm && gm.zero_color_hint_fa) zeroColorHint=gm.zero_color_hint_fa;
    }catch(e){ showToast((e && e.message) || 'کالا ذخیره شد؛ ساخت ماتریس SKU ناموفق بود','error'); }
    const cells=collectProdStockCells();
    if(cells.length){
      try{
        const mx=await api('POST','/product-variants/stock-matrix',{
          product_id:Number(savedId), cells,
          warehouse_id:el('p-matrix-wh')?.value||el('p-warehouse')?.value||undefined,
          // فقط ساختار SKU؛ تعداد از جدول موجودی اول دوره یا اسناد انبار
          structure_only:true
        });
        if(mx && mx.zero_color_hint_fa) zeroColorHint=mx.zero_color_hint_fa;
      }catch(e){ showToast((e && e.message) || 'کالا ذخیره شد؛ ثبت موجودی رنگ×سایز ناموفق بود','error'); }
    }
  }
  // ذخیره موفق: پیش‌نویس کامل پاک شود تا closeModal هشدار ندهد
  if(typeof pcsDraftReset==='function') pcsDraftReset(Number(savedId)||0);
  else if(typeof pcsDraftClearWh==='function') pcsDraftClearWh(null);
  closeModal();
  const ready=saved&&saved.production_readiness;
  if(ready && Array.isArray(ready.hard) && ready.hard.length){
    showToast('ذخیره شد — مشخصات ضروری تولید ناقص: '+(ready.hard[0].message_fa||ready.hard[0].code),'error');
  }else if(ready && Array.isArray(ready.soft) && ready.soft.length){
    showToast('ذخیره شد — هشدار تولید: '+(ready.soft[0].message_fa||ready.soft[0].code));
  }else{
    showToast(id?'ذخیره شد':'ذخیره شد — موجودی اول دوره را در بخش «موجودی» همین کالا ثبت کنید');
  }
  if(zeroColorHint) setTimeout(()=>showToast(zeroColorHint),1600);
  try{
    await _refreshProdWithCats(_prodCanEdit);
    if(window._accProdRefresh){ try{ window._accProdRefresh(); }catch(_){} window._accProdRefresh=null; }
  }catch(_){ /* ذخیره موفق بود؛ تازه‌سازی لیست جداست */ }
}

