async function refreshWorkspaceBadge(){
  try{
    const co=await api('GET','/companies').catch(()=>null);
    const fy=await api('GET','/fiscal-year').catch(()=>null);
    CACHE.companies=co;
    const active=(co?.companies||[]).find(c=>c.isActive);
    const label=[active?.name, fy?.current?.label].filter(Boolean).join(' · ');
    let badge=el('workspaceBadge');
    if(!badge){
      const right=document.querySelector('.topbar .right');
      if(!right) return;
      badge=document.createElement('span');
      badge.id='workspaceBadge';
      badge.className='clock';
      badge.style.cssText='max-width:220px;overflow:hidden;text-overflow:ellipsis;cursor:pointer';
      badge.title='شرکت و سال مالی فعال — کلیک برای تنظیمات';
      badge.onclick=()=>settOpenTab('general');
      right.insertBefore(badge, right.firstChild);
    }
    if(label){ badge.textContent=label; badge.style.display=''; }
    else badge.style.display='none';
    const brand=el('brandRole');
    if(brand && active?.name) brand.textContent=active.name;
  }catch(_){}
}
async function runIntegrityCheck(){
  const box=el('integrity-result'); if(box) box.textContent='در حال بررسی...';
  try{
    const r=await api('POST','/system/integrity-check',{});
    const d=r?.data||{};
    const ok=d.ok!==false && !(d.errors||[]).length;
    if(box) box.innerHTML=ok?`<span data-csp-style="${CSP.style(`color:var(--green)`)}">✅ یکپارچگی تأیید شد</span>`:`<span data-csp-style="${CSP.style(`color:var(--red)`)}">⚠️ ${esc((d.errors||[]).join('؛ ')||d.message||'مشکل یافت شد')}</span>`;
  }catch(e){ if(box) box.textContent='خطا در بررسی'; }
}
