let _pendingUserSave = null;
async function saveUser(id){
  const name=el('u-name').value.trim(), username=el('u-username').value.trim(),
        pass=el('u-pass')?.value||'', role=el('u-role').value,
        phone=el('u-phone').value, active=+el('u-active').value,
        commission_cash=parsePct(el('u-comm-cash')?.value||0),
        commission_cheque=parsePct(el('u-comm-cheque')?.value||0);
  if(!name){ showToast('نام الزامی است','error'); return; }
  const commInput=el('u-comm-cash');
  const isLocked=commInput?.dataset.locked==='1';
  const origCash=parseFloat(commInput?.dataset.orig||0);
  const origCheque=parseFloat(el('u-comm-cheque')?.dataset.orig||0);
  const rateChanged=id&&(Math.abs(commission_cash-origCash)>0.001||Math.abs(commission_cheque-origCheque)>0.001);
  if(id && isLocked && rateChanged){
    _pendingUserSave={id,name,username,pass,role,phone,active,commission_cash,commission_cheque,show_phone_on_invoice:(el('u-show-phone-inv')?.value==='0'?0:1),...userRepFieldsFromForm(),sales_warehouse_id:+el('u-sales-warehouse')?.value||null,sales_cash_box_id:+el('u-sales-cashbox')?.value||null,person:userPersonFieldsFromForm()};
    openModal(`
      <div class="modal-head"><h3>🔒 تغییر نرخ انگیزه فروش</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
      <div class="modal-body">
        <p data-csp-style="${CSP.style(`margin-bottom:12px`)}">نرخ انگیزه فروش <b>${esc(name)}</b> قفل است.</p>
        <p data-csp-style="${CSP.style(`margin-bottom:16px;color:var(--muted);font-size:13px`)}">نقد: ${fmtPct(origCash)}٪ ← ${fmtPct(commission_cash)}٪ &nbsp;|&nbsp; چک: ${fmtPct(origCheque)}٪ ← ${fmtPct(commission_cheque)}٪</p>
        <p>آیا می‌خواهید محاسبه انگیزه فروش همه فاکتورهای قبلی این کارشناس با نرخ جدید مجدداً انجام شود؟</p>
      </div>
      <div class="modal-foot">
        <button class="btn green" data-csp-click="${CSP.bind('click',function(event){confirmIncentiveChange(true)})}">بله، همه فاکتورها محاسبه مجدد شوند</button>
        <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف (بدون تغییر نرخ)</button>
      </div>`);
    return;
  }
  await _doSaveUser(id,{name,username,pass,role,phone,active,commission_cash,commission_cheque,show_phone_on_invoice:(el('u-show-phone-inv')?.value==='0'?0:1),...userRepFieldsFromForm(),sales_warehouse_id:+el('u-sales-warehouse')?.value||null,sales_cash_box_id:+el('u-sales-cashbox')?.value||null,person:userPersonFieldsFromForm()});
}
async function confirmIncentiveChange(yes){
  closeModal();
  if(!_pendingUserSave) return;
  const {id,...data}=_pendingUserSave; _pendingUserSave=null;
  if(yes) await _doSaveUser(id,{...data,force:true});
}
async function _doSaveUser(id,{name,username,pass,role,phone,active,commission_cash,commission_cheque,force,commission_basis,monthly_target,quarterly_target,annual_target,bonus_pct,commission_fixed,penalty_pct,supervisor_commission_pct,supervisor_id,employment_status,rep_code,rep_subtype,territory,rep_opening_balance,bank_name,bank_account,bank_iban,sales_warehouse_id,sales_cash_box_id,show_phone_on_invoice,person}){
  try{
    const repFields={commission_basis,monthly_target,quarterly_target,annual_target,bonus_pct,commission_fixed,penalty_pct,supervisor_commission_pct,supervisor_id,employment_status,rep_code,rep_subtype,territory,rep_opening_balance,bank_name,bank_account,bank_iban,sales_warehouse_id,sales_cash_box_id,show_phone_on_invoice:show_phone_on_invoice==null?1:(show_phone_on_invoice?1:0)};
    if(id){
      await api('PUT','/admin/users/'+id,{name,role,phone,active,password:pass||undefined,commission_cash,commission_cheque,force:force||undefined,...repFields,person});
      const catIds=[...document.querySelectorAll('.u-cat-cb:checked')].map(cb=>+cb.value).filter(Boolean);
      await api('PUT','/admin/users/'+id+'/catalog-categories',{category_ids:catIds}).catch(()=>api('PUT','/auth/users/'+id+'/catalog-categories',{category_ids:catIds}).catch(()=>{}));
    } else {
      if(!username||!pass){ showToast('نام کاربری و رمز الزامی است','error'); return; }
      const created=await api('POST','/admin/users',{name,username,password:pass,phone,role,commission_cash,commission_cheque,...repFields,person});
      const newId=created?.id||created?.user?.id;
      if(newId){
        const catIds=[...document.querySelectorAll('.u-cat-cb:checked')].map(cb=>+cb.value).filter(Boolean);
        if(catIds.length) await api('PUT','/admin/users/'+newId+'/catalog-categories',{category_ids:catIds}).catch(()=>api('PUT','/auth/users/'+newId+'/catalog-categories',{category_ids:catIds}).catch(()=>{}));
      }
    }
    CACHE.users=await api('GET','/auth/users'); closeModal(); refreshSettUsers(); showToast('ذخیره شد');
  }catch(e){}
}
async function resetPass(id,name){
  if(!confirm('برای '+name+' یک رمز تصادفی ساخته می‌شود، نشست‌های او بسته می‌شود و در ورود بعدی باید رمز را عوض کند. ادامه می‌دهید؟')) return;
  try{
    const r=await api('POST','/auth/reset-password',{user_id:id,generate:true});
    const temp=r&&r.temporary_password;
    if(!temp){ showToast('رمز بازنشانی شد'); return; }
    openModal(`<div class="modal-head"><h3>رمز یک‌بارمصرف</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
      <div class="modal-body">
        <p class="muted">این رمز فقط همین‌جا نشان داده می‌شود. آن را به ${esc(name)} بدهید. در ورود بعدی باید عوضش کند.</p>
        <input dir="ltr" readonly value="${esc(temp)}" data-csp-click="${CSP.bind('click',function(){this.select()})}">
      </div>
      <div class="modal-foot"><button class="btn" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">بستن</button></div>`);
  }catch(e){
    showToast(e.message||'بازنشانی رمز ناموفق','error');
  }
}

/* ============================================================
   REPORTS (admin)
============================================================ */
let repRange={from:'',to:''};
let repPreset='all';

function setRepPreset(presetKey){
  repPreset = presetKey;
  const tj = todayJalali();
  if(presetKey === 'today'){
    repRange.from = tj; repRange.to = tj;
  } else if(presetKey === 'week'){
    repRange.from = jDateAddDays(tj, -7); repRange.to = tj;
  } else if(presetKey === 'month'){
    const parts = tj.split('/');
    if(parts.length===3) { repRange.from = `${parts[0]}/${parts[1]}/01`; repRange.to = tj; }
  } else if(presetKey === 'year'){
    const parts = tj.split('/');
    if(parts.length===3) { repRange.from = `${parts[0]}/01/01`; repRange.to = tj; }
  } else if(presetKey === 'all'){
    repRange.from = ''; repRange.to = '';
  }
  if(el('rep-from')) el('rep-from').value = repRange.from;
  if(el('rep-to')) el('rep-to').value = repRange.to;
  loadReports();
}

