const ACC_NOFILTER_TABS = new Set(['chart','coa-codes','account-groups','ledger-accounts','subsidiary-accounts','detail-accounts','detail-categories','other-details','equity-info','shareholders','currencies','fx-rates','pos-devices','pos-report','scale-settings','company-profile','opening-recv-cheques','opening-pay-cheques','journal-docs','cost-centers','customer-groups','party-groups','parties','product-groups','product-colors','product-sizes','balance-sheet','suppliers','banks','check-categories','cash-boxes','persons','item-kardex','inv-batches','fabric-rolls','fabric-roll-kardex','cutting-lays','inv-reservations','inv-landed','petty-cash','trust-checks','warehouses','warehouse-ops','warehouse-report','variant-stock-report','inv-reconcile','stocktaking','opening-stock','variant-reclass','commission-rules','consignments','adv-reports','production','production-orders','cutting-lays','production-boms','production-dashboard','production-close','production-monthly-profit','production-cost-sheet','production-estimate','production-kanban','production-variance','production-reports','production-mrp','production-rates','production-access','payroll','cheque-register','units','fiscal-period','company-settings','orders','portal-units','portal-my-dept','bank-recon','budgeting','reserves','vat-return','seasonal-169','cash-flow-std','kpi-dashboard','party-control-dashboard']);

// Generic wrapper: accounting pages share header; reuse shell when switching tabs.
function buildAccFilterHtml(tabKey){
  return `<div data-csp-style="${CSP.style(`display:flex;gap:6px;align-items:center;flex-wrap:wrap`)}">
    ${presetSelect('accPresetSel',accPreset,'applyAccPreset')}
    ${accPreset==='custom'?`
    <input id="accFrom" data-jdate placeholder="از تاریخ" data-csp-style="${CSP.style(`padding:7px 10px;border:1.5px solid var(--border);border-radius:8px;width:120px;font-size:12px`)}" value="${accDateFrom}" data-csp-change="${CSP.bind('change',function(event){accDateFrom=this.value})}" data-csp-input="${CSP.bind('input',function(event){accDateFrom=this.value})}">
    <input id="accTo" data-jdate placeholder="تا تاریخ" data-csp-style="${CSP.style(`padding:7px 10px;border:1.5px solid var(--border);border-radius:8px;width:120px;font-size:12px`)}" value="${accDateTo}" data-csp-change="${CSP.bind('change',function(event){accDateTo=this.value})}" data-csp-input="${CSP.bind('input',function(event){accDateTo=this.value})}">
    <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){applyAccDatesFromInputs();accPreset='custom';_accRecvCache=null;loadAccTab(accTab)})}">🔍 اعمال</button>
    <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){accDateFrom='';accDateTo='';accPreset='all';_accRecvCache=null;refreshAccFilterChrome();loadAccTab(accTab)})}">✕</button>`:
    `<span class="tag" data-csp-style="${CSP.style(`background:var(--purple-light);color:var(--purple)`)}">${accDateFrom||'ابتدا'} الی ${accDateTo||'انتها'}</span>`}
    ${(tabKey==='general'&&isAdmin())?`<button class="btn sm ghost" title="بازسازی اسناد حسابداری برای همه عملیات گذشته" data-csp-click="${CSP.bind('click',function(event){resyncAccounting()})}">🔄 همگام‌سازی</button>`:''}
  </div>`;
}
function renderAccPage(tabKey, icon, title, navId){
  accTab = tabKey;
  accNavId = navId || '';
  if(accPreset!=='custom'&&accPreset!=='all'&&!accDateFrom) [accDateFrom,accDateTo]=jPresetRange(accPreset);
  const showFilter = !ACC_NOFILTER_TABS.has(tabKey);
  const viewRoot = document.getElementById('view');
  // فقط شل داخل #view فعلی (مثلاً بدنه پنجره MDI) — نه شل داشبورد پشت‌صحنه
  const shell = viewRoot ? viewRoot.querySelector('#accShellPanel') : null;
  if(shell){
    const titleEl = shell.querySelector('#accShellTitle') || el('accShellTitle');
    if(titleEl) titleEl.textContent = `${icon} ${title}`;
    const fw = shell.querySelector('#accShellFilterWrap') || el('accShellFilterWrap');
    if(fw){
      fw.style.display = showFilter ? '' : 'none';
      if(showFilter){ fw.innerHTML = buildAccFilterHtml(tabKey); attachDatepickers(fw); }
    }
    loadAccTab(tabKey);
    return;
  }
  const target = viewRoot || el('view');
  target.innerHTML = `
    <div class="panel" id="accShellPanel">
      <div class="panel-head" data-csp-style="${CSP.style(`display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px`)}">
        <h4 id="accShellTitle">${icon} ${title}</h4>
        <div id="accShellFilterWrap" data-csp-style="${CSP.style(`${showFilter?'':'display:none'}`)}">${showFilter?buildAccFilterHtml(tabKey):''}</div>
      </div>
      <div class="panel-body" id="accBody"><div class="muted">در حال بارگذاری...</div></div>
    </div>`;
  if(showFilter) attachDatepickers(target.querySelector('#accShellFilterWrap'));
  loadAccTab(tabKey);
}
