function syncTblStickyTop(){
  try{
    const tb=document.querySelector('.topbar');
    if(!tb) return;
    const h=Math.ceil(tb.getBoundingClientRect().bottom+8);
    if(h>40 && h<200) document.documentElement.style.setProperty('--tbl-sticky-top', h+'px');
  }catch(_){}
}
/** جدّ با overflow≠visible → containing-block استیکی؛ افست topbar آنجا ردیف‌ها را می‌پوشاند. */
function tblHasClippingAncestor(el){
  if(!el||!el.parentElement) return false;
  try{
    let n=el.parentElement;
    while(n && n!==document.documentElement && n!==document.body){
      // پوشش جدول، MDI و مودال اسکرول‌پورت خودشان هستند؛ top در CSS صفر است نه افست topbar
      if(n.classList&&(n.classList.contains('tbl-wrap')||n.classList.contains('mdi-body')||n.classList.contains('mdi-win')||n.classList.contains('modal')||n.classList.contains('modal-body'))){
        n=n.parentElement; continue;
      }
      if(n.classList&&(n.classList.contains('erp-fold')||n.classList.contains('fup-folder'))) return true;
      const s=window.getComputedStyle(n);
      const ox=s.overflowX||s.overflow||'visible';
      const oy=s.overflowY||s.overflow||'visible';
      if(/^(auto|scroll|hidden|clip)$/.test(oy) || /^(auto|scroll|hidden)$/.test(ox)) return true;
      n=n.parentElement;
    }
  }catch(_){}
  return false;
}
function tblDisableSticky(table){
  if(!table) return;
  table.classList.add('tbl-no-sticky');
  const wrap=table.closest('.tbl-wrap');
  if(wrap) wrap.classList.add('tbl-no-sticky');
}
function enhanceAccTables(root){
  if(!root||typeof enhanceDataTable!=='function') return;
  syncTblStickyTop();
  root.querySelectorAll('.tbl-wrap').forEach(wrap=>{
    if(wrap.dataset.quickSearch==='1') return;
    const t=wrap.querySelector('table.tbl');
    const tb=t&&t.tBodies[0];
    if(!tb || tb.rows.length<3) return;
    if(tb.rows.length===1 && tb.rows[0].querySelector('td[colspan]')) return;
    wrap.dataset.quickSearch='1';
    const bar=document.createElement('div');
    bar.className='toolbar tbl-quick-search-bar';
    bar.setAttribute('data-csp-style', CSP.style('margin-bottom:8px;gap:8px;flex-wrap:wrap'));
    const inp=document.createElement('input');
    inp.type='search';
    inp.className='tbl-quick-search';
    inp.placeholder='جستجو در این لیست…';
    inp.setAttribute('autocomplete','off');
    inp.setAttribute('data-csp-style', CSP.style('min-width:200px;max-width:360px;padding:7px 10px;border:1.5px solid var(--border);border-radius:8px'));
    inp.addEventListener('input', function(){
      const q=typeof toAsciiDigits==='function'?toAsciiDigits(this.value.trim().toLowerCase()):this.value.trim().toLowerCase();
      [...tb.rows].forEach(tr=>{
        if(tr.querySelector('td[colspan]')) return;
        const hay=(tr.textContent||'').toLowerCase();
        tr.style.display=!q || hay.includes(q)?'':'none';
      });
      // جمع ستون = همان ردیف‌های visible (نه کل دیتاست)
      if(typeof tblAfterRowFilter==='function') tblAfterRowFilter(t);
      else if(typeof tblRebuildFooter==='function') tblRebuildFooter(t);
    });
    bar.appendChild(inp);
    if(wrap.parentNode) wrap.parentNode.insertBefore(bar, wrap);
  });
  root.querySelectorAll('table.tbl').forEach(t=>{
    const wrap=t.closest('.tbl-wrap');
    const wrapScrolls=wrap && !wrap.classList.contains('tbl-flow');
    if(!wrapScrolls && tblHasClippingAncestor(t)) tblDisableSticky(t);
    if(typeof tblSyncColumns==='function') tblSyncColumns(t);
    if(t.dataset.enhanced==='1') return;
    if(!t.tBodies[0]||t.tBodies[0].rows.length===0) return;
    if(typeof tblEnsureRowIds==='function') tblEnsureRowIds(t);
    const dataRows=[...t.tBodies[0].rows].filter(r=>!r.querySelector('td[colspan], .empty'));
    const wantFooter=t.dataset.noSum!=='1' && dataRows.length>=2;
    const hasId=dataRows.some(r=>r.dataset.id);
    const bulk=hasId && typeof tblInferBulkDelete==='function'?tblInferBulkDelete(t):null;
    if(bulk) enhanceDataTable(t,{selectable:true, bulkDelete:bulk, footer:wantFooter});
    else enhanceDataTable(t,{footer:wantFooter});
  });
}

/* ============================================================
   GENERIC PRODUCT CART — shared by purchase/return modals
   (sales invoices keep their own invCart/pick-card grid; this is a
   simpler row-list picker suited to accounting-only, desktop-first forms)
============================================================ */
let genCart = [];
let genCartDiscInputId = null; // set per-modal; null = no overall discount
let GEN_CART_PRICE_FIELD = 'price'; // 'price' for sales-return, 'cost' for purchases
async function genCartAdd(pid){
  const p = findInvProduct(pid) || (CACHE.allProducts||[]).find(x=>Number(x.id)===Number(pid)) || (CACHE.products||[]).find(x=>Number(x.id)===Number(pid));
  if(!p){ try{ showToast('کالا یافت نشد','error'); }catch(_){ } return; }
  const pidN = Number(p.id);
  const defPrice = GEN_CART_PRICE_FIELD==='cost' ? (p.cost||0) : (p.price||0);
  const whId=typeof headerPurchaseWarehouseId==='function'?headerPurchaseWarehouseId():null;
  // خرید: ورود کالا اگر پک زنده خالی باشد ماتریس تعریف‌شده؛ برگشت فروش: زنده (+defined اگر allow_neg)
  let pack=null;
  try{
    pack=await resolveServerAutoPack(pidN, whId, {
      preferDefinedIfEmpty: GEN_CART_PRICE_FIELD==='cost'
    });
  }catch(_){ pack=null; }
  if(pack && pack.has_matrix){
    let live=livePackRowsForSale(pack, whId);
    if(GEN_CART_PRICE_FIELD==='cost' && !live.length) live=pack.matrix||[];
    if(!live.length){
      const whName=whId&&typeof warehouseNameById==='function'?warehouseNameById(whId):'';
      showToast(whName
        ?('در «'+whName+'» هیچ رنگ/سایز تعریف‌شده برای این کالا نیست')
        :'هیچ رنگ/سایز تعریف‌شده برای این کالا نیست','error');
      return;
    }
    live.forEach(function(v){
      const vid=Number(v.variant_id!=null?v.variant_id:v.id)||null;
      const ex=genCart.find(r=>Number(r.product_id)===pidN && Number(r.variant_id||0)===Number(vid||0) && !r.batch_id && !r.is_fabric_roll);
      if(ex) ex.qty += 1;
      else genCart.push({
        product_id:pidN, name:p.name, qty:1, price:defPrice, disc:0, disc_amount:0, description:'',
        warehouse_id:headerPurchaseWarehouseId(),
        variant_id:vid,
        color_id:v.color_id||null,
        size_id:v.size_id||null,
        color_name:v.color_name||'',
        size_name:v.size_name||'',
        color:v.color_name||''
      });
    });
    showToast('پک کامل ('+fmt(live.length)+' قطعه) به سبد اضافه شد');
    renderGenCart();
    return;
  }
  const defaultQty = p.pack_size > 1 ? p.pack_size : 1;
  const ex = genCart.find(r=>Number(r.product_id)===pidN && !r.variant_id && !r.batch_id && !r.is_fabric_roll);
  if(ex) ex.qty += defaultQty;
  else genCart.push({product_id:pidN,name:p.name,qty:defaultQty,price:defPrice,disc:0,disc_amount:0,description:'',warehouse_id:headerPurchaseWarehouseId()});
  renderGenCart();
}
function renderGenCart(){
  const rowsEl=el('genCartRows'); if(!rowsEl) return;
  const showLineDisc=canAccounting();
  const countEl=el('poCartCount'); if(countEl) countEl.textContent=fmt(genCart.length)+' ردیف';
  const colSpan=showLineDisc?8:6;
  const priceLabel = GEN_CART_PRICE_FIELD==='cost' ? 'بهای خرید (ریال)' : 'فی (ریال)';
  const freight = (typeof moneyVal==='function' && el('po-freight')) ? moneyVal('po-freight') : 0;
  const freightSeller=freightTypeIsSeller(el('po-freight-type')?.value);
  const freightShares=allocateFreightShares(genCart, freight, el('po-freight-alloc')?.value||'amount');
  const chargedFreight=freightSeller?0:freight;
  if(!genCart.length){
    rowsEl.innerHTML=`<div class="inv-lines-empty">ردیفی اضافه نشده — کالا را از جستجو انتخاب کنید</div>`;
  } else {
    rowsEl.innerHTML = `<table class="inv-lines-tbl"><thead><tr>
      <th>کالا</th>
      <th class="col-qty">تعداد</th>
      <th class="col-price">${priceLabel}</th>
      ${showLineDisc?`<th class="col-disc">تخفیف ٪</th><th class="col-disc-amt">تخفیف مبلغ</th>`:''}
      <th class="col-wh">انبار مقصد</th>
      <th class="col-sum">جمع ردیف</th>
      <th class="col-rm"></th>
    </tr></thead><tbody>${genCart.map((r,i)=>{
      const gross=r.qty*r.price;
      const lineDiscAmt=showLineDisc?lineDiscApplied(r):0;
      const lineSum=Math.max(0,gross-lineDiscAmt);
      return `
      <tr>
        <td class="cn">${esc(r.name)}${(r.color_name||r.size_name)?`<div class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">${esc(variantAttrsLabel(r.color_name, r.size_name, ' · '))}</div>`:(r.is_fabric_roll||r.color?`<div class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">طاقه ${esc(r.roll_no||'جدید')} ${esc(r.color||'')}</div>`:'')}</td>
        <td class="col-qty"><input type="number" class="num-fit" min="0.001" step="0.001" inputmode="decimal" value="${fmtQty(r.qty)}" data-csp-change="${CSP.bind('change',function(event){genCart[(i)].qty=Math.max(0.001,parseQty(this.value,1));this.value=fmtQty(genCart[(i)].qty);if(canAccounting())invSyncLineDisc(genCart,(i),'pct');renderGenCart()})}"></td>
        <td class="col-price"><input type="text" inputmode="numeric" class="money num-fit" value="${moneyInit(r.price)}" data-csp-change="${CSP.bind('change',function(event){genCart[(i)].price=moneyParseInput(this);if(canAccounting())invSyncLineDisc(genCart,(i),'pct');renderGenCart()})}"></td>
        ${showLineDisc?`<td class="col-disc"><input type="number" class="num-fit" min="0" max="100" step="0.01" value="${r.disc||0}" data-csp-change="${CSP.bind('change',function(event){genCart[(i)].disc=+this.value||0;invSyncLineDisc(genCart,(i),'pct');renderGenCart()})}"></td>
        <td class="col-disc-amt"><input type="number" class="num-fit" min="0" value="${r.disc_amount||0}" data-csp-change="${CSP.bind('change',function(event){genCart[(i)].disc_amount=+this.value||0;invSyncLineDisc(genCart,(i),'amt');renderGenCart()})}"></td>`:''}
        <td class="col-wh"><select data-csp-change="${CSP.bind('change',function(event){genCart[(i)].warehouse_id=+this.value||null})}">${warehouseOptionsHtml(r.warehouse_id,'— انبار فاکتور —')}</select></td>
        <td class="col-sum mono">${fmt(lineSum)}${freightShares[i]?`<div class="muted" data-csp-style="${CSP.style(`font-size:10px;font-weight:500`)}">کرایه ${fmt(freightShares[i])}${freight?(' · '+Math.round(freightShares[i]*100/freight)+'٪'):''}</div>`:''}</td>
        <td class="col-rm"><button type="button" class="rm" title="حذف" data-csp-click="${CSP.bind('click',function(event){genCart.splice((i),1);renderGenCart()})}">×</button></td>
      </tr>
      <tr class="desc-row"><td colspan="${colSpan}"><input type="text" placeholder="توضیحات ردیف (اختیاری)" value="${esc(r.description||'')}" data-csp-change="${CSP.bind('change',function(event){genCart[(i)].description=this.value})}"></td></tr>`;
    }).join('')}</tbody></table>`;
  }
  const totEl=el('genCartTot');
  const linesDiscTotal = showLineDisc ? genCart.reduce((a,r)=>a+lineDiscApplied(r),0) : 0;
  const subtotal=invCartSubtotalAfterLineDisc(genCart);
  let poFinal=subtotal;
  if(genCartDiscInputId){
    const discAmtEl=el('po-disc-amt');
    let discPct=+el(genCartDiscInputId)?.value||0;
    let discAmt=discAmtEl?Math.max(0,Math.round(Number(discAmtEl.value)||0)):Math.round(subtotal*discPct/100);
    if(discAmtEl && !discAmt && discPct){ discAmt=Math.round(subtotal*discPct/100); discAmtEl.value=discAmt; }
    else if(discAmtEl && discAmt && subtotal>0){ discPct=Math.min(100,Math.round(discAmt*10000/subtotal)/100); const pe=el(genCartDiscInputId); if(pe && document.activeElement!==pe) pe.value=discPct; }
    poFinal=subtotal-discAmt+chargedFreight;
    if(totEl) totEl.innerHTML = `
      ${linesDiscTotal?`<div class="l"><span>جمع تخفیف ردیف‌ها:</span><span class="mono" data-csp-style="${CSP.style(`color:var(--orange)`)}">${fmt(linesDiscTotal)} ریال</span></div>`:''}
      <div class="l"><span>جمع کل (پس از تخفیف ردیف‌ها):</span><span class="mono">${fmt(subtotal)} ریال</span></div>
      <div class="l"><span>تخفیف کل فاکتور (${fmt(discPct)}٪ / مبلغ):</span><span class="mono">${fmt(discAmt)} ریال</span></div>
      ${freight?`<div class="l"><span>کرایه حمل ${freightSeller?'(عهده فروشنده — روی مبلغ تأمین‌کننده نمی‌آید)':'(عهده خریدار)'}:</span><span class="mono">${fmt(freight)} ریال</span></div>`:''}
      <div class="l final"><span>مبلغ نهایی:</span><span class="mono">${fmt(poFinal)} ریال</span></div>`;
  } else if(totEl) {
    totEl.innerHTML = `<div class="l final"><span>جمع:</span><span class="mono">${fmt(subtotal)} ریال</span></div>`;
  }
  window._poLastFinal = poFinal;
  if(typeof syncPoCashPayAmount==='function') syncPoCashPayAmount();
  try{ bindNumFit(rowsEl); }catch(_){}
}
function genProductSearchHtml(){
  return `<div data-csp-style="${CSP.style(`position:relative`)}">
    <input type="text" id="genProdSearch" class="search" data-csp-style="${CSP.style(`width:100%;margin-bottom:10px`)}" placeholder="جستجوی کالا برای افزودن..." data-csp-input="${CSP.bind('input',function(event){genProdShowDrop(this.value)})}" data-csp-focus="${CSP.bind('focus',function(event){genProdShowDrop(this.value)})}">
    <div id="genProdDrop" class="cust-si-drop" data-csp-style="${CSP.style(`display:none;position:fixed;width:280px;max-height:220px`)}"></div>
    <button type="button" class="btn sm ghost" data-csp-style="${CSP.style(`width:100%`)}" data-csp-click="${CSP.bind('click',function(event){genProdQuickModal(el('genProdSearch')?.value||'')})}">➕ ساخت کالای جدید</button>
  </div>`;
}
function genProdShowDrop(q){
  const drop=el('genProdDrop'), inp=el('genProdSearch'); if(!drop||!inp) return;
  const term=(q||'').trim().toLowerCase();
  let list=(CACHE.allProducts&&CACHE.allProducts.length?CACHE.allProducts:CACHE.products)||[];
  if(term){ list=list.filter(p=>textMatchesQuery((p.name||'')+' '+(p.code||''), term)); }
  const rect=inp.getBoundingClientRect();
  drop.style.top=(rect.bottom+2)+'px'; drop.style.left=rect.left+'px'; drop.style.width=rect.width+'px'; drop.style.display='block';
  const items=list.slice(0,40).map(p=>`
    <div class="cust-si-item" data-csp-click="${CSP.bind('click',function(event){genCartAdd((p.id));el('genProdSearch').value='';el('genProdDrop').style.display='none'})}">
      <span>${esc(p.name)}</span><span class="cust-si-meta">موجودی: ${fmtQtyFa(p.stock||0)}</span>
    </div>`).join('');
  const quickBtn=term?`<div class="cust-si-item" data-csp-style="${CSP.style(`color:var(--purple);font-weight:600`)}" data-csp-click="${CSP.bind('click',function(event){genProdQuickModal(`${String((CSP.htmlDecode(String(esc(term)))) ?? '')}`)})}">➕ ساخت کالا «${esc(term)}»</div>`:'';
  drop.innerHTML = items || quickBtn || '<div class="cust-si-empty">کالایی یافت نشد — دکمه ساخت کالای جدید را بزنید</div>';
  if(items && quickBtn) drop.innerHTML += quickBtn;
}
async function genProdQuickModal(prefill){
  await ensureProductCategories();
  await ensureUomCatalog();
  const name=(prefill||'').trim();
  openModal(`
    <div class="modal-head"><h3>➕ ساخت سریع کالا</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg full"><label>نام کالا *</label><input id="gq-name" value="${esc(name)}"></div>
      <div class="fg"><label>دسته‌بندی</label><select id="gq-cat"><option value="">— بدون دسته —</option>
        ${(CACHE.productCategories||[]).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}
      </select></div>
      <div class="fg"><label>کد</label><input id="gq-code"></div>
      <div class="fg"><label>قیمت فروش (ریال)</label><input id="gq-price" type="text" inputmode="numeric" class="money" value="0"></div>
      <div class="fg"><label>بهای تمام‌شده (ریال)</label><input id="gq-cost" type="text" inputmode="numeric" class="money" value="0"></div>
      <div class="fg"><label>واحد</label>${uomSelectHtml('gq-unit','','عدد')}</div>
    </div></div>
    <div class="modal-foot"><button class="btn" data-csp-click="${CSP.bind('click',function(event){saveGenProdQuick()})}">💾 ساخت و افزودن به سبد</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
}
async function saveGenProdQuick(){
  const name=el('gq-name').value.trim();
  if(!name){ showToast('نام کالا الزامی است','error'); return; }
  try{
    const p=await api('POST','/products/quick',{
      name, category_id:+el('gq-cat').value||null, code:el('gq-code').value,
      price:moneyVal('gq-price'), cost:moneyVal('gq-cost'), ...uomPayload('gq-unit')
    });
    if(!CACHE.allProducts) CACHE.allProducts=[];
    CACHE.allProducts.unshift(p); CACHE.products.unshift(p);
    genCartAdd(p.id); closeModal(); showToast('کالا ساخته و به سبد اضافه شد');
  }catch(e){}
}
document.addEventListener('click',e=>{ if(!e.target.closest('#genProdSearch')&&!e.target.closest('#genProdDrop')){ const d=el('genProdDrop'); if(d) d.style.display='none'; } });

