let PARTY_GROUP_FILTER='';
let PARTY_SEARCH='';
let _partySearchTimer=null;
async function renderPartiesTab(body){
  const groupFilter=PARTY_GROUP_FILTER;
  const search=PARTY_SEARCH;
  await ensurePartyGroups();
  let qp='?limit=200'; const qps=['limit=200'];
  if(groupFilter) qps.push('party_group_id='+encodeURIComponent(groupFilter));
  if(search) qps.push('search='+encodeURIComponent(search));
  qp='?'+qps.join('&');
  const resp=await api('GET','/parties'+qp)||{};
  const rows=resp.data||resp||[];
  const total=resp.pagination?.total ?? rows.length;
  CACHE.parties=rows;
  const natureLabel={debit:'بدهکار',credit:'بستانکار','':'بی‌حساب'};
  const roleLabel={customer:'مشتری',supplier:'تأمین‌کننده',employee:'کارمند',partner:'شریک',marketer:'بازاریاب',other:'سایر'};
  const balRows=rows.map(p=>({...p, balance:Number(p.balance!=null?p.balance:(p.opening_balance_toman||p.opening_balance||0))}));
  const balT=balTotals(balRows);
  body.innerHTML=`
    <div class="list-split">
      <aside class="list-side">
        <div data-csp-style="${CSP.style(`font-weight:700;font-size:13px;margin-bottom:8px;color:var(--purple);display:flex;justify-content:space-between;align-items:center`)}">
          <span>گروه اشخاص</span>
          <button type="button" class="btn sm icon" title="گروه جدید" data-csp-click="${CSP.bind('click',function(event){partyGroupModal()})}">➕</button>
        </div>
        <div id="partyGroupFilter" class="list-pills" data-value="${esc(groupFilter)}">
          <button type="button" class="btn sm ${!groupFilter?'':'ghost'}" data-csp-style="${CSP.style(`justify-content:flex-start;text-align:right`)}" data-csp-click="${CSP.bind('click',function(event){filterPartyGroup('')})}">کلیه اشخاص</button>
          ${(CACHE.partyGroups||[]).filter(g=>g.code!==0).map(g=>`
            <button type="button" class="btn sm ${groupFilter==String(g.id)?'':'ghost'}" data-csp-style="${CSP.style(`justify-content:flex-start;text-align:right`)}" data-csp-click="${CSP.bind('click',function(event){filterPartyGroup(`${String((g.id) ?? '')}`)})}">${esc(g.name)}</button>
          `).join('')}
        </div>
      </aside>
      <div class="list-main">
        <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px;flex-wrap:wrap;gap:8px`)}">
          <button class="btn" data-csp-click="${CSP.bind('click',function(event){partyModal()})}">➕ شخص جدید <span class="muted">F4</span></button>
          <input id="partySearch" placeholder="جستجو نام/تلفن/کد... F10" value="${esc(search)}" data-csp-style="${CSP.style(`padding:7px 10px;border:1.5px solid var(--border);border-radius:8px;font-size:13px;min-width:200px`)}">
          <span class="muted" data-csp-style="${CSP.style(`font-size:12px`)}">${fmt(rows.length)}${total>rows.length?' از '+fmt(total):''} نفر</span>
        </div>
        <div class="tbl-wrap tbl-scroll"><table class="tbl" id="partiesTbl" data-bulk-delete="/parties" data-bulk-label="حذف" data-bulk-perm="admin" data-bulk-confirm="{n} شخص حذف/غیرفعال شود؟" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
          <th data-col-kind="skip">کد</th><th data-col-kind="skip">کد تفصیلی</th><th data-col-kind="skip">نام</th><th data-col-kind="skip">تلفن ۱</th><th data-col-kind="skip">شهر</th><th data-col-kind="skip">گروه</th><th data-col-kind="skip">سمت‌ها</th><th data-col-kind="skip">ماهیت مانده</th>
          <th data-col-kind="debit">بدهکار ${moneyColLabel()}</th><th data-col-kind="credit">بستانکار ${moneyColLabel()}</th><th class="no-sort">عملیات</th>
        </tr></thead><tbody>${balRows.map(p=>`<tr data-id="${p.id}">
          <td class="mono" data-col-kind="skip">${esc(p.person_code||'-')}</td>
          <td class="mono muted" data-col-kind="skip">${esc(p.coa_code||'-')}</td>
          <td data-col-kind="skip">${esc(p.prefix||'')} ${esc(p.full_name||p.company_name||p.biz||'-')}</td>
          <td class="mono" data-col-kind="skip">${esc(p.phone||'-')}</td>
          <td data-col-kind="skip">${esc(p.city||'-')}</td>
          <td data-col-kind="skip">${esc(p.party_group_name||'-')}</td>
          <td data-col-kind="skip">${(p.party_roles||[]).map(r=>roleLabel[r]||r).join('، ')||'-'}</td>
          <td data-col-kind="skip">${balNatureBadgeHtml(p)}${(p.account_nature&&natureLabel[p.account_nature])?`<div class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">گروه: ${natureLabel[p.account_nature]}</div>`:''}</td>
          ${balDebitTd(p.balance)}${balCreditTd(p.balance)}
          <td class="no-sort" data-csp-style="${CSP.style(`white-space:nowrap`)}">
            <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){partyModal((p.id))})}">✏️</button>
            <button class="btn sm blue" data-csp-click="${CSP.bind('click',function(event){showPartyTurnover((p.id),`${String((CSP.htmlDecode(String(esc(p.full_name||p.biz||'')))) ?? '')}`)})}">📒 گردش</button>
            <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deleteParty((p.id))})}">🗑️</button>
          </td>
        </tr>`).join('')||emptyRow(11)}</tbody>
        <tfoot><tr data-csp-style="${CSP.style(`border-top:2px solid var(--border);background:var(--purple-light);font-weight:700`)}">
          <td colspan="8">مانده خالص (${fmt(balRows.length)} نفر) — ${balNetLabel(balT)}<div class="muted" data-csp-style="${CSP.style(`font-size:11px;font-weight:500`)}">بدهکاران ${fmt(balT.debit)} · بستانکاران ${fmt(balT.credit)} → تفاضل</div></td>
          <td class="mono" data-csp-style="${CSP.style(`font-weight:800;color:#dc2626`)}">${balT.netDebit?fmt(balT.netDebit):'-'}</td>
          <td class="mono" data-csp-style="${CSP.style(`font-weight:800;color:var(--green)`)}">${balT.netCredit?fmt(balT.netCredit):'-'}</td>
          <td></td>
        </tr></tfoot></table></div>
      </div>
    </div>`;
  const ps=el('partySearch');
  if(ps){
    ps.focus();
    const pos=ps.value.length; try{ ps.setSelectionRange(pos,pos); }catch(_){}
    ps.addEventListener('input',()=>{
      PARTY_SEARCH=ps.value;
      clearTimeout(_partySearchTimer);
      _partySearchTimer=setTimeout(()=>loadAccTab('parties'),280);
    });
  }
  if(typeof enhanceDataTable==='function') enhanceDataTable(el('partiesTbl'),{
    selectable:true,
    footer:false,
    bulkDelete:typeof tblInferBulkDelete==='function'?tblInferBulkDelete(el('partiesTbl')):null
  });
}
function filterPartyGroup(id){ PARTY_GROUP_FILTER=id; loadAccTab('parties'); }
async function showPartyTurnover(id,name,role){
  try{
    const q=(role&&['customer','supplier','person'].includes(String(role)))?('?role='+encodeURIComponent(role)):'';
    const d=await api('GET','/parties/'+id+'/turnover'+q);
    if(!d){ showToast('شخص یافت نشد','error'); return; }
    const entries=(d.entries||[]).map(e=>({
      date:e.date,
      description:e.description||e.type_label||'-',
      debit:e.debit||0,
      credit:e.credit||0,
      balance:e.balance||e.running_balance||0
    }));
    const title=(d.title||'گردش')+': '+name;
    const totalDebit=d.totalDebit!=null?d.totalDebit:entries.reduce((a,e)=>a+(Number(e.debit)||0),0);
    const totalCredit=d.totalCredit!=null?d.totalCredit:entries.reduce((a,e)=>a+(Number(e.credit)||0),0);
    const closing=d.closing!=null?d.closing:(d.books_closing!=null?d.books_closing:(entries.length?entries[entries.length-1].balance:0));
    const side=(closing||0)>0?'بدهکار':((closing||0)<0?'بستانکار':'صفر');
    const sideColor=(closing||0)>0?'var(--red)':((closing||0)<0?'var(--green)':'inherit');
    const repHint=d.has_incentive_ledger&&d.linked_rep_id
      ? `<div class="muted" data-csp-style="${CSP.style(`padding:10px 16px;border-bottom:1px solid var(--border);font-size:12px;line-height:1.7`)}">پرداخت و تعهد انگیزه این نماینده روی حساب تفصیلی همین شخص سند می‌شود و در جدول زیر می‌آید. خلاصه عملیاتی: <button class="btn sm" data-csp-click="${CSP.bind('click',function(event){closeModal();go('acc-reps');setTimeout(function(){loadRepDetail(Number(d.linked_rep_id))},80)})}">صورت‌حساب نماینده${d.linked_rep_name?' — '+esc(d.linked_rep_name):''}</button></div>`
      : '';
    const body=entries.length
      ? `${repHint}<div class="tbl-wrap" data-csp-style="${CSP.style(`max-height:70vh`)}"><table class="tbl"><thead><tr>
        <th>تاریخ</th><th>شرح</th><th>بدهکار ${moneyColLabel()}</th><th>بستانکار ${moneyColLabel()}</th><th>مانده ${moneyColLabel()}</th>
      </tr></thead><tbody>${entries.map(r=>`<tr>
        <td class="mono">${escDate(r.date)}</td><td>${esc(r.description||'-')}</td>
        <td class="mono">${fmt(r.debit||0)}</td><td class="mono">${fmt(r.credit||0)}</td>
        <td class="mono">${fmt(r.balance||0)}</td>
      </tr>`).join('')}</tbody>
      <tfoot><tr data-csp-style="${CSP.style(`border-top:2px solid var(--border);background:var(--purple-light);font-weight:700`)}">
        <td colspan="2">جمع دوره</td>
        <td class="mono" data-csp-style="${CSP.style(`color:var(--orange)`)}">${fmt(totalDebit)}</td>
        <td class="mono" data-csp-style="${CSP.style(`color:var(--green)`)}">${fmt(totalCredit)}</td>
        <td class="mono" data-csp-style="${CSP.style(`color:${sideColor}`)}">${fmt(closing||0)}</td>
      </tr></tfoot></table></div>
      <div data-csp-style="${CSP.style(`padding:12px 16px;border-top:1px solid var(--border);font-weight:700`)}">
        مانده نهایی (هم‌تراز کنترل حساب): <span data-csp-style="${CSP.style(`color:${sideColor}`)}">${fmt(closing||0)} ریال${side!=='صفر'?' ('+side+')':''}</span>
        <div class="muted" data-csp-style="${CSP.style(`font-weight:500;margin-top:6px;font-size:12px`)}">جمع بدهکار ${fmt(totalDebit)} ریال · جمع بستانکار ${fmt(totalCredit)} ریال · منبع مانده party-books</div>
      </div>`
      : `${repHint}<div data-csp-style="${CSP.style(`padding:24px;text-align:center`)}"><p class="muted">هنوز ردیف گردشی برای این شخص ثبت نشده است.</p><p class="muted" data-csp-style="${CSP.style(`font-size:12px`)}">پس از ثبت سند حسابداری، فاکتور، خرید یا پرداخت، گردش اینجا دیده می‌شود. پرداخت انگیزه به نمایندهٔ لینک‌شده هم روی همین حساب شخص می‌نشیند.</p></div>`;
    openModal(`
      <div class="modal-head"><h3>📒 ${esc(title)}</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
      <div class="modal-body" data-csp-style="${CSP.style(`padding:0`)}">${body}</div>
      <div class="modal-foot"><button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">بستن</button></div>`);
  }catch(e){ showToast('خطا در بارگذاری گردش','error'); }
}
