async function deleteParty(id){
  if(!confirm('این شخص غیرفعال/حذف شود؟')) return;
  try{ await api('DELETE','/parties/'+id); showToast('حذف شد'); loadAccTab('parties'); }catch(e){}
}
function exportPartiesExcel(){
  downloadAuth('/parties/export/excel','parties.csv');
}
function importPartiesExcel(){
  const inp=document.createElement('input'); inp.type='file'; inp.accept='.csv,.xlsx,.xls,text/csv';
  inp.onchange=async()=>{
    const f=inp.files[0]; if(!f) return;
    const text=await f.text();
    const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);
    if(lines.length<2){ showToast('فایل خالی است','error'); return; }
    const sep=lines[0].includes(';')?';':',';
    const headers=lines[0].split(sep).map(h=>h.replace(/^"|"$/g,'').trim());
    const rows=[];
    for(let i=1;i<lines.length;i++){
      const cols=lines[i].split(sep).map(c=>c.replace(/^"|"$/g,'').trim());
      const obj={};
      headers.forEach((h,idx)=>obj[h]=cols[idx]||'');
      rows.push({
        full_name: obj['نام']||obj['نام*']||obj.full_name||obj.name,
        phone: obj['تلفن']||obj['تلفن*']||obj.phone,
        prefix: obj['پیشوند']||obj.prefix,
        mobile: obj['موبایل']||obj.mobile,
        city: obj['شهر']||obj.city,
        party_group_name: obj['گروه']||obj.party_group_name,
        party_roles: (obj['سمت‌ها']||obj.roles||'customer').split(/[|,،]/).map(x=>x.trim()).filter(Boolean),
        email: obj['ایمیل']||obj.email,
        national_id: obj['کد ملی']||obj.national_id
      });
    }
    try{
      const r=await api('POST','/parties/import',{rows});
      showToast(`ورود انجام شد — جدید: ${r.created||0}، رد شده: ${r.skipped||0}`);
      loadAccTab('parties');
    }catch(e){}
  };
  inp.click();
}
async function saveParty(id){
  const full_name=el('pty-name').value.trim();
  const phone=el('pty-phone').value.trim();
  if(!full_name||!phone){ showToast('نام و تلفن الزامی است','error'); return; }
  const roles=[...document.querySelectorAll('.pty-role:checked')].map(x=>x.value);
  if(!roles.length){ showToast('حداقل یک سمت انتخاب کنید','error'); return; }
  const party_group_id=el('pty-party_group_id').value;
  if(!party_group_id){ showToast('انتخاب گروه اشخاص الزامی است','error'); return; }
  const data={
    person_code:el('pty-code').value.trim()||undefined,
    coa_code:el('pty-coa').value.trim(),
    prefix:el('pty-prefix').value,
    full_name, company_name:el('pty-company').value,
    phone, secondary_phone:el('pty-phone2').value, mobile:el('pty-mobile').value,
    fax:el('pty-fax').value, email:el('pty-email').value,
    national_id:el('pty-national_id').value, economic_code:el('pty-economic_code').value,
    postal_code:el('pty-postal_code').value, birth_date:el('pty-birth_date').value,
    referrer:el('pty-referrer').value, city:el('pty-city').value, province:el('pty-province').value,
    address:el('pty-address').value,
    party_group_id,
    party_roles:roles,
    position_id:+el('pty-position')?.value||null,
    credit_limit_rial:moneyVal('pty-credit'), opening_balance_rial:(()=>{const a=Math.abs(moneyVal('pty-opening')||0); const side=el('pty-open-credit')?.checked?'credit':'debit'; return side==='credit'?-a:a;})(),
    account_nature:el('pty-nature').value, notes:el('pty-note').value,
    user_id:+el('pty-expert')?.value||undefined,
    assigned_to:+el('pty-expert')?.value||undefined,
    biz:full_name
  };
  try{
    const saved=id?await api('PUT','/parties/'+id,data):await api('POST','/parties',data);
    const partyId=id||saved?.data?.id||saved?.id;
    const portalRole=el('pty-portal-role')?.value||'none';
    try{
      await api('PUT','/portal/access',{
        party_id:partyId||undefined,
        phone,
        name:full_name,
        portal_role:portalRole,
        send_sms:!!el('pty-portal-sms')?.checked
      });
    }catch(pe){
      showToast('شخص ذخیره شد ولی دسترسی پورتال: '+(pe.message||'خطا'),'error');
      closeModal(); loadAccTab('parties'); return;
    }
    closeModal(); showToast('ذخیره شد'); loadAccTab('parties');
  }catch(e){}
}

async function renderSuppliersTab(body){
  const [suppliers,balances]=await Promise.all([api('GET','/suppliers'),api('GET','/suppliers/balances/list')]);
  CACHE.suppliers=suppliers||[];
  const balMap={}; (balances||[]).forEach(b=>balMap[b.id]=b.payable);
  const total=Object.values(balMap).reduce((a,v)=>a+v,0);
  body.innerHTML=`
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px`)}"><button class="btn" data-csp-click="${CSP.bind('click',function(event){supplierModal()})}">➕ تأمین‌کننده جدید</button></div>
    <div class="tbl-wrap"><table class="tbl" data-bulk-delete="/suppliers" data-bulk-label="حذف" data-bulk-confirm="{n} تأمین‌کننده حذف شود؟"><thead><tr>
      <th>نام</th><th>تلفن</th><th>آدرس</th><th>مانده پرداختنی (ت)</th><th class="no-sort">عملیات</th>
    </tr></thead><tbody>${(suppliers||[]).map(s=>`<tr data-id="${s.id}">
      <td>${esc(s.name)}</td><td class="mono">${esc(s.phone||'-')}</td>${tdClip(s.address||'-', 200, true)}
      <td class="mono" data-csp-style="${CSP.style(`font-weight:700;color:${(balMap[s.id]||0)>0?'var(--red)':'var(--green)'}`)}">${fmt(balMap[s.id]||0)}</td>
      <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
        <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){supplierModal((s.id))})}">✏️</button>
        <button class="btn sm green" data-csp-click="${CSP.bind('click',function(event){supplierPaymentModal((s.id),`${String((CSP.htmlDecode(String(esc(s.name)))) ?? '')}`)})}">💵 پرداخت</button>
        <button class="btn sm blue" data-csp-click="${CSP.bind('click',function(event){showSupplierLedger((s.id),`${String((CSP.htmlDecode(String(esc(s.name)))) ?? '')}`)})}">📋 دفتر معین</button>
        <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deleteSupplier((s.id))})}">🗑️</button>
      </td>
    </tr>`).join('')||emptyRow(5)}</tbody>
    <tfoot><tr data-csp-style="${CSP.style(`border-top:2px solid var(--border);background:var(--purple-light);font-weight:700`)}">
      <td colspan="3">جمع کل مانده پرداختنی</td>
      <td class="mono" data-csp-style="${CSP.style(`font-weight:800;color:var(--red)`)}">${fmt(total)}</td><td></td>
    </tr></tfoot></table></div>`;
}
async function supplierModal(id){
  if(canAccounting()&&!CACHE.partyGroups) CACHE.partyGroups=await api('GET','/party-groups')||[];
  const s=id?(CACHE.suppliers||[]).find(x=>x.id===id):{};
  const supPartyGroups=(CACHE.partyGroups||[]).filter(g=>g.entity_type==='supplier'||g.entity_type==='all');
  openModal(`
    <div class="modal-head"><h3>${id?'ویرایش تأمین‌کننده':'تأمین‌کننده جدید'}</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg full"><label>نام * ${hlp('نام شرکت یا تولیدی تأمین‌کننده کالا.')}</label><input id="sup-name" value="${esc(s.name||'')}"></div>
      <div class="fg"><label>تلفن</label><input id="sup-phone" value="${esc(s.phone||'')}"></div>
      <div class="fg full"><label>آدرس</label><input id="sup-address" value="${esc(s.address||'')}"></div>
      ${!id?`<div class="fg"><label>مانده اولیه ${moneyColLabel()} ${hlp('مبلغی که از قبل به این تأمین‌کننده بدهکاریم.')}</label><input id="sup-balance" type="text" inputmode="numeric" class="money" value="0"></div>`:''}
      <div class="fg full"><label>گروه اشخاص</label><select id="sup-party_group_id">
        <option value="">-- بدون گروه --</option>
        ${supPartyGroups.map(g=>`<option value="${g.id}" ${s.party_group_id===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}
      </select></div>
      <div class="fg full"><label>یادداشت</label><textarea id="sup-note">${esc(s.note||'')}</textarea></div>
      ${coaCodeFieldHtml('supplier', id, s.coa_code)}
      ${supplierExtraFieldsHtml(s)}
    </div></div>
    <div class="modal-foot"><button class="btn" data-csp-click="${CSP.bind('click',function(event){saveSupplier((id||0))})}">💾 ذخیره</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
}
async function saveSupplier(id){
  const name=el('sup-name').value.trim();
  if(!name){ showToast('نام الزامی است','error'); return; }
  const data={name,phone:el('sup-phone').value,address:el('sup-address').value,note:el('sup-note').value};
  if(el('sup-party_group_id')) data.party_group_id=+el('sup-party_group_id').value||null;
  if(usesExtendedCoa()) Object.assign(data,collectPartyExtraData('sup'));
  if(!id) data.balance=moneyVal('sup-balance');
  try{
    if(id) await api('PUT','/suppliers/'+id,data); else await api('POST','/suppliers',data);
    closeModal(); showToast('ذخیره شد'); loadAccTab('suppliers');
  }catch(e){}
}
