async function renderInvReservationsTab(body){
  if(!CACHE.allProducts?.length) CACHE.allProducts=await api('GET','/products')||[];
  const data=await api('GET','/inventory/reservations')||{rows:[]};
  body.innerHTML=`
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px;gap:8px`)}">
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){invRsvModal()})}">➕ رزرو جدید</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){loadAccTab('inv-reservations')})}">🔄</button>
    </div>
    <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
      <th>شماره</th><th>نوع</th><th>کالا</th><th>تعداد</th><th>مصرف‌شده</th><th>وضعیت</th><th></th>
    </tr></thead><tbody>
    ${(data.rows||[]).map(r=>{
      const p=(CACHE.allProducts||[]).find(x=>x.id===r.product_id);
      return `<tr>
        <td class="mono">${esc(r.reservation_no)}</td><td>${esc(r.kind)}</td>
        <td>${esc(p?.name||('#'+r.product_id))}</td>
        <td class="num">${fmtQtyFa(r.qty)}</td><td class="num">${fmtQtyFa(r.qty_consumed||0)}</td>
        <td>${esc(r.status)}</td>
        <td>${r.status==='active'?`<button class="btn sm" data-csp-click="${CSP.bind('click',function(event){invRsvRelease((r.id))})}">آزادسازی</button>`:''}</td>
      </tr>`;
    }).join('')||'<tr><td colspan="7" class="empty">رزروی نیست</td></tr>'}
    </tbody></table></div>`;
}
function invRsvModal(){
  const prods=CACHE.allProducts||[];
  showModal('رزرو موجودی',`
    <div class="form-grid">
      <div class="fg"><label>کالا</label>${productSelect('ir-prod','',prods)}</div>
      <div class="fg"><label>تعداد</label><input id="ir-qty" type="number" min="1" value="1"></div>
      <div class="fg"><label>نوع</label><select id="ir-kind"><option value="sales">فروش</option><option value="production">تولید</option><option value="project">پروژه</option><option value="manual">دستی</option></select></div>
      <div class="fg"><label>یادداشت</label><input id="ir-note"></div>
    </div>
    <div data-csp-style="${CSP.style(`margin-top:12px;text-align:left`)}"><button class="btn" data-csp-click="${CSP.bind('click',function(event){invRsvSave()})}">ثبت رزرو</button></div>`);
}
async function invRsvSave(){
  try{
    await api('POST','/inventory/reservations',{
      product_id:+el('ir-prod').value, qty:+el('ir-qty').value,
      kind:el('ir-kind').value, note:el('ir-note').value||''
    });
    closeModal(); showToast('رزرو ثبت شد'); loadAccTab('inv-reservations');
  }catch(e){}
}
async function invRsvRelease(id){
  if(!confirm('این رزرو آزاد شود؟')) return;
  try{ await api('POST','/inventory/reservations/'+id+'/release',{}); showToast('آزاد شد'); loadAccTab('inv-reservations'); }catch(e){}
}

async function renderInvLandedTab(body){
  if(!CACHE.allProducts?.length) CACHE.allProducts=await api('GET','/products')||[];
  body.innerHTML=`
    <div class="panel">
      <div class="panel-head"><h4>ثبت هزینه حمل / گمرک / بیمه (Landed Cost)</h4></div>
      <div class="panel-body">
        <p class="muted" data-csp-style="${CSP.style(`margin-bottom:12px;line-height:1.8`)}">هزینه‌های قابل انتساب به موجودی (IAS 2) روی میانگین موزون کالا سرمایه می‌شوند؛ کالا باید موجودی داشته باشد. ابطال کامل (R13) میانگین و سند حسابداری را برمی‌گرداند.</p>
        <div class="form-grid">
          <div class="fg"><label>تاریخ</label><input id="lc-date" data-jdate value="${todayJalali()}"></div>
          <div class="fg"><label>روش تسهیم</label>
            <select id="lc-method"><option value="value">بر اساس ارزش</option><option value="qty">بر اساس تعداد</option><option value="manual">دستی</option></select>
          </div>
          <div class="fg"><label>حمل (ریال)</label><input id="lc-freight" type="number" min="0" value="0"></div>
          <div class="fg"><label>گمرک (ریال)</label><input id="lc-customs" type="number" min="0" value="0"></div>
          <div class="fg"><label>بیمه (ریال)</label><input id="lc-ins" type="number" min="0" value="0"></div>
          <div class="fg"><label>کالا برای تسهیم</label>
            ${productSelect('lc-prod','',(CACHE.allProducts||[]))}
          </div>
          <div class="fg"><label>تعداد مبنا</label><input id="lc-qty" type="number" min="0" value="1"></div>
          <div class="fg"><label>ارزش مبنا (ریال)</label><input id="lc-base" type="number" min="0" value="0"></div>
          <div class="fg"><label>شماره سند برای ابطال</label><input id="lc-void-id" type="number" min="1" placeholder="مثلاً ۱۲"></div>
        </div>
        <div data-csp-style="${CSP.style(`margin-top:14px;display:flex;gap:8px;flex-wrap:wrap`)}">
          <button class="btn" data-csp-click="${CSP.bind('click',function(event){invLandedPost()})}">ثبت و تسهیم</button>
          <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){invLandedVoid()})}">⛔ ابطال سند</button>
        </div>
      </div>
    </div>`;
  initCustSearches(body);
}
async function invLandedPost(){
  const lines=[];
  const f=+el('lc-freight').value||0, c=+el('lc-customs').value||0, i=+el('lc-ins').value||0;
  if(f>0) lines.push({cost_type:'freight', amount_rial:f});
  if(c>0) lines.push({cost_type:'customs', amount_rial:c});
  if(i>0) lines.push({cost_type:'insurance', amount_rial:i});
  if(!lines.length){ showToast('حداقل یک مبلغ هزینه وارد کنید','error'); return; }
  if(!(+el('lc-prod').value)){ showToast('کالا را انتخاب کنید','error'); return; }
  try{
    const doc=await api('POST','/inventory/landed-cost',{
      date:el('lc-date').value, alloc_method:el('lc-method').value, lines
    });
    const r=await api('POST','/inventory/landed-cost/'+doc.id+'/post',{
      date:el('lc-date').value,
      allocations:[{
        product_id:+el('lc-prod').value,
        qty:+el('lc-qty').value||0,
        base_value_rial:+el('lc-base').value||0,
        allocated_rial: lines.reduce((a,l)=>a+l.amount_rial,0)
      }]
    });
    showToast('هزینه حمل ثبت شد — شماره سند '+doc.id+' (برای ابطال نگه دارید)');
    try{ el('lc-void-id').value=String(doc.id); }catch(_){}
    return r;
  }catch(e){ showToast(e.message||'خطا در ثبت هزینه حمل','error'); }
}
async function invLandedVoid(){
  const id=+el('lc-void-id')?.value||0;
  if(!id){ showToast('شماره سند هزینه حمل را وارد کنید','error'); return; }
  if(!confirm('ابطال کامل هزینه حمل #'+id+'؟ میانگین و سند حسابداری برمی‌گردد.')) return;
  try{
    await api('POST','/inventory/landed-cost/'+id+'/void',{ reason:'ابطال از UI' });
    showToast('هزینه حمل ابطال شد');
  }catch(e){ showToast(e.message||'خطا در ابطال','error'); }
}

/* ============================================================
   WAREHOUSES (انبارها) — each product belongs to exactly one warehouse;
   products.stock remains the single total. See routes/warehouses.js for
   the documented limits of this simplified (non-per-warehouse-quantity) model.
============================================================ */
function productOptions(selectedId){
  return `<option value="">-- انتخاب کالا --</option>` + (CACHE.allProducts||[]).map(p=>`<option value="${p.id}" ${p.id===selectedId?'selected':''}>${esc(p.name)} (${esc(p.code||'-')}) — موجودی: ${fmtQtyFa(p.stock||0)}</option>`).join('');
}
async function renderWarehousesTab(body){
  const [warehouses,lookup,leafRep]=await Promise.all([
    api('GET','/warehouses')||[],
    api('GET','/warehouses/lookup-options')||{},
    api('GET','/warehouses/coa-leaf-report',null,false,true).catch(()=>null)
  ]);
  CACHE.warehouses=warehouses;
  CACHE.warehouseLookup=lookup;
  CACHE.coaLeafReport=leafRep||null;
  const entityMap=Object.fromEntries((lookup.entities||[]).map(o=>[o.value,o.label]));
  const typeMap=Object.fromEntries((lookup.types||[]).map(o=>[o.value,o.label]));
  const leafMap=new Map(((leafRep&&leafRep.warehouses)||[]).map(x=>[x.warehouse_id,x]));
  const leafBanner=(leafRep&&leafRep.summary&&leafRep.summary.needs_attention&&isAdmin())
    ?`<div class="alert warn coa-leaf-banner">⚠️ نگاشت حساب برگ ناقص است — ${fmtQtyFa(leafRep.summary.warehouses_perpetual_unmapped)} انبار دائمی فعال بی‌نگاشت، ${fmtQtyFa(leafRep.summary.settings_nonleaf||0)} کلید غیربرگ، ${fmtQtyFa(leafRep.summary.settings_not_found||0)} یافت‌نشده، ${fmtQtyFa(leafRep.summary.nonleaf_accounts_with_lines)} حساب غیربرگ دارای سطر. حالت: <b>${esc(leafRep.flag.value==='enforce'?'اجباری (enforce)':'هشدار (warn)')}</b>.
      <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){openCoaLeafReportModal()})}">📋 گزارش نگاشت</button></div>`:'';
  body.innerHTML=`
    ${leafBanner}
    <div class="toolbar coa-leaf-toolbar"><button class="btn" data-csp-click="${CSP.bind('click',function(event){warehouseModal()})}">➕ انبار جدید</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){openCoaLeafReportModal()})}">📋 گزارش نگاشت حساب برگ</button></div>
    <div class="tbl-wrap"><table class="tbl" data-bulk-delete="/warehouses" data-bulk-label="حذف" data-bulk-confirm="{n} انبار حذف شود؟"><thead><tr>
      <th>کد</th><th>نام انبار</th><th>واحد</th><th>نوع</th><th>حساب موجودی</th><th>حساب بهای تمام‌شده</th><th>مرکز هزینه</th><th>روش ثبت</th><th>آدرس</th><th>پیش‌فرض</th><th>وضعیت</th><th class="no-sort">عملیات</th>
    </tr></thead><tbody>${warehouses.map(w=>`<tr data-id="${w.id}">
      <td class="mono">${esc(w.code||'-')}</td>
      <td>${esc(w.name)}</td>
      <td>${entityMap[w.entity]||w.entity||'-'}</td>
      <td>${typeMap[w.warehouse_type]||w.warehouse_type||'-'}</td>
      <td class="mono" title="${esc(w.inventory_account_name||'')}">${esc(w.inventory_account_code||w.inventory_coa_code||'—')}${(leafMap.get(w.id)&&leafMap.get(w.id).perpetual&&!leafMap.get(w.id).mapped)?' <span class="tag t-cancel">بی‌نگاشت</span>':''}</td>
      <td class="mono">${esc(w.cogs_coa_code||'—')}</td>
      <td>${esc(w.cost_center_code?w.cost_center_code+' — ':'')}${esc(w.cost_center_name||'—')}</td>
      <td>${w.inventory_system==='periodic'?'ادواری':'دائمی'}</td>
      ${tdClip(w.address||'-', 180, true)}
      <td>${w.is_default?'<span class="tag t-done">✓</span>':'-'}</td>
      <td>${w.active?'<span class="tag t-done">فعال</span>':'<span class="tag t-cancel">غیرفعال</span>'}</td>
      <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
        <button class="btn sm blue" data-csp-click="${CSP.bind('click',function(event){viewWarehouseStock((w.id),`${String((CSP.htmlDecode(String(esc(w.name)))) ?? '')}`)})}">📦 موجودی</button>
        ${w.inventory_system==='periodic'?`<button class="btn sm orange" data-csp-click="${CSP.bind('click',function(event){warehousePeriodCloseModal((w.id),`${String((CSP.htmlDecode(String(esc(w.name)))) ?? '')}`)})}">📅 بستن دوره</button>
        <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){warehousePeriodClosesModal((w.id),`${String((CSP.htmlDecode(String(esc(w.name)))) ?? '')}`)})}">📋 دوره‌ها / بازگشایی</button>`:''}
        <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){warehouseModal((w.id))})}">✏️</button>
        <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deleteWarehouse((w.id))})}">🗑️</button>
      </td>
    </tr>`).join('')||emptyRow(12)}</tbody></table></div>`;
}
/* v586 Phase 3 — گزارش نگاشت حساب برگ (دسته‌ها + کنترلی + انبار غیرفعال) */
async function openCoaLeafReportModal(){
  let rep=null;
  try{ rep=await api('GET','/warehouses/coa-leaf-report'); }catch(e){ return; }
  if(!rep) return;
  CACHE.coaLeafReport=rep;
  const reasonFa={empty:'خالی',not_found:'یافت نشد',not_leaf:'غیربرگ',wrong_group:'ناسازگار با کاربرد',control:'کنترلی'};
  const sum=rep.summary||{};
  const mkSetRows=(rows,emptyMsg)=>(rows||[]).map(s=>`<tr><td class="mono">${esc(s.key)}</td><td class="mono">${esc(s.code)}</td><td>${esc(s.name||'')}</td><td>${esc(reasonFa[s.reason]||s.reason||'')}</td><td>${esc(s.source||'')}</td></tr>`).join('')||`<tr><td colspan="5" class="empty">${emptyMsg}</td></tr>`;
  const whRows=(rep.warehouses_unmapped||[]).map(w=>`<tr>
    <td>${esc(w.name)}${w.fixed_asset_type?' <span class="tag t-cancel">دارایی ثابت</span>':''}</td>
    <td>${w.perpetual?'دائمی':'ادواری'}</td>
    <td class="mono">${esc(w.inventory_coa_code||'—')}</td><td>${w.inventory_ok?'<span class="tag t-done">OK</span>':esc(reasonFa[w.inventory_reason]||'')}</td>
    <td class="mono">${esc(w.cogs_coa_code||'—')}</td><td>${w.cogs_ok?'<span class="tag t-done">OK</span>':esc(reasonFa[w.cogs_reason]||'')}</td>
  </tr>`).join('')||'<tr><td colspan="6" class="empty">انبار دائمی فعال بی‌نگاشت نیست</td></tr>';
  const whInactiveRows=(rep.warehouses_inactive_unmapped||[]).map(w=>`<tr>
    <td>${esc(w.name)}</td><td class="mono">${esc(w.inventory_coa_code||'—')}</td><td class="mono">${esc(w.cogs_coa_code||'—')}</td>
  </tr>`).join('')||'<tr><td colspan="3" class="empty">انبار غیرفعال بی‌نگاشت نیست</td></tr>';
  const ctrlRows=(rep.control_accounts||[]).map(c=>`<tr>
    <td class="mono">${esc(c.code)}</td><td>${esc(c.name||'')}</td>
    <td class="num">${fmtQtyFa(c.active_detail_count)}</td>
    <td class="num">${fmtQtyFa(c.lines_on_control)}${c.needs_attention?' <span class="tag t-cancel">توجه</span>':''}</td>
    <td class="mono muted">${esc((c.keys||[]).join(', '))}</td>
  </tr>`).join('')||'<tr><td colspan="5" class="empty">حساب کنترلی نیست</td></tr>';
  const balCtl=(rep.nonleaf_balances_split&&rep.nonleaf_balances_split.control)||[];
  const balNon=(rep.nonleaf_balances_split&&rep.nonleaf_balances_split.non_control)||(rep.nonleaf_balances||[]);
  const balRowFn=(rows,empty)=>rows.map(b=>`<tr><td class="mono">${esc(b.code)}</td><td>${esc(b.name||'')}</td><td class="num">${fmtQtyFa(b.line_count)}</td><td class="num">${fmt(b.balance_rial)}</td></tr>`).join('')||`<tr><td colspan="4" class="empty">${empty}</td></tr>`;
  const flagCtl=isAdmin()?`<div class="fg"><label>حالت اجرای قانون حساب برگ ${hlp('warn: سند ثبت می‌شود و فقط هشدار/لاگ می‌ماند. enforce: فروش انبار بی‌نگاشت و سطر غیربرگ رد می‌شود (422). فقط بعد از تکمیل همهٔ نگاشت‌ها enforce کنید.')}</label>
      <select id="leaf-flag"><option value="warn" ${rep.flag.value!=='enforce'?'selected':''}>warn — فقط هشدار</option><option value="enforce" ${rep.flag.value==='enforce'?'selected':''}>enforce — اجباری</option></select></div>`:`<div class="muted">حالت: ${esc(rep.flag.value)}</div>`;
  openModal(`
    <div class="modal-head"><h3>📋 گزارش نگاشت حساب برگ</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body coa-leaf-report">
      <p class="coa-leaf-report-intro muted">گزارش فقط‌خواندنی است؛ هیچ نگاشتی خودکار پر نمی‌شود. کلیدهای کنترلی در شمارش «غیربرگ» نیستند. نگاشت هر انبار را از «✏️ ویرایش انبار» تکمیل کنید.</p>
      <div class="coa-leaf-kpis muted">کلیدها: ${fmtQtyFa(sum.settings_keys_total||0)} · غیربرگ: ${fmtQtyFa(sum.settings_nonleaf||0)} · یافت‌نشده: ${fmtQtyFa(sum.settings_not_found||0)} · کنترلی: ${fmtQtyFa(sum.settings_control||0)} · انبار دائمی بی‌نگاشت: ${fmtQtyFa(sum.warehouses_perpetual_unmapped||0)}</div>
      ${flagCtl}
      <h4>انبارهای دائمی فعال بی‌نگاشت</h4>
      <div class="tbl-wrap"><table class="tbl coa-leaf-tbl"><thead><tr><th>انبار</th><th>روش</th><th>موجودی</th><th>وضعیت</th><th>بهای تمام‌شده</th><th>وضعیت</th></tr></thead><tbody>${whRows}</tbody></table></div>
      <h4>انبارهای غیرفعال بی‌نگاشت (دائمی)</h4>
      <div class="tbl-wrap"><table class="tbl coa-leaf-tbl"><thead><tr><th>انبار</th><th>موجودی</th><th>بهای تمام‌شده</th></tr></thead><tbody>${whInactiveRows}</tbody></table></div>
      <h4>کلیدهای غیربرگ (نیازمند توجه)</h4>
      <div class="tbl-wrap"><table class="tbl coa-leaf-tbl"><thead><tr><th>کلید</th><th>کد</th><th>نام</th><th>علت</th><th>منبع</th></tr></thead><tbody>${mkSetRows(rep.settings_nonleaf,'همه برگ‌اند')}</tbody></table></div>
      <h4>کلیدهای کنترلی (سطر باید روی تفصیلی برود)</h4>
      <div class="tbl-wrap"><table class="tbl coa-leaf-tbl"><thead><tr><th>کلید</th><th>کد</th><th>نام</th><th>علت</th><th>منبع</th></tr></thead><tbody>${mkSetRows(rep.settings_control,'کلید کنترلی غیربرگ نیست')}</tbody></table></div>
      <h4>کلیدهای یافت‌نشده</h4>
      <div class="tbl-wrap"><table class="tbl coa-leaf-tbl"><thead><tr><th>کلید</th><th>کد</th><th>نام</th><th>علت</th><th>منبع</th></tr></thead><tbody>${mkSetRows(rep.settings_not_found,'همه یافت شدند')}</tbody></table></div>
      <h4>حساب‌های کنترلی — سطر روی خود حساب</h4>
      <div class="tbl-wrap"><table class="tbl coa-leaf-tbl"><thead><tr><th>کد</th><th>نام</th><th>تفصیلی فعال</th><th>سطر روی کنترل</th><th>کلیدها</th></tr></thead><tbody>${ctrlRows}</tbody></table></div>
      <h4>مانده غیربرگ — کنترلی</h4>
      <div class="tbl-wrap"><table class="tbl coa-leaf-tbl"><thead><tr><th>کد</th><th>نام</th><th>تعداد سطر</th><th>مانده (ریال)</th></tr></thead><tbody>${balRowFn(balCtl,'مانده کنترلی نیست')}</tbody></table></div>
      <h4>مانده غیربرگ — غیرکنترلی</h4>
      <div class="tbl-wrap"><table class="tbl coa-leaf-tbl"><thead><tr><th>کد</th><th>نام</th><th>تعداد سطر</th><th>مانده (ریال)</th></tr></thead><tbody>${balRowFn(balNon,'مانده غیرکنترلی نیست')}</tbody></table></div>
    </div>
    <div class="modal-foot">${isAdmin()?`<button class="btn" data-csp-click="${CSP.bind('click',function(event){saveLeafFlag()})}">💾 ذخیرهٔ حالت</button>`:''}
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">بستن</button></div>`);
}
async function saveLeafFlag(){
  const v=el('leaf-flag')?.value||'warn';
  if(v==='enforce'&&!confirm('با enforce، فروش از انبار بی‌نگاشت و ثبت سند روی حساب غیربرگ رد می‌شود. ادامه می‌دهید؟')) return;
  try{
    await api('PUT','/settings',{ledger_leaf_enforcement:v});
    CACHE.coaLeafReport=null;
    closeModal(); showToast('حالت حساب برگ: '+v); loadAccTab('warehouses');
  }catch(e){}
}
function warehousePeriodCloseModal(id,name){
  const ym=todayJalali().slice(0,7);
  openModal(`<div class="modal-head"><h3>بستن دوره ادواری — ${esc(name||'')}</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
  <div class="modal-body"><div class="form-grid">
    <div class="fg"><label>برچسب دوره</label><input id="wpc-label" value="${esc(ym)}"></div>
    <div class="fg"><label>از تاریخ</label><input id="wpc-from" value="${esc(ym+'/01')}"></div>
    <div class="fg"><label>تا تاریخ</label><input id="wpc-to" value="${esc(todayJalali())}"></div>
    <div class="fg"><label>موجودی اول دوره (ریال)</label><input id="wpc-begin" class="money" inputmode="numeric" value="${moneyInit(0)}"></div>
    <div class="fg"><label>خریدهای دوره (ریال)</label><input id="wpc-purch" class="money" inputmode="numeric" value="${moneyInit(0)}"></div>
    <div class="fg full"><label>شمارش پایان دوره (هر خط: product_id | qty | unit_cost_rial)</label>
      <textarea id="wpc-counts" rows="6" dir="ltr" placeholder="12 | 10 | 500000"></textarea></div>
    <div class="fg full"><label>یادداشت</label><input id="wpc-note"></div>
  </div>
  <div class="muted" data-csp-style="${CSP.style(`margin-top:8px;line-height:1.8`)}">COGS = اول‌دوره + خرید − پایان‌دوره. سند تعدیل ثبت می‌شود و موجودی عملیاتی از شمارش به‌روز می‌گردد.</div></div>
  <div class="modal-foot"><button class="btn" data-csp-click="${CSP.bind('click',function(event){saveWarehousePeriodClose((id))})}">💾 بستن دوره</button>
    <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
  el('modalRoot')?.querySelectorAll('input').forEach(ensureMoneyField);
}
async function saveWarehousePeriodClose(id){
  const counts=(el('wpc-counts').value||'').split(/\n+/).map(line=>{
    const p=line.split('|').map(s=>s.trim()).filter(Boolean);
    if(p.length<2) return null;
    return {product_id:+p[0], qty:+p[1]||0, unit_cost_rial:+p[2]||0};
  }).filter(Boolean);
  try{
    await api('POST','/warehouses/'+id+'/period-close',{
      period_label:el('wpc-label').value.trim(),
      start_date:el('wpc-from').value.trim(),
      end_date:el('wpc-to').value.trim(),
      beginning_inventory_rial:moneyVal('wpc-begin'),
      purchases_rial:moneyVal('wpc-purch'),
      counts, note:el('wpc-note').value.trim()
    });
    closeModal(); showToast('دوره ادواری بسته شد'); loadAccTab('warehouses');
  }catch(e){}
}
async function warehousePeriodClosesModal(whId,name){
  let rows=[];
  try{ rows=await api('GET','/warehouses/'+whId+'/period-closes')||[]; }catch(e){ showToast(e.message||'خطا','error'); return; }
  if(!Array.isArray(rows)) rows=[];
  openModal(`<div class="modal-head"><h3>دوره‌های ادواری — ${esc(name||'')}</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
  <div class="modal-body">
    <div class="muted" data-csp-style="${CSP.style(`margin-bottom:10px;line-height:1.8;font-size:12px`)}">بازگشایی = ابطال سند تعدیل دوره و بازگرداندن موجودی به مقدار قبل از شمارش (R13). علت الزامی است.</div>
    <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
      <th>دوره</th><th>بازه</th><th>COGS</th><th>وضعیت</th><th>عملیات</th>
    </tr></thead><tbody>
    ${rows.map(r=>`<tr>
      <td class="mono">${esc(r.period_label||'-')}</td>
      <td class="mono">${esc((r.start_date||'')+' → '+(r.end_date||''))}</td>
      <td class="num">${fmt(r.cogs_rial||0)}</td>
      <td>${r.status==='reopened'?'<span class="tag t-cancel">بازگشایی‌شده</span>':(r.status==='closed'?'<span class="tag t-done">بسته</span>':esc(r.status||'-'))}</td>
      <td>${r.status==='closed'?`<button class="btn sm orange" data-csp-click="${CSP.bind('click',function(event){warehousePeriodReopen((whId),(r.id))})}">↩ بازگشایی</button>`:'—'}</td>
    </tr>`).join('')||'<tr><td colspan="5" class="empty">دوره‌ای ثبت نشده</td></tr>'}
    </tbody></table></div>
  </div>
  <div class="modal-foot"><button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">بستن</button></div>`);
}
async function warehousePeriodReopen(whId,closeId){
  const reason=prompt('علت بازگشایی دوره (الزامی):');
  if(reason==null) return;
  if(!String(reason).trim()){ showToast('علت بازگشایی الزامی است','error'); return; }
  try{
    await api('POST','/warehouses/'+whId+'/period-closes/'+closeId+'/reopen',{reason:String(reason).trim()});
    showToast('دوره بازگشایی شد');
    warehousePeriodClosesModal(whId,'');
    loadAccTab('warehouses');
  }catch(e){}
}
