function financialReportConfigModal(){
  openModal(`<div class="modal-head"><h3>${lucide('chart')} تعریف صورت مالی پویا</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
  <div class="modal-body"><div class="fg"><label>نام گزارش *</label><input id="fr-name" placeholder="مثلاً ترازنامه مدیریتی"></div>
  <div class="fg" data-csp-style="${CSP.style(`margin-top:10px`)}"><label>هر ردیف: عنوان | sum/subtract/subtotal | پیشوند حساب‌ها با کاما</label>
    <textarea id="fr-lines" rows="9" dir="rtl" placeholder="دارایی‌های جاری | sum | 11&#10;بدهی‌های جاری | subtract | 21&#10;خالص | subtotal |"></textarea></div>
  <div class="muted" data-csp-style="${CSP.style(`margin-top:8px`)}">فرمول آزاد اجرا نمی‌شود؛ فقط عملگرهای امن و پیشوندهای معتبر حساب پذیرفته می‌شوند.</div></div>
  <div class="modal-foot"><button class="btn" data-csp-click="${CSP.bind('click',function(event){saveFinancialReportConfig()})}">${lucide('save')} ذخیره</button><button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
}
async function saveFinancialReportConfig(){
  const name=el('fr-name').value.trim();
  const rows=el('fr-lines').value.split(/\r?\n/).filter(Boolean).map(line=>{const [row_label,operation,prefixes]=line.split('|').map(x=>(x||'').trim());return {row_label,operation:operation||'sum',account_prefixes:prefixes?prefixes.split(',').map(x=>x.trim()).filter(Boolean):[],show_subtotal:operation==='subtotal'};});
  try{await api('PUT','/adv-reports/report-configurations/'+encodeURIComponent(name),{rows});closeModal();showToast('پیکربندی گزارش ذخیره شد');loadAdvReport();}catch(e){}
}
