function prodBomCostPanelHtml(id, bom){
  window._prodBomCostId=id;
  const fgs=prodBomFgProducts(bom||{});
  const multi=fgs.length>1;
  const period=todayJalali().slice(0,7);
  const qtyFields=multi
    ? fgs.map(p=>`<div class="fg"><label>تعداد ${esc(p.name||('#'+p.id))}</label><input class="pbe-cost-qty-p" data-pid="${p.id}" type="number" min="0" step="any" value="1" data-csp-input="${CSP.bind('input',function(){prodBomScheduleCost((id))})}"></div>`).join('')
    : `<div class="fg"><label>مقدار هدف</label><input id="pbe-cost-qty" type="number" min="1" step="any" value="300" data-csp-input="${CSP.bind('input',function(){prodBomScheduleCost((id))})}"></div>`;
  return `
    <p class="muted" data-csp-style="${CSP.style(`font-size:12px;line-height:1.7;margin-bottom:8px`)}">${multi
      ? 'برای هر محصول تعداد جدا وارد کنید. قلم و دوخت اختصاصی در همان تعداد ضرب می‌شود؛ قلم و عملیات مشترک در جمع تعدادها. بها با تغییر تعداد یا دوره همان‌جا تازه می‌شود و سند حسابداری نمی‌سازد.'
      : 'برآورد استاندارد برای این مقدار و دوره. سند حسابداری نمی‌سازد. بهای واقعی از حواله، لایه‌چینی، دستمزد ۵۲۰۱ و نرخ مرکز همان دوره می‌آید. اگر نرخ مرکز خالی باشد هشدار پایین می‌آید.'}</p>
    <div class="form-grid">
      ${qtyFields}
      <div class="fg"><label>دوره (سال/ماه)</label><input id="pbe-cost-period" value="${esc(period)}" placeholder="1405/05" data-csp-input="${CSP.bind('input',function(){prodBomScheduleCost((id))})}"></div>
    </div>
    <button class="btn" type="button" data-csp-style="${CSP.style(`margin-top:8px`)}" data-csp-click="${CSP.bind('click',function(event){prodBomComputeFullCost((id))})}">محاسبه بها</button>
    <div id="pbe-cost-result" data-csp-style="${CSP.style(`margin-top:12px`)}"></div>`;
}
function prodBomScheduleCost(id){
  clearTimeout(window._pbeCostTimer);
  window._pbeCostTimer=setTimeout(function(){ prodBomComputeFullCost(id); }, 400);
}
async function prodBomComputeFullCost(id){
  const per=[...document.querySelectorAll('.pbe-cost-qty-p')];
  const qtyMap={};
  per.forEach(n=>{ const pid=n.getAttribute('data-pid'); if(pid) qtyMap[pid]=n.value===''?0:(+n.value||0); });
  const qtySum=per.length?Object.values(qtyMap).reduce((s,n)=>s+(+n||0),0):(+el('pbe-cost-qty')?.value||300);
  const qty=per.length?qtySum:(+el('pbe-cost-qty')?.value||300);
  const period=(el('pbe-cost-period')?.value||'').trim();
  const box=el('pbe-cost-result');
  if(box) box.innerHTML=`<div class="muted">در حال محاسبه…</div>`;
  try{
    let path='/production/boms/'+id+'/full-cost?qty='+encodeURIComponent(qty);
    if(per.length) path+='&output_qtys='+encodeURIComponent(JSON.stringify(qtyMap));
    if(period) path+='&period='+encodeURIComponent(period);
    const r=await api('GET',path)||{};
    const unit=r.breakdown?.unit_cost_rial ?? r.unit_cost_rial;
    const stages=r.stages||[];
    if(!box) return;
    const warns=r.warnings||[];
    const outs=r.outputs||[];
    const mains=outs.filter(o=>o.type==='main'||o.type==='co');
    const headBits=mains.length>1
      ? mains.map(o=>`<b>${esc(o.name||('#'+o.product_id))}</b> ${fmt(o.unit_cost_rial||0)} ریال <span class="muted">(تعداد ${toFa(o.qty||0)})</span>`).join(' · ')
      : `<b>بهای واحد:</b> <span class="mono">${fmt(unit||0)}</span> ریال`;
    box.innerHTML=`
      <div data-csp-style="${CSP.style(`margin-bottom:10px;padding:8px 12px;border-radius:8px;background:var(--well);border:1px solid var(--border);font-size:13px;line-height:1.8`)}">
        ${headBits}
        ${r.qty_start!=null?` · شروع: ${toFa(r.qty_start)}`:''}
        ${r.total_yield_percent!=null?` · بازده کل: ${r.total_yield_percent}%`:''}
        ${r.breakdown?.net_rial!=null?` · خالص: ${fmt(r.breakdown.net_rial)} ریال`:''}
        ${r.breakdown?.overhead_rial!=null?` · سربار کل: ${fmt(r.breakdown.overhead_rial)} ریال`:''}
      </div>
      ${warns.length?`<div data-csp-style="${CSP.style(`margin-bottom:10px;padding:8px 12px;border-radius:8px;background:#fff8e6;border:1px solid #e6c35c;font-size:12px;line-height:1.8`)}"><b>هشدار سربار/نرخ:</b><ul data-csp-style="${CSP.style(`margin:4px 0 0 18px`)}">${warns.map(w=>`<li>${esc(typeof w==='string'?w:(w.detail||w.code||JSON.stringify(w)))}</li>`).join('')}</ul>
        <button class="btn sm ghost" type="button" data-csp-click="${CSP.bind('click',function(){go('acc-production-rates')})}">رفتن به نرخ سربار مراکز</button></div>`:''}
      <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
        <th>مرحله</th><th>مرکز</th><th>ورود</th><th>خروج</th><th>مواد</th><th>دستمزد</th><th>سربار</th><th>محرک</th><th>نرخ</th><th>بهای خروجی</th><th>واحد</th>
      </tr></thead><tbody>
        ${stages.map(s=>`<tr>
          <td class="num">${s.seq??''}</td>
          <td>${esc(s.cost_center||String(s.cost_center_id||''))}</td>
          <td class="num">${s.qty_in??''}</td>
          <td class="num">${s.qty_out??''}</td>
          <td class="num">${fmt(s.material_rial||0)}</td>
          <td class="num">${fmt(s.labor_rial||0)}</td>
          <td class="num" data-csp-style="${CSP.style(!(s.overhead_rial>0)&&((s.material_rial>0)||(s.labor_rial>0))?'color:var(--red)':'')}">${fmt(s.overhead_rial||0)}</td>
          <td class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">${esc(s.overhead_driver||'—')} × ${s.overhead_driver_qty??'—'}</td>
          <td class="num">${fmt(s.overhead_rate_rial||0)}</td>
          <td class="num">${fmt(s.cost_out_rial||0)}</td>
          <td class="num">${fmt(s.unit_cost_out_rial||0)}</td>
        </tr>`).join('')||`<tr><td colspan="11" class="muted" data-csp-style="${CSP.style(`text-align:center`)}">مرحله‌ای برای نمایش نیست (فرمول بدون مسیر)</td></tr>`}
      </tbody></table></div>
      ${outs.length?`<h5 data-csp-style="${CSP.style(`margin:14px 0 6px`)}">تسهیم بها بین محصولات</h5>
      <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin:0 0 6px`)}">${per.length?'اختصاصی = مواد و دوخت همان محصول × تعداد خودش. مشترک = جمع تعدادها، بعد تقسیم به نسبت همین تعدادها.':'اختصاصی = مواد/عملیات exclusive؛ مشترک = سهم٪ خروجی از باقیمانده WIP.'}</p>
      <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
        <th>نوع</th><th>محصول</th><th>مقدار</th><th>سهم٪</th><th>اختصاصی</th><th>مشترک</th><th>مبلغ</th><th>بهای واحد</th>
      </tr></thead><tbody>
        ${outs.map(o=>`<tr>
          <td>${esc(o.type||'')}</td><td>${esc(o.name||('#'+o.product_id))}</td>
          <td class="num">${o.qty??''}</td><td class="num">${o.share_percent??''}</td>
          <td class="num">${fmt(o.exclusive_rial||0)}</td><td class="num">${fmt(o.shared_rial!=null?o.shared_rial:(o.amount_rial||0))}</td>
          <td class="num">${fmt(o.amount_rial||0)}</td><td class="num">${fmt(o.unit_cost_rial||0)}</td>
        </tr>`).join('')}
      </tbody></table></div>`:''}`;
  }catch(e){
    const msg=e.message||e.error||e.code||'خطا در محاسبه';
    const labor=/نرخ دستمزد|E_LABOR_RATE_ZERO|LABOR_RATE/.test(String(msg)+String(e.code||''));
    if(box) box.innerHTML=`<div data-csp-style="${CSP.style(`color:var(--red);line-height:1.8`)}">${esc(msg)}${labor?' — در تب مسیر عملیات، روش و نرخ دستمزد را وارد کنید.':''}</div>
      ${labor?`<button class="btn sm" type="button" data-csp-style="${CSP.style(`margin-top:8px`)}" data-csp-click="${CSP.bind('click',function(){prodBomEditModal((id),'ops')})}">رفتن به مسیر عملیات</button>
      <button class="btn sm ghost" type="button" data-csp-click="${CSP.bind('click',function(){go('acc-production-rates')})}">نرخ ماهانه مراکز</button>`:''}`;
    showToast(msg,'error');
  }
}
function prodBomLineRowHtml(L, locked, excludeProductId, multi){
  L=L||{};
  const type=L.line_type||'material';
  const exclude=excludeProductId!=null?excludeProductId:(window._prodBomEditProductId||0);
  const isMulti=multi!=null?!!multi:!!(window._prodBomFgProducts&&window._prodBomFgProducts.length>1);
  let matrixObj=null;
  try{ matrixObj=L.size_matrix?(typeof L.size_matrix==='string'?JSON.parse(L.size_matrix):L.size_matrix):null; }catch(_){ matrixObj=null; }
  const hasMatrix=matrixObj&&typeof matrixObj==='object'&&Object.keys(matrixObj).length>0;
  const matrixBadge=hasMatrix?'📐':'—';
  const colorMode=L.component_color_mode||'none';
  const cid='pbe-comp-'+(L.id||('n'+Math.random().toString(36).slice(2,8)));
  const comps=(CACHE.allProducts||[]).filter(p=>Number(p.id)!==Number(exclude) && (isBomComponentEligible(p) || Number(p.id)===Number(L.component_product_id)));
  const matrixJson=hasMatrix?esc(JSON.stringify(matrixObj)):'';
  const colorModeLabel={none:'بدون (پیش‌فرض)',inherit_fg:'همرنگ محصول/سفارش',fixed:'رنگ ثابت کاتالوگ'};
  const scope=L.product_scope||'shared';
  const scopeLabel=scope==='exclusive'
    ? ('اختصاصی: '+(L.scoped_product_name||('#'+(L.scoped_product_id||''))))
    : 'مشترک';
  if(locked){
    const colorName=((window._prodBomColors||[]).find(c=>Number(c.id)===Number(L.component_color_id))||{}).name;
    return `<tr>
      <td>${type==='packaging'?'بسته‌بندی':'مواد'}</td>
      <td>${esc(L.product_name||('#'+L.component_product_id))}</td>
      ${isMulti?`<td>${esc(scopeLabel)}</td>`:''}
      <td class="num">${L.qty_per_base??0}</td>
      <td class="num">${L.scrap_percent??0}</td>
      <td>${matrixBadge}</td>
      <td>${esc(colorModeLabel[colorMode]||colorMode)}${colorMode==='fixed'&&colorName?(' · '+esc(colorName)):''}</td>
      <td></td>
    </tr>`;
  }
  return `<tr class="pbe-line" data-line-id="${L.id||''}">
    <td><select class="pbe-type"><option value="material" ${type==='material'?'selected':''}>مواد</option><option value="packaging" ${type==='packaging'?'selected':''}>بسته‌بندی</option></select></td>
    <td>${productSelect(cid, L.component_product_id, comps, {inputClass:'pbe-comp'})}</td>
    ${isMulti?`<td>${prodBomScopeOptsHtml(scope, L.scoped_product_id, window._prodBomFgProducts||[])}</td>`:''}
    <td><input class="pbe-qty" type="number" step="any" min="0" value="${L.qty_per_base??1}" data-csp-style="${CSP.style(`width:90px`)}"></td>
    <td><input class="pbe-scrap" type="number" min="0" max="99.9" step="0.1" value="${L.scrap_percent??0}" data-csp-style="${CSP.style(`width:70px`)}"></td>
    <td>
      <input type="hidden" class="pbe-size-matrix" value="${matrixJson}">
      <button type="button" class="btn sm ghost" title="ماتریس سایز — مصرف هر سایز" data-csp-click="${CSP.bind('click',function(event){prodBomOpenSizeMatrix(event.target.closest('tr'))})}">${hasMatrix?'📐 ویرایش':'📐'}</button>
    </td>
    <td>
      <select class="pbe-color-mode" title="چگونه رنگ جزء از روی رنگ سفارش/محصول حل شود" data-csp-style="${CSP.style(`width:140px`)}">
        <option value="none" ${colorMode==='none'?'selected':''}>بدون</option>
        <option value="inherit_fg" ${colorMode==='inherit_fg'?'selected':''}>از رنگ سفارش</option>
        <option value="fixed" ${colorMode==='fixed'?'selected':''}>ثابت</option>
      </select>
      <div class="pbe-color-pick-wrap" ${colorMode==='fixed'?'':'hidden'} data-csp-style="${CSP.style(`margin-top:4px`)}">
        <select class="pbe-color-id" title="رنگ کاتالوگ جزء (از فهرست رنگ‌ها)" data-csp-style="${CSP.style(`width:140px`)}">${prodBomColorOptionsHtml(L.component_color_id)}</select>
      </div>
    </td>
    <td>${L.id?`<button class="btn sm red" type="button" data-csp-click="${CSP.bind('click',function(event){prodBomDeleteLine((L.bom_id||0),(L.id))})}">×</button>`:`<button class="btn sm red" type="button" data-csp-click="${CSP.bind('click',function(event){this.closest('tr').remove()})}">×</button>`}</td>
  </tr>`;
}
async function prodBomFillColorSelect(selectedId, productId){
  const sel=el('pbe-color-id'); if(!sel) return;
  let list=[];
  try{
    const rows=await api('GET','/product-variants/colors')||[];
    list=Array.isArray(rows)?rows:(rows.rows||[]);
  }catch(_){ list=[]; }
  window._prodBomColors=list;
  // Prefer colors already on the FG style matrix when available
  let styleColorIds=null;
  if(productId){
    try{
      const style=await api('GET','/product-variants/style/'+productId);
      const ids=new Set((style&&style.variants||[]).map(v=>Number(v.color_id)).filter(Boolean));
      if(ids.size) styleColorIds=ids;
    }catch(_){ styleColorIds=null; }
  }
  const opts=styleColorIds?list.filter(c=>styleColorIds.has(Number(c.id))):list;
  const use=opts.length?opts:list;
  sel.innerHTML='<option value="">— همه رنگ‌ها (سطح مدل) —</option>'+use.map(c=>`<option value="${c.id}" ${Number(c.id)===Number(selectedId)?'selected':''}>${esc(c.name||'')}</option>`).join('');
  // Refresh line color dropdowns with same catalog
  document.querySelectorAll('tr.pbe-line select.pbe-color-id').forEach(s=>{
    const cur=s.value;
    s.innerHTML=prodBomColorOptionsHtml(cur);
  });
}
async function prodBomOpenSizeMatrix(tr){
  if(!tr) return;
  const pid=window._prodBomEditProductId;
  let sizes=[];
  try{
    const names=await cuttingSizeLabelsForProduct(pid);
    sizes=(names||[]).map(n=>({name:String(n)}));
  }catch(_){ sizes=[]; }
  if(!sizes.length){
    showToast('برای این کالا سایز تعریف نشده — در کارت کالا سایزها را تیک بزنید و ماتریس بسازید','error');
    return;
  }
  let cur={};
  try{ cur=JSON.parse(tr.querySelector('.pbe-size-matrix')?.value||'{}')||{}; }catch(_){ cur={}; }
  const rowsHtml=sizes.map(s=>{
    const name=s.name||s.code||String(s.id);
    const val=cur[name]!=null?cur[name]:'';
    return `<tr><td>${esc(name)}</td><td><input class="pbe-mx-qty" data-size="${esc(name)}" type="number" step="any" min="0" value="${val}" placeholder="خالی = مقدار پایه" data-csp-style="${CSP.style(`width:120px`)}"></td></tr>`;
  }).join('');
  openNestedModal(`
    <div class="modal-head"><h3>ماتریس سایز — مصرف per قطعه</h3><button class="x" type="button" data-csp-click="${CSP.bind('click',function(){closeNestedModal()})}">×</button></div>
    <div class="modal-body">
      <p class="muted" data-csp-style="${CSP.style(`font-size:12px;line-height:1.7`)}">فقط سایزهایی که مصرف متفاوت از مقدار پایه دارند را پر کنید. خالی = همان مقدار پایه ردیف.</p>
      <div class="tbl-wrap"><table class="tbl"><thead><tr><th>سایز</th><th>مصرف</th></tr></thead><tbody>${rowsHtml}</tbody></table></div>
    </div>
    <div class="modal-foot" data-csp-style="${CSP.style(`display:flex;gap:8px;justify-content:flex-end`)}">
      <button class="btn secondary" type="button" id="pbe-mx-clear">پاک کردن</button>
      <button class="btn secondary" type="button" data-csp-click="${CSP.bind('click',function(){closeNestedModal()})}">انصراف</button>
      <button class="btn" type="button" id="pbe-mx-save">ذخیره</button>
    </div>`);
  const root=document.getElementById('nestedModalRoot');
  root?.querySelector('#pbe-mx-clear')?.addEventListener('click', ()=>{
    tr.querySelector('.pbe-size-matrix').value='';
    const btn=tr.querySelector('button.btn.sm.ghost');
    if(btn) btn.textContent='📐';
    closeNestedModal();
  });
  root?.querySelector('#pbe-mx-save')?.addEventListener('click', ()=>{
    const out={};
    root.querySelectorAll('.pbe-mx-qty').forEach(inp=>{
      const v=+inp.value;
      if(v>0) out[inp.dataset.size]=v;
    });
    const json=Object.keys(out).length?JSON.stringify(out):'';
    tr.querySelector('.pbe-size-matrix').value=json;
    const btn=tr.querySelector('button.btn.sm.ghost');
    if(btn) btn.textContent=json?'📐 ویرایش':'📐';
    closeNestedModal();
  });
}
function prodBomAddLineRow(){
  const body=el('pbe-lines'); if(!body) return;
  const multi=!!(window._prodBomFgProducts&&window._prodBomFgProducts.length>1);
  body.insertAdjacentHTML('beforeend', prodBomLineRowHtml(null, false, window._prodBomEditProductId, multi));
  initCustSearches(body);
  prodBomBindColorModeToggles(body);
}
async function prodBomSaveHeader(id){
  try{
    const bom=window._prodBomEditBom||{};
    const peers=(bom.outputs||[]).filter(o=>(o.output_type==='main'||o.output_type==='co')&&Number(o.product_id)!==Number(bom.product_id)).map(o=>Number(o.product_id));
    const payload={
      name:el('pbe-name')?.value||'',
      base_qty:+el('pbe-base')?.value||1,
      yield_percent:+el('pbe-yield')?.value||100,
      size_range:el('pbe-size-range')?.value||'',
      color_variant:el('pbe-color-variant')?.value||'',
      color_id:+el('pbe-color-id')?.value||null,
      note:el('pbe-note')?.value||''
    };
    if(peers.length){
      payload.has_coproducts=true;
      payload.co_product_ids=peers;
    }
    await api('PUT','/production/boms/'+id, payload);
    showToast('فرمول ذخیره شد');
  }catch(e){ showToast(e.message||'خطا','error'); }
}
async function prodBomSaveLines(id){
  const rows=[...document.querySelectorAll('#pbe-lines tr.pbe-line')];
  if(!rows.length){ showToast('حداقل یک قلم اضافه کنید','error'); return; }
  try{
    const lines=rows.map(tr=>{
      let size_matrix=null;
      const raw=tr.querySelector('.pbe-size-matrix')?.value||'';
      if(raw){ try{ size_matrix=JSON.parse(raw); }catch(_){ size_matrix=null; } }
      const mode=tr.querySelector('.pbe-color-mode')?.value||'none';
      const scope=tr.querySelector('.pbe-scope')?.value||'shared';
      const scoped=+tr.querySelector('.pbe-scoped-pid')?.value||null;
      return {
        component_product_id:+tr.querySelector('.pbe-comp')?.value,
        qty_per_base:+tr.querySelector('.pbe-qty')?.value||0,
        scrap_percent:+tr.querySelector('.pbe-scrap')?.value||0,
        line_type:tr.querySelector('.pbe-type')?.value||'material',
        size_matrix: size_matrix||'',
        component_color_mode: mode,
        component_color_id: mode==='fixed'?(+tr.querySelector('.pbe-color-id')?.value||null):null,
        product_scope: scope,
        scoped_product_id: scope==='exclusive'?scoped:null
      };
    }).filter(L=>L.component_product_id&&L.qty_per_base>0);
    if(!lines.length){ showToast('اقلام معتبر نیست','error'); return; }
    const bad=lines.find(L=>L.product_scope==='exclusive'&&!L.scoped_product_id);
    if(bad){ showToast('برای قلم اختصاصی، محصول هدف را انتخاب کنید','error'); return; }
    await api('POST','/production/boms/'+id+'/lines/bulk',{replace:true, lines});
    showToast(toFa(lines.length)+' قلم ذخیره شد');
    await prodBomEditModal(id);
  }catch(e){ showToast(e.message||e.error||'خطا در ذخیره اقلام','error'); }
}
async function prodBomDeleteLine(bomId, lineId){
  if(!bomId||!lineId) return;
  if(!confirm('این قلم حذف شود؟')) return;
  try{ await api('DELETE','/production/boms/'+bomId+'/lines/'+lineId); showToast('حذف شد'); await prodBomEditModal(bomId); }
  catch(e){ showToast(e.message||'خطا','error'); }
}
async function prodBomActivate(id){
  try{
    const ready=await api('GET','/production/boms/'+id+'/completeness?mode=activate');
    if(!ready.ok){
      const msgs=(ready.hard||[]).map(m=>m.message_fa||m.code).slice(0,6).join('\n• ');
      showToast('فعال‌سازی ممکن نیست — مشخصات ضروری ناقص است'+(msgs?('\n• '+msgs):''),'error');
      if(el('pbe-ready')) el('pbe-ready').innerHTML=prodCompletenessBannerHtml(ready,'آمادگی فعال‌سازی فرمول');
      return;
    }
  }catch(_){}
  const valid_from=prompt('تاریخ شروع اعتبار (جلالی):', todayJalali());
  if(!valid_from) return;
  if(!confirm('فعال‌سازی این فرمول؟ پس از فعال شدن قفل می‌شود.')) return;
  try{
    await api('POST','/production/boms/'+id+'/activate',{valid_from});
    showToast('فرمول فعال شد'); closeModal(); reloadProdAccTab('production-boms');
  }catch(e){
    const extra=(e.payload&&e.payload.missing)||(e.missing)||[];
    const tip=Array.isArray(extra)&&extra.length?('\n• '+extra.slice(0,5).map(m=>m.message_fa||m.code).join('\n• ')):'';
    showToast((e.message||e.error||'خطا در فعال‌سازی')+tip,'error');
  }
}
async function prodBomApplyRouting(id){
  try{
    await api('POST','/production/boms/'+id+'/apply-routing-template',{});
    showToast('مسیر عملیات پیش‌فرض اعمال شد');
    if(el('activeModal')) await prodBomEditModal(id,'ops');
    else reloadProdAccTab('production-boms');
  }catch(e){ showToast(e.message||'خطا','error'); }
}
async function prodBomDelete(id){
  return prodBomRemoveGate(id);
}
function prodBomDepStatusLabel(s){
  return ({draft:'پیش‌نویس',released:'آزادشده',in_progress:'در جریان',completed:'تکمیل',closed:'بسته',cancelled:'لغو'})[s]||s||'—';
}
async function prodBomFetchDeps(id){
  return await api('GET','/production/boms/'+id+'/dependencies');
}
async function prodBomEditGate(id){
  let dep;
  try{ dep=await prodBomFetchDeps(id); }
  catch(e){ showToast(e.message||e.error||'خطا در خواندن وابستگی','error'); return; }
  if(dep.actions?.edit==='inplace'){
    await prodBomEditModal(id);
    return;
  }
  if(dep.actions?.edit!=='version_up'){
    await prodBomEditModal(id);
    return;
  }
  const openN=Number(dep.open_count)||0;
  showModal('ویرایش فرمول فعال — '+esc(dep.code||''),`
    <p data-csp-style="${CSP.style(`line-height:1.8;margin:0 0 8px`)}">فرمول <b>${esc(dep.code||'')}</b> (v${dep.version||1}-${esc(dep.revision||'A')}) در وضعیت <b>فعال</b> است و برای حفظ تاریخچه <b>قفل</b> شده.</p>
    <div class="prod-bom-dep-box ${openN?'is-blocked':'is-ok'}">
      <div><b>وابستگی‌ها:</b> سفارش باز ${toFa(openN)} · سفارش بسته‌شده/سایر ${toFa(dep.closed_order_count||0)}${dep.is_default?' · فرمول پیش‌فرض کالا':''}</div>
      ${openN?`<ul class="prod-bom-dep-list">${(dep.open_orders||[]).map(o=>`<li><span class="mono">${esc(o.order_no||('#'+o.id))}</span> — ${esc(prodBomDepStatusLabel(o.status))} · ${toFa(o.qty_planned||0)} عدد · ${esc(o.date||'')}</li>`).join('')}</ul>`:''}
    </div>
    <p class="muted" data-csp-style="${CSP.style(`font-size:12px;line-height:1.7`)}">تغییر ساختاری امن: «نسخه جدید» یک پیش‌نویس کپی می‌سازد؛ پس از تکمیل و فعال‌سازی، نسخه قبلی خودکار بایگانی می‌شود. مشاهده فقط‌خواندنی هم ممکن است.</p>
    <div data-csp-style="${CSP.style(`margin-top:14px;display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap`)}">
      <button type="button" class="btn secondary" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button>
      <button type="button" class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal();prodBomEditModal((id))})}">فقط مشاهده</button>
      <button type="button" class="btn" data-csp-click="${CSP.bind('click',function(event){closeModal();prodBomVersionUp((id))})}">نسخه جدید برای ویرایش</button>
    </div>`);
}
async function prodBomRemoveGate(id){
  let dep;
  try{ dep=await prodBomFetchDeps(id); }
  catch(e){ showToast(e.message||e.error||'خطا در خواندن وابستگی','error'); return; }
  const mode=dep.actions?.remove||'none';
  const openN=Number(dep.open_count)||0;
  const blocked=mode==='blocked'||openN>0;
  if(mode==='already_archived'||mode==='none'){
    showToast(mode==='already_archived'?'این فرمول از قبل بایگانی است':'حذف برای این وضعیت مجاز نیست','error');
    return;
  }
  const title=mode==='soft_delete'?'حذف پیش‌نویس فرمول':'بایگانی فرمول فعال';
  const actionLabel=mode==='soft_delete'?'حذف نرم':'بایگانی';
  const explain=mode==='soft_delete'
    ? 'پیش‌نویس به‌صورت نرم حذف می‌شود (وضعیت obsolete + deleted_at) و از فهرست خارج می‌گردد — حذف فیزیکی نیست.'
    : 'فرمول فعال بایگانی می‌شود و دیگر برای سفارش جدید پیشنهاد نمی‌شود. تاریخچه و سفارش‌های بسته‌شده حفظ می‌مانند.';
  showModal(title+' — '+esc(dep.code||''),`
    <p data-csp-style="${CSP.style(`line-height:1.8;margin:0 0 8px`)}">${esc(explain)}</p>
    <div class="prod-bom-dep-box ${blocked?'is-blocked':'is-ok'}">
      <div><b>وابستگی‌ها:</b> سفارش باز ${toFa(openN)} · سایر سفارش‌ها ${toFa(dep.closed_order_count||0)}${dep.is_default?' · فرمول پیش‌فرض کالا (پس از بایگانی/حذف پاک می‌شود)':''}</div>
      ${openN?`<ul class="prod-bom-dep-list">${(dep.open_orders||[]).map(o=>`<li><span class="mono">${esc(o.order_no||('#'+o.id))}</span> — ${esc(prodBomDepStatusLabel(o.status))} · برنامه ${toFa(o.qty_planned||0)} · ${esc(o.date||'')}</li>`).join('')}</ul>
      <p data-csp-style="${CSP.style(`margin:8px 0 0;color:#b33`)}">تا وقتی سفارش باز به این فرمول وصل است، ${actionLabel} ممکن نیست. ابتدا سفارش را ببندید/لغو کنید یا BOM سفارش را عوض کنید.</p>`
        :`<p class="muted" data-csp-style="${CSP.style(`margin:6px 0 0`)}">مانعی از سفارش باز نیست.</p>`}
    </div>
    ${!blocked&&mode==='archive'?`<div class="fg" data-csp-style="${CSP.style(`margin-top:8px`)}"><label>دلیل بایگانی (اختیاری)</label><input id="pb-arch-reason" placeholder="مثلاً جایگزین با نسخه جدید"></div>`:''}
    <div data-csp-style="${CSP.style(`margin-top:14px;display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap`)}">
      <button type="button" class="btn secondary" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button>
      <button type="button" class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal();prodBomEditModal((id))})}">مشاهده فرمول</button>
      ${blocked?'':`<button type="button" class="btn red" data-csp-click="${CSP.bind('click',function(event){prodBomRemoveConfirm((id),(mode))})}">${actionLabel}</button>`}
    </div>`);
}
async function prodBomRemoveConfirm(id, mode){
  try{
    if(mode==='soft_delete'){
      await api('DELETE','/production/boms/'+id);
      showToast('پیش‌نویس حذف شد');
    }else{
      const reason=el('pb-arch-reason')?.value||'بایگانی از فهرست BOM';
      await api('POST','/production/boms/'+id+'/archive',{reason});
      showToast('فرمول بایگانی شد');
    }
    closeModal();
    reloadProdAccTab('production-boms');
  }catch(e){ showToast(e.message||e.error||'خطا','error'); }
}
async function prodBomDeactivateGate(id){
  let dep;
  try{ dep=await prodBomFetchDeps(id); }
  catch(e){ showToast(e.message||e.error||'خطا','error'); return; }
  const openN=Number(dep.open_count)||0;
  if(openN>0){
    showModal('غیرفعال‌سازی ممکن نیست — '+esc(dep.code||''),`
      <div class="prod-bom-dep-box is-blocked">
        <div>این فرمول در ${toFa(openN)} سفارش باز استفاده شده.</div>
        <ul class="prod-bom-dep-list">${(dep.open_orders||[]).map(o=>`<li><span class="mono">${esc(o.order_no||('#'+o.id))}</span> — ${esc(prodBomDepStatusLabel(o.status))}</li>`).join('')}</ul>
      </div>
      <div data-csp-style="${CSP.style(`margin-top:14px;text-align:left`)}"><button type="button" class="btn secondary" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">بستن</button></div>`);
    return;
  }
  if(!confirm('فرمول فعال به پیش‌نویس برگردد؟ (فقط وقتی سفارش باز ندارد)')) return;
  try{
    await api('POST','/production/boms/'+id+'/deactivate',{});
    showToast('فرمول غیرفعال شد (پیش‌نویس)');
    reloadProdAccTab('production-boms');
  }catch(e){ showToast(e.message||e.error||'خطا','error'); }
}
async function prodBomVersionUp(id){
  if(!confirm('نسخه جدید پیش‌نویس از این فرمول ساخته شود؟')) return;
  try{
    const r=await api('POST','/production/boms/'+id+'/version-up',{reason:'ویرایش از UI'});
    showToast('نسخه جدید ساخته شد'); closeModal();
    await prodBomEditModal(r.id||r.new_id||r.bom_id);
  }catch(e){ showToast(e.message||'خطا','error'); }
}

function prodFmtToman(rial){
  if(rial==null||rial==='') return '—';
  return fmt(Number(rial)||0);
}

window._prodChartJsPromise=null;
window._prodCharts=window._prodCharts||{};
function destroyProdCharts(){
  Object.values(window._prodCharts||{}).forEach(c=>{ try{ c.destroy(); }catch(e){} });
  window._prodCharts={};
}
function loadProdChartJs(){
  if(window.Chart) return Promise.resolve(window.Chart);
  if(window._prodChartJsPromise) return window._prodChartJsPromise;
  window._prodChartJsPromise=new Promise((resolve,reject)=>{
    const s=document.createElement('script');
    s.src=CSP.scriptUrl('/vendor/chart.umd.js');
    s.onload=()=>resolve(window.Chart);
    s.onerror=()=>reject(new Error('Chart.js load failed'));
    document.head.appendChild(s);
  });
  return window._prodChartJsPromise;
}
function prodChartColors(){
  const cs=getComputedStyle(document.documentElement);
  return {
    primary:(cs.getPropertyValue('--purple')||'#1A5C38').trim(),
    secondary:(cs.getPropertyValue('--purple2')||'#2E7D4F').trim(),
    gold:(cs.getPropertyValue('--gold')||'#C9A843').trim(),
    blue:(cs.getPropertyValue('--blue')||'#2563EB').trim(),
    orange:(cs.getPropertyValue('--orange')||'#D97706').trim(),
  };
}
async function prodDashRenderCharts(dash){
  if(!dash?.data) return;
  try{
    await loadProdChartJs();
    const c=prodChartColors();
    const palette=[c.primary,c.secondary,c.gold,c.blue,c.orange,c.primary+'99'];
    const trendSeries=dash.data.trends?.unit_cost?.data?.series||[];
    const trendCtx=el('pd-chart-unit-cost');
    if(trendCtx&&trendSeries.length){
      window._prodCharts.unitCost=new Chart(trendCtx,{
        type:'line',
        data:{
          labels:trendSeries.map(p=>p.period_label),
          datasets:[{
            label:'بهای واحد (ریال)',
            data:trendSeries.map(p=>Number(p.unit_cost_rial)||0),
            borderColor:c.primary,
            backgroundColor:c.primary+'22',
            fill:true,
            tension:0.25,
            pointRadius:3
          }]
        },
        options:{
          responsive:true,
          maintainAspectRatio:false,
          plugins:{legend:{display:false}},
          scales:{y:{ticks:{callback:v=>fmt(v)}}}
        }
      });
    }
    const mix=dash.data.cost_mix||{};
    const mixDefs=[
      ['material_rial','مواد'],['labor_rial','دستمزد'],['overhead_rial','سربار'],
      ['packaging_rial','بسته‌بندی'],['subcontract_rial','پیمانکاری']
    ];
    const mixLabels=[], mixData=[], mixColors=[];
    mixDefs.forEach(([k,label],i)=>{
      const v=Number(mix[k]||0);
      if(v>0){ mixLabels.push(label); mixData.push(v); mixColors.push(palette[i%palette.length]); }
    });
    const mixCtx=el('pd-chart-cost-mix');
    if(mixCtx&&mixData.length){
      window._prodCharts.costMix=new Chart(mixCtx,{
        type:'doughnut',
        data:{labels:mixLabels,datasets:[{data:mixData,backgroundColor:mixColors,borderWidth:0}]},
        options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{boxWidth:12,font:{size:11}}}}}
      });
    }
  }catch(e){ console.warn('prod charts',e); }
}

/** دروازهٔ ترتیبی مسیر ۶مرحله‌ای — ProdJourneyGate (prod-journey-gate.js) */
function prodJourneyGateApi(){
  return (typeof ProdJourneyGate!=='undefined' && ProdJourneyGate) ? ProdJourneyGate : null;
}
function prodJourneyRemember(state){
  window._prodJourneyState=state||null;
  return state;
}
function prodJourneyCanEnterSilent(target){
  const G=prodJourneyGateApi();
  const state=window._prodJourneyState;
  if(!G || !state || !Array.isArray(state.steps)) return true;
  const idx=typeof target==='number' ? target : G.stepIndexForTarget(target);
  if(idx<0) return true;
  return !!G.canEnter(state.steps, idx).ok;
}
function prodJourneyTryEnter(target){
  const G=prodJourneyGateApi();
  const state=window._prodJourneyState;
  if(!G || !state || !Array.isArray(state.steps)) return true;
  const idx=typeof target==='number' ? target : G.stepIndexForTarget(target);
  if(idx<0) return true;
  const gate=G.canEnter(state.steps, idx);
  if(gate.ok) return true;
  const msg=G.blockMessage(state.steps, idx);
  if(typeof showToast==='function') showToast(msg, 'error');
  else if(typeof alert==='function') alert(msg);
  return false;
}
const PROD_JOURNEY_TTL_MS=20000;
async function prodJourneyEnsureState(opts){
  // کش کوتاه ۲۰ث — جهش بین صفحات تولید؛ force بعد از mutate (BOM/سفارش/لایه)
  const force=!!(opts&&opts.force);
  const period=window._prodDashPeriod||todayJalali().slice(0,7);
  const cached=window._prodJourneyState;
  if(!force && cached && cached.period===period && (Date.now()-(cached.fetchedAt||0))<PROD_JOURNEY_TTL_MS){
    return cached;
  }
  return fetchProdJourneyState(period);
}
function prodJourneyInvalidate(){
  window._prodJourneyState=null;
}
function reloadProdAccTab(tab){
  prodJourneyInvalidate();
  return loadAccTab(tab);
}
async function prodJourneyGoRoute(route){
  try{ await prodJourneyEnsureState(); }catch(_){}
  if(!prodJourneyTryEnter(route)) return;
  go(route);
}
function prodJourneyStepClick(stepIndex){
  const state=window._prodJourneyState;
  if(!state || !state.steps || !state.steps[stepIndex]) return;
  if(!prodJourneyTryEnter(stepIndex)) return;
  const s=state.steps[stepIndex];
  if(s.goFn==='goCuttingLaysView'){
    // از کارت مسیر؛ گیت همین‌جا پاس شده — بدون گیت دوباره
    window._cuttingLaysView=(s.goArg==='pending-pack'||s.goArg==='active-pack')?s.goArg:'lays';
    try{ sessionStorage.setItem('cuttingLaysView', window._cuttingLaysView); }catch(_){}
    go('acc-cutting-lays');
    return;
  }
  if(s.go) go(s.go);
}
/** ورود از منو/سایدبار به صفحات مسیر تولید — در صورت قفل، داشبورد + پیام خطا */
async function prodJourneyRouteEnter(target, renderFn){
  try{ await prodJourneyEnsureState(); }catch(_){}
  if(target==='acc-cutting-lays'){
    let view=window._cuttingLaysView||(typeof sessionStorage!=='undefined'?sessionStorage.getItem('cuttingLaysView'):null)||'lays';
    if(view!=='pending-pack' && view!=='active-pack') view='lays';
    if(!prodJourneyCanEnterSilent(view)){
      // منو یک صفحه برای لایه‌چینی + صف PACK + PACK فعال است؛ اگر PACK قفل بود ولی لایه‌چینی باز، بدون toast به تب lays
      if((view==='pending-pack'||view==='active-pack') && prodJourneyCanEnterSilent('lays')){
        window._cuttingLaysView='lays';
        try{ sessionStorage.setItem('cuttingLaysView','lays'); }catch(_){}
        return renderFn();
      }
      prodJourneyTryEnter(view);
      return renderAccPage('production-dashboard','📊','داشبورد تولید');
    }
    return renderFn();
  }
  if(!prodJourneyTryEnter(target)){
    return renderAccPage('production-dashboard','📊','داشبورد تولید');
  }
  return renderFn();
}
async function fetchProdJourneyState(period){
  // v557: موازی — پنج GET مستقل؛ خطای یکی بقیه را بلاک نکند
  const settled=await Promise.allSettled([
    api('GET','/production/reports/dashboard?period='+encodeURIComponent(period)),
    api('GET','/production/cutting-lays'),
    api('GET','/production/orders?limit=200'),
    api('GET','/production/boms'),
    api('GET','/production/reports/kanban'),
  ]);
  const val=(i, fb)=>{
    const s=settled[i];
    return (s && s.status==='fulfilled') ? s.value : fb;
  };
  const dash=val(0, null);
  const lays=val(1, {rows:[]})||{rows:[]};
  const orders=val(2, {rows:[]})||{rows:[]};
  const boms=val(3, {rows:[]})||{rows:[]};
  const kanban=val(4, null);
  const k=dash?.data?.kpis||{};
  const orderRows=Array.isArray(orders)?orders:(orders.rows||[]);
  const openOrders=(dash?.data?.open_orders||[]).length || orderRows.filter(o=>o.status!=='closed'&&o.status!=='cancelled'&&o.status!=='completed').length;
  const releasedOrders=orderRows.filter(o=>{
    const st=String(o.status||'');
    return st && !['draft','cancelled','voided'].includes(st);
  }).length;
  const bomRows=Array.isArray(boms)?boms:(boms.rows||boms.data||[]);
  const activeBoms=bomRows.filter(b=>b.status==='active'||b.is_active).length;
  const layRows=(lays&&lays.rows)||[];
  const postedLays=layRows.filter(r=>r.status!=='reversed' && ((r.packs||[]).some(p=>p.status==='posted') || Number(r.pack_posted)===1));
  const pendingPack=layRows.filter(r=>r.status!=='reversed' && !(r.packs||[]).some(p=>p.status==='posted') && Number(r.pack_posted)!==1).length;
  // v409: پیشرفت واقعی = حداقل یک مرحله done (نه in_progress از آزادسازی)
  const allStages=kanban?.data?.all_stages||[];
  const stagesProgressed=allStages.some(s=>String(s.status||'')==='done')
    || (kanban?.data?.columns||[]).some(c=>(c.cards||[]).some(card=>String(card.status||'')==='done'));
  const hasAdvStages=allStages.length>0
    || orderRows.some(o=>['fixed_adv','variable_adv'].includes(String(o.analysis_type||'')));
  const hasUnitCost=Number(k.unit_cost?.value_rial||0)>0 || orderRows.some(o=>Number(o.unit_cost_rial||0)>0);
  const stageStrip=buildProdStageStrip(orderRows, allStages);
  const G=prodJourneyGateApi();
  const metrics={
    activeBoms,
    releasedOrders,
    hasLay:layRows.some(r=>r.status!=='reversed'),
    hasAdvStages,
    stagesProgressed,
    kanbanTouched:stagesProgressed, // سازگاری با تست/کلاینت قدیمی
    postedPacks:postedLays.length,
    pendingPack,
    hasUnitCost,
  };
  const steps=G
    ? G.buildSteps(metrics)
    : [
      {n:'۱', title:'فرمول ساخت', desc:'مواد، مسیر و نرخ دستمزد', go:'acc-production-boms', cta:'باز کردن BOM', done:activeBoms>0, path:'both', how:'فرمول فعال لازم است.', index:0},
      {n:'۲', title:'سفارش تولید', desc:'برنامه، آزادسازی، مراحل', go:'acc-production-orders', cta:'سفارش‌ها', done:releasedOrders>0, path:'order', how:'سفارش آزادشده لازم است.', index:1},
      {n:'۳', title:'لایه‌چینی', desc:'مصرف طاقه → WIP', goFn:'goCuttingLaysView', goArg:'lays', cta:'ثبت لایه‌چینی', done:layRows.some(r=>r.status!=='reversed'), path:'cut', how:'لایه‌چینی لازم است.', index:2},
      {n:'۴', title:'مراحل BOM / تابلوی خط', desc:hasAdvStages?'حواله/خروجی/سند هر مرحله':'مخصوص سفارش چندمرحله‌ای', go:'acc-production-kanban', cta:'کانبان', done:!hasAdvStages || stagesProgressed, path:'order', how:'حداقل یک مرحله done لازم است.', index:3},
      {n:'۵', title:'PACK / رسید محصول', desc:'با سفارش: بسته‌بندی WIP؛ بدون سفارش: ورود FG؛ فروش‌پذیر با finalize', goFn:'goCuttingLaysView', goArg:'pending-pack', cta:pendingPack?'PACK معلق':'بسته\u200cبندی / رسید', done:postedLays.length>0 && pendingPack===0, path:'cut', how:'PACK لازم است؛ ورود فروش‌پذیر با سفارش فقط در نهایی\u200cسازی.', index:4},
      {n:'۶', title:'بهای تمام‌شده', desc:'برگه بها و سود', go:'acc-production-cost-sheet', cta:'برگه بها', done:hasUnitCost, path:'both', how:'بهای واحد لازم است.', index:5},
    ];
  let nextIdx=G ? G.nextIndex(steps) : steps.findIndex(s=>!s.done);
  // فقط وقتی پیش‌نیازهای قبل از PACK کامل‌اند، اقدام بعدی را به PACK بکش
  if(pendingPack>0 && nextIdx>=0){
    const packIdx=4;
    const priorOk=steps.slice(0, packIdx).every(s=>s.done);
    if(priorOk && !steps[packIdx].done) nextIdx=packIdx;
  }
  return prodJourneyRemember({
    period, fetchedAt: Date.now(), ordersFresh: true,
    dash, k, openOrders, releasedOrders, activeBoms, pendingPack,
    steps, nextIdx, orderRows, layRows, metrics, stageStrip,
  });
}
/** نوار پیشرفت مراحل BOM برای سفارش‌های پیشرفته باز */
function buildProdStageStrip(orderRows, allStages){
  const adv=orderRows.filter(o=>['fixed_adv','variable_adv'].includes(String(o.analysis_type||''))
    && !['draft','cancelled','voided','closed'].includes(String(o.status||'')));
  if(!adv.length) return '';
  const byOrder={};
  for(const s of (allStages||[])){
    const oid=s.order_id||s.orderId;
    if(!oid) continue;
    if(!byOrder[oid]) byOrder[oid]=[];
    byOrder[oid].push(s);
  }
  const stFa={pending:'منتظر',in_progress:'در جریان',done:'انجام شد',skipped:'رد شده',blocked:'متوقف'};
  const cards=adv.slice(0,8).map(o=>{
    const stages=(byOrder[o.id]||[]).slice().sort((a,b)=>Number(a.seq||0)-Number(b.seq||0));
    const done=stages.filter(s=>s.status==='done').length;
    const total=stages.length;
    const chips=stages.map(s=>{
      const cls=s.status==='done'?'is-done':(s.status==='in_progress'?'is-next':(s.status==='blocked'?'is-locked':''));
      const label=(s.operation_name||s.name||('مرحله '+s.seq))+' · '+prodStageScopeHtml(s)+' · '+(stFa[s.status]||s.status||'—')+' · '+toFa(s.qty_in||0);
      return `<span class="prod-stage-chip ${cls}" title="${esc(label)}">${esc(String(s.seq||''))} ${esc(prodStageScopeHtml(s))}</span>`;
    }).join('');
    return `<div class="prod-stage-order">
      <div class="prod-stage-order-head"><b>${esc(o.order_no||('#'+o.id))}</b>
        <span class="muted">${prodFgNamesHtml(o)}</span>
        <span class="muted">${fmt(done)}/${fmt(total)} مرحله</span>
        <button type="button" class="btn sm ghost" data-csp-click="${CSP.bind('click',function(){prodJourneyGoRoute('acc-production-kanban')})}">کانبان</button>
      </div>
      <div class="prod-stage-chips">${chips||'<span class="muted">مراحل هنوز ساخته نشده — سفارش را آزاد کنید</span>'}</div>
    </div>`;
  }).join('');
  return `<div class="panel" data-csp-style="${CSP.style(`margin:12px 0`)}"><div class="panel-head"><h4>پیشرفت مراحل BOM (ترتیب حسابداری)</h4></div>
    <div class="panel-body" data-csp-style="${CSP.style(`display:flex;flex-direction:column;gap:10px`)}">
      <p class="muted" data-csp-style="${CSP.style(`margin:0;line-height:1.7;font-size:12px`)}">هر مرحله فقط بعد از حواله مواد (در صورت تعریف)، ثبت هزینه/دستمزد/سربار و خروجی با سند حسابداری «انجام شد» می‌شود؛ سپس مرحلهٔ بعد باز است. پارچهٔ طاقه‌دار از لایه‌چینی مصرف می‌شود و دوباره در حوالهٔ مرحله حواله نمی‌شود.</p>
      ${cards}
    </div></div>`;
}
function prodJourneyHtml(state){
  const { steps, nextIdx, k, openOrders, activeBoms, pendingPack, stageStrip }=state;
  const G=prodJourneyGateApi();
  const stepNav=i=>CSP.bind('click',function(){prodJourneyStepClick(i)});
  const lockedHint=i=>{
    if(!G) return '';
    const gate=G.canEnter(steps, i);
    if(gate.ok || steps[i].done) return '';
    const first=gate.blockers[0];
    return first ? ('قفل — اول: '+first.title) : 'قفل';
  };
  return `
    <div class="prod-home-hero">
      <div>
        <h3 data-csp-style="${CSP.style(`margin:0 0 6px;font-size:20px`)}">داشبورد تولید</h3>
        <p class="muted" data-csp-style="${CSP.style(`margin:0;line-height:1.8`)}">ترتیب مراحل در <b>BOM → مسیر عملیات</b> تعریف می‌شود؛ هر مرحله باید با حواله/رسید/سند حسابداری کامل شود سپس مرحله بعد. مسیر داشبورد ۱→۶ ناوبری کارگاه است و با تکمیل واقعی مراحل قفل می‌شود.</p>
      </div>
      <div class="prod-home-hero-actions">
        <button class="btn" data-csp-click="${CSP.bind('click',function(){goCuttingLaysView('lays')})}">✂️ لایه‌چینی</button>
        <button class="btn ghost" data-csp-click="${CSP.bind('click',function(){prodJourneyGoRoute('acc-production-orders')})}">سفارش جدید</button>
        <button class="btn ghost" data-csp-click="${CSP.bind('click',function(){prodJourneyGoRoute('acc-production-kanban')})}">کانبان</button>
      </div>
    </div>
    <div class="prod-kpi-grid">
      ${typeof ProdUI!=='undefined'&&ProdUI.kpiCard?ProdUI.kpiCard({label:'تولید دوره', value:fmt(k.produced?.value||0), icon:'📦'}):statCard('g','📦',fmt(k.produced?.value||0),'تولید')}
      ${typeof ProdUI!=='undefined'&&ProdUI.kpiCard?ProdUI.kpiCard({label:'سفارش باز', value:fmt(openOrders), icon:'🏭'}):statCard('b','🏭',fmt(openOrders),'سفارش باز')}
      ${typeof ProdUI!=='undefined'&&ProdUI.kpiCard?ProdUI.kpiCard({label:'منتظر رسید محصول', value:fmt(pendingPack), icon:'📦'}):statCard('o','📦',fmt(pendingPack),'منتظر رسید محصول')}
      ${typeof ProdUI!=='undefined'&&ProdUI.kpiCard?ProdUI.kpiCard({label:'فرمول فعال', value:fmt(activeBoms), icon:'📐'}):statCard('r','📐',fmt(activeBoms),'فرمول فعال')}
    </div>
    ${stageStrip||''}
    <div class="prod-dual-path">
      <div class="prod-path-card">
        <b>✂️ مسیر برش و بسته‌بندی</b>
        <span class="muted">طاقه → لایه‌چینی (= تکمیل مرحلهٔ برش در سفارش پیشرفته) → PACK → رسید فروش‌پذیر در نهایی‌سازی — پارچه دوباره در حواله مرحله مصرف نمی‌شود</span>
        <div class="prod-path-actions">
          <button type="button" class="btn sm" data-csp-click="${CSP.bind('click',function(){go('acc-fabric-rolls')})}">طاقه</button>
          <button type="button" class="btn sm" data-csp-click="${CSP.bind('click',function(){goCuttingLaysView('lays')})}">لایه‌چینی</button>
          ${pendingPack?`<button type="button" class="btn sm orange" data-csp-click="${CSP.bind('click',function(){goCuttingLaysView('pending-pack')})}">${fmt(pendingPack)} منتظر محصول</button>`:''}
        </div>
      </div>
      <div class="prod-path-card">
        <b>🏭 مسیر مراحل BOM</b>
        <span class="muted">BOM مسیر → سفارش پیشرفته → مرحله N: حواله+هزینه+خروجی+JE → مرحله N+1 → نهایی‌سازی</span>
        <div class="prod-path-actions">
          <button type="button" class="btn sm" data-csp-click="${CSP.bind('click',function(){prodJourneyGoRoute('acc-production-boms')})}">فرمول</button>
          <button type="button" class="btn sm" data-csp-click="${CSP.bind('click',function(){prodJourneyGoRoute('acc-production-orders')})}">سفارش</button>
          <button type="button" class="btn sm ghost" data-csp-click="${CSP.bind('click',function(){prodJourneyGoRoute('acc-production-kanban')})}">کانبان</button>
        </div>
      </div>
    </div>
    <div class="prod-journey" role="list" aria-label="مسیر شش‌مرحله‌ای تولید">
      ${steps.map((s,i)=>{
        const locked=G?!G.canEnter(steps,i).ok:false;
        const hint=lockedHint(i);
        return `<button type="button" class="prod-journey-card${s.done?' is-done':''}${i===nextIdx?' is-next':''}${locked?' is-locked':''}" ${locked?'aria-disabled="true"':''} data-csp-click="${stepNav(i)}">
        <span class="prod-journey-n">${s.n}</span>
        <b>${esc(s.title)}</b>
        <span class="muted">${esc(s.desc)}</span>
        <span class="prod-journey-cta">${s.done?'✓ انجام شده — ':locked?('🔒 '+esc(hint)+' — '):i===nextIdx?'▶ اقدام بعدی — ':''}${esc(s.cta)}</span>
      </button>`;
      }).join('')}
    </div>
    ${nextIdx>=0?`<div class="panel" data-csp-style="${CSP.style(`margin:12px 0`)}"><div class="panel-head"><h4>اقدام بعدی</h4></div>
      <div class="panel-body" data-csp-style="${CSP.style(`display:flex;gap:8px;flex-wrap:wrap`)}">
        <button class="btn" data-csp-click="${stepNav(nextIdx)}">▶ ${esc(steps[nextIdx].title)}</button>
        ${!activeBoms?`<button class="btn ghost" data-csp-click="${CSP.bind('click',function(){prodJourneyGoRoute('acc-production-boms')})}">اول فرمول بسازید</button>`:''}
        ${pendingPack && steps.slice(0,4).every(s=>s.done)?`<button class="btn ghost" data-csp-click="${CSP.bind('click',function(){goCuttingLaysView('pending-pack')})}">${fmt(pendingPack)} لایه منتظر رسید محصول</button>`:''}
      </div></div>`:''}`;
}
