async function renderProductionCloseTab(body){
  const period=(window._prodClosePeriod||todayJalali().slice(0,7));
  window._prodClosePeriod=period;
  let periods=[], status=null, pre=null, calc=null, errMsg='';
  try{ periods=(await api('GET','/production/close'))?.periods||[]; }catch(e){}
  try{ status=await api('GET','/production/close/'+encodeURIComponent(period)); }catch(e){ status=null; }
  const periodStatus=status?.status||status?.period?.status||'';
  if(window._prodCloseDoPrecheck){
    try{ pre=await api('POST','/production/close/'+encodeURIComponent(period)+'/precheck',{}); }
    catch(e){ errMsg=e.message||e.code||'خطا در پیش‌بررسی'; }
    try{ calc=await api('POST','/production/close/'+encodeURIComponent(period)+'/calculate',{method:'proration'}); }
    catch(e){ if(!errMsg) errMsg=e.message||e.code||'خطا در محاسبه'; }
    window._prodCloseDoPrecheck=false;
  }
  const checks=(pre?.checks||[]).map(c=>`<tr><td>${esc(c.label||c.code)}</td><td>${c.status==='pass'?'✅':'❌'} ${esc(c.message||'')}</td></tr>`).join('');
  body.innerHTML=`<div class="prod-scope">
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px;gap:8px;flex-wrap:wrap`)}">
      <label>دوره: <input id="pc-period" value="${esc(period)}" placeholder="1405/04" data-csp-style="${CSP.style(`width:90px`)}"></label>
      <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){prodCloseReload()})}">بارگذاری وضعیت</button>
      <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){prodCloseOpenPeriod()})}">باز کردن دوره</button>
      <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){prodCloseRunPrecheck()})}">پیش‌بررسی و محاسبه</button>
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){prodCloseExecute()})}" ${!pre||!pre.can_close?'disabled':''}>اجرای بستن</button>
      ${periodStatus==='closed'?`<button class="btn ghost" data-csp-style="${CSP.style(`color:var(--red)`)}" data-csp-click="${CSP.bind('click',function(event){prodCloseReopen()})}">بازگشایی دوره</button>`:''}
    </div>
    <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:8px`)}">وضعیت دوره: <b>${esc(periodStatus||'ثبت‌نشده')}</b> — برای بستن ابتدا «باز کردن دوره» سپس «پیش‌بررسی و محاسبه» را بزنید.</p>
    ${errMsg?`<div class="muted" data-csp-style="${CSP.style(`color:var(--state-danger,#C0392B);margin-bottom:8px`)}">${esc(errMsg)}</div>`:''}
    <div data-csp-style="${CSP.style(`display:grid;grid-template-columns:1fr 1fr;gap:12px`)}">
      <div class="panel"><div class="panel-head"><h4>پیش‌بررسی</h4></div>
        <div class="panel-body tbl-wrap"><table class="tbl"><tbody>${checks||'<tr><td colspan="2" class="muted">هنوز پیش‌بررسی اجرا نشده</td></tr>'}</tbody></table></div></div>
      <div class="panel"><div class="panel-head"><h4>خلاصه محاسبه</h4></div>
        <div class="panel-body" data-csp-style="${CSP.style(`font-size:13px`)}">
          ${calc?`<p>انحراف دستمزد: <b>${prodFmtToman(calc.labor?.variance_rial)}</b> ت</p>
          <p>انحراف سربار: <b>${prodFmtToman(calc.overhead?.variance_rial)}</b> ت</p>
          <p>روش: ${esc(calc.materiality?.method_auto||'—')}</p>`:'<span class="muted">پس از پیش‌بررسی نمایش داده می‌شود</span>'}
        </div></div>
    </div>
    ${periods.length?`<div class="muted" data-csp-style="${CSP.style(`margin-top:10px;font-size:12px`)}">دوره‌های ثبت‌شده: ${periods.map(p=>esc(p.period_label||p.period)+' ('+esc(p.status)+')').join(' · ')}</div>`:''}</div>`;
}
function prodCloseReload(){
  window._prodClosePeriod=el('pc-period')?.value||todayJalali().slice(0,7);
  window._prodCloseDoPrecheck=false;
  loadAccTab('production-close');
}
function prodCloseRunPrecheck(){
  window._prodClosePeriod=el('pc-period')?.value||todayJalali().slice(0,7);
  window._prodCloseDoPrecheck=true;
  loadAccTab('production-close');
}
async function prodCloseOpenPeriod(){
  const period=el('pc-period')?.value||window._prodClosePeriod;
  try{
    await api('POST','/production/close/'+encodeURIComponent(period)+'/open',{});
    showToast('دوره '+period+' باز شد'); loadAccTab('production-close');
  }catch(e){ showToast(e.message||e.code||'خطا','error'); }
}
async function prodCloseExecute(){
  const period=el('pc-period')?.value||window._prodClosePeriod;
  if(!confirm('بستن دوره '+period+' — ادامه؟')) return;
  try{
    await api('POST','/production/close/'+encodeURIComponent(period)+'/execute',{method:'proration'});
    showToast('دوره بسته شد'); loadAccTab('production-close');
  }catch(e){ showToast(e.message||e.code||'خطا','error'); }
}
async function prodCloseReopen(){
  const period=el('pc-period')?.value||window._prodClosePeriod;
  const reason=prompt('دلیل بازگشایی دوره (الزامی):');
  if(reason==null) return;
  if(!String(reason).trim()){ showToast('دلیل الزامی است','error'); return; }
  try{
    await api('POST','/production/close/'+encodeURIComponent(period)+'/reopen',{reason:String(reason).trim()});
    showToast('دوره بازگشایی شد'); loadAccTab('production-close');
  }catch(e){ showToast(e.message||e.code||'خطا','error'); }
}

