async function prodCostSheetLoad(){
  const id=el('pcs-order-id')?.value;
  if(!id){ showToast('سفارش را انتخاب کنید','error'); return; }
  window._prodCostSheetOrderId=id;
  const area=el('pcs-sheet-area');
  if(area) area.innerHTML='<div class="muted">در حال بارگذاری...</div>';
  let sheet=null;
  try{ sheet=await api('GET','/production/reports/cost-sheet?order_id='+encodeURIComponent(id)); }
  catch(e){
    if(area) area.innerHTML=`<div class="muted">${esc(e.message||'خطا در بارگذاری')}</div>`;
    el('pcs-btn-print')&&(el('pcs-btn-print').disabled=true);
    el('pcs-btn-excel')&&(el('pcs-btn-excel').disabled=true);
    return;
  }
  const s=sheet.data?.summary||{};
  const stages=sheet.data?.stages||[];
  const cut=sheet.data?.cutting||{};
  const incomplete=!!sheet.data?.incomplete;
  const costFinal=!!sheet.data?.cost_final && !incomplete;
  const reasons=(sheet.data?.incomplete_reasons||[]).map(r=>r.message||r.code).filter(Boolean);
  el('pcs-btn-print')&&(el('pcs-btn-print').disabled=false);
  el('pcs-btn-excel')&&(el('pcs-btn-excel').disabled=false);
  if(!area) return;
  const banner=incomplete
    ?`<div role="alert" data-csp-style="${CSP.style(`margin:0 0 12px;padding:12px 14px;border:1px solid #c45c26;border-radius:8px;background:#fff4ec;color:#5c2b0a;line-height:1.8`)}">
        <div data-csp-style="${CSP.style(`font-weight:700;margin-bottom:4px`)}">⚠ برگه موقت — بهای نهایی صادر نشده</div>
        <div>${reasons.map(m=>esc(m)).join('<br>')||'پیش‌نیاز لایه‌چینی / ضایعات برش ناقص است.'}</div>
        <div data-csp-style="${CSP.style(`margin-top:8px`)}"><button type="button" class="btn sm" data-csp-click="${CSP.bind('click',function(){goCuttingLaysView('lays')})}">رفتن به لایه‌چینی</button></div>
      </div>`
    :(cut.requires_fabric_cutting
      ?`<div data-csp-style="${CSP.style(`margin:0 0 10px;padding:10px 12px;border:1px solid #b7d4c4;border-radius:8px;background:#f2f7f3;color:#1a5c38;font-size:12px;line-height:1.7`)}">
          ✅ بهای نهایی با لایه‌چینی · متر واقعی ${toFa(cut.actual_meters||0)} · استاندارد ${toFa(cut.matrix_meters||0)} · انحراف ${toFa(cut.fabric_variance_m||0)} م · ضایعات عادی ${toFa(cut.waste_normal_m||0)} م · غیرعادی ${toFa(cut.waste_abnormal_m||0)} م (${prodFmtToman(cut.lay_waste_rial)} ریال → ۵۲۲۱)
        </div>`:'');
  area.innerHTML=`
    <div id="pcs-print-sheet">
      ${banner}
      <h2>برگه بهای تمام‌شده — ${esc(s.order_no||'')}${costFinal?'':' <span class="muted" data-csp-style="'+CSP.style('font-size:14px')+'">(موقت)</span>'}</h2>
      <div class="pcs-meta">${(s.products||[]).length>1?(s.products||[]).map(p=>esc(p.product_name||('#'+p.product_id))+' '+toFa(p.qty_planned||0)).join(' · '):esc(s.product_name||'')} · دوره ${esc(s.period_label||'')} · ${esc(s.status||'')} · ${costFinal?'بهای نهایی':'بهای موقت'}</div>
      ${(s.products||[]).length>1?`<div class="tbl-wrap" data-csp-style="${CSP.style(`margin:8px 0`)}"><table class="tbl"><thead><tr><th>محصول</th><th class="num">تعداد برنامه</th><th class="num">سهم٪</th><th class="num">بهای سهم</th><th class="num">بهای واحد</th></tr></thead><tbody>${s.products.map(p=>`<tr><td>${esc(p.product_name||('#'+p.product_id))}</td><td class="num">${toFa(p.qty_planned||0)}</td><td class="num">${toFa(p.cost_share_percent||0)}</td><td class="num">${prodFmtToman(p.cost_rial)} ریال</td><td class="num">${prodFmtToman(p.unit_cost_rial)} ریال</td></tr>`).join('')}</tbody></table><p class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">بهای سهم از جمع سفارش × درصد فرمول است. تعداد هر محصول جداست و درصد را عوض نمی‌کند.</p></div>`:''}
      <div class="pcs-grid">
        <div><span>تعداد برنامه</span><strong class="mono">${(s.products||[]).length>1?(s.products||[]).map(p=>toFa(p.qty_planned||0)).join(' + '):(s.qty_planned??'—')}</strong></div>
        <div><span>تعداد تولید</span><strong class="mono">${s.qty_produced??'—'}</strong></div>
        <div><span>بهره‌وری</span><strong class="mono">${s.yield_pct??'—'}٪</strong></div>
        <div><span>بهای واحد</span><strong class="mono">${prodFmtToman(s.unit_cost_rial)} ریال</strong></div>
        <div><span>مواد</span><strong class="mono">${prodFmtToman(s.material_cost_rial)} ریال</strong></div>
        <div><span>دستمزد</span><strong class="mono">${prodFmtToman(s.labor_cost_rial)} ریال</strong></div>
        <div><span>سربار</span><strong class="mono">${prodFmtToman(s.overhead_cost_rial)} ریال</strong></div>
        <div><span>بسته‌بندی</span><strong class="mono">${prodFmtToman(s.packaging_cost_rial)} ریال</strong></div>
        <div><span>پیمانکاری</span><strong class="mono">${prodFmtToman(s.subcontract_cost_rial)} ریال</strong></div>
        <div><span>ضایعات غیرعادی برش</span><strong class="mono">${prodFmtToman(cut.lay_waste_rial||cut.order_abnormal_waste_rial||s.abnormal_waste_rial)} ریال</strong></div>
        <div><span>جمع کل</span><strong class="mono">${prodFmtToman(s.total_cost_rial)} ریال</strong></div>
      </div>
      <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
        <th>مرحله</th><th>تخصیص</th><th>مرکز هزینه</th><th>ورودی</th><th>خروجی</th>
        <th>مواد (ت)</th><th>دستمزد (ت)</th><th>سربار (ت)</th><th>بهای مرحله (ت)</th>
      </tr></thead><tbody>
        ${stages.map(st=>`<tr>
          <td>${esc(st.seq)}</td>
          <td>${esc(prodStageScopeHtml(st))}</td>
          <td>${esc(st.cc_code||'')} ${esc(st.cc_name||'')}</td>
          <td class="num">${st.qty_in??'—'}</td>
          <td class="num">${st.qty_out??'—'}</td>
          <td class="num">${prodFmtToman(st.material_in_rial)}</td>
          <td class="num">${prodFmtToman(st.labor_rial)}</td>
          <td class="num">${prodFmtToman(st.overhead_rial)}</td>
          <td class="num">${prodFmtToman(st.cost_out_rial)}</td>
        </tr>`).join('')||emptyRow(9)}
      </tbody></table></div>
      <p data-csp-style="${CSP.style(`font-size:11px;color:var(--muted);margin-top:12px`)}">کار در جریان باقیمانده: ${prodFmtToman(sheet.data?.wip_rial)} ریال · ${sheet.data?.balanced?'✅ WIP متوازن':'⚠️ WIP نامتوازن'} · ${costFinal?'✅ بهای نهایی':'⚠️ بهای موقت (لایه‌چینی/ضایعات ناقص)'}</p>
    </div>`;
}
function prodCostSheetPrint(){
  const cleanup=()=>document.body.classList.remove('pcs-print-active');
  document.body.classList.add('pcs-print-active');
  window.addEventListener('afterprint',cleanup,{once:true});
  window.print();
  setTimeout(cleanup,1500);
}
function prodCostSheetExcel(){
  const id=el('pcs-order-id')?.value;
  if(!id){ showToast('شناسه سفارش را وارد کنید','error'); return; }
  downloadAuth('/production/reports/PR-02/export?order_id='+encodeURIComponent(id)+'&format=xlsx','cost-sheet-'+id+'.xlsx');
}
function prodOrderCostSheet(id){
  window._prodCostSheetOrderId=String(id);
  go('acc-production-cost-sheet');
}

/* ============================================================
   برآورد سریع — POST/GET /production/mrp/estimate
============================================================ */
async function renderProductionEstimateTab(body){
  if(!CACHE.allProducts||!CACHE.allProducts.length) CACHE.allProducts=await api('GET','/products')||[];
  const mfg=(CACHE.allProducts||[]).filter(p=>p.is_manufactured==1||p.item_type==='finished');
  const canCost=window.ProdUI?window.ProdUI.canSeeCost():!!window.__canSeeCost;
  body.innerHTML=`
    <div class="prod-scope">
    <div class="prod-panel" data-csp-style="${CSP.style(`margin-bottom:14px`)}">
      <div class="prod-panel-head">🧮 برآورد سریع بهای تولید</div>
      <div class="prod-panel-body">
        <div class="form-grid">
          <div class="fg"><label>محصول</label>
            ${productSelect('pe-product','',mfg)}</div>
          <div class="fg"><label>تعداد</label><input id="pe-qty" type="number" min="1" value="100"></div>
          <div class="fg"><label>حاشیه سود (٪) — اختیاری</label><input id="pe-markup" type="number" min="0" value="35"></div>
        </div>
        <div data-csp-style="${CSP.style(`margin-top:10px;display:flex;gap:8px;flex-wrap:wrap`)}">
          <button class="btn" id="pe-btn-calc" data-csp-click="${CSP.bind('click',function(event){prodEstimateRun()})}">📊 محاسبه</button>
          <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){prodEstimateRunMrp()})}">▶️ اجرای MRP</button>
        </div>
      </div>
    </div>
    <div id="pe-result"><div class="muted" data-csp-style="${CSP.style(`font-size:13px`)}">محصول و تعداد را انتخاب کنید — محاسبه خودکار یا دکمه «محاسبه».</div></div>
    </div>`;
  initCustSearches(body);
  el('pe-product')?.addEventListener('change', prodEstimateScheduleLive);
  el('pe-qty')?.addEventListener('input', prodEstimateScheduleLive);
  el('pe-markup')?.addEventListener('input', prodEstimateScheduleLive);
}
let _peTimer=null;
function prodEstimateScheduleLive(){
  clearTimeout(_peTimer);
  const btn=el('pe-btn-calc'); if(btn) btn.disabled=true;
  _peTimer=setTimeout(prodEstimateRun,400);
}
async function prodEstimateRun(){
  const productId=+el('pe-product')?.value||0;
  const qty=+el('pe-qty')?.value||0;
  const area=el('pe-result');
  if(!productId||qty<=0){ if(area) area.innerHTML='<div class="muted">محصول و تعداد معتبر وارد کنید</div>'; return; }
  const btn=el('pe-btn-calc'); if(btn) btn.disabled=true;
  if(area) area.innerHTML='<div class="muted">در حال محاسبه...</div>';
  let r=null;
  try{ r=await api('GET','/production/mrp/estimate?product_id='+productId+'&qty='+qty); }
  catch(e){ if(area) area.innerHTML=`<div class="muted">${esc(e.message||'خطا در محاسبه')}</div>`; if(btn) btn.disabled=false; return; }
  if(btn) btn.disabled=false;
  if(!area) return;
  const markupPct=+el('pe-markup')?.value||35;
  const unitCost=r.cost?.unit_cost_rial;
  const customPrice=unitCost!=null?Math.round(unitCost*(1+markupPct/100)):null;
  const PU=window.ProdUI;
  const money=v=>PU?PU.moneyCell(v):(window.__canSeeCost?fmt(v||0)+' ریال':'—');
  area.innerHTML=`
    <div class="prod-kpi-grid">
      ${PU?PU.kpiCard({icon:'📦',label:'بهای واحد',value:money(unitCost)}):''}
      ${PU?PU.kpiCard({icon:'💰',label:'قیمت پیشنهادی',value:money(r.pricing?.suggested_price_rial)}):''}
      ${PU?PU.kpiCard({icon:'📈',label:'حاشیه فروش',value:(r.pricing?.margin_on_sale_pct??'—')+'٪'}):''}
      ${PU?PU.kpiCard({icon:'⚖️',label:'نقطه سربه‌سر تخفیف',value:(r.discount_analysis?.breakeven_discount_pct??'—')+'٪'}):''}
    </div>
    <div class="prod-panel" data-csp-style="${CSP.style(`margin-bottom:14px`)}">
      <div class="prod-panel-head">جزئیات بها (${esc(r.bom_code||'')})</div>
      <div class="prod-panel-body tbl-wrap"><table class="tbl"><tbody>
        <tr><td>مواد</td><td class="num">${money(r.cost?.material_rial)}</td></tr>
        <tr><td>بسته‌بندی</td><td class="num">${money(r.cost?.packaging_rial)}</td></tr>
        <tr><td>دستمزد</td><td class="num">${money(r.cost?.labor_rial)}</td></tr>
        <tr><td>سربار</td><td class="num">${money(r.cost?.overhead_rial)}</td></tr>
        <tr><td>پیمانکاری</td><td class="num">${money(r.cost?.subcontract_rial)}</td></tr>
        <tr data-csp-style="${CSP.style(`font-weight:700`)}"><td>جمع خالص</td><td class="num">${money(r.cost?.net_rial)}</td></tr>
        ${markupPct!==35&&customPrice!=null?`<tr data-csp-style="${CSP.style(`font-weight:700;color:var(--brand-mid)`)}"><td>قیمت با حاشیه ${markupPct}٪</td><td class="num">${money(customPrice)}</td></tr>`:''}
      </tbody></table></div>
    </div>
    <div class="prod-panel">
      <div class="prod-panel-head">سناریوهای تخفیف</div>
      <div class="prod-panel-body tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
        <th>تخفیف٪</th><th>خالص</th><th>کمیسیون</th><th>سود</th><th>حاشیه٪</th>
      </tr></thead><tbody>
        ${(r.discount_analysis?.scenarios||[]).map(s=>`<tr>
          <td class="num">${s.discount_pct}</td><td class="num">${money(s.net_rial)}</td>
          <td class="num">${money(s.commission_rial)}</td><td class="num">${money(s.profit_rial)}</td>
          <td class="num">${s.margin_pct}٪</td>
        </tr>`).join('')||emptyRow(5)}
      </tbody></table></div>
    </div>
    ${(r.warnings||[]).length?`<div class="muted" data-csp-style="${CSP.style(`margin-top:8px;font-size:12px`)}">⚠️ ${r.warnings.map(w=>esc(w.message||w.code||w)).join(' · ')}</div>`:''}`;
}
async function prodEstimateRunMrp(){
  try{
    const r=await api('POST','/production/mrp/run',{});
    showToast('MRP اجرا شد — '+(r.total_items||0)+' قلم · '+(r.shortage_items||0)+' کسری');
    go('acc-production-mrp');
  }catch(e){ showToast(e.message||'خطا','error'); }
}

/* ============================================================
   تابلوی خط تولید (کانبان) — GET /production/reports/kanban
============================================================ */
async function renderProductionKanbanTab(body){
  body.innerHTML=`<div class="prod-scope">
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px;gap:8px`)}">
      <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){prodKanbanLoad()})}">🔄 تازه‌سازی</button>
      <label data-csp-style="${CSP.style(`display:flex;align-items:center;gap:6px;font-size:12px`)}">
        <input type="checkbox" id="pk-auto" data-csp-style="${CSP.style(`width:auto`)}" data-csp-change="${CSP.bind('change',function(event){prodKanbanToggleAuto()})}"> خودکار هر ۳۰ ثانیه
      </label>
    </div>
    <div id="pk-board"><div class="muted">در حال بارگذاری...</div></div>
  </div>`;
  await prodKanbanLoad();
}
async function prodKanbanLoad(){
  const board=el('pk-board');
  let r=null;
  try{ r=await api('GET','/production/reports/kanban'); }
  catch(e){ if(board) board.innerHTML=`<div class="muted">${esc(e.message||'خطا در بارگذاری')}</div>`; return; }
  if(!board) return;
  const cols=r.data?.columns||[];
  const cardCount=cols.reduce((n,c)=>n+(c.cards||[]).length,0);
  let pendingPackRows=[];
  try{
    const lays=await api('GET','/production/cutting-lays');
    const layRows=(lays&&lays.rows)||[];
    pendingPackRows=layRows.filter(row=>row.status!=='reversed' && !(row.packs||[]).some(p=>p.status==='posted') && Number(row.pack_posted)!==1);
  }catch(_){ pendingPackRows=[]; }
  const stLabel={pending:'📝',in_progress:'🔵',done:'✅',blocked:'⛔'};
  const emptyHint=!cardCount?`<div class="panel" data-csp-style="${CSP.style(`margin-bottom:12px`)}"><div class="panel-body" data-csp-style="${CSP.style(`line-height:1.8;font-size:13px`)}">
    <b>تابلوی خط مخصوص سفارش چندمرحله‌ای (fixed_adv / variable_adv) است.</b>
    مسیر برش بعد از لایه‌چینی به «رسید انبار محصول» می‌رود نه کانبان.
    ${pendingPackRows.length?`<div data-csp-style="${CSP.style(`margin-top:8px`)}"><button type="button" class="btn sm orange" data-csp-click="${CSP.bind('click',function(){goCuttingLaysView('pending-pack')})}">📦 ${fmt(pendingPackRows.length)} لایه منتظر ورود به انبار محصول</button></div>`:''}
  </div></div>`:'';
  const cutCol=pendingPackRows.length?`<div class="prod-kanban-col">
    <div class="prod-kanban-col-head"><span>✂️ برش / WIP</span><span>(${pendingPackRows.length})</span></div>
    ${pendingPackRows.map(lay=>`<div class="prod-kanban-card st-in_progress" data-csp-click="${CSP.bind('click',function(){goCuttingLaysView('pending-pack')})}">
      <div data-csp-style="${CSP.style(`font-weight:700`)}">${esc(lay.lay_no||('#'+lay.id))}</div>
      <div>${esc(lay.product_name||'')}</div>
      <div class="num">${esc(lay.color||'')} · ${lay.qty_pieces?fmt(lay.qty_pieces):fmtQtyFa(lay.actual_meters||0)}</div>
      <div>⌛ منتظر رسید محصول</div>
    </div>`).join('')}
  </div>`:'';
  board.innerHTML=`
    ${emptyHint}
    <div class="prod-kanban-board">
      ${cutCol}
      ${cols.map(c=>`<div class="prod-kanban-col">
        <div class="prod-kanban-col-head"><span>${esc(c.cc_code||'')} ${esc(c.cc_name||'')}</span><span>(${c.cards.length})</span></div>
        ${c.cards.map(card=>`<div class="prod-kanban-card st-${esc(card.status)}" data-csp-click="${CSP.bind('click',function(event){prodOrderOpenFromKanban((card.order_id))})}">
          <div data-csp-style="${CSP.style(`font-weight:700`)}">${esc(card.order_no)}</div>
          <div>${prodFgNamesHtml(card)}</div>
          <div>${esc(prodStageScopeHtml(card))} · ${toFa(card.qty_in||0)}</div>
          <div class="num">${card.qty_in??0} → ${card.qty_out??0}</div>
          <div>${stLabel[card.status]||''} ${esc(card.status)}</div>
        </div>`).join('')||`<div class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">خالی</div>`}
      </div>`).join('')||(!cutCol?'<div class="muted">داده‌ای یافت نشد</div>':'')}
    </div>
    <div class="muted" data-csp-style="${CSP.style(`margin-top:10px;font-size:12px`)}">سفارش‌های مرحله‌ای باز: ${r.totals?.open_orders??0}${pendingPackRows.length?' · لایه‌های منتظر محصول: '+pendingPackRows.length:''}</div>`;
}
async function prodOrderOpenFromKanban(orderId){
  try{
    const data=await api('GET','/production/execution/orders/'+orderId+'/stages');
    if((data.stages||[]).length){ prodOrderStagesModal(orderId); return; }
  }catch(_){}
  go('acc-production-orders');
}
let _pkAutoTimer=null;
function prodKanbanToggleAuto(){
  const on=el('pk-auto')?.checked;
  clearInterval(_pkAutoTimer);
  if(on) _pkAutoTimer=setInterval(prodKanbanLoad,30000);
}

/* ============================================================
   ماتریس انحراف — GET /production/reports/variance-matrix?period=
============================================================ */
async function renderProductionVarianceTab(body){
  const period=window._prodVariancePeriod||todayJalali().slice(0,7);
  window._prodVariancePeriod=period;
  body.innerHTML=`<div class="prod-scope">
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px;gap:8px;flex-wrap:wrap`)}">
      <label>دوره: <input id="pv-period" value="${esc(period)}" placeholder="1405/04" data-csp-style="${CSP.style(`width:90px`)}"></label>
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){prodVarianceLoad()})}">🔄 بارگذاری</button>
    </div>
    <div id="pv-area"><div class="muted">در حال بارگذاری...</div></div>
  </div>`;
  await prodVarianceLoad();
}
async function prodVarianceLoad(){
  const period=el('pv-period')?.value||window._prodVariancePeriod;
  window._prodVariancePeriod=period;
  const area=el('pv-area');
  let r=null;
  try{ r=await api('GET','/production/reports/variance-matrix?period='+encodeURIComponent(period)); }
  catch(e){ if(area) area.innerHTML=`<div class="muted">${esc(e.message||'خطا در بارگذاری — دسترسی بها لازم است')}</div>`; return; }
  if(!area) return;
  const matrix=r.data?.matrix||[];
  const types=[...new Set(matrix.flatMap(m=>Object.keys(m.types||{})))];
  const typeLabels={material_price:'قیمت مواد',material_qty:'مقدار مواد',labor:'دستمزد',overhead:'سربار'};
  const PU=window.ProdUI;
  const varCell=v=>PU?PU.varianceCell(v):(v||0);
  area.innerHTML=`
    <div class="tbl-wrap"><table class="tbl"><thead><tr>
      <th>مرکز هزینه</th>${types.map(t=>`<th>${esc(typeLabels[t]||t)}</th>`).join('')}<th>جمع</th>
    </tr></thead><tbody>
      ${matrix.map(m=>{
        const rowTotal=types.reduce((s,t)=>s+(Number(m.types[t])||0),0);
        return `<tr>
          <td data-label="مرکز هزینه">${esc(m.cc_code||'')} ${esc(m.cc_name||'')}</td>
          ${types.map(t=>`<td data-label="${esc(typeLabels[t]||t)}" class="num">${varCell(m.types[t]||0)}</td>`).join('')}
          <td data-label="جمع" class="num">${varCell(rowTotal)}</td>
        </tr>`;
      }).join('')||emptyRow(types.length+2)}
    </tbody></table></div>
    <div class="muted" data-csp-style="${CSP.style(`margin-top:8px;font-size:12px`)}">جمع کل انحراف دوره: ${varCell(r.totals?.total_rial||0)}</div>`;
}

/* ============================================================
   MRP — POST /production/mrp/run + GET /production/mrp/runs/:id
============================================================ */
async function renderProductionMrpTab(body){
  body.innerHTML=`<div class="prod-scope">
    <div class="prod-panel" data-csp-style="${CSP.style(`margin-bottom:14px`)}">
      <div class="prod-panel-head">📦 برنامه‌ریزی مواد (MRP)</div>
      <div class="prod-panel-body">
        <div class="form-grid">
          <div class="fg"><label>افق (روز)</label><input id="pm-horizon" type="number" min="1" value="30"></div>
        </div>
        <button class="btn" data-csp-style="${CSP.style(`margin-top:8px`)}" data-csp-click="${CSP.bind('click',function(event){prodMrpRun()})}">▶️ اجرای MRP</button>
      </div>
    </div>
    <div id="pm-result"><div class="muted" data-csp-style="${CSP.style(`font-size:13px`)}">برای دیدن نیازمندی‌های مواد، اجرا کنید.</div></div>
  </div>`;
}
async function prodMrpRun(){
  const area=el('pm-result');
  if(area) area.innerHTML='<div class="muted">در حال اجرای MRP...</div>';
  let r=null;
  try{ r=await api('POST','/production/mrp/run',{horizon_days:+el('pm-horizon')?.value||30}); }
  catch(e){ if(area) area.innerHTML=`<div class="muted">${esc(e.message||'خطا')}</div>`; return; }
  if(!area) return;
  const reqs=r.requirements||[];
  area.innerHTML=`
    <div class="prod-kpi-grid">
      ${window.ProdUI?window.ProdUI.kpiCard({icon:'📋',label:'کد اجرا',value:esc(r.code||'')}):''}
      ${window.ProdUI?window.ProdUI.kpiCard({icon:'📦',label:'کل اقلام',value:r.total_items??0}):''}
      ${window.ProdUI?window.ProdUI.kpiCard({icon:'⚠️',label:'کسری',value:r.shortage_items??0,deltaGood:false}):''}
    </div>
    <div class="tbl-wrap"><table class="tbl"><thead><tr>
      <th>کالا</th><th>نیاز ناخالص</th><th>موجود</th><th>رزرو</th><th>نیاز خالص</th><th>پیشنهاد خرید</th><th>وضعیت</th>
    </tr></thead><tbody>
      ${reqs.map(q=>`<tr>
        <td data-label="کالا">${esc(q.product_name||('#'+q.product_id))}</td>
        <td data-label="نیاز ناخالص" class="num">${qtyFmt(q.gross_req_qty)}</td>
        <td data-label="موجود" class="num">${qtyFmt(q.on_hand_qty)}</td>
        <td data-label="رزرو" class="num">${qtyFmt(q.reserved_qty)}</td>
        <td data-label="نیاز خالص" class="num">${qtyFmt(q.net_req_qty)}</td>
        <td data-label="پیشنهاد خرید" class="num" data-csp-style="${CSP.style(`color:${q.suggested_qty>0?'var(--state-danger)':'inherit'}`)}">${qtyFmt(q.suggested_qty)}</td>
        <td data-label="وضعیت">${q.action==='purchase'?'🔴 خرید':'🟢 کافی'}</td>
      </tr>`).join('')||emptyRow(7)}
    </tbody></table></div>`;
}
function qtyFmt(v){ return window.ProdUI?window.ProdUI.qty(v):fmtQtyFa(v||0); }

/* ============================================================
   نرخ سربار مراکز — GET/POST /production/cost-centers/rates
============================================================ */
const OH_DRIVER_META={
  output_qty:{label:'تعداد خروجی',unit:'ریال سربار به ازای هر عدد خروجی',budgetUnit:'عدد خروجی برنامه‌ای ماه',sample:100,sampleLabel:'۱۰۰ عدد خروجی',tip:'محرک واقعی = تعداد شروع‌شدهٔ رسید (خوب+ضایعات).'},
  direct_labor_rial:{pct:true,label:'دستمزد مستقیم (پایه ریالی)',unit:'درصد از دستمزد مستقیم (مثلاً ۲۰٪)',budgetUnit:'میلیون‌ریال دستمزد برنامه‌ای ماه',sample:10,sampleLabel:'۱۰ میلیون ریال دستمزد',tip:'سربار = دستمزد جذب‌شدهٔ همین رسید × درصد. پیش‌فرض ۲۰٪. حقوق ماهانه را اینجا بودجه نکنید — فیلد «دستمزد مستقیم / عدد» جداست.'},
  labor_rial:{pct:true,label:'دستمزد مستقیم (پایه ریالی)',unit:'درصد از دستمزد مستقیم (مثلاً ۲۰٪)',budgetUnit:'میلیون‌ریال دستمزد برنامه‌ای ماه',sample:10,sampleLabel:'۱۰ میلیون ریال دستمزد',tip:'سربار = دستمزد جذب‌شده × درصد.'},
  direct_labor_hours:{label:'ساعت کارگر',unit:'ریال سربار به ازای هر ساعت کارگر',budgetUnit:'ساعت کارگر برنامه‌ای ماه',sample:8,sampleLabel:'۸ ساعت کارگر',tip:'محرک واقعی از ثبت ساعات کارگر، وگرنه از مسیر BOM (setup+run×تعداد)×خدمه.'},
  machine_hours:{label:'ساعت ماشین',unit:'ریال سربار به ازای هر ساعت ماشین',budgetUnit:'ساعت ماشین برنامه‌ای ماه',sample:6,sampleLabel:'۶ ساعت ماشین',tip:'محرک واقعی از دقیقه ماشین رسید یا Σ(دقیقه/واحد مسیر)×تعداد ÷ ۶۰.'},
  material_rial:{pct:true,label:'مواد مستقیم',unit:'درصد از مواد مستقیم (مثلاً ۲۰٪)',budgetUnit:'میلیون‌ریال مواد برنامه‌ای ماه',sample:50,sampleLabel:'۵۰ میلیون ریال مواد',tip:'سربار = مواد (+بسته‌بندی در تحلیل متغیر) × درصد. پیش‌فرض ۲۰٪.'},
  manual:{label:'دستی',unit:'ریال سربار به ازای واحد محرک دستی',budgetUnit:'واحد محرک دستی برنامه‌ای ماه',sample:1,sampleLabel:'۱ واحد دستی',tip:'محرک واقعی = فیلد «مقدار محرک دستی» روی سفارش تولید (manual_driver_qty).'}
};
function ohDriverMeta(d){ return OH_DRIVER_META[d]||OH_DRIVER_META.output_qty; }
/** ویرایش نرخ سربار و ثبت جذب معین‌ها فقط مدیر و حسابداری (سرور هم همین را enforce می‌کند). */
function ohRateEditor(){ return !!(ME && (ME.role==='admin' || ME.role==='accounting')); }
function shiftJalaliYm(label,delta){
  const m=String(label||'').match(/^(\d{4})\/(\d{1,2})/);
  if(!m) return '';
  let y=+m[1], mo=+m[2]+delta;
  while(mo<1){ mo+=12; y--; }
  while(mo>12){ mo-=12; y++; }
  return y+'/'+String(mo).padStart(2,'0');
}
