function prodReconcileBucketRows(preview){
  const labels=[
    ['material_cost_rial','مواد'],
    ['packaging_cost_rial','بسته‌بندی'],
    ['labor_cost_rial','دستمزد'],
    ['overhead_cost_rial','سربار'],
    ['subcontract_cost_rial','پیمانکاری'],
    ['abnormal_waste_rial','ضایعات غیرعادی'],
    ['scrap_credit_rial','ضایعات قابل فروش'],
  ];
  return labels.map(([key,label])=>{
    const now=Number(preview.before&&preview.before[key])||0;
    const doc=Number(preview.documents&&preview.documents[key])||0;
    const mark=now===doc?'':' data-csp-style="'+CSP.style('background:rgba(180,40,40,.08)')+'"';
    return `<tr${mark}><td>${label}</td><td class="num">${fmt(now)}</td><td class="num">${fmt(doc)}</td></tr>`;
  }).join('');
}
async function prodOrderReconcileCost(id){
  let preview=null;
  try{ preview=await api('GET','/production/orders/'+id+'/cost-reconcile'); }
  catch(e){ showToast(e.message||'خطا','error'); return; }
  const residual=Math.abs(Number(preview.after_residual_rial)||0);
  const projected=Math.abs(Number(preview.projected_after_auto_rial!=null?preview.projected_after_auto_rial:preview.after_residual_rial)||0);
  const zeroAfter=residual<=5;
  const needCols=!!preview.can_align_columns || !preview.aligned;
  const needReceipt=!!preview.can_align_receipt || (!zeroAfter && !!preview.aligned);
  const sharedNote=Number(preview.shared_lay_waste_rial||0)>0
    ? `<p class="muted" data-csp-style="${CSP.style('font-size:12px;line-height:1.7;margin:8px 0 0')}">اتلاف طولی برش مشترک قدیمی (${fmt(preview.shared_lay_waste_rial)} ریال) در ماندهٔ بستن نیست چون وارد کار در جریان نشده است.</p>`
    : '';
  const gap=Number(preview.receipt_gap_rial)||0;
  const receiptHint=!zeroAfter
    ? `<p data-csp-style="${CSP.style('margin:8px 0 0;line-height:1.7')}">رسید الان: <b>${fmt(preview.receipts_rial)}</b> · خالص مورد انتظار: <b>${fmt(preview.expected_receipts_rial)}</b> · اختلاف: <b>${fmt(gap)}</b> ریال. تطبیق رسید سهم انبار را به بهای کالا و سهم فروش‌رفته را به بهای تمام‌شده می‌برد (ADR-006).</p>`
    : '';
  const actionLabel=needCols&&needReceipt?'اعمال اصلاح بها (ستون‌ها + رسید)'
    : needCols?'یکی کردن با اسناد'
    : needReceipt?'تطبیق رسید با خالص WIP'
    : '';
  showModal('اصلاح بهای '+esc(preview.order_no||''),`
    <p class="muted" data-csp-style="${CSP.style('font-size:12px;line-height:1.7;margin:0 0 10px')}">۱) ستون‌های سفارش با حواله، دستمزد، سربار و ضایعات ثبت‌شده یکی می‌شود. ۲) اگر مانده از خود رسید باشد، مبلغ رسید با خالص WIP تطبیق می‌شود (موجودی/COGS؛ مراحل دوباره باز نمی‌شوند).</p>
    <div class="tbl-wrap"><table class="tbl"><thead><tr><th>قلم</th><th>الان روی سفارش</th><th>جمع اسناد</th></tr></thead><tbody>
      ${prodReconcileBucketRows(preview)}
    </tbody></table></div>
    <p data-csp-style="${CSP.style('margin:10px 0 0;line-height:1.7')}">ماندهٔ الان: <b>${fmt(preview.before_residual_rial)}</b> ریال. بعد از اعمال کامل: <b>${fmt(preview.projected_after_auto_rial!=null?preview.projected_after_auto_rial:preview.after_residual_rial)}</b> ریال.${projected<=5?' بعدش می‌توانید بستن را بزنید.':''}</p>
    ${sharedNote}${receiptHint}
    <div data-csp-style="${CSP.style('margin-top:14px;display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap')}">
      <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button>
      ${actionLabel?`<button class="btn" id="po-reconcile-save" data-csp-click="${CSP.bind('click',function(event){prodOrderReconcileCostSave((id))})}">${actionLabel}</button>`:''}
    </div>`);
}
async function prodOrderReconcileCostSave(id){
  const btn=el('po-reconcile-save');
  if(btn) btn.disabled=true;
  try{
    const result=await api('POST','/production/orders/'+id+'/cost-reconcile',{mode:'auto'});
    closeModal();
    const left=Math.abs(Number(result.after_residual_rial)||0);
    if(left<=5) showToast('اصلاح بها انجام شد. حالا بستن را بزنید.');
    else if(result.receipts_touched) showToast('رسید تطبیق شد ولی مانده هنوز صفر نیست — برگه بها را بررسی کنید.','error');
    else showToast(result.applied?'ستون‌ها یکی شد؛ مانده از رسید است و تطبیق ممکن نشد.':'چیزی برای اعمال نبود.','error');
    reloadProdAccTab('production-orders');
  }catch(e){
    showToast(e.message||'خطا','error');
    if(btn) btn.disabled=false;
  }
}
async function prodOrderClose(id){
  try{ await api('POST','/production/orders/'+id+'/close',{}); showToast('بسته شد'); reloadProdAccTab('production-orders'); }
  catch(e){ /* toast از api — residual/E_WIP_NOT_ZERO */ }
}
async function prodOrderReceiptModal(id){
  let order=null, preview=null;
  try{ order=await api('GET','/production/orders/'+id); }catch(e){ showToast(e.message||'خطا','error'); return; }
  const planned=+order.qty_planned||0;
  const produced=+order.qty_produced||0;
  const remain=Math.max(0, planned-produced);
  const defQty=remain>0?remain:planned||1;
  try{ preview=await api('GET','/production/orders/'+id+'/preview?qty_produced='+encodeURIComponent(defQty)); }catch(e){ preview=null; }
  const unitHint=preview?.costs?.unit_cost_rial!=null?('برآورد بهای واحد: '+fmt(preview.costs.unit_cost_rial)+' ریال'):'دستمزد از فرمول ساخت/نرخ مرکز؛ سربار از نرخ مرکز هزینه';
  let variants=[];
  try{
    variants=(await api('GET','/product-variants?product_id='+order.product_id+'&include_default=0')||[]).filter(v=>!v.is_default);
  }catch(e){ variants=[]; }
  let bd={};
  try{ bd=order.size_breakdown?(typeof order.size_breakdown==='string'?JSON.parse(order.size_breakdown):order.size_breakdown):{}; }catch(_){ bd={}; }
  const orderColor=String(order.color||'').trim();
  const prefQty=(v)=>{
    if(!orderColor||String(v.color_name||'')!==orderColor) return 0;
    return Number(bd[v.size_name])||0;
  };
  const varBlock=variants.length?`<div class="tbl-wrap" data-csp-style="${CSP.style(`margin-top:10px`)}"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr><th>رنگ</th><th>سایز</th><th>تعداد رسید</th></tr></thead><tbody>${variants.map(v=>`<tr><td>${esc(v.color_name||'')}</td><td>${esc(displaySizeName(v.size_name)||'')}</td><td><input class="pr-vqty num-fit" data-vid="${v.id}" type="number" min="0" value="${prefQty(v)}"></td></tr>`).join('')}</tbody></table><p class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">جمع این ردیف‌ها باید با تعداد سالم برابر باشد.${orderColor?' رنگ سفارش: '+esc(orderColor):''}</p></div>`:'';
  showModal('رسید تولید — '+esc(order.order_no||''),`
    <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:10px`)}">برنامه: ${toFa(planned)} · تولیدشده: ${toFa(produced)} · باقیمانده: ${toFa(remain)}</p>
    <div class="form-grid">
      <div class="fg"><label>سالم پذیرفته‌شده *</label><input id="pr-good" type="number" value="${defQty}" min="0" data-csp-input="${CSP.bind('input',function(event){prodReceiptPreview((id))})}"></div>
      <div class="fg"><label>ضایعات عادی</label><input id="pr-wn" type="number" value="0" min="0"></div>
      <div class="fg"><label>ضایعات غیرعادی</label><input id="pr-wa" type="number" value="0" min="0"></div>
      <div class="fg"><label>تاریخ</label><input id="pr-date" value="${todayJalali()}"></div>
      <div class="fg full"><label><input type="checkbox" id="pr-partial" data-csp-style="${CSP.style(`width:auto`)}" ${remain>0&&defQty<planned?'checked':''}> رسید جزئی (سفارش در جریان می‌ماند)</label></div>
    </div>
    ${varBlock}
    <p id="pr-hint" data-csp-style="${CSP.style(`font-size:12px;color:var(--muted);margin-top:8px`)}">${esc(unitHint)}</p>
    <div data-csp-style="${CSP.style(`margin-top:14px;display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap`)}">
      <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button>
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){prodOrderReceiptSave((id),true)})}">ثبت جزئی</button>
      <button class="btn green" data-csp-click="${CSP.bind('click',function(event){prodOrderReceiptSave((id),false)})}">ثبت نهایی و تکمیل</button>
    </div>`);
}
async function prodReceiptPreview(id){
  const q=+el('pr-good')?.value||0;
  if(!(q>0)) return;
  try{
    const preview=await api('GET','/production/orders/'+id+'/preview?qty_produced='+q);
    const hint=el('pr-hint');
    if(hint&&preview?.costs?.unit_cost_rial!=null) hint.textContent='برآورد بهای واحد: '+fmt(preview.costs.unit_cost_rial)+' ریال';
  }catch(e){}
}
async function prodOrderReceiptSave(id, forcePartial){
  const qty=+el('pr-good')?.value||0;
  if(!(qty>0) && !(+el('pr-wn')?.value||0) && !(+el('pr-wa')?.value||0)){
    showToast('مقدار سالم یا ضایعات را وارد کنید','error'); return;
  }
  const isPartial=forcePartial===true || !!el('pr-partial')?.checked;
  const variant_lines=[...document.querySelectorAll('.pr-vqty')].map(inp=>({
    variant_id:+inp.getAttribute('data-vid'), qty:+inp.value||0
  })).filter(l=>l.qty>0);
  if(document.querySelector('.pr-vqty')){
    const sum=variant_lines.reduce((a,l)=>a+l.qty,0);
    if(Math.abs(sum-qty)>0.001){ showToast('جمع رنگ و سایز باید با تعداد سالم برابر باشد','error'); return; }
  }
  if(!isPartial && !confirm('ثبت نهایی — سفارش تکمیل می‌شود. ادامه؟')) return;
  try{
    const r=await api('POST','/production/orders/'+id+'/receipt',{
      date:el('pr-date').value,
      qty_produced:qty,
      waste_normal:+el('pr-wn').value||0,
      waste_abnormal:+el('pr-wa').value||0,
      is_partial:isPartial?1:0,
      auto_labor:true,
      variant_lines
    });
    closeModal();
    showToast('ثبت شد — بهای واحد '+fmt(r.costs?.unit_cost_rial||0)+' ریال');
    reloadProdAccTab('production-orders');
  }catch(e){ showToast(e.message||'خطا','error'); }
}

/* ============================================================
   حواله مواد (آنالیز متغیر) — GET issue-template + POST /:id/issue
============================================================ */
async function seedIssueAvgFrom(prefix, reload){
  const inputs=[...document.querySelectorAll('input[data-seed-cost="'+prefix+'"]')];
  if(!inputs.length){ showToast('کالایی برای ثبت بها نیست','error'); return; }
  for(const inp of inputs){
    const unit=Math.round(Number(String(inp.value).replace(/,/g,''))||0);
    if(unit<=0){ showToast('بهای هر واحد را برای همهٔ کالاهای بدون بها وارد کنید','error'); return; }
  }
  try{
    let needDoc=0;
    for(const inp of inputs){
      const unit=Math.round(Number(String(inp.value).replace(/,/g,''))||0);
      const r=await api('POST','/inventory/seed-avg-cost',{product_id:+inp.dataset.pid, unit_cost_rial:unit, date:todayJalali()});
      if(r && r.needs_opening_doc) needDoc++;
    }
    showToast(needDoc?('بهای اولیه ثبت شد — '+needDoc+' کالا کاردکس ندارد؛ موجودی آن را با «سند موجودی اول دوره» ثبت کنید'):'بهای اولیه ثبت شد');
    if(typeof reload==='function') reload();
  }catch(e){ /* toast از api */ }
}
let _pimAltSearchTimer=null;
function prodIssueAltSearch(i, whId, q){
  clearTimeout(_pimAltSearchTimer);
  _pimAltSearchTimer=setTimeout(async function(){
    const box=el('pim-alt-dd-'+i);
    if(!box) return;
    const qs=new URLSearchParams({q:String(q||'').trim(),page:'1',pageSize:'20',include_zero:'0'});
    if(whId) qs.set('warehouse_id',String(whId));
    try{
      const resp=await api('GET','/warehouses/products/search?'+qs.toString());
      const rows=listRows(resp);
      const row=document.querySelector('#pim-rows tr[data-idx="'+i+'"]');
      const primPid=row?Number(row.dataset.pid):0;
      const filtered=rows.filter(p=>Number(p.id)!==primPid);
      if(!filtered.length){
        box.hidden=false;
        box.innerHTML='<div class="muted" data-csp-style="'+CSP.style('padding:8px')+'">کالایی با موجودی یافت نشد</div>';
        return;
      }
      box.hidden=false;
      box.innerHTML=filtered.map(p=>{
        const avail=p.available!=null?p.available:(p.wh_qty!=null?p.wh_qty:0);
        const label=(p.name||'')+' ('+(p.code||p.sku||'-')+')';
        return `<button type="button" class="btn sm ghost" data-csp-style="${CSP.style('display:block;width:100%;text-align:right')}" data-csp-click="${CSP.bind('click',function(){prodIssueAltPick((i),(p.id),label,avail)})}">${esc(p.name)} <span class="mono">${esc(p.code||p.sku||'')}</span> — موجود: ${fmt(avail)}</button>`;
      }).join('');
    }catch(_){ box.hidden=true; }
  },250);
}
function prodIssueAltPick(i, id, label, available){
  const hid=el('pim-alt-id-'+i);
  const q=el('pim-alt-q-'+i);
  const dd=el('pim-alt-dd-'+i);
  if(hid) hid.value=String(id||'');
  if(q){
    q.value=label||'';
    q.dataset.altName=String(label||'').replace(/\s*\(.*$/,'');
    q.dataset.altAvail=available!=null?String(available):'';
  }
  if(dd) dd.hidden=true;
  prodIssueAltReason(i);
  prodIssueUpdateSubmitState();
}
function prodIssueAltReason(i){
  const row=document.querySelector('#pim-rows tr[data-idx="'+i+'"]');
  if(!row) return;
  const altId=Number(el('pim-alt-id-'+i)?.value)||0;
  const altQty=Number(row.querySelector('.pim-alt-qty')?.value)||0;
  const reasonEl=el('pim-reason-'+i);
  if(!reasonEl) return;
  if(!(altId>0 && altQty>0)){
    if(reasonEl.dataset.auto==='1'){ reasonEl.value=''; reasonEl.dataset.auto=''; }
    prodIssueRecalc(i);
    return;
  }
  const primName=row.dataset.pname||('#'+row.dataset.pid);
  const stock=row.dataset.stock!=null && row.dataset.stock!==''?row.dataset.stock:'—';
  const AQ=+row.querySelector('.pim-qty-actual')?.value||0;
  const altName=(el('pim-alt-q-'+i)?.dataset.altName)||(el('pim-alt-q-'+i)?.value)||('#'+altId);
  const auto='تأمین کسری از کالای جایگزین «'+altName+'» به‌مقدار '+altQty+
    ' (موجودی «'+primName+'»: '+stock+'، نیاز: '+AQ+')';
  if(!reasonEl.value.trim() || reasonEl.dataset.auto==='1'){
    reasonEl.value=auto;
    reasonEl.dataset.auto='1';
  }
  prodIssueRecalc(i);
}
function prodIssueReasonManual(i){
  const reasonEl=el('pim-reason-'+i);
  if(reasonEl) reasonEl.dataset.auto='';
  prodIssueUpdateSubmitState();
}
async function prodOrderIssueModal(id){
  let tpl=null;
  try{ tpl=await api('GET','/production/orders/'+id+'/issue-template'); }
  catch(e){ showToast(e.message||'خطا در دریافت الگو','error'); return; }
  const lines=tpl.lines||[];
  const whId=Number(tpl.warehouse_raw_id)||0;
  const seeCost=!(window.ProdUI) || window.ProdUI.canSeeCost();
  const lineAvgOk=L=>L.avg_cost_ok!=null?Number(L.avg_cost_ok)>0:Number(L.average_cost_rial)>0;
  const zeroCost=lines.filter(L=>!lineAvgOk(L));
  const canCost=typeof canAccounting==='function' && canAccounting();
  const zeroHint=zeroCost.length
    ? (canCost
      ? `<div class="prod-empty" data-csp-style="${CSP.style(`margin-bottom:10px`)}"><div data-csp-style="${CSP.style(`margin-bottom:8px`)}">این کالاها موجودی دارند ولی بها ندارند. بهای هر واحد (ریال) را بنویسید — سند افتتاحیه ثبت می‌شود و حواله باز می‌شود.</div>${zeroCost.map(L=>`<label data-csp-style="${CSP.style(`display:flex;gap:8px;align-items:center;margin:6px 0`)}"><span>${esc(L.name||('#'+L.product_id))}</span><input data-seed-cost="pim" data-pid="${L.product_id}" inputmode="numeric" placeholder="بهای هر واحد" data-csp-style="${CSP.style(`width:140px`)}"></label>`).join('')}<button type="button" class="btn sm" data-csp-click="${CSP.bind('click',function(){seedIssueAvgFrom('pim',function(){prodOrderIssueModal(id)})})}">ثبت بها</button></div>`
      : `<div class="prod-empty" data-csp-style="${CSP.style(`margin-bottom:10px;border-color:#C0392B;color:#C0392B`)}">بهای میانگین صفر است. از حسابداری بخواهید بها را ثبت کند: ${esc(zeroCost.map(L=>L.name||('#'+L.product_id)).join('، '))}</div>`)
    : '';
  const cutLockedCount=lines.filter(L=>Number(L.fabric_cut_locked)===1).length;
  const cutHint=cutLockedCount
    ? `<div class="prod-empty" data-csp-style="${CSP.style(`margin-bottom:10px;border-color:#2D7A5F`)}">پارچه‌ای که در لایه‌چینی <b>همین سفارش/کالای دوخته</b> مصرف شده از حواله قفل است تا دوباره‌مصرف نشود. لایه‌چینی محصول دیگر روی این سفارش اثر ندارد. بقیهٔ اقلام BOM (آستر، زیپ، …) را ثبت کنید.</div>`
    : '';
  const shortLines=lines.filter(L=>Number(L.stock_short)===1 && Number(L.fabric_cut_locked)!==1);
  const shortHint=shortLines.length
    ? `<div class="prod-empty" data-csp-style="${CSP.style(`margin-bottom:10px;border-color:#C0392B;color:#C0392B`)}">موجودی انبار مواد برای این اقلام کمتر از مقدار حواله است: ${esc(shortLines.map(L=>(L.name||('#'+L.product_id))+' (موجود '+(L.stock_available??'—')+' / نیاز '+(L.qty_actual??L.qty_standard)+')').join('؛ '))} — کسری را از <b>کالای جایگزین</b> تأمین کنید، یا رسید/خرید ثبت کنید، یا مقدار واقعی را کم کنید.</div>`
    : '';
  const pimRowsHtml=lines.map((L,i)=>{
    const locked=Number(L.fabric_cut_locked)===1;
    const lockNote=locked
      ? (' <span class="muted">(مصرف‌شده در لایه‌چینی همین سفارش/کالا'+(L.fabric_cut_meters!=null?' — '+L.fabric_cut_meters+' '+esc(L.unit_label||'متر'):'')+')</span>')
      : (L.fabric_qty_allowed!=null && Number(L.fabric_cut_meters)>0
        ? (' <span class="muted">(مانده مجاز '+L.fabric_qty_allowed+' '+esc(L.unit_label||'متر')+')</span>') : '');
    const short=Number(L.stock_short)===1 && !locked;
    const shortNote=short
      ? (' <span style="color:#C0392B">(کسری انبار: موجود '+(L.stock_available??'—')+')</span>') : '';
    const needQty=Number(L.qty_actual!=null?L.qty_actual:L.qty_standard)||0;
    const stockAvail=L.stock_available!=null?Number(L.stock_available):null;
    const shortfall=short && stockAvail!=null?Math.max(0, Math.round((needQty-stockAvail)*1000)/1000):0;
    let altBlock='';
    if(short){
      const stAlt=CSP.style('margin-top:6px;padding:6px;border:1px dashed #C0392B;border-radius:6px;background:#FFF8F7');
      const stMuted=CSP.style('font-size:11px;margin-bottom:4px');
      const stRel=CSP.style('position:relative');
      const stQ=CSP.style('width:100%;min-width:160px');
      const stDd=CSP.style('position:absolute;z-index:40;right:0;left:0;max-height:200px;overflow:auto;background:#fff;border:1px solid var(--border);border-radius:8px');
      const stLab=CSP.style('display:flex;gap:6px;align-items:center;margin-top:4px;font-size:11px');
      const stQty=CSP.style('width:90px');
      altBlock=
        '<div class="pim-alt" data-csp-style="'+stAlt+'">'+
          '<div class="muted" data-csp-style="'+stMuted+'">تأمین کسری از کالای دیگر (پیش‌فرض '+shortfall+'):</div>'+
          '<div data-csp-style="'+stRel+'">'+
            '<input type="hidden" class="pim-alt-id" id="pim-alt-id-'+i+'" value="">'+
            '<input type="search" class="pim-alt-q" id="pim-alt-q-'+i+'" autocomplete="off" placeholder="جستجوی کالای جایگزین در انبار مواد…"'+
              ' data-csp-input="'+CSP.bind('input',function(){prodIssueAltSearch(i,whId,this.value)})+'"'+
              ' data-csp-focus="'+CSP.bind('focus',function(){prodIssueAltSearch(i,whId,this.value)})+'"'+
              ' data-csp-style="'+stQ+'">'+
            '<div id="pim-alt-dd-'+i+'" hidden data-csp-style="'+stDd+'"></div>'+
          '</div>'+
          '<label data-csp-style="'+stLab+'">مقدار پوشش'+
            '<input class="pim-alt-qty" type="number" step="0.001" value="'+shortfall+'" data-csp-style="'+stQty+'"'+
              ' data-csp-input="'+CSP.bind('input',function(){prodIssueAltReason(i);prodIssueUpdateSubmitState()})+'">'+
          '</label>'+
        '</div>';
    }
    const costCells=seeCost
      ? ('<td class="num" id="pim-vp-'+i+'">۰</td><td class="num" id="pim-vq-'+i+'">۰</td><td class="num" id="pim-vt-'+i+'">۰</td>')
      : '';
    return '<tr data-idx="'+i+'" data-pid="'+L.product_id+'" data-pname="'+esc(L.name||'')+'" data-sq="'+L.qty_standard+
      '" data-sp="'+(L.std_cost_rial||0)+'" data-ap="'+(L.average_cost_rial||0)+'" data-avg-ok="'+(lineAvgOk(L)?1:0)+
      '" data-fabric-locked="'+(locked?1:0)+'" data-stock="'+(stockAvail!=null?stockAvail:'')+'" data-stock-short="'+(short?1:0)+'">'+
      '<td>'+esc(L.name||('#'+L.product_id))+(lineAvgOk(L)?'':' <span class="muted">(بدون بها)</span>')+lockNote+shortNote+altBlock+'</td>'+
      '<td class="num">'+L.qty_standard+'</td>'+
      '<td><input class="pim-qty-actual" type="number" step="0.001" value="'+L.qty_actual+'" '+(locked?'readonly disabled':'')+
        ' data-csp-style="'+CSP.style('width:90px')+'" data-csp-input="'+CSP.bind('input',function(){prodIssueRecalc(i);prodIssueAltReason(i)})+'"></td>'+
      '<td class="num pim-pct" id="pim-pct-'+i+'">۰٪</td>'+costCells+
      '<td><input class="pim-reason" id="pim-reason-'+i+'" placeholder="دلیل انحراف" '+(locked?'disabled':'')+
        ' data-csp-style="'+CSP.style('width:140px')+'" data-csp-input="'+CSP.bind('input',function(){prodIssueReasonManual(i)})+'"></td>'+
      '</tr>';
  }).join('')||('<tr><td colspan="'+(seeCost?8:5)+'" data-csp-style="'+CSP.style('text-align:center')+'">فرمولی برای این سفارش نیست</td></tr>');
  showModal('حواله مواد — آنالیز متغیر',`
    <div class="form-grid" data-csp-style="${CSP.style(`margin-bottom:10px`)}"><div class="fg"><label>تاریخ</label><input id="pim-date" value="${todayJalali()}"></div></div>
    ${zeroHint}${cutHint}${shortHint}
    <div id="pim-summary" class="prod-issue-summary" data-csp-style="${CSP.style(`display:${seeCost?'flex':'none'};gap:16px;flex-wrap:wrap;margin-bottom:10px;font-size:12px`)}"></div>
    <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}" data-wh="${whId}"><thead><tr>
      <th>کالا</th><th>استاندارد</th><th>واقعی</th><th>انحراف٪</th>
      ${seeCost?'<th>انحراف نرخ</th><th>انحراف مقدار</th><th>جمع انحراف</th>':''}
      <th>دلیل (در صورت انحراف زیاد)</th>
    </tr></thead><tbody id="pim-rows">${pimRowsHtml}</tbody></table></div>
    <p data-csp-style="${CSP.style(`font-size:11px;color:var(--muted);margin-top:8px`)}">ℹ️ انحراف مواد اطلاعاتی است و سند حسابداری ندارد (ADR-011). متر پارچهٔ بریده‌شده از مسیر لایه‌چینی مصرف شده و دوباره حواله نمی‌شود. در کسری موجودی، الباقی از کالای جایگزین حواله می‌شود و دلیل انحراف خودکار توضیح داده می‌شود.</p>
    <div data-csp-style="${CSP.style(`margin-top:14px;display:flex;gap:8px;justify-content:flex-end`)}">
      <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button>
      <button class="btn" id="pim-btn-submit" data-csp-click="${CSP.bind('click',function(event){prodOrderIssueSave((id))})}" ${zeroCost.length?'disabled title="بهای میانگین صفر"':''}>ثبت حواله</button>
    </div>`);
  lines.forEach((L,i)=>{
    prodIssueRecalc(i);
    api('GET','/product-variants?product_id='+L.product_id+'&include_default=0').then(vars=>{
      const active=(vars||[]).filter(v=>!v.is_default);
      if(!active.length) return;
      const row=document.querySelector('#pim-rows tr[data-idx="'+i+'"] td');
      if(!row || row.querySelector('.pim-variant')) return;
      row.insertAdjacentHTML('beforeend', '<div><select class="pim-variant"><option value="">رنگ/سایز</option>'+active.map(v=>'<option value="'+v.id+'">'+esc(v.color_name||'')+' / '+esc(displaySizeName(v.size_name)||'')+'</option>').join('')+'</select></div>');
    }).catch(()=>{});
  });
  prodIssueUpdateSubmitState();
}
function prodIssueRecalc(i){
  const row=document.querySelector(`#pim-rows tr[data-idx="${i}"]`);
  if(!row) return;
  const locked=Number(row.dataset.fabricLocked)===1;
  const SQ=+row.dataset.sq||0, SP=+row.dataset.sp||0, AP=+row.dataset.ap||0;
  const AQ=+row.querySelector('.pim-qty-actual').value||0;
  // Locked fabric is consumed at cutting — do not treat zero issue as a variance that blocks submit.
  const v=locked
    ? {pct:0,varPrice:0,varQtyR:0,total:0,favorable:true}
    :(window.ProdUI?window.ProdUI.calcVariance(AQ,SQ,AP,SP):{pct:SQ?((AQ-SQ)/SQ*100):(AQ>0?100:0),varPrice:0,varQtyR:0,total:0,favorable:false});
  const fav='#2D7A5F', unfav='#C0392B';
  const color=v.favorable?fav:(Math.abs(v.pct)>0.0001?unfav:'inherit');
  const cell=el('pim-pct-'+i);
  if(cell){ cell.textContent=locked?'قفل':(window.ProdUI?window.ProdUI.pct(v.pct,true):v.pct.toFixed(1)+'٪'); cell.style.color=locked?fav:color; }
  const fmtN=(n)=> (window.ProdUI&&window.ProdUI.rial)?window.ProdUI.rial(n):String(Math.round(n||0));
  const vp=el('pim-vp-'+i); if(vp){ vp.textContent=fmtN(v.varPrice); vp.style.color=(v.varPrice||0)<0?fav:(v.varPrice?unfav:'inherit'); }
  const vq=el('pim-vq-'+i); if(vq){ vq.textContent=fmtN(v.varQtyR); vq.style.color=(v.varQtyR||0)<0?fav:(v.varQtyR?unfav:'inherit'); }
  const vt=el('pim-vt-'+i); if(vt){ vt.textContent=fmtN(v.total); vt.style.color=v.favorable?fav:(v.total?unfav:'inherit'); }
  const reasonEl=el('pim-reason-'+i);
  const threshold=5;
  if(reasonEl){
    if(!locked && Math.abs(v.pct)>threshold && !reasonEl.value.trim()){
      reasonEl.classList.add('prod-required-error');
      reasonEl.placeholder=`دلیل انحراف ${v.pct.toFixed(1)}٪ الزامی`;
    } else {
      reasonEl.classList.remove('prod-required-error');
    }
  }
  prodIssueUpdateSummary();
  prodIssueUpdateSubmitState();
}
function prodIssueUpdateSummary(){
  const box=el('pim-summary'); if(!box) return;
  const rows=document.querySelectorAll('#pim-rows tr[data-idx]');
  let std=0, act=0, totVar=0;
  rows.forEach(row=>{
    const SQ=+row.dataset.sq||0, SP=+row.dataset.sp||0, AP=+row.dataset.ap||0;
    const AQ=+row.querySelector('.pim-qty-actual').value||0;
    const v=window.ProdUI?window.ProdUI.calcVariance(AQ,SQ,AP,SP):{total:0};
    std += Math.round(SQ*SP); act += Math.round(AQ*AP); totVar += (v.total||0);
  });
  const fmt=(n)=> (window.ProdUI&&window.ProdUI.rial)?window.ProdUI.rial(n):String(n);
  const col=totVar<0?'#2D7A5F':(totVar>0?'#C0392B':'inherit');
  box.innerHTML=`<span>استاندارد: <b>${fmt(std)}</b></span><span>واقعی: <b>${fmt(act)}</b></span><span style="color:${col}">انحراف کل: <b>${fmt(totVar)}</b></span>`;
}
function prodIssueUpdateSubmitState(){
  const rows=document.querySelectorAll('#pim-rows tr[data-idx]');
  let blocked=false;
  rows.forEach(row=>{
    if(Number(row.dataset.fabricLocked)===1) return;
    const reasonEl=row.querySelector('.pim-reason');
    if(reasonEl && reasonEl.classList.contains('prod-required-error')) blocked=true;
    const AQ=+row.querySelector('.pim-qty-actual')?.value||0;
    const avgOk=row.dataset.avgOk!=null?Number(row.dataset.avgOk)>0:Number(row.dataset.ap)>0;
    if(AQ>0 && !avgOk) blocked=true;
    const stockRaw=row.dataset.stock;
    if(stockRaw!=='' && stockRaw!=null && AQ>0){
      const stock=+stockRaw;
      if(Number.isFinite(stock) && AQ>stock+1e-9){
        const altId=Number(row.querySelector('.pim-alt-id')?.value)||0;
        const altQty=+row.querySelector('.pim-alt-qty')?.value||0;
        if(!(altId>0 && altQty+stock+1e-9>=AQ)) blocked=true;
      }
    }
  });
  const btn=el('pim-btn-submit'); if(btn) btn.disabled=blocked;
}
async function prodOrderIssueSave(id){
  const rows=document.querySelectorAll('#pim-rows tr[data-idx]');
  const materials=[];
  rows.forEach(row=>{
    // Omit fully cut fabric so server does not 409 the whole multi-line issue.
    if(Number(row.dataset.fabricLocked)===1) return;
    const altId=Number(row.querySelector('.pim-alt-id')?.value)||0;
    const altQty=+row.querySelector('.pim-alt-qty')?.value||0;
    const line={
      product_id:+row.dataset.pid,
      variant_id:+row.querySelector('.pim-variant')?.value||undefined,
      qty_actual:+row.querySelector('.pim-qty-actual').value||0,
      reason:row.querySelector('.pim-reason')?.value||'',
    };
    if(altId>0 && altQty>0){
      line.alternate_product_id=altId;
      line.alternate_qty=altQty;
    }
    materials.push(line);
  });
  if(!materials.length){ showToast('قلمی برای حواله نمانده — پارچه در لایه‌چینی مصرف شده','error'); return; }
  try{
    await api('POST','/production/orders/'+id+'/issue',{date:el('pim-date').value,materials});
    closeModal(); showToast('حواله ثبت شد'); reloadProdAccTab('production-orders');
  }catch(e){ /* toast از api */ }
}

/* ============================================================
   نمای مرحله‌ای سفارش (fixed_adv/variable_adv) — §6.5 stage-flow
============================================================ */
async function prodOrderStagesModal(orderId){
  let data=null, order=null;
  try{
    data=await api('GET','/production/execution/orders/'+orderId+'/stages');
    order=await api('GET','/production/orders/'+orderId);
  }catch(e){ showToast(e.message||'خطا در دریافت مراحل','error'); return; }
  const stages=data.stages||[];
  const PU=window.ProdUI;
  const STATUS_FA={done:'انجام شد',in_progress:'در جریان',pending:'منتظر',blocked:'متوقف',skipped:'رد شده'};
  // v527: اقلام فرمول(ها) که به هیچ عملیاتی وصل نیستند → روی هیچ مرحله‌ای حواله نمی‌شوند
  const gaps=Array.isArray(data.material_gaps)?data.material_gaps:[];
  const canFixBom=typeof canPerm==='function' && canPerm('production_bom','edit');
  const gapsHtml=gaps.length?`<div class="prod-empty" data-csp-style="${CSP.style(`margin:0 0 10px;border-color:#C0392B;color:#C0392B;text-align:right`)}">
      ⚠ این اقلام فرمول به هیچ عملیاتی وصل نیستند و روی هیچ مرحله‌ای حواله نمی‌شوند: ${gaps.map(g=>esc('«'+g.name+'»'+(g.bom_code?' ('+g.bom_code+')':''))).join('، ')}.
      ${canFixBom?[...new Set(gaps.map(g=>g.bom_id))].map(bid=>`<button class="btn sm ghost" type="button" data-csp-style="${CSP.style(`margin-inline-start:6px`)}" data-csp-click="${CSP.bind('click',function(event){prodBomEditModal((bid),'ops')})}">اتصال مواد در فرمول ${esc((gaps.find(g=>g.bom_id===bid)||{}).bom_code||('#'+bid))}</button>`).join(''):'از مدیر تولید بخواهید در فرمول (تب مسیر عملیات) وصل کند.'}
    </div>`:'';
  showModal('مراحل سفارش '+esc(order.order_no||''),`
    <div class="prod-scope">
    ${gapsHtml}
    <p class="prod-floor-lead">جریان کار از راست به چپ: شروع → حواله مواد (در صورت نیاز) → ثبت خروجی. مواد فقط روی مرحله‌ای می‌آید که در فرمول به همان عملیات وصل شده باشد؛ قلم وصل‌نشده روی هیچ مرحله‌ای (حتی برش) نمی‌آید. اگر مرحلهٔ برش پارچهٔ طاقه‌ای دارد (واحد متر/یارد، یا طاقهٔ ثبت‌شده حتی اگر واحد کالا کیلو نوشته شده)، «ثبت خروجی» همان فرم لایه‌چینی را برای این سفارش باز می‌کند و پارچه از طاقه مصرف می‌شود. در سفارش چندمحصولی، مرحلهٔ مشترک جمع تعدادها را دارد و مرحلهٔ اختصاصی فقط تعداد همان محصول را؛ تمام شدن مرحلهٔ قبل، تعداد اختصاصی را عوض نمی‌کند.</p>
    ${PU?PU.stageFlow(stages):''}
    <div class="tbl-wrap" data-csp-style="${CSP.style(`margin-top:12px`)}"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
      <th>#</th><th>عملیات / مرکز</th><th>تخصیص</th><th>وضعیت</th><th>ورودی</th><th>خروجی</th><th>عملیات</th>
    </tr></thead><tbody>
      ${(()=>{ const lastDone=(stages.filter(x=>x.status==='done').pop()); return stages.map(s=>{ const canRev=lastDone&&s.id===lastDone.id; const ex=String(s.product_scope||'')==='exclusive'; return `<tr>
        <td>${esc(s.seq)}</td>
        <td><b>${esc(s.operation_name||s.cc_name||'')}</b><div class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">${esc(s.cc_code||'')} ${esc(s.cc_name||'')}</div></td>
        <td>${ex?('اختصاصی'+(s.scoped_product_name?' · '+esc(s.scoped_product_name):'')):'مشترک'}</td>
        <td>${PU?PU.badge(s.status):esc(STATUS_FA[s.status]||s.status)}</td>
        <td class="num">${s.qty_in??'—'}</td>
        <td class="num">${s.qty_out??'—'}${s.cut_coverage&&s.status!=='done'?`<div class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">برش ${toFa(s.cut_coverage.lay_qty)} از ${toFa(s.cut_coverage.need)}</div>`:''}</td>
        <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
          ${s.status==='pending'?`<button class="btn sm" data-csp-click="${CSP.bind('click',function(event){prodStageStart((orderId),(s.id))})}">شروع</button>`:''}
          ${s.status==='in_progress'&&order.analysis_type==='variable_adv'?`<button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){prodStageIssueModal((orderId),(s.id))})}">حواله مواد</button>`:''}
          ${['fixed_adv','variable_adv'].includes(order.analysis_type)&&['in_progress','done'].includes(s.status)?`<button class="btn sm ghost" title="مصرف بیش از استاندارد فرمول در همین مرحله (مثلاً زیپ خراب)" data-csp-click="${CSP.bind('click',function(event){prodStageExtraModal((orderId),(s.id),(s.status))})}">مصرف اضافه</button>`:''}
          ${s.status==='in_progress'?`<button class="btn sm" data-csp-click="${CSP.bind('click',function(event){prodStageOutputModal((orderId),(s.id),(s.qty_in||0),(prodStageScopeHtml(s)))})}">ثبت خروجی</button>`:''}
          ${s.status==='pending'?`<button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){prodStageSkip((orderId),(s.id))})}">رد کردن</button>`:''}
          ${s.is_subcontract && s.status==='in_progress'?`<button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){prodStageSubSend((orderId),(s.id),(s.supplier_id||0),(s.qty_in||0))})}">📤 ارسال پیمانکار</button>`:''}
          ${s.is_subcontract && ['in_progress','done'].includes(s.status)?`<button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){prodStageSubReceive((orderId),(s.id),(s.operation_id||0))})}">📥 دریافت پیمانکار</button>`:''}
          ${['pending','in_progress'].includes(s.status)?`<button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){prodStageBlock((orderId),(s.id))})}">توقف</button>`:''}
          ${s.status==='blocked'?`<button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){prodStageUnblock((orderId),(s.id))})}">رفع توقف</button>`:''}
          ${canRev?`<button class="btn sm ghost" data-csp-style="${CSP.style(`color:var(--red)`)}" data-csp-click="${CSP.bind('click',function(event){prodStageReverse((orderId),(s.id))})}">ابطال مرحله</button>`:''}
        </td>
      </tr>`; }).join('') || emptyRow(7); })()}
    </tbody></table></div>
    ${stages.length && stages[stages.length-1].status==='done'?`<div data-csp-style="${CSP.style(`margin-top:12px;text-align:left`)}">
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){prodOrderFinalize((orderId))})}">✅ نهایی‌سازی سفارش و رسید تولید</button>
    </div>`:''}
    </div>`);
}
async function prodStageExtraModal(orderId,stageId,stageStatus){
  let tpl=null, list=null;
  try{
    [tpl,list]=await Promise.all([
      api('GET','/production/execution/orders/'+orderId+'/stages/'+stageId+'/issue-template'),
      api('GET','/production/execution/orders/'+orderId+'/stages/'+stageId+'/extra-issues'),
    ]);
  }catch(e){ showToast(e.message||'خطا در دریافت مواد مرحله','error'); return; }
  const open=stageStatus==='in_progress';
  const reasons=(list&&list.reasons)||[];
  const lines=((tpl&&tpl.lines)||[]).filter(L=>!Number(L.via_cutting_lay));
  const CLS_FA={normal:'عادی — در بهای محصول',abnormal:'غیرعادی — ۵۲۲۱'};
  const reasonOpts=reasons.map(r=>`<option value="${esc(r.code)}" data-cls="${esc(r.default_class)}">${esc(r.label)}</option>`).join('');
  const rows=(list&&list.rows)||[];
  showModal('مصرف اضافهٔ مواد — مرحله',`
    <div class="prod-scope">
    <p class="prod-floor-lead">وقتی در این مرحله بیش از استاندارد فرمول مصرف شد (مثلاً ۱۰ زیپ لازم بود ولی چند زیپ خراب شد و ۲۰ عدد مصرف شد)، فقط <b>مقدار اضافه</b> را اینجا بزنید. مقدار استاندارد خودش با مرحله کسر می‌شود.
    «عادی» تا سقف درصد ضایعات عادی عملیات در بهای محصول می‌ماند؛ بیشتر از سقف یا دلیل غیرعادی، هزینهٔ ضایعات غیرعادی (۵۲۲۱) همان مرکز هزینه می‌شود و بهای محصول را بالا نمی‌برد. پارچهٔ طاقه‌ای اینجا نیست؛ مصرف واقعی آن با «متر واقعی» لایه‌چینی ثبت می‌شود.</p>
    ${open?(lines.length?`<div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
      <th>قلم</th><th class="num">استاندارد مرحله</th><th class="num">مقدار اضافه</th><th>دلیل</th><th>طبقه</th><th>توضیح</th>
    </tr></thead><tbody>
    ${lines.map((L,i)=>`<tr data-pex-row="${i}" data-pid="${L.product_id}">
      <td>${esc(L.name||('#'+L.product_id))}${L.scoped_product_name?`<div class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">${esc(L.scoped_product_name)}</div>`:''}</td>
      <td class="num">${fmtQtyFa(L.qty_standard||0)} ${esc(L.unit||'')}</td>
      <td><input class="pex-qty" type="number" min="0" step="0.001" value="" placeholder="۰" data-csp-style="${CSP.style(`width:90px`)}"></td>
      <td><select class="pex-reason" data-csp-change="${CSP.bind('change',function(){const o=this.selectedOptions[0]; const c=this.closest('tr').querySelector('.pex-cls'); if(c&&o) c.value=o.dataset.cls||'abnormal';})}"><option value="">— دلیل —</option>${reasonOpts}</select></td>
      <td><select class="pex-cls"><option value="abnormal">${CLS_FA.abnormal}</option><option value="normal">${CLS_FA.normal}</option></select></td>
      <td><input class="pex-note" placeholder="اختیاری؛ برای «سایر» الزامی" data-csp-style="${CSP.style(`width:100%;min-width:140px`)}"></td>
    </tr>`).join('')}
    </tbody></table></div>
    <div data-csp-style="${CSP.style(`margin-top:10px;text-align:left`)}"><button class="btn" data-csp-click="${CSP.bind('click',function(){prodStageExtraSave(orderId,stageId,stageStatus)})}">ثبت مصرف اضافه</button></div>`
      :`<p class="prod-empty">${esc((tpl&&tpl.empty_hint)||'برای این مرحله قلم مصرفی (غیر از پارچهٔ طاقه‌ای) در فرمول نیست.')}</p>`)
      :'<p class="prod-empty">مرحله تمام شده است. برای اصلاح، «ابطال مرحله» را بزنید؛ همهٔ مصرف‌های اضافهٔ آن هم برمی‌گردد.</p>'}
    <h4 data-csp-style="${CSP.style(`margin:14px 0 6px`)}">مصرف‌های اضافهٔ ثبت‌شده</h4>
    <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
      <th>سند</th><th>قلم</th><th class="num">مقدار</th><th>طبقه</th><th>دلیل</th><th class="num">مبلغ</th><th>وضعیت</th><th></th>
    </tr></thead><tbody>
    ${rows.map(r=>`<tr>
      <td class="mono">${esc(r.doc_no||'')}</td>
      <td>${esc(r.product_name||('#'+r.product_id))}</td>
      <td class="num">${fmtQtyFa(r.qty||0)} ${esc(r.unit||'')}</td>
      <td>${esc(CLS_FA[r.extra_class]||r.extra_class||'')}</td>
      <td>${esc(r.note||'')}</td>
      <td class="num">${r.amount_rial!=null?prodFmtToman(r.amount_rial):'—'}</td>
      <td>${r.status==='posted'?'ثبت‌شده':'ابطال‌شده'}</td>
      <td>${open&&r.status==='posted'?`<button class="btn sm ghost" data-csp-style="${CSP.style(`color:var(--red)`)}" data-csp-click="${CSP.bind('click',function(){prodStageExtraVoid(orderId,stageId,r.id,stageStatus)})}">ابطال</button>`:''}</td>
    </tr>`).join('')||emptyRow(8)}
    </tbody></table></div>
    </div>`);
}
async function prodStageExtraSave(orderId,stageId,stageStatus){
  const out=[];
  for(const tr of document.querySelectorAll('[data-pex-row]')){
    const qty=parseQty(tr.querySelector('.pex-qty')?.value,0);
    if(!(qty>0)) continue;
    const reason=tr.querySelector('.pex-reason')?.value||'';
    const note=(tr.querySelector('.pex-note')?.value||'').trim();
    if(!reason){ showToast('برای هر قلم دارای مقدار، دلیل را انتخاب کنید','error'); return; }
    if(reason==='other' && !note){ showToast('برای دلیل «سایر» توضیح بنویسید','error'); return; }
    out.push({ product_id:+tr.dataset.pid, qty, reason_code:reason, extra_class:tr.querySelector('.pex-cls')?.value||'', note });
  }
  if(!out.length){ showToast('حداقل یک قلم با مقدار اضافه وارد کنید','error'); return; }
  if(!confirm('ثبت مصرف اضافه؟ مواد از انبار کسر و سند حسابداری صادر می‌شود.')) return;
  try{
    const r=await api('POST','/production/execution/orders/'+orderId+'/stages/'+stageId+'/extra-issues',{lines:out});
    const ab=(r.lines||[]).filter(x=>x.extra_class==='abnormal').length;
    showToast('مصرف اضافه '+(r.doc_no||'')+' ثبت شد'+(ab?' — بخشی غیرعادی (۵۲۲۱) شد':''));
    prodStageExtraModal(orderId,stageId,stageStatus);
  }catch(e){ showToast(e.detail||e.message||e.code||'خطا','error'); }
}
async function prodStageExtraVoid(orderId,stageId,issueId,stageStatus){
  const reason=prompt('دلیل ابطال مصرف اضافه:')||'';
  if(!reason.trim()){ showToast('دلیل الزامی است','error'); return; }
  try{
    await api('POST','/production/execution/orders/'+orderId+'/stages/'+stageId+'/extra-issues/'+issueId+'/void',{reason});
    showToast('مصرف اضافه ابطال شد — مواد به انبار برگشت و سند معکوس شد');
    prodStageExtraModal(orderId,stageId,stageStatus);
  }catch(e){ showToast(e.detail||e.message||e.code||'خطا','error'); }
}
