function prodStageAltSearch(prefix, i, whId, q){
  const box=el(prefix+'-alt-dd-'+i);
  if(!box) return;
  const query=String(q||'').trim();
  if(query.length<1){ box.hidden=true; box.innerHTML=''; return; }
  clearTimeout(prodStageAltSearch._t);
  prodStageAltSearch._t=setTimeout(async()=>{
    const qs=new URLSearchParams({q:query, limit:'12'});
    if(whId) qs.set('warehouse_id',String(whId));
    try{
      const resp=await api('GET','/warehouses/products/search?'+qs.toString());
      const rows=listRows(resp);
      const host=document.querySelector('['+prefix+'-alt="'+i+'"]');
      const primPid=host?Number(host.dataset.pid):0;
      const filtered=rows.filter(p=>Number(p.id)!==primPid);
      if(!filtered.length){
        box.hidden=false;
        box.innerHTML='<div class="muted" data-csp-style="'+CSP.style('padding:8px')+'">کالایی با موجودی یافت نشد</div>';
        return;
      }
      box.hidden=false;
      box.innerHTML=filtered.map(p=>{
        const avail=p.available!=null?p.available:(p.wh_qty!=null?p.wh_qty:0);
        const label=(p.name||'')+' ('+(p.code||p.sku||'-')+')';
        return `<button type="button" class="btn sm ghost" data-csp-style="${CSP.style('display:block;width:100%;text-align:right')}" data-csp-click="${CSP.bind('click',function(){prodStageAltPick(prefix,i,(p.id),label,avail)})}">${esc(p.name)} <span class="mono">${esc(p.code||p.sku||'')}</span> — موجود: ${fmt(avail)}</button>`;
      }).join('');
    }catch(_){ box.hidden=true; }
  },250);
}
function prodStageAltPick(prefix, i, id, label, available){
  const hid=el(prefix+'-alt-id-'+i);
  const q=el(prefix+'-alt-q-'+i);
  const dd=el(prefix+'-alt-dd-'+i);
  if(hid) hid.value=String(id||'');
  if(q){
    q.value=label||'';
    q.dataset.altName=String(label||'').replace(/\s*\(.*$/,'');
    q.dataset.altAvail=available!=null?String(available):'';
  }
  if(dd) dd.hidden=true;
  prodStageAltReason(prefix, i);
}
function prodStageAltReason(prefix, i){
  const row=document.querySelector('['+prefix+'-alt="'+i+'"]');
  if(!row) return;
  const altId=Number(el(prefix+'-alt-id-'+i)?.value)||0;
  const altQty=Number(row.querySelector('.'+prefix+'-alt-qty')?.value)||0;
  const reasonEl=el(prefix+'-reason-'+i);
  if(reasonEl){
    if(!(altId>0 && altQty>0)){
      if(reasonEl.dataset.auto==='1'){ reasonEl.value=''; reasonEl.dataset.auto=''; }
    }else{
      const primName=row.dataset.pname||('#'+row.dataset.pid);
      const stock=row.dataset.stock!=null && row.dataset.stock!==''?row.dataset.stock:'—';
      const AQ=+row.dataset.need||0;
      const altName=(el(prefix+'-alt-q-'+i)?.dataset.altName)||(el(prefix+'-alt-q-'+i)?.value)||('#'+altId);
      const auto='تأمین کسری از کالای جایگزین «'+altName+'» به‌مقدار '+altQty+
        ' (موجودی «'+primName+'»: '+stock+'، نیاز: '+AQ+')';
      if(!reasonEl.value.trim() || reasonEl.dataset.auto==='1'){
        reasonEl.value=auto;
        reasonEl.dataset.auto='1';
      }
    }
  }
  if(prefix==='pso') prodStageOutputBalance(Number(el('pso-qty-in')?.value)||0);
  if(prefix==='psi') prodStageIssueUpdateSubmit();
}
function prodStageAltBlock(prefix, i, whId, shortfall){
  const stAlt=CSP.style('margin-top:6px;padding:6px;border:1px dashed #C0392B;border-radius:6px;background:#FFF8F7');
  const stMuted=CSP.style('font-size:11px;margin-bottom:4px');
  const stRel=CSP.style('position:relative');
  const stQ=CSP.style('width:100%;min-width:160px');
  const stDd=CSP.style('position:absolute;z-index:40;right:0;left:0;max-height:200px;overflow:auto;background:#fff;border:1px solid var(--border);border-radius:8px');
  const stLab=CSP.style('display:flex;gap:6px;align-items:center;margin-top:4px;font-size:11px');
  const stQty=CSP.style('width:90px');
  return '<div class="'+prefix+'-altbox" data-csp-style="'+stAlt+'">'+
    '<div class="muted" data-csp-style="'+stMuted+'">تأمین کسری از کالای دیگر (پوشش لازم '+shortfall+'):</div>'+
    '<div data-csp-style="'+stRel+'">'+
      '<input type="hidden" class="'+prefix+'-alt-id" id="'+prefix+'-alt-id-'+i+'" value="">'+
      '<input type="search" id="'+prefix+'-alt-q-'+i+'" autocomplete="off" placeholder="جستجوی کالای جایگزین در انبار مواد…"'+
        ' data-csp-input="'+CSP.bind('input',function(){prodStageAltSearch(prefix,i,whId,this.value)})+'"'+
        ' data-csp-focus="'+CSP.bind('focus',function(){prodStageAltSearch(prefix,i,whId,this.value)})+'"'+
        ' data-csp-style="'+stQ+'">'+
      '<div id="'+prefix+'-alt-dd-'+i+'" hidden data-csp-style="'+stDd+'"></div>'+
    '</div>'+
    '<label data-csp-style="'+stLab+'">مقدار پوشش'+
      '<input class="'+prefix+'-alt-qty" type="number" step="0.001" value="'+shortfall+'" data-csp-style="'+stQty+'"'+
        ' data-csp-input="'+CSP.bind('input',function(){prodStageAltReason(prefix,i)})+'">'+
    '</label>'+
    '<input id="'+prefix+'-reason-'+i+'" placeholder="دلیل تأمین از کالای دیگر" data-csp-style="'+CSP.style('width:100%;margin-top:4px')+'"'+
      ' data-csp-input="'+CSP.bind('input',function(){const r=el(prefix+'-reason-'+i); if(r) r.dataset.auto="";})+'">'+
  '</div>';
}
function prodStageCollectAlts(prefix){
  const materials=[];
  document.querySelectorAll('['+prefix+'-alt]').forEach(row=>{
    const altId=Number(row.querySelector('.'+prefix+'-alt-id')?.value)||0;
    const altQty=+row.querySelector('.'+prefix+'-alt-qty')?.value||0;
    const idx=row.getAttribute(prefix+'-alt');
    const line={
      product_id:+row.dataset.pid,
      qty_actual:+(row.querySelector('.'+prefix+'-qty')?.value||row.dataset.qtyActual)||0,
      reason:el(prefix+'-reason-'+idx)?.value||'',
    };
    if(altId>0 && altQty>0){
      line.alternate_product_id=altId;
      line.alternate_qty=altQty;
    }
    materials.push(line);
  });
  return materials;
}
async function prodStageOutputModal(orderId,stageId,qtyIn,scopeLabel){
  const qi=+qtyIn||0;
  let tpl=null;
  try{ tpl=await api('GET','/production/execution/orders/'+orderId+'/stages/'+stageId+'/issue-template'); }
  catch(_){ tpl=null; }
  if(tpl && tpl.cut_lay && Number(tpl.cut_lay.required)===1 && Number(tpl.cut_lay.covered)!==1){
    const cl=tpl.cut_lay;
    const fabs=Array.isArray(cl.fabrics)?cl.fabrics:[];
    const miss=Array.isArray(cl.missing_fabrics)?cl.missing_fabrics:[];
    const fabricsText=fabs.length>1?cuttingFabricStatusText(fabs):'';
    showToast('خروجی برش با لایه‌چینی ثبت می‌شود؛ پارچه از طاقه مصرف می‌شود'+(fabs.length>1&&miss.length?(' — برش‌نخورده: '+miss.map(f=>f.name||('#'+f.product_id)).join('، ')):''));
    window._cutFabricsText=fabricsText;
    await cuttingLayModal(null,{orderId:orderId});
    window._cutFabricsText='';
    return;
  }
  const whId=Number(tpl&&tpl.warehouse_raw_id)||0;
  const isVar=tpl&&tpl.analysis_type==='variable_adv';
  const unissued=isVar?(tpl.unissued||[]):[];
  const shortLines=isVar?[]:(tpl&&tpl.lines||[]).filter(L=>Number(L.stock_short)===1);
  const unissuedHtml=unissued.length?`
    <div id="pso-unissued" class="prod-empty" data-csp-style="${CSP.style(`margin:10px 0;border-color:#C0392B;color:#C0392B`)}">
      این اقلام فرمولِ مرحله هنوز حواله نشده و تا حواله نشوند خروجی ثبت نمی‌شود:
      <b>${unissued.map(m=>esc(m.name)+' ('+fmtQtyFa(m.qty_standard)+')').join('، ')}</b>.
      اگر موجودی کم است، در همان «حواله مواد» کالای جایگزین انتخاب کنید.
      <div data-csp-style="${CSP.style(`margin-top:8px`)}"><button type="button" class="btn sm" data-csp-click="${CSP.bind('click',function(){prodStageIssueModal(orderId,stageId)})}">حواله مواد</button></div>
    </div>`:'';
  const shortHtml=unissuedHtml+(shortLines.length?(`
    <div class="prod-empty" data-csp-style="${CSP.style(`margin:10px 0;border-color:#C0392B;color:#C0392B`)}">موجودی انبار مواد برای حوالهٔ این مرحله کم است. برای هر قلم کسری یک کالای دیگر انتخاب کنید تا جمع اصل (تا سقف موجود) و جایگزین برابر نیاز شود. استاندارد فرمول روی قلم اصلی می‌ماند.</div>
    <div id="pso-shorts">${shortLines.map((L,i)=>{
      const need=Number(L.qty_actual!=null?L.qty_actual:L.qty_standard)||0;
      const stock=L.stock_available!=null?Number(L.stock_available):0;
      const shortfall=Math.max(0, Math.round((need-stock)*1000)/1000);
      return '<div class="pso-short" pso-alt="'+i+'" data-pid="'+L.product_id+'" data-pname="'+esc(L.name||'')+'" data-stock="'+stock+'" data-need="'+need+'" data-qty-actual="'+need+'" data-csp-style="'+CSP.style('margin-bottom:8px')+'">'+
        '<div><b>'+esc(L.name||('#'+L.product_id))+'</b> <span style="color:#C0392B">موجود '+stock+' / نیاز '+need+'</span></div>'+
        prodStageAltBlock('pso', i, whId, shortfall)+
      '</div>';
    }).join('')}</div>`):'');
  showModal('ثبت خروجی مرحله',`
    <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:8px`)}">${scopeLabel?esc(scopeLabel)+' — ':''}ورودی مرحله: ${toFa(qi)} — جمع خروجی+ضایعات+دوباره‌کاری باید برابر ورودی باشد. این عدد فقط همین مرحله است.</p>
    <input type="hidden" id="pso-qty-in" value="${qi}">
    <div class="form-grid">
      <div class="fg"><label>خروجی سالم</label><input id="pso-out" type="number" min="0" value="${qi}" data-csp-input="${CSP.bind('input',function(event){prodStageOutputBalance((qi))})}"></div>
      <div class="fg"><label>ضایعات عادی</label><input id="pso-wn" type="number" min="0" value="0" data-csp-input="${CSP.bind('input',function(event){prodStageOutputBalance((qi))})}"></div>
      <div class="fg"><label>ضایعات غیرعادی</label><input id="pso-wa" type="number" min="0" value="0" data-csp-input="${CSP.bind('input',function(event){prodStageOutputBalance((qi))})}"></div>
      <div class="fg"><label>دوباره‌کاری</label><input id="pso-rw" type="number" min="0" value="0" data-csp-input="${CSP.bind('input',function(event){prodStageOutputBalance((qi))})}"></div>
      <div class="fg"><label>تاریخ</label><input id="pso-date" value="${todayJalali()}"></div>
      <div class="fg"><label><input type="checkbox" id="pso-qc" data-csp-style="${CSP.style(`width:auto`)}"> تأیید کیفیت (QC) شد</label></div>
      <div class="fg full"><label>دلیل ضایعات غیرعادی / یادداشت QC</label><input id="pso-note" placeholder="در صورت ضایعات غیرعادی الزامی"></div>
    </div>
    <p id="pso-bal" class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-top:8px`)}"></p>
    ${shortHtml}
    <div data-csp-style="${CSP.style(`margin-top:14px;display:flex;gap:8px;justify-content:flex-end`)}">
      <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button>
      <button class="btn" id="pso-btn" data-csp-click="${CSP.bind('click',function(event){prodStageOutputSave((orderId),(stageId),(qi))})}">ثبت</button>
    </div>`);
  prodStageOutputBalance(qi);
}
function prodStageShortCovered(prefix){
  let ok=true;
  document.querySelectorAll('['+prefix+'-alt]').forEach(row=>{
    const need=+row.dataset.need||0;
    const stock=+row.dataset.stock||0;
    if(!(need>stock+1e-9)) return;
    const altId=Number(row.querySelector('.'+prefix+'-alt-id')?.value)||0;
    const altQty=+row.querySelector('.'+prefix+'-alt-qty')?.value||0;
    const altAvail=Number(el(prefix+'-alt-q-'+row.getAttribute(prefix+'-alt'))?.dataset.altAvail);
    if(!(altId>0 && altQty>0 && stock+altQty+1e-9>=need)) ok=false;
    if(altId>0 && Number.isFinite(altAvail) && altQty>altAvail+1e-9) ok=false;
  });
  return ok;
}
function prodStageOutputBalance(qi){
  const out=+el('pso-out')?.value||0, wn=+el('pso-wn')?.value||0, wa=+el('pso-wa')?.value||0, rw=+el('pso-rw')?.value||0;
  const sum=out+wn+wa+rw;
  const qtyOk=Math.abs(sum-(+qi||0))<0.0001;
  const altOk=prodStageShortCovered('pso') && !el('pso-unissued');
  const bal=el('pso-bal');
  if(bal){
    const qtyTxt=qtyOk?('✓ تراز صحیح ('+sum+')'):('⚠ جمع='+sum+' ≠ ورودی '+qi);
    bal.textContent=qtyTxt+(altOk?'':(el('pso-unissued')?' — اول حوالهٔ مواد این مرحله':' — کسری مواد با کالای جایگزین کامل نشده'));
    bal.style.color=(qtyOk&&altOk)?'inherit':'var(--state-danger,#C0392B)';
  }
  const btn=el('pso-btn'); if(btn) btn.disabled=!(qtyOk&&altOk);
}
async function prodStageOutputSave(orderId,stageId,qtyIn){
  const out=+el('pso-out').value||0, wn=+el('pso-wn').value||0, wa=+el('pso-wa').value||0, rw=+el('pso-rw').value||0;
  if(Math.abs(out+wn+wa+rw-(+qtyIn||0))>0.0001){ showToast('جمع خروجی با ورودی مرحله برابر نیست','error'); return; }
  if(wa>0 && !(el('pso-note')?.value||'').trim()){ showToast('دلیل ضایعات غیرعادی الزامی است','error'); return; }
  try{
    const body={
      qty_out:out,
      waste_normal:wn,
      waste_abnormal:wa,
      rework:rw,
      date:el('pso-date').value,
      qc_passed:el('pso-qc')?.checked?1:0,
      note:el('pso-note')?.value||'',
      waste_reason:el('pso-note')?.value||'',
    };
    const alts=prodStageCollectAlts('pso').filter(m=>m.alternate_product_id);
    if(alts.length) body.materials=alts;
    await api('POST','/production/execution/orders/'+orderId+'/stages/'+stageId+'/output',body);
    showToast('خروجی مرحله ثبت شد'); prodOrderStagesModal(orderId);
  }catch(e){ showToast(e.message||'خطا','error'); }
}
async function prodStageIssueModal(orderId,stageId){
  let tpl=null;
  try{ tpl=await api('GET','/production/execution/orders/'+orderId+'/stages/'+stageId+'/issue-template'); }
  catch(e){ showToast(e.message||'خطا در دریافت الگوی حواله','error'); return; }
  const lines=tpl.lines||[];
  const issuable=lines.filter(L=>Number(L.via_cutting_lay)!==1);
  const layOnly=lines.filter(L=>Number(L.via_cutting_lay)===1);
  const whId=Number(tpl.warehouse_raw_id)||0;
  const hint=tpl.empty_hint||'مادهٔ مرتبط با این مرحله نیست';
  const lineAvgOk=L=>L.avg_cost_ok!=null?Number(L.avg_cost_ok)>0:Number(L.average_cost_rial)>0;
  const zeroCost=issuable.filter(L=>!lineAvgOk(L));
  const canCost=typeof canAccounting==='function' && canAccounting();
  const zeroHint=zeroCost.length
    ? (canCost
      ? `<div class="prod-empty" data-csp-style="${CSP.style(`margin-bottom:10px`)}"><div data-csp-style="${CSP.style(`margin-bottom:8px`)}">این کالاها موجودی دارند ولی بها ندارند. بهای هر واحد (ریال) را بنویسید — سند افتتاحیه ثبت می‌شود و حواله باز می‌شود.</div>${zeroCost.map(L=>`<label data-csp-style="${CSP.style(`display:flex;gap:8px;align-items:center;margin:6px 0`)}"><span>${esc(L.name||('#'+L.product_id))}</span><input data-seed-cost="psi" data-pid="${L.product_id}" inputmode="numeric" placeholder="بهای هر واحد" data-csp-style="${CSP.style(`width:140px`)}"></label>`).join('')}<button type="button" class="btn sm" data-csp-click="${CSP.bind('click',function(){seedIssueAvgFrom('psi',function(){prodStageIssueModal(orderId,stageId)})})}">ثبت بها</button></div>`
      : `<div class="prod-empty" data-csp-style="${CSP.style(`margin-bottom:10px;border-color:#C0392B;color:#C0392B`)}">بهای میانگین صفر است. از حسابداری بخواهید بها را ثبت کند: ${esc(zeroCost.map(L=>L.name||('#'+L.product_id)).join('، '))}</div>`)
    : '';
  // v527: اقلام بدون عملیات در فرمول — روی هیچ مرحله‌ای (این یکی هم) حواله نمی‌شوند
  const bomGaps=Array.isArray(tpl.bom_gaps)?tpl.bom_gaps:[];
  const gapsHint=bomGaps.length?`<div class="prod-empty" data-csp-style="${CSP.style(`margin-bottom:10px;border-color:#C0392B;color:#C0392B`)}">⚠ در فرمول به هیچ عملیاتی وصل نیست و اینجا هم نمی‌آید: ${esc(bomGaps.map(g=>'«'+g.name+'»'+(g.bom_code?' ('+g.bom_code+')':'')).join('، '))} — در فرمول → مسیر عملیات وصل کنید (روی فرمول فعال هم مجاز است).</div>`:'';
  showModal('حواله مواد مرحله',`
    <div class="prod-scope">
    <div class="form-grid" data-csp-style="${CSP.style(`margin-bottom:10px`)}"><div class="fg"><label>تاریخ</label><input id="psi-date" value="${todayJalali()}"></div></div>
    ${gapsHint}
    ${layOnly.length?`<div class="prod-empty" data-csp-style="${CSP.style(`margin-bottom:10px`)}">پارچهٔ طولی این مرحله از حواله مصرف نمی‌شود: ${esc(layOnly.map(L=>L.name||('#'+L.product_id)).join('، '))}. از «ثبت خروجی» لایه‌چینی همین سفارش را ثبت کنید.</div>`:''}
    ${!issuable.length?`<div class="prod-empty">${lines.length?'قلمی جز پارچهٔ طولی برای حوالهٔ این مرحله نیست.':esc(hint)}</div>`:zeroHint}
    <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
      <th>کالا</th><th>استاندارد</th><th>واقعی</th><th>دلیل انحراف</th>
    </tr></thead><tbody id="psi-rows">
      ${issuable.map((L,i)=>{
        const short=Number(L.stock_short)===1;
        const need=Number(L.qty_actual!=null?L.qty_actual:L.qty_standard)||0;
        const stock=L.stock_available!=null?Number(L.stock_available):null;
        const shortfall=short&&stock!=null?Math.max(0, Math.round((need-stock)*1000)/1000):0;
        const scopeChip=L.product_scope?` <span class="po-chip${L.product_scope==='exclusive'?' is-ex':''}">${esc(L.product_scope==='exclusive'?('اختصاصی'+(L.scoped_product_name?' · '+L.scoped_product_name:'')):'مشترک')}</span>`:'';
        const shortNote=(short?(' <span style="color:#C0392B">(کسری انبار: موجود '+(stock??'—')+' / نیاز '+need+')</span>'):'')
          +(Number(L.issued_qty)>0?(' <span class="muted">(قبلاً حواله‌شده: '+fmtQtyFa(L.issued_qty)+')</span>'):'');
        const alt=short?prodStageAltBlock('psi', i, whId, shortfall):'';
        return `<tr class="psi-row"${short?` psi-alt="${i}"`:''} data-pid="${L.product_id}" data-pname="${esc(L.name||'')}" data-sq="${L.qty_standard}" data-need="${need}" data-stock="${stock!=null?stock:''}" data-avg-ok="${lineAvgOk(L)?1:0}">
        <td>${esc(L.name||('#'+L.product_id))}${scopeChip}${!lineAvgOk(L)?' <span class="muted">(بدون بها)</span>':''}${shortNote}${alt}</td>
        <td class="num">${L.qty_standard}</td>
        <td><input class="psi-qty" type="number" step="0.001" value="${L.qty_actual}" data-csp-style="${CSP.style(`width:90px`)}" data-csp-input="${CSP.bind('input',function(){const row=this.closest('tr'); if(row) row.dataset.need=this.value; prodStageIssueUpdateSubmit();})}"></td>
        <td><input class="psi-reason" placeholder="در صورت انحراف" data-csp-style="${CSP.style(`width:140px`)}"></td>
      </tr>`;
      }).join('')||`<tr><td colspan="4" class="muted" data-csp-style="${CSP.style(`text-align:center`)}">—</td></tr>`}
    </tbody></table></div>
    <div data-csp-style="${CSP.style(`margin-top:14px;display:flex;gap:8px;justify-content:flex-end`)}">
      <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button>
      <button class="btn" id="psi-btn-submit" data-csp-click="${CSP.bind('click',function(event){prodStageIssueSave((orderId),(stageId))})}" ${(!issuable.length||zeroCost.length)?'disabled':''} ${zeroCost.length?'title="بهای میانگین صفر"':''}>ثبت حواله</button>
    </div>
    </div>`);
  prodStageIssueUpdateSubmit();
}
function prodStageIssueUpdateSubmit(){
  const btn=el('psi-btn-submit'); if(!btn) return;
  let blocked=!prodStageShortCovered('psi');
  document.querySelectorAll('#psi-rows tr.psi-row').forEach(row=>{
    const q=+row.querySelector('.psi-qty')?.value||0;
    if(q>0 && !(Number(row.dataset.avgOk)>0)) blocked=true;
  });
  btn.disabled=blocked;
}
async function prodStageIssueSave(orderId,stageId){
  const materials=[];
  document.querySelectorAll('#psi-rows tr.psi-row').forEach(row=>{
    const altId=Number(row.querySelector('.psi-alt-id')?.value)||0;
    const altQty=+row.querySelector('.psi-alt-qty')?.value||0;
    const line={
      product_id:+row.dataset.pid,
      qty_actual:+row.querySelector('.psi-qty')?.value||0,
      reason:row.querySelector('.psi-reason')?.value||row.querySelector('.psi-altbox .psi-reason')?.value||'',
    };
    const auto=row.querySelector('.psi-reason') && row.querySelector('[id^="psi-reason-"]');
    if(auto && auto.value && !line.reason) line.reason=auto.value;
    if(altId>0 && altQty>0){
      line.alternate_product_id=altId;
      line.alternate_qty=altQty;
      const altReason=el('psi-reason-'+row.getAttribute('psi-alt'))?.value||'';
      if(altReason) line.reason=altReason;
    }
    materials.push(line);
  });
  if(!materials.length){ showToast('حداقل یک ردیف معتبر وارد کنید','error'); return; }
  const zeroLive=materials.filter(m=>{
    if(!(m.qty_actual>0)) return false;
    const row=document.querySelector('#psi-rows tr.psi-row[data-pid="'+m.product_id+'"]');
    return row && !(Number(row.dataset.avgOk)>0);
  });
  if(zeroLive.length){
    showToast('بهای میانگین برخی اقلام صفر است — ابتدا فاکتور خرید ثبت کنید','error');
    return;
  }
  try{
    await api('POST','/production/execution/orders/'+orderId+'/stages/'+stageId+'/issue',{date:el('psi-date').value,materials});
    closeModal(); showToast('حواله مرحله ثبت شد'); prodOrderStagesModal(orderId);
  }catch(e){ /* toast از api */ }
}
/** Prefill map variant_id → qty from order matrix / legacy breakdown. */
function prodOrderFinalizePref(order, variants){
  const pref={};
  const byCell=new Map();
  (variants||[]).forEach(v=>{
    if(v.color_id!=null && v.size_id!=null) byCell.set(Number(v.color_id)+':'+Number(v.size_id), Number(v.id));
  });
  (order.matrix_lines||[]).forEach(l=>{
    let vid=l.variant_id!=null?Number(l.variant_id):null;
    if(!vid && l.color_id!=null && l.size_id!=null) vid=byCell.get(Number(l.color_id)+':'+Number(l.size_id))||null;
    const q=Number(l.qty_planned)||0;
    if(vid && q>0) pref[vid]=q;
  });
  if(!Object.keys(pref).length){
    let bd={};
    try{ bd=order.size_breakdown?(typeof order.size_breakdown==='string'?JSON.parse(order.size_breakdown):order.size_breakdown):{}; }catch(_){ bd={}; }
    const orderColor=String(order.color||'').trim();
    (variants||[]).forEach(v=>{
      if(orderColor && String(v.color_name||'')!==orderColor) return;
      const q=Number(bd[v.size_name])||0;
      if(q>0) pref[Number(v.id)]=q;
    });
  }
  return pref;
}
function prodOrderFinalizeLinesFromPref(pref){
  return Object.entries(pref||{})
    .map(([vid,qty])=>({variant_id:Number(vid), qty:Number(qty)||0}))
    .filter(l=>l.variant_id && l.qty>0);
}
async function prodOrderFinalizePost(orderId, qtyGood, variant_lines, outputs){
  const body={qty_produced:qtyGood};
  if(variant_lines&&variant_lines.length) body.variant_lines=variant_lines;
  if(outputs&&outputs.length) body.outputs=outputs;
  const r=await api('POST','/production/execution/orders/'+orderId+'/finalize', body);
  closeModal();
  const nRec=(r.receipts||[]).length;
  showToast('نهایی شد — بهای واحد '+fmt(r.unit_cost_rial||0)+' ریال'+(nRec>1?' · '+toFa(nRec)+' رسید FG':''));
  reloadProdAccTab('production-orders');
}
function prodOrderFinalizeOutputsFromDom(order){
  const plan=order.fg_plan||[];
  if(!(order.is_multiproduct||plan.length>1)) return null;
  const inputs=[...document.querySelectorAll('.pf-out-qty')];
  if(!inputs.length){
    return plan.map(p=>({product_id:Number(p.product_id), qty:Number(p.qty_planned)||0})).filter(o=>o.qty>0);
  }
  return inputs.map(inp=>({
    product_id:+inp.getAttribute('data-pid'),
    qty:+inp.value||0
  })).filter(o=>o.product_id&&o.qty>0);
}
function prodOrderFinalizeFgBlock(order, qtyGood){
  const plan=order.fg_plan||[];
  if(!(order.is_multiproduct||plan.length>1)) return '';
  return `<div class="tbl-wrap" data-csp-style="${CSP.style(`margin-top:10px`)}"><label>رسید محصولات اصلی</label>
    <table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr><th>نقش</th><th>محصول</th><th>تعداد رسید</th><th>سهم٪</th></tr></thead>
    <tbody>${plan.map(p=>{
      const isOrder=Number(p.product_id)===Number(order.product_id);
      const defQ=Number(p.qty_planned)||0;
      return `<tr><td>محصول اصلی${isOrder?' ★':''}</td><td>${esc(p.product_name||('#'+p.product_id))}</td>
        <td><input class="pf-out-qty num-fit" data-pid="${p.product_id}" type="number" min="0" step="any" value="${defQ}"></td>
        <td class="num">${toFa(Number(p.cost_share_percent)||0)}</td></tr>`;
    }).join('')}</tbody></table>
    <p class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">پیش‌فرض هر ردیف تعداد برنامهٔ همان محصول است. اگر مرحلهٔ آخر مشترک باشد خروجی‌اش جمع همه است و رسید هر محصول جدا می‌ماند. سهم٪ از فرمول است.</p></div>`;
}
async function prodOrderFinalizeVariants(productId){
  try{
    const raw=await api('GET','/product-variants?product_id='+productId+'&include_default=0');
    return (Array.isArray(raw)?raw:(raw&&Array.isArray(raw.rows)?raw.rows:[])).filter(v=>!v.is_default);
  }catch(e){ return []; }
}
function prodOrderFinalizePrefFor(order, productId, variants){
  const pref={};
  const byCell=new Map();
  const known=new Set();
  (variants||[]).forEach(v=>{
    known.add(Number(v.id));
    if(v.color_id!=null && v.size_id!=null) byCell.set(Number(v.color_id)+':'+Number(v.size_id), Number(v.id));
  });
  (order.matrix_lines||[]).forEach(l=>{
    if(l.product_id!=null && Number(l.product_id)!==Number(productId)) return;
    let vid=l.variant_id!=null?Number(l.variant_id):null;
    if(vid && !known.has(vid)) vid=null;
    if(!vid && l.color_id!=null && l.size_id!=null) vid=byCell.get(Number(l.color_id)+':'+Number(l.size_id))||null;
    const q=Number(l.qty_planned)||0;
    if(vid && q>0) pref[vid]=(pref[vid]||0)+q;
  });
  return pref;
}
function prodOrderFinalizeBindMatrix(){
  document.querySelectorAll('.pf-vqty[data-pid]').forEach(inp=>{
    inp.addEventListener('input', function(){
      const pid=this.getAttribute('data-pid');
      const sum=[...document.querySelectorAll('.pf-vqty[data-pid="'+pid+'"]')].reduce((s,i)=>s+(+i.value||0),0);
      const q=document.querySelector('.pf-out-qty[data-pid="'+pid+'"]');
      if(q) q.value=sum;
    });
  });
}
async function prodOrderFinalizeMulti(order, orderId, qtyGood){
  const plan=order.fg_plan||[];
  const blocks=[];
  for(const p of plan){
    const variants=await prodOrderFinalizeVariants(p.product_id);
    blocks.push({p, variants, pref:prodOrderFinalizePrefFor(order, p.product_id, variants)});
  }
  const sections=blocks.map(b=>{
    const p=b.p;
    const isOrder=Number(p.product_id)===Number(order.product_id);
    const name=p.product_name||('#'+p.product_id);
    const matrix=b.variants.length?`<table class="tbl" data-csp-style="${CSP.style(`font-size:12px;margin-top:6px`)}"><thead><tr><th>رنگ</th><th>سایز</th><th>تعداد رسید</th></tr></thead><tbody>${b.variants.map(v=>`<tr><td>${esc(v.color_name||'')}</td><td>${esc(displaySizeName(v.size_name)||'')}</td><td><input class="pf-vqty num-fit" data-vid="${v.id}" data-pid="${p.product_id}" type="number" min="0" step="any" value="${b.pref[Number(v.id)]||0}"></td></tr>`).join('')}</tbody></table>
      <p class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">جمع رنگ×سایز همین محصول باید با تعداد رسید خودش برابر باشد.</p>`
      :`<p class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">این محصول رنگ×سایز فعال ندارد — فقط تعداد رسید ثبت می‌شود.</p>`;
    return `<section class="pf-fg" data-pid="${p.product_id}" data-name="${esc(name)}" data-csp-style="${CSP.style(`margin-top:12px`)}">
      <label>${esc(name)}${isOrder?' ★':''} <span class="muted">سهم ${toFa(Number(p.cost_share_percent)||0)}٪</span></label>
      <div class="fg"><label>تعداد رسید</label><input class="pf-out-qty num-fit" data-pid="${p.product_id}" ${isOrder?'data-order="1"':''} type="number" min="0" step="any" value="${Number(p.qty_planned)||0}"></div>
      ${matrix}
    </section>`;
  }).join('');
  showModal('نهایی‌سازی — '+esc(order.order_no||''),`
    <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:8px`)}">خروجی آخرین مرحله: <b>${toFa(qtyGood)}</b>. اگر مرحلهٔ آخر مشترک باشد این عدد جمع همهٔ محصولات است. رسید هر محصول جدا می‌ماند و جدول رنگ×سایز هر کدام مال همان محصول است.</p>
    ${sections}
    <div data-csp-style="${CSP.style(`margin-top:14px;display:flex;gap:8px;justify-content:flex-end`)}">
      <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){closeModal();prodOrderStagesModal((orderId))})}">بازگشت</button>
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){prodOrderFinalizeSave((orderId),(qtyGood))})}">✅ ثبت رسید و نهایی‌سازی</button>
    </div>`);
  prodOrderFinalizeBindMatrix();
}
async function prodOrderFinalize(orderId){
  let order=null, stages=[];
  try{
    order=await api('GET','/production/orders/'+orderId);
    const data=await api('GET','/production/execution/orders/'+orderId+'/stages');
    stages=data.stages||[];
  }catch(e){ showToast(e.message||'خطا','error'); return; }
  const last=stages[stages.length-1];
  const qtyGood=+last?.qty_out||0;
  if(!(qtyGood>0)){ showToast('خروجی آخرین مرحله صفر است','error'); return; }

  const multi=!!(order.is_multiproduct||(order.fg_plan||[]).length>1);
  if(multi){
    await prodOrderFinalizeMulti(order, orderId, qtyGood);
    return;
  }
  const fgBlock=prodOrderFinalizeFgBlock(order, qtyGood);

  let variants=[];
  try{
    const raw=await api('GET','/product-variants?product_id='+order.product_id+'&include_default=0');
    variants=(Array.isArray(raw)?raw:(raw&&Array.isArray(raw.rows)?raw.rows:[])).filter(v=>!v.is_default);
  }catch(e){ variants=[]; }

  const hasOrderPlan=!!((order.matrix_lines&&order.matrix_lines.length)||order.has_matrix_lines);
  // Non-matrix, or matrix plan on server but variant list failed to load:
  // POST without variant_lines → resolveFinalizeApparelLines uses production_order_lines.
  if(!variants.length){
    if(multi){
      showModal('نهایی‌سازی — '+esc(order.order_no||''),`
        <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:8px`)}">خروجی آخرین مرحله (محصول سفارش): <b>${toFa(qtyGood)}</b></p>
        ${fgBlock}
        <div data-csp-style="${CSP.style(`margin-top:14px;display:flex;gap:8px;justify-content:flex-end`)}">
          <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){closeModal();prodOrderStagesModal((orderId))})}">بازگشت</button>
          <button class="btn" data-csp-click="${CSP.bind('click',function(event){prodOrderFinalizeSave((orderId),(qtyGood))})}">✅ ثبت رسید و نهایی‌سازی</button>
        </div>`);
      return;
    }
    if(!confirm('نهایی‌سازی سفارش و ثبت رسید تولید — ادامه؟')) return;
    try{ await prodOrderFinalizePost(orderId, qtyGood, null, prodOrderFinalizeOutputsFromDom(order)); }
    catch(e){ /* toast از api */ }
    return;
  }

  const pref=prodOrderFinalizePref(order, variants);
  const planSum=Object.values(pref).reduce((a,n)=>a+(Number(n)||0),0);
  const planMatches=planSum>0 && Math.abs(planSum-qtyGood)<=0.001;

  // Plan already equals final output — same as backend resolveFinalizeApparelLines.
  // Do not force an empty matrix modal (PO-0006 class of bug).
  // Multiproduct: still show modal so co qtys can be confirmed/edited.
  if(planMatches && !multi){
    const lines=prodOrderFinalizeLinesFromPref(pref);
    const summary=lines.length<=6
      ? '\n'+lines.map(l=>{
          const v=variants.find(x=>Number(x.id)===Number(l.variant_id));
          return '• '+(v?(v.color_name||'')+' / '+(v.size_name||''):('#'+l.variant_id))+' = '+l.qty;
        }).join('\n')
      : '\n('+toFa(lines.length)+' ترکیب رنگ×سایز از برنامه سفارش)';
    if(!confirm('نهایی‌سازی سفارش و ثبت رسید تولید — ادامه؟'+summary)) return;
    try{ await prodOrderFinalizePost(orderId, qtyGood, lines, null); }
    catch(e){ /* toast از api */ }
    return;
  }
  // Order has plan rows but prefill could not map them — still try server auto-plan.
  if(hasOrderPlan && planSum<=0 && !multi){
    if(!confirm('نهایی‌سازی سفارش و ثبت رسید تولید — ادامه؟\n(برنامه رنگ×سایز از سرور)')) return;
    try{ await prodOrderFinalizePost(orderId, qtyGood, null, null); }
    catch(e){ /* toast از api */ }
    return;
  }

  const mismatch=planSum>0 && Math.abs(planSum-qtyGood)>0.001;
  const varBlock=variants.length?`<div class="tbl-wrap" data-csp-style="${CSP.style(`margin-top:10px`)}"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr><th>رنگ</th><th>سایز</th><th>تعداد رسید</th></tr></thead><tbody>${variants.map(v=>`<tr><td>${esc(v.color_name||'')}</td><td>${esc(displaySizeName(v.size_name)||'')}</td><td><input class="pf-vqty num-fit" data-vid="${v.id}" type="number" min="0" value="${pref[Number(v.id)]||0}"></td></tr>`).join('')}</tbody></table>
    <p class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">جمع ردیف‌ها باید با خروجی نهایی (${toFa(qtyGood)}) برابر باشد.${mismatch?' برنامه سفارش '+toFa(planSum)+' با خروجی فرق دارد — تعداد واقعی را اصلاح کنید.':planSum?'':' برنامه رنگ×سایز روی سفارش خالی است — تعداد واقعی هر ترکیب را وارد کنید.'}</p></div>`:'';

  showModal('نهایی‌سازی — '+esc(order.order_no||''),`
    <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:8px`)}">خروجی آخرین مرحله: <b>${toFa(qtyGood)}</b>${variants.length?' — برای کالای رنگ×سایز تعداد هر ترکیب را مشخص کنید تا موجودی فروش‌پذیر درست ثبت شود.':''}</p>
    ${fgBlock}
    ${varBlock}
    <div data-csp-style="${CSP.style(`margin-top:14px;display:flex;gap:8px;justify-content:flex-end`)}">
      <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){closeModal();prodOrderStagesModal((orderId))})}">بازگشت</button>
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){prodOrderFinalizeSave((orderId),(qtyGood))})}">✅ ثبت رسید و نهایی‌سازی</button>
    </div>`);
}
async function prodOrderFinalizeSave(orderId, qtyGood){
  let qty=+qtyGood||0;
  const mainOut=document.querySelector('.pf-out-qty');
  // اگر تعداد اصلی در جدول هم‌محصول عوض شده باشد همان مبناست
  const outInputs=[...document.querySelectorAll('.pf-out-qty')];
  if(outInputs.length){
    // محصول سفارش = اولین ردیف اصلی یا همان qtyGood؛ مقدار اصلی از input با data-pid سفارش
    // (در save به order دسترسی نداریم — از بزرگ‌ترین/اولین با نقش اصلی از مقدار پیش‌فرض)
  }
  const outputs=outInputs.length?outInputs.map(inp=>({
    product_id:+inp.getAttribute('data-pid'), qty:+inp.value||0
  })).filter(o=>o.product_id&&o.qty>0):null;
  if(outputs&&outputs.length){
    // qty_produced = مقدار محصول اصلی اگر در outputs باشد، وگرنه qtyGood
    // تشخیص اصلی: معمولاً اولین ردیف یا همان مقدار پیش‌فرض؛ سرور با product_id سفارش sync می‌کند
    const mainInp=document.querySelector('.pf-out-qty[data-order="1"]')||outInputs.find(inp=>{
      const tr=inp.closest('tr');
      return tr&&/اصلی/.test(tr.textContent||'');
    })||outInputs[0];
    if(mainInp) qty=+mainInp.value||qty;
    if(!(qty>0)){ showToast('تعداد محصول اصلی باید مثبت باشد','error'); return; }
    if(outputs.some(o=>!(o.qty>0))){ showToast('تعداد همهٔ محصولات رسید باید مثبت باشد','error'); return; }
  }
  const tagged=[...document.querySelectorAll('.pf-vqty[data-pid]')];
  let variant_lines;
  if(tagged.length){
    variant_lines=[];
    const pids=[...new Set(tagged.map(inp=>inp.getAttribute('data-pid')))];
    for(const pid of pids){
      const lines=[...document.querySelectorAll('.pf-vqty[data-pid="'+pid+'"]')].map(inp=>({
        product_id:+pid, variant_id:+inp.getAttribute('data-vid'), qty:+inp.value||0
      })).filter(l=>l.variant_id&&l.qty>0);
      const want=+document.querySelector('.pf-out-qty[data-pid="'+pid+'"]')?.value||0;
      const name=document.querySelector('.pf-fg[data-pid="'+pid+'"]')?.getAttribute('data-name')||'';
      if(!lines.length){ showToast('رنگ×سایز '+(name||'محصول')+' را وارد کنید','error'); return; }
      const sum=lines.reduce((a,l)=>a+l.qty,0);
      if(Math.abs(sum-want)>0.001){
        showToast('جمع رنگ×سایز '+(name||'محصول')+' باید با تعداد رسید همان محصول برابر باشد','error');
        return;
      }
      variant_lines.push(...lines);
    }
  }else{
    variant_lines=[...document.querySelectorAll('.pf-vqty')].map(inp=>({
      variant_id:+inp.getAttribute('data-vid'), qty:+inp.value||0
    })).filter(l=>l.qty>0);
    if(document.querySelector('.pf-vqty')){
      if(!variant_lines.length){ showToast('برای کالای رنگ و سایز، تعداد هر ترکیب را مشخص کنید','error'); return; }
      const sum=variant_lines.reduce((a,l)=>a+l.qty,0);
      if(Math.abs(sum-qty)>0.001){ showToast('جمع رنگ و سایز باید با تعداد محصول اصلی برابر باشد','error'); return; }
    }
  }
  if(!confirm('نهایی‌سازی سفارش و ثبت رسید تولید — ادامه؟')) return;
  try{ await prodOrderFinalizePost(orderId, qty, variant_lines.length?variant_lines:null, outputs); }
  catch(e){ /* toast از api */ }
}

async function prodStageSubSend(orderId,stageId,supplierId,qtyIn){
  if(!CACHE.suppliers) try{ CACHE.suppliers=await api('GET','/suppliers')||[]; }catch(e){ CACHE.suppliers=[]; }
  showModal('ارسال به پیمانکار',`
    <div class="form-grid">
      <div class="fg"><label>تأمین‌کننده</label>${supplierSelect('pss-supplier',supplierId||0)}</div>
      <div class="fg"><label>مقدار (خالی = کل ورودی ${qtyIn||''})</label><input id="pss-qty" type="number" min="0" step="0.001"></div>
      <div class="fg"><label>تاریخ</label><input id="pss-date" value="${todayJalali()}"></div>
    </div>
    <div data-csp-style="${CSP.style(`margin-top:14px;display:flex;gap:8px;justify-content:flex-end`)}">
      <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button>
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){prodStageSubSendSave((orderId),(stageId))})}">ارسال</button>
    </div>`);
  setTimeout(()=>initSupplierSearches(document.getElementById('modal')||document),50);
}
async function prodStageSubSendSave(orderId,stageId){
  const body={date:el('pss-date').value};
  const sid=+el('pss-supplier')?.value||0;
  const qty=+el('pss-qty').value;
  if(sid) body.supplier_id=sid;
  if(qty>0) body.qty=qty;
  try{
    await api('POST','/production/execution/orders/'+orderId+'/stages/'+stageId+'/subcontract/send',body);
    closeModal(); showToast('ارسال به پیمانکار ثبت شد'); prodOrderStagesModal(orderId);
  }catch(e){ showToast(e.message||'خطا','error'); }
}
async function prodStageSubReceive(orderId,stageId,operationId){
  let feeToman=0;
  try{
    if(operationId){
      // fee may be on stage list; try order stages
      const data=await api('GET','/production/execution/orders/'+orderId+'/stages');
      const st=(data.stages||[]).find(s=>Number(s.id)===Number(stageId));
      feeToman=Math.round(Number(st?.subcontract_fee_rial||st?.fee_unit_rial||0))||0;
    }
  }catch(e){}
  showModal('دریافت از پیمانکار',`
    <div class="form-grid">
      <div class="fg"><label>مقدار دریافتی *</label><input id="psr-qty" type="number" min="0" step="0.001" value="0"></div>
      <div class="fg"><label>ضایعات</label><input id="psr-waste" type="number" min="0" step="0.001" value="0"></div>
      <div class="fg"><label>مفقودی</label><input id="psr-lost" type="number" min="0" step="0.001" value="0"></div>
      <div class="fg"><label>کارمزد واحد (ریال) — خالی = از فرمول ساخت</label><input id="psr-fee" type="number" min="0" placeholder="${feeToman||'از فرمول'}" value=""></div>
      <div class="fg"><label>تاریخ</label><input id="psr-date" value="${todayJalali()}"></div>
    </div>
    <div data-csp-style="${CSP.style(`margin-top:14px;display:flex;gap:8px;justify-content:flex-end`)}">
      <button class="btn secondary" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button>
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){prodStageSubReceiveSave((orderId),(stageId))})}">دریافت</button>
    </div>`);
}
async function prodStageSubReceiveSave(orderId,stageId){
  const qty=+el('psr-qty').value||0;
  if(qty<=0){ showToast('مقدار دریافتی الزامی است','error'); return; }
  const body={
    qty_received:qty,
    qty_waste:+el('psr-waste').value||0,
    qty_lost:+el('psr-lost').value||0,
    date:el('psr-date').value,
  };
  const feeRaw=el('psr-fee')?.value;
  if(feeRaw!==''&&feeRaw!=null) body.fee_unit_rial=(+String(feeRaw).replace(/[^\d]/g,"")||0);
  try{
    await api('POST','/production/execution/orders/'+orderId+'/stages/'+stageId+'/subcontract/receive',body);
    closeModal(); showToast('دریافت از پیمانکار ثبت شد'); prodOrderStagesModal(orderId);
  }catch(e){ showToast(e.message||'خطا','error'); }
}

/* ============================================================
   LEGACY PRODUCTION RUNS (اجرای تولید قدیمی) — read-only history.
   This screen predates the advanced production module: it bumped
   products.stock / warehouse_stock directly with no journal entry, no WIP
   and no production-period lock. With the advanced module installed the
   server refuses new writes (409 E_LEGACY_PRODUCTION_DISABLED), so the
   buttons are hidden unless an admin turns the escape hatch back on.
   New production goes through «سفارش‌های تولید».
============================================================ */
async function renderProductionTab(body){
  if(!CACHE.allProducts||!CACHE.allProducts.length) CACHE.allProducts=await api('GET','/products')||[];
  const [runs,cfg]=await Promise.all([api('GET','/production'),api('GET','/production/config')]);
  const c=cfg||{overhead_method:'tag',overhead_fixed_rate:'0',overhead_period_production_qty:'0',overhead_auto_suggest:'0'};
  const legacyBlocked=!!c.legacy_blocked;
  const isAdmin=ME.role==='admin';
  body.innerHTML=`
    ${legacyBlocked?`<div class="panel" data-csp-style="${CSP.style(`margin-bottom:14px;border-right:4px solid var(--state-warning,#E67E22)`)}">
      <div class="panel-body" data-csp-style="${CSP.style(`padding:12px 16px;font-size:13px;line-height:1.9`)}">
        🔒 <b>ثبت اجرای تولید قدیمی غیرفعال است.</b> این مسیر موجودی و بهای کالا را بدون سند حسابداری، بدون کالای در جریان ساخت و بدون قفل دورهٔ تولید تغییر می‌داد.
        تولید جدید را از <button type="button" class="btn sm ghost" data-csp-click="${CSP.bind('click',function(){go('acc-production-orders')})}">سفارش‌های تولید</button> ثبت کنید.
        ردیف‌های زیر صرفاً تاریخچه‌اند و فقط خواندنی هستند.
      </div></div>`:''}
    <div class="panel" data-csp-style="${CSP.style(`margin-bottom:14px`)}">
      <div class="panel-head" data-csp-style="${CSP.style(`padding:12px 16px;font-weight:700;color:var(--purple)`)}">⚙️ تنظیمات سربار تولید</div>
      <div class="panel-body" data-csp-style="${CSP.style(`padding:14px 16px`)}">
        <div class="form-grid" data-csp-style="${CSP.style(`margin-bottom:10px`)}">
          <div class="fg"><label>روش محاسبه</label>
            <select id="oh-method">
              <option value="tag" ${c.overhead_method==='tag'?'selected':''}>هزینه‌های برچسب‌خورده سربار</option>
              <option value="fixed" ${c.overhead_method==='fixed'?'selected':''}>نرخ ثابت به ازای هر واحد</option>
              <option value="both" ${c.overhead_method==='both'?'selected':''}>هر دو روش</option>
            </select></div>
          <div class="fg"><label>نرخ ثابت سربار (ریال/واحد)</label><input id="oh-fixed" type="text" inputmode="numeric" class="money" value="${moneyInit(c.overhead_fixed_rate)}"></div>
          <div class="fg"><label>تعداد تولید دوره (اختیاری)</label><input id="oh-period-qty" type="number" min="0" value="${c.overhead_period_production_qty||0}" placeholder="خالی = جمع اجراهای دوره"></div>
        </div>
        <button class="btn sm" data-csp-click="${CSP.bind('click',function(event){saveOverheadConfig()})}">💾 ذخیره تنظیمات سربار</button>
        <label data-csp-style="${CSP.style(`display:flex;align-items:center;gap:6px;font-size:12px;margin-right:12px`)}">
          <input type="checkbox" id="oh-auto" ${c.overhead_auto_suggest==='1'?'checked':''} data-csp-style="${CSP.style(`width:auto`)}"> پیشنهاد خودکار سربار هنگام ثبت تولید (اگر خالی باشد)
        </label>
        <div class="muted" data-csp-style="${CSP.style(`font-size:11px;margin-top:8px`)}">هزینه‌هایی که در «عملیات پرداخت» با گزینه «سربار تولید» ثبت می‌شوند، در محاسبه خودکار سربار لحاظ می‌شوند.</div>
        ${isAdmin&&c.advanced_available?`<label data-csp-style="${CSP.style(`display:flex;align-items:center;gap:6px;font-size:12px;margin-top:10px`)}">
          <input type="checkbox" id="oh-legacy" ${c.legacy_runs_enabled==='1'?'checked':''} data-csp-style="${CSP.style(`width:auto`)}">
          اجرای تولید قدیمی مجاز باشد (فقط برای تعمیر/پخش دوبارهٔ outbox دستگاه — سند حسابداری نمی‌زند)
        </label>`:''}
      </div>
    </div>
    ${legacyBlocked?'':`<div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px`)}"><button class="btn" data-csp-click="${CSP.bind('click',function(event){productionModal()})}">➕ ثبت اجرای تولید</button></div>`}
    <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
      <th>تاریخ</th><th>کالا</th><th>تعداد تولیدی</th><th>ضایعات</th><th>بهای کل (ت)</th><th>بهای واحد (ت)</th><th>حاشیه سود واحد (ت)</th><th>کارایی</th><th>عملیات</th>
    </tr></thead><tbody>${(runs||[]).map(r=>`<tr>
      <td class="mono">${escDate(r.date)}</td><td>${esc(r.product_name||'-')}</td>
      <td class="mono">${fmtQtyFa(r.qty_produced)}</td><td class="mono">${fmtQtyFa(r.waste_qty||0)}</td>
      <td class="mono">${fmt(r.total_cost)}</td><td class="mono" data-csp-style="${CSP.style(`font-weight:700`)}">${fmt(Math.round(r.unit_cost))}</td>
      <td class="mono" data-csp-style="${CSP.style(`color:${r.margin>=0?'var(--green)':'var(--red)'}`)}">${fmt(Math.round(r.margin))}</td>
      <td class="mono">${Math.round(r.efficiency*100)}٪</td>
      <td>${r.voided?`<span class="tag">ابطال‌شده</span>`:(legacyBlocked?`<span class="muted">—</span>`:`<button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deleteProductionRun((r.id))})}">🚫 ابطال</button>`)}</td>
    </tr>`).join('')||emptyRow(9)}</tbody></table></div>
    <div class="muted" data-csp-style="${CSP.style(`font-size:11px;margin-top:8px`)}">این بخش صرفاً برای تحلیل هزینه و کارایی تولید است و سند حسابداری ایجاد نمی‌کند (دفتر مواد اولیه/در جریان ساخت ندارد). به همین دلیل پس از نصب مدول تولید پیشرفته، ثبت جدید از این مسیر بسته است و تولید واقعی از «سفارش‌های تولید» ثبت می‌شود.</div>`;
}
async function saveOverheadConfig(){
  try{
    const body={
      overhead_method:el('oh-method').value,
      overhead_fixed_rate:moneyVal('oh-fixed'),
      overhead_period_production_qty:+el('oh-period-qty').value||0,
      overhead_auto_suggest:el('oh-auto')?.checked?'1':'0'
    };
    if(el('oh-legacy')) body.legacy_runs_enabled=el('oh-legacy').checked?'1':'0';
    await api('PUT','/production/config',body);
    showToast('تنظیمات سربار ذخیره شد');
    if(el('oh-legacy')) loadAccTab('production');
  }catch(e){}
}
