async function loadRecvChequesForPay(prefix){
  const sel=el(prefix+'-recv-chq'); if(!sel) return;
  try{
    const rows=await api('GET','/cheque-records?direction=in')||[];
    const list=(Array.isArray(rows)?rows:[]).filter(r=>{
      if(r.record_status==='reversed') return false;
      const lc=String(r.lifecycle_status||'').trim();
      return !lc || lc==='registered' || lc==='in_hand' || lc==='pending';
    });
    sel.innerHTML='<option value="">— انتخاب چک —</option>'+list.map(r=>{
      const label=`${esc(r.cheque_number||('#'+r.id))} — ${fmt(r.amount)} ریال — ${esc(r.party_name||'-')} — سررسید ${escDate(r.due_date||'-')}`;
      return `<option value="${r.id}" data-amt="${Number(r.amount)||0}">${label}</option>`;
    }).join('');
    if(!list.length) sel.innerHTML='<option value="">— چک دریافتی قابل‌خرج نیست —</option>';
  }catch(e){
    sel.innerHTML='<option value="">— خطا در بارگذاری —</option>';
  }
}
async function saveOutboundChequePayment(prefix, ctx){
  const pt=el(prefix+'-paytype')?.value||'';
  const date=el(prefix+'-date')?.value||todayJalali();
  const note=typeof payNoteWithRef==='function'?payNoteWithRef(prefix, ctx.note||''):(ctx.note||'');
  if(pt==='cheque_recv'||(pt==='cheque' && el(prefix+'-cheque-recv-fields')?.style.display!=='none')){
    const chequeId=+el(prefix+'-recv-chq')?.value||0;
    if(!chequeId){ showToast('چک دریافتی را انتخاب کنید','error'); return false; }
    const body={ date, note };
    if(ctx.supplier_id) body.supplier_id=ctx.supplier_id;
    if(ctx.party_id) body.party_id=ctx.party_id;
    if(ctx.account_code) body.account_code=ctx.account_code;
    await api('POST','/cheque-records/'+chequeId+'/endorse', body);
    return true;
  }
  // cheque_book (or legacy cheque)
  const amount=ctx.amount!=null?ctx.amount:moneyVal(prefix+'-amount');
  if(!amount||amount<=0){ showToast('مبلغ معتبر وارد کنید','error'); return false; }
  let party_id=+ctx.party_id||0;
  if(!party_id) party_id=+el(prefix+'ChqParty')?.value||0;
  if(!party_id){ showToast('ذینفع روی برگه چک را انتخاب کنید','error'); return false; }
  const cheque_number=String(el(prefix+'-chq-num')?.value||'').trim();
  if(!cheque_number){ showToast('شماره چک الزامی است','error'); return false; }
  const bankId=+el(prefix+'-bank')?.value||0;
  if(!bankId){ showToast('بانک دسته‌چک را انتخاب کنید','error'); return false; }
  const branch=String(el(prefix+'-chq-branch')?.value||'').trim();
  if(!validateChequeBranchValue(branch)) return false;
  const bank=(CACHE.banks||[]).find(b=>Number(b.id)===bankId);
  const legal=readChequeLegalFields(prefix+'-chq');
  const created=await api('POST','/cheque-records',{
    direction:'out', amount, party_id, cheque_number,
    bank_name:bank?.name||'', branch,
    account_number:el(prefix+'-chq-acct')?.value||'', sheba:el(prefix+'-chq-sheba')?.value||'',
    sayadi:el(prefix+'-chq-sayadi')?.value||'', due_date:el(prefix+'-chq-due')?.value||'',
    issue_date:date, note:note||'پرداخت از دسته‌چک',
    check_category_id:+el(prefix+'-checkcat')?.value||null, ...legal
  });
  const id=created&&created.id;
  if(!id){ showToast('ثبت چک ناموفق بود','error'); return false; }
  if(ctx.expense){
    await api('POST','/cheque-records/'+id+'/expense',{
      date,
      cost_section:ctx.cost_section||'admin',
      cost_center_id:ctx.cost_center_id||null,
      account_code:ctx.account_code||null,
      category:ctx.category||null,
      is_overhead:!!ctx.is_overhead
    });
  }else{
    const payBody={ date };
    if(ctx.account_key) payBody.account_key=ctx.account_key;
    if(ctx.account_code && !ctx.party_settle){
      // account payment: debit the chosen COA leaf via account_key fallback path — pass as named settings only if mapped;
      // otherwise party-aware pay uses party_id on the cheque leaf (already set).
    }
    await api('POST','/cheque-records/'+id+'/pay', payBody);
  }
  return true;
}
function activePosTerminals(){
  return (CACHE.posTerminals||[]).filter(t=>t.active!==0&&t.active!==false);
}
function payPosFieldHtml(prefix){
  const terms=activePosTerminals();
  const only=terms.length===1?String(terms[0].id):'';
  const empty=terms.length?'':`<div class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-top:4px;line-height:1.7`)}">کارتخوان فعالی برای ثبت این دریافت در دسترس نیست.</div>`;
  return `<div class="fg" id="${prefix}-pos-fg" data-csp-style="${CSP.style(`display:none`)}"><label>کارتخوان</label>
    <select id="${prefix}-pos"><option value="">— انتخاب کارتخوان —</option>
    ${terms.map(t=>`<option value="${t.id}" ${only&&String(t.id)===only?'selected':''}>${esc(t.name||t.terminal_id||'')} — ${esc(t.terminal_id||'')}</option>`).join('')}
    </select>${empty}</div>`;
}
function defaultInvPosIfSingle(){
  const sel=el('inv-pos');
  if(!sel || sel.value || window._invBuilderId) return;
  const terms=activePosTerminals();
  if(terms.length===1) sel.value=String(terms[0].id);
}
async function ensurePayCaches(){
  async function soft(path){
    try{ return await api('GET', path, null, false, true) || []; }
    catch{ return []; }
  }
  if(!CACHE.banks) CACHE.banks=await soft('/banks');
  if(!CACHE.cashBoxes) CACHE.cashBoxes=await soft('/cash-boxes');
  if(!CACHE.checkCategories) CACHE.checkCategories=await soft('/check-categories');
  try{
    const pos=await api('GET','/pos/terminals/choices', null, false, true);
    if(Array.isArray(pos)) CACHE.posTerminals=pos;
  }catch(e){
    if(!Array.isArray(CACHE.posTerminals)) CACHE.posTerminals=[];
  }
  if(!CACHE.costCenters) CACHE.costCenters=await soft('/accounting/cost-centers');
}
function payFg(prefix, kind){
  return el(prefix+'-'+kind+'-fg') || el(prefix+'-'+kind)?.closest('.fg');
}
function payMultiToggleHtml(prefix){
  return `<div class="fg full"><label data-csp-style="${CSP.style(`display:flex;align-items:center;gap:8px;cursor:pointer`)}">
    <input type="checkbox" id="${prefix}-multi" data-csp-change="${CSP.bind('change',function(){payToggleMulti(`${String((prefix) ?? '')}`)})}" data-csp-style="${CSP.style(`width:auto`)}"> ثبت چند قسط / مرحله‌ای
  </label></div>
  <div id="${prefix}-multi-block" class="fg full" data-csp-style="${CSP.style(`display:none`)}">
    <div class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:6px;line-height:1.8`)}">هر قسط یک سند جدا با همان روش و همان صندوق یا بانک سربرگ است.</div>
    <div id="${prefix}-dest-summary" class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:8px;line-height:1.8;color:var(--brand-mid,#2D7A5F);font-weight:600`)}"></div>
    <div id="${prefix}-multi-rows"></div>
    <button type="button" class="btn sm ghost" data-csp-click="${CSP.bind('click',function(){payAddInstRow(`${String((prefix) ?? '')}`)})}">➕ قسط دیگر</button>
  </div>`;
}
function payDestSummary(prefix){
  const pt=el(prefix+'-paytype')?.value||'cash';
  const bankId=+el(prefix+'-bank')?.value||0;
  const cashId=+el(prefix+'-cashbox')?.value||0;
  const posId=+el(prefix+'-pos')?.value||0;
  const bank=(CACHE.banks||[]).find(b=>Number(b.id)===bankId);
  const cash=(CACHE.cashBoxes||[]).find(b=>Number(b.id)===cashId);
  const pos=(CACHE.posTerminals||[]).find(t=>Number(t.id)===posId);
  const out=payFlow(prefix)==='out';
  const typeLbl=(out
    ? {cash:'پرداخت نقد از صندوق',bank:'برداشت از حساب بانکی',bank_transfer:'برداشت از حساب بانکی',cheque:'صدور چک',cheque_book:'پرداخت از دسته‌چک',cheque_recv:'پرداخت از چک دریافتی',pos_card:'کارتخوان'}
    : {cash:'دریافت نقد در صندوق',bank:'واریز به حساب بانکی',bank_transfer:'واریز به حساب بانکی',cheque:'چک دریافتنی',pos_card:'کارتخوان (وجوه در راه)'}
  )[pt]||pt;
  let dest='';
  if(pt==='cash' && cash) dest=' — '+cash.name;
  else if((pt==='bank'||pt==='bank_transfer') && bank) dest=' — '+bank.name;
  else if(pt==='cheque' && out && bank) dest=' — '+bank.name;
  else if(pt==='cheque' && !out) dest=' — اسناد دریافتنی نزد صندوق';
  else if(pt==='pos_card' && pos) dest=' — '+(pos.name||pos.terminal_id||'کارتخوان');
  else if(pt==='cash') dest=' (صندوق را انتخاب کنید)';
  else if(pt==='bank'||pt==='bank_transfer') dest=' (بانک را انتخاب کنید)';
  else if(pt==='cheque' && out) dest=' (بانک صادرکننده را انتخاب کنید)';
  else if(pt==='pos_card') dest=' (کارتخوان را انتخاب کنید)';
  const box=el(prefix+'-dest-summary');
  if(box) box.textContent=(out?'مبدأ وجه همه اقساط: ':'مقصد همه اقساط: ')+typeLbl+dest;
}
function payFlow(prefix){
  if(prefix==='cde'){
    const k=el('cde-kind')?.value||'';
    if(k==='settlement'||k==='person_receipt'||k==='account_receipt') return 'in';
    return 'out';
  }
  return (prefix==='pp'||prefix==='apay'||prefix==='ex'||prefix==='sp')?'out':'in';
}
function payNoteWithRef(prefix, note){
  const ref=String(el(prefix+'-bankref')?.value||'').trim();
  const base=String(note||'').trim();
  if(!ref) return base;
  return (base?base+' | ':'')+'پیگیری: '+ref;
}
function payBankRefHtml(prefix){
  const out=payFlow(prefix)==='out';
  const label=out?'شماره پیگیری حواله':'شماره پیگیری واریز';
  return `<div class="fg" id="${prefix}-bankref-fg" data-csp-style="${CSP.style(`display:none`)}"><label>${label}</label><input id="${prefix}-bankref" dir="ltr" placeholder="کد رهگیری بانک"></div>`;
}
let _payInstRows={};
function payToggleMulti(prefix){
  const on=!!el(prefix+'-multi')?.checked;
  const box=el(prefix+'-multi-block');
  const amtFg=el(prefix+'-amount')?.closest('.fg');
  if(box) box.style.display=on?'block':'none';
  if(amtFg) amtFg.style.display=on?'none':'flex';
  if(on){
    if(!_payInstRows[prefix]||!_payInstRows[prefix].length) _payInstRows[prefix]=[{amount:''},{amount:''}];
    payRenderInst(prefix);
    payDestSummary(prefix);
  }
}
function payAddInstRow(prefix){
  (_payInstRows[prefix]=_payInstRows[prefix]||[]).push({amount:''});
  payRenderInst(prefix);
}
function payRenderInst(prefix){
  const box=el(prefix+'-multi-rows'); if(!box) return;
  const rows=_payInstRows[prefix]||[];
  box.innerHTML=rows.map((r,i)=>`<div class="form-grid" data-csp-style="${CSP.style(`margin-bottom:6px`)}">
    <div class="fg"><label>مبلغ قسط ${toFa(i+1)}</label>
      <input class="money" inputmode="numeric" value="${esc(r.amount||'')}" data-csp-change="${CSP.bind('change',function(){_payInstRows[`${String((prefix) ?? '')}`][(i)].amount=this.value})}">
    </div>
    ${rows.length>1?`<div class="fg"><button type="button" class="btn sm red" data-csp-click="${CSP.bind('click',function(){_payInstRows[`${String((prefix) ?? '')}`].splice((i),1);payRenderInst(`${String((prefix) ?? '')}`)})}">حذف</button></div>`:''}
  </div>`).join('');
  if(typeof enhanceMoneyInputs==='function') enhanceMoneyInputs(box);
  box.querySelectorAll('input').forEach(inp=>{ if(typeof ensureMoneyField==='function') ensureMoneyField(inp); });
}
function payInstAmounts(prefix){
  if(!el(prefix+'-multi')?.checked) return null;
  return (_payInstRows[prefix]||[]).map(r=>parseInt(String(r.amount||'').replace(/[^\d]/g,''),10)||0);
}
function payIdemKey(){
  if(!window._payIdemKey) window._payIdemKey='pay-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);
  return window._payIdemKey;
}
function payIdemDone(){ window._payIdemKey=null; }
async function paySubmitLocked(work){
  if(window._payBusy){ showToast('ثبت قبلی هنوز تمام نشده','error'); return; }
  window._payBusy=true;
  try{ return await work(); }
  finally{ window._payBusy=false; }
}
function payFormFail(msg){
  const box=el('pay-form-error');
  if(box){ box.style.display='block'; box.textContent=msg||'ثبت ناموفق بود'; }
  showToast(msg||'ثبت ناموفق بود','error');
}
function payInstallmentBody(amounts, extra){
  const body=Object.assign({}, extra||{}, { idempotency_key: payIdemKey() });
  if(amounts.length>1) body.installments=amounts;
  else body.amount=amounts[0];
  return body;
}
// XOR: نقد→صندوق، بانک/چک→بانک، کارتخوان→ترمینال؛ کارمزد انتقال فقط برای واریز بانکی
function payFeeCcOptionsHtml(selectedId){
  const opts=(CACHE.costCenters||[]).filter(c=>c.active!==0);
  const req=typeof isExpenseCcRequired==='function' && isExpenseCcRequired();
  return `<option value="">${req?'— مرکز هزینه کارمزد —':'— بدون مرکز (یا همان مرکز سند) —'}</option>`+
    opts.map(c=>`<option value="${c.id}" ${Number(c.id)===Number(selectedId||0)?'selected':''}>${esc(c.code?c.code+' — ':'')}${esc(c.name)}</option>`).join('');
}
function payBankFeeHtml(prefix, selectedFeeCcId){
  return `<div class="fg" id="${prefix}-fee-fg" data-csp-style="${CSP.style(`display:none`)}"><label>کارمزد خدمات بانکی (ریال) ${hlp('فقط وقتی وجه از حساب بانکی شرکت خارج می‌شود. از همان بانک کسر و روی برگ کارمزد (معین زیر ۶۱۱۵) می‌نشیند. مبلغ طرف‌حساب شامل کارمزد نیست.')}</label><input id="${prefix}-fee" type="text" inputmode="numeric" class="money" placeholder="۰"></div>
    <div class="fg" id="${prefix}-fee-cc-fg" data-csp-style="${CSP.style(`display:none`)}"><label>مرکز هزینه کارمزد بانکی ${hlp('مرکز جدا برای سطر کارمزد (۶۱۱۵). اگر خالی بماند و مرکز سند پر باشد همان مرکز استفاده می‌شود. با روشن بودن «الزام مرکز هزینه» وقتی کارمزد > ۰ اجباری است.')}</label>
      <select id="${prefix}-fee-cc">${payFeeCcOptionsHtml(selectedFeeCcId)}</select></div>`;
}
function payFeeCcVal(prefix){
  return +el(prefix+'-fee-cc')?.value||null;
}
function syncPayFeeCcDefault(prefix, docCcId){
  const sel=el(prefix+'-fee-cc');
  if(!sel || sel.value) return;
  const doc=+docCcId||0;
  if(doc) sel.value=String(doc);
}
/** Leaf under coa_bank_fee (6115) for party-voucher fee lines — never post to a parent group. */
function resolveBankFeeCodeForUi(){
  const root=String((CACHE.settings||{}).coa_bank_fee||'6115').trim()||'6115';
  const walk=(code)=>{
    if(!code) return '';
    if(typeof vcCoaIsLeaf==='function' ? vcCoaIsLeaf(code) : !(CACHE.chartOfAccounts||[]).some(a=>a.parent_code===code && a.is_active!==0)) return code;
    const kids=(CACHE.chartOfAccounts||[]).filter(a=>a.parent_code===code && a.is_active!==0)
      .sort((a,b)=>String(a.code).localeCompare(String(b.code),'en'));
    for(const k of kids){
      const leaf=walk(k.code);
      if(leaf) return leaf;
    }
    return '';
  };
  return walk(root)||root;
}
function payFeeVal(prefix){
  const n=moneyVal(prefix+'-fee');
  return (n&&n>0)?n:0;
}
function toggleBankFields(prefix){
  const pt=el(prefix+'-paytype')?.value||'cash';
  const isChequeIn = pt==='cheque' && payFlow(prefix)==='in';
  const isChequeBook = pt==='cheque_book' || (pt==='cheque' && payFlow(prefix)==='out');
  const isChequeRecv = pt==='cheque_recv';
  const isChequeOut = isChequeBook || isChequeRecv;
  const isBank = pt==='bank' || pt==='bank_transfer';
  const isCash = pt==='cash';
  const isPos = pt==='pos_card';
  const inbound=payFlow(prefix)==='in';
  const bankFg=payFg(prefix,'bank');
  const cashFg=payFg(prefix,'cashbox');
  const posFg=el(prefix+'-pos-fg');
  const ccWrap=el(prefix+'-cc-wrap');
  const feeFg=el(prefix+'-fee-fg');
  const feeCcFg=el(prefix+'-fee-cc-fg');
  const refFg=el(prefix+'-bankref-fg');
  const chequeBlock=el(prefix+'-cheque-block');
  const outBlock=el(prefix+'-cheque-out-block');
  const bookFields=el(prefix+'-cheque-book-fields');
  const recvFields=el(prefix+'-cheque-recv-fields');
  if(bankFg) bankFg.style.display=(isBank||isChequeBook)?'flex':'none';
  if(cashFg) cashFg.style.display=isCash?'flex':'none';
  if(posFg) posFg.style.display=isPos?'flex':'none';
  if(refFg) refFg.style.display=isBank?'flex':'none';
  if(chequeBlock){
    chequeBlock.style.display=isChequeIn?'block':'none';
    if(isChequeIn && prefix==='prr' && typeof renderPrrCheques==='function') renderPrrCheques();
    if(isChequeIn && typeof chequeBlock.scrollIntoView==='function') chequeBlock.scrollIntoView({block:'nearest'});
  }
  if(outBlock) outBlock.style.display=isChequeOut?'block':'none';
  if(bookFields) bookFields.style.display=isChequeBook?'block':'none';
  if(isChequeBook){
    ensureBankBranchesCache().then(rows=>{
      const dl=el(prefix+'-chq-branch-dl');
      if(!dl) return;
      const labels=[];
      (rows||[]).forEach(r=>{
        const v=String(r.branch_name||r.branch_code||'').trim();
        if(!v||v==='0') return;
        labels.push(bankBranchDisplayLabel(r));
      });
      dl.innerHTML=[...new Set(labels)].map(n=>`<option value="${esc(n)}"></option>`).join('');
    }).catch(()=>{});
  }
  if(recvFields){
    recvFields.style.display=isChequeRecv?'block':'none';
    if(isChequeRecv) loadRecvChequesForPay(prefix);
  }
  const amtFg=el(prefix+'-amount')?.closest('.fg');
  if(amtFg){
    const multiOn=!!el(prefix+'-multi')?.checked && !isChequeIn && !isChequeRecv;
    if(isChequeIn || isChequeRecv) amtFg.style.display='none';
    else if(chequeBlock || outBlock) amtFg.style.display=multiOn?'none':'flex';
  }
  if((isChequeIn||isChequeRecv||isChequeBook) && el(prefix+'-multi')?.checked){
    el(prefix+'-multi').checked=false;
    const box=el(prefix+'-multi-block'); if(box) box.style.display='none';
  }
  if(ccWrap){ ccWrap.style.display=isChequeBook?'flex':'none'; if(isChequeBook) updateCheckCategoryOptions(prefix); }
  if(feeFg){
    feeFg.style.display=isBank?'flex':'none';
    if(!isBank && el(prefix+'-fee')) el(prefix+'-fee').value='';
  }
  if(feeCcFg){
    feeCcFg.style.display=isBank?'flex':'none';
    if(!isBank && el(prefix+'-fee-cc')) el(prefix+'-fee-cc').value='';
  }
  if(!(isBank || isChequeBook) && el(prefix+'-bank')) el(prefix+'-bank').value='';
  if(!isCash && el(prefix+'-cashbox')) el(prefix+'-cashbox').value='';
  if(!isPos && el(prefix+'-pos')) el(prefix+'-pos').value='';
  payDestSummary(prefix);
}
// Shared: repopulate the دسته چک select to only show checkbooks for the chosen bank
function updateCheckCategoryOptions(prefix){
  const bankId=+el(prefix+'-bank')?.value||0;
  const sel=el(prefix+'-checkcat'); if(!sel) return;
  const opts=(CACHE.checkCategories||[]).filter(c=>c.active&&(!bankId||c.bank_id===bankId));
  sel.innerHTML='<option value="">— انتخاب نشده —</option>'+opts.map(c=>`<option value="${c.id}">${esc(c.name)} (${esc(c.bank_name||'')})</option>`).join('');
}
async function saveSupplierPayment(id){
  const amount=moneyVal('sp-amount');
  if(!amount||amount<=0){ showToast('مبلغ معتبر وارد کنید','error'); return; }
  const pay_type=el('sp-paytype')?.value||'cash';
  if(isOutboundChequePay(pay_type)){
    let party_id=0;
    const sup=(CACHE.suppliers||[]).find(x=>Number(x.id)===Number(id));
    party_id=sup&&sup.party_id?Number(sup.party_id):0;
    if(!party_id) party_id=+el('spChqParty')?.value||0;
    try{
      if(typeof initPartySearches==='function') initPartySearches(el('modalRoot'));
      const ok=await saveOutboundChequePayment('sp',{
        party_id, supplier_id:id, amount,
        note:el('sp-note')?.value||'', party_settle:true
      });
      if(!ok) return;
      closeModal(); showToast('پرداخت چک ثبت شد'); loadAccTab('suppliers');
    }catch(e){ showToast((e&&e.message)||'ثبت پرداخت چک ناموفق بود','error'); }
    return;
  }
  const fee=payFeeVal('sp');
  const feeCc=payFeeCcVal('sp');
  if(fee>0 && isExpenseCcRequired() && !feeCc){ showToast('مرکز هزینه کارمزد بانکی الزامی است','error'); return; }
  try{
    await api('POST','/purchases/payments',{
      supplier_id:id, amount:amount, pay_type,
      date:el('sp-date').value, note:payNoteWithRef('sp', el('sp-note').value),
      bank_id:+el('sp-bank').value||null,
      cash_box_id:+el('sp-cashbox')?.value||null,
      check_category_id:+el('sp-checkcat')?.value||null,
      fee_rial:fee,
      fee_cost_center_id:feeCc
    });
    closeModal(); showToast('پرداخت ثبت شد'); loadAccTab('suppliers');
  }catch(e){}
}

