async function saveSalesReturn(){
  const cust_id=+el('sr-cust').value;
  if(!cust_id){ showToast('مشتری را انتخاب کنید','error'); return; }
  const mode=srMode();
  let invoice_id=null, rows=[];
  if(mode==='linked'){
    invoice_id=+el('sr-invoice')?.value||0;
    if(!invoice_id){ showToast('یک فاکتور را انتخاب کنید','error'); return; }
    rows=[...document.querySelectorAll('.sr-qty-input')].map(inp=>({
      product_id:+inp.dataset.pid,
      variant_id:+inp.dataset.vid||null,
      qty:+inp.value||0,
    })).filter(r=>r.qty>0);
  } else {
    if(!canOpenReturnWithoutInvoice()){ showToast('برگشت بدون فاکتور فقط برای مدیر/حسابداری است','error'); return; }
    rows=srOpenRows.filter(r=>r.qty>0).map(r=>({
      product_id:r.product_id, qty:r.qty, price:r.price,
      variant_id:r.variant_id||null,
      color_name:r.color_name||'',
      size_name:r.size_name||'',
      warehouse_id:r.warehouse_id||null,
    }));
  }
  if(!rows.length){ showToast('حداقل برای یک کالا تعداد برگشتی وارد کنید','error'); return; }
  const warehouse_id=+el('sr-wh')?.value||null;
  if(!invoice_id&&!warehouse_id&&rows.some(r=>!r.warehouse_id)){ showToast('برگشت بدون فاکتور: انبار مقصد برگشت را انتخاب کنید','error'); el('sr-wh')?.focus(); return; }
  const reason_code=(el('sr-reason')?.value||'').trim();
  const extraDisc=returnExtraDiscInputs('sr');
  const payload={
    cust_id,invoice_id,warehouse_id,date:el('sr-date').value,note:el('sr-note').value,rows,
    extra_disc_amt:extraDisc.amt||0,
    extra_disc_pct:extraDisc.pct||0,
  };
  if(reason_code) payload.reason_code=reason_code;
  try{
    if(_srEditId){
      await api('PUT','/accounting/sales-returns/'+_srEditId,payload);
      closeModal(); showToast('برگشت از فروش ویرایش شد'); _srEditId=null; loadAccTab('sales-returns');
    } else {
      await api('POST','/accounting/sales-returns',payload);
      closeModal(); showToast('برگشت از فروش ثبت شد'); loadAccTab('sales-returns');
    }
  }catch(e){}
}
async function deleteSalesReturn(id){
  if(!confirm('این برگشت ابطال شود؟ (سند معکوس ثبت می‌شود)')) return;
  try{ await api('DELETE','/accounting/sales-returns/'+id); showToast('ابطال شد'); loadAccTab('sales-returns'); }catch(e){}
}

