let PRODUCT_GROUP_FILTER='';
let PRODUCT_GROUP_VIEW='tree'; // tree | flat | shared | private
async function renderProductGroupsTab(body){
  const groupFilter=PRODUCT_GROUP_FILTER;
  const view=PRODUCT_GROUP_VIEW||'tree';
  const rows=await api('GET','/product-categories')||[];
  const byId=Object.fromEntries(rows.map(r=>[r.id,r]));
  const usable=rows.filter(g=>g.code!==0);
  const roots=usable.filter(g=>!g.parent_id);
  const subs=usable.filter(g=>!!g.parent_id);
  const sharedN=usable.filter(g=>g.is_shared).length;
  const privateN=usable.length-sharedN;
  const prodTotal=usable.reduce((s,g)=>s+(g.product_count||0),0);
  const childrenOf=pid=>usable.filter(g=>g.parent_id==pid);
  const orphanSubs=subs.filter(g=>!byId[g.parent_id]||byId[g.parent_id]?.code===0);

  let list=usable;
  if(view==='shared') list=usable.filter(g=>g.is_shared);
  else if(view==='private') list=usable.filter(g=>!g.is_shared);
  else if(groupFilter) list=usable.filter(g=>g.id===+groupFilter||g.parent_id===+groupFilter);

  const childHtml=g=>`
    <div class="grp-child" data-grp-q="${esc(((g.name||'')+' '+(g.code||'')+' '+(byId[g.parent_id]?.name||'')).toLowerCase())}">
      <div class="grp-node-ico sub">${lucide('tags')}</div>
      <div class="grp-node-main">
        <b>${esc(g.name)}</b>
        <div class="meta">
          <span class="mono">کد ${g.code||'—'}</span>
          <span>${fmt(g.product_count||0)} کالا</span>
          ${g.is_shared?'<span class="tag t-done">مجاز</span>':'<span class="tag t-cancel">خصوصی</span>'}
        </div>
      </div>
      <div class="grp-node-ops">
        <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){event.stopPropagation();productGroupModal((g.id))})}" title="ویرایش">${lucide('pen')}</button>
        <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){event.stopPropagation();deleteProductGroup((g.id))})}" title="حذف">حذف</button>
      </div>
    </div>`;

  const treeHtml=roots.map(r=>{
    const kids=childrenOf(r.id);
    const open=groupFilter && (String(r.id)===String(groupFilter) || kids.some(k=>String(k.id)===String(groupFilter)));
    return `<div class="grp-node ${open||!groupFilter?'open':''}" data-grp-q="${esc(((r.name||'')+' '+(r.code||'')+' '+kids.map(k=>k.name).join(' ')).toLowerCase())}" data-grp-node>
      <div class="grp-node-head" data-csp-click="${CSP.bind('click',function(event){grpToggleNode(this)})}">
        <span class="grp-chev">${lucide('back')}</span>
        <div class="grp-node-ico">${lucide('folder')}</div>
        <div class="grp-node-main">
          <b>${esc(r.name)}</b>
          <div class="meta">
            <span class="mono">کد ${r.code||'—'}</span>
            <span>${fmt(kids.length)} زیرگروه</span>
            <span>${fmt(r.product_count||0)} کالا</span>
            ${r.is_shared?'<span class="tag t-done">مجاز</span>':'<span class="tag t-cancel">خصوصی</span>'}
          </div>
        </div>
        <div class="grp-node-ops" data-csp-click="${CSP.bind('click',function(event){event.stopPropagation()})}">
          <button class="btn sm ghost" title="زیرگروه جدید" data-csp-click="${CSP.bind('click',function(event){productGroupModal(0,(r.id))})}">${lucide('sparkles')}</button>
          <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){productGroupModal((r.id))})}" title="ویرایش">${lucide('pen')}</button>
          <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deleteProductGroup((r.id))})}" title="حذف">حذف</button>
        </div>
      </div>
      <div class="grp-node-body">
        ${kids.length?kids.map(childHtml).join(''):`<div class="muted" data-csp-style="${CSP.style(`font-size:12px;padding:6px 0`)}">زیرگروهی ندارد — با دکمه ستاره زیرگروه بسازید.</div>`}
      </div>
    </div>`;
  }).join('');

  const flatHtml=`<div class="grp-card-grid" id="grp-grid-prg">${list.map(g=>`
    <div class="grp-card" data-grp-q="${esc(((g.name||'')+' '+(g.code||'')+' '+(byId[g.parent_id]?.name||'')).toLowerCase())}">
      <div class="grp-card-top">
        <div class="grp-node-ico ${g.parent_id?'sub':''}">${lucide(g.parent_id?'tags':'folder')}</div>
        <div data-csp-style="${CSP.style(`flex:1;min-width:0`)}">
          <h4>${esc(g.name)}</h4>
          <div class="muted">${g.parent_id?('زیرگروهِ '+esc(byId[g.parent_id]?.name||'—')):'گروه اصلی'} · کد ${g.code||'—'}</div>
        </div>
      </div>
      <div class="grp-card-foot">
        <div data-csp-style="${CSP.style(`display:flex;gap:6px;flex-wrap:wrap`)}">
          <span class="tag t-new">${fmt(g.product_count||0)} کالا</span>
          ${g.is_shared?'<span class="tag t-done">مجاز</span>':'<span class="tag t-cancel">خصوصی</span>'}
        </div>
        <div class="grp-node-ops">
          ${!g.parent_id?`<button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){productGroupModal(0,(g.id))})}" title="زیرگروه">${lucide('sparkles')}</button>`:''}
          <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){productGroupModal((g.id))})}">${lucide('pen')}</button>
          <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deleteProductGroup((g.id))})}">حذف</button>
        </div>
      </div>
    </div>`).join('')}</div>`;

  body.innerHTML=`
    <div class="grp-shell">
      ${grpHubSwitch('product-groups')}
      <div class="grp-hero">
        <div class="grp-hero-top">
          <div>
            <h2>${lucide('tags')} گروه‌ها و زیرگروه‌های کالا</h2>
            <p>گروه اصلی و زیرگروه‌ها را درختی ببینید، جستجو کنید، و دسترسی نمایش (مجاز/خصوصی) را مدیریت کنید.</p>
          </div>
          <div class="grp-hero-actions">
            <button class="btn" data-csp-click="${CSP.bind('click',function(event){productGroupModal()})}">${lucide('folder')} گروه اصلی</button>
            <button class="btn green" data-csp-click="${CSP.bind('click',function(event){productGroupModal(0,'pick')})}">${lucide('sparkles')} زیرگروه جدید</button>
          </div>
        </div>
        <div class="grp-stats">
          <div class="grp-stat"><div class="v">${fmt(roots.length)}</div><div class="l">گروه اصلی</div></div>
          <div class="grp-stat"><div class="v">${fmt(subs.length)}</div><div class="l">زیرگروه</div></div>
          <div class="grp-stat"><div class="v">${fmt(prodTotal)}</div><div class="l">کالا</div></div>
          <div class="grp-stat"><div class="v">${fmt(privateN)}</div><div class="l">خصوصی</div></div>
        </div>
      </div>
      <div class="grp-toolbar">
        <input type="search" id="grp-q-prg" placeholder="جستجو در گروه‌ها و زیرگروه‌ها…" data-csp-input="${CSP.bind('input',function(event){grpFilterProductGroups(this.value)})}">
        <div class="grp-chips">
          <button type="button" class="grp-chip ${view==='tree'?'active':''}" data-csp-click="${CSP.bind('click',function(event){setProductGroupView('tree')})}">درختی</button>
          <button type="button" class="grp-chip ${view==='flat'?'active':''}" data-csp-click="${CSP.bind('click',function(event){setProductGroupView('flat')})}">کارتی</button>
          <button type="button" class="grp-chip ${view==='shared'?'active':''}" data-csp-click="${CSP.bind('click',function(event){setProductGroupView('shared')})}">فقط مجاز (${fmt(sharedN)})</button>
          <button type="button" class="grp-chip ${view==='private'?'active':''}" data-csp-click="${CSP.bind('click',function(event){setProductGroupView('private')})}">فقط خصوصی (${fmt(privateN)})</button>
        </div>
      </div>
      ${usable.length
        ? (view==='tree'
            ? `<div class="grp-tree" id="grp-grid-prg">${treeHtml}${orphanSubs.length?`<div class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-top:8px`)}">زیرگروه‌های بدون والد معتبر:</div>${orphanSubs.map(childHtml).join('')}`:''}</div>`
            : flatHtml)
        : `<div class="grp-empty">هنوز گروه کالایی نیست — «گروه اصلی» را بزنید.</div>`}
      <div id="grp-empty-prg" class="grp-empty" data-csp-style="${CSP.style(`display:none`)}">نتیجه‌ای پیدا نشد.</div>
    </div>`;
}
function setProductGroupView(v){ PRODUCT_GROUP_VIEW=v; PRODUCT_GROUP_FILTER=''; loadAccTab('product-groups'); }
function filterProductGroup(id){ PRODUCT_GROUP_FILTER=id; PRODUCT_GROUP_VIEW='tree'; loadAccTab('product-groups'); }
function grpFilterProductGroups(q){
  q=(q||'').trim().toLowerCase();
  const grid=el('grp-grid-prg'); if(!grid) return;
  let n=0;
  grid.querySelectorAll('[data-grp-q]').forEach(c=>{
    const hay=c.getAttribute('data-grp-q')||'';
    const ok=!q||hay.includes(q);
    if(c.classList.contains('grp-node')){
      c.style.display=ok?'':'none';
      if(ok && q) c.classList.add('open');
    } else {
      c.style.display=ok?'':'none';
    }
    if(ok) n++;
  });
  const empty=el('grp-empty-prg');
  if(empty) empty.style.display=n?'none':'block';
}
async function productGroupModal(id, parentHint){
  const list=await api('GET','/product-categories')||[];
  const g=id?(list.find(x=>x.id===id)||{}):{};
  let parentVal=g.parent_id||'';
  if(!id && parentHint && parentHint!=='pick') parentVal=parentHint;
  const roots=list.filter(x=>x.id!==id && !x.parent_id && x.code!==0);
  const needPick=!id && parentHint==='pick';
  openModal(`
    <div class="modal-head"><h3>${id?'ویرایش گروه کالا':(parentVal||needPick?'زیرگروه جدید':'گروه اصلی جدید')}</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg"><label>کد</label><input id="prg-code" type="number" value="${g.code||''}"></div>
      <div class="fg full"><label>نام گروه *</label><input id="prg-name" value="${esc(g.name||'')}" autofocus></div>
      <div class="fg full"><label>گروه والد ${hlp('اگر والد انتخاب شود، این مورد به‌عنوان زیرگروه ثبت می‌شود.')}</label>
        <select id="prg-parent"><option value="">— بدون والد (گروه اصلی) —</option>
        ${list.filter(x=>x.id!==id && x.code!==0).map(x=>`<option value="${x.id}" ${String(parentVal)==String(x.id)?'selected':''}>${esc(x.name)}${x.parent_id?' (زیرگروه)':''}</option>`).join('')}</select></div>
      <div class="fg full">${typeof settToggle==='function'?settToggle('prg-shared', g.is_shared!==0,'اجازه نمایش به سایر کاربران','اگر خاموش باشد فقط ایجادکننده، مدیر و حسابدار می‌بینند'):`<label data-csp-style="${CSP.style(`display:flex;align-items:center;gap:8px;cursor:pointer`)}"><input id="prg-shared" type="checkbox" data-csp-style="${CSP.style(`width:auto`)}" ${g.is_shared!==0?'checked':''}> اجازه نمایش به سایر کاربران</label>`}</div>
      ${moayanAcctHtml('prg','حساب معین این گروه کالا — اختیاری؛ فقط حساب برگ. تغییر نگاشت روی اسناد قبلی اثر ندارد.')}
      ${ivalLevelFieldHtml('prg-val-level',g.valuation_level,'انبار / سراسری')}
      <div class="fg full"><label>توضیحات</label><textarea id="prg-desc">${esc(g.description||'')}</textarea></div>
    </div></div>
    <div class="modal-foot"><button class="btn" data-csp-click="${CSP.bind('click',function(event){saveProductGroup((id||0))})}">ذخیره</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
  if(needPick && roots.length===1){ const sel=el('prg-parent'); if(sel) sel.value=String(roots[0].id); }
  if(!CACHE.chartOfAccounts) CACHE.chartOfAccounts=await api('GET','/accounting/chart-of-accounts')||[];
  if(g.coa_code) moayanAcctPick('prg', g.coa_code);
}
async function saveProductGroup(id){
  const name=el('prg-name').value.trim();
  if(!name){ showToast('نام گروه الزامی است','error'); return; }
  const data={name,code:el('prg-code').value,parent_id:el('prg-parent').value||null,description:el('prg-desc').value,is_shared:el('prg-shared').checked,coa_code:el('prg-account-code')?.value||''};
  if(el('prg-val-level')) data.valuation_level=el('prg-val-level').value||'';
  try{
    if(id) await api('PUT','/product-categories/'+id,data); else await api('POST','/product-categories',data);
    CACHE.productCategories=null; CACHE.productCats=null; CACHE._prodCats=null; CACHE._prodMetaLoaded=false; clearPageCache();
    closeModal(); showToast('ذخیره شد'); loadAccTab('product-groups');
  }catch(e){}
}
async function deleteProductGroup(id){
  if(!confirm('این گروه حذف شود؟')) return;
  try{
    await api('DELETE','/product-categories/'+id);
    CACHE.productCategories=null; CACHE.productCats=null; CACHE._prodCats=null; CACHE._prodMetaLoaded=false; clearPageCache();
    showToast('حذف شد'); loadAccTab('product-groups');
  }catch(e){}
}


/* ============================================================
   WAREHOUSE COMPREHENSIVE REPORT + SYNC DEVICES ADMIN
============================================================ */
/* ── v577 فاز ۴ انبار: نرمال‌سازی ردیف گزارش‌های موجودی/ارزش (منبع: کاردکس Σ) ──
   بک‌اند ممکن است فیلدهای kardex_qty / ledger_value_rial / avg_rate_rial / drift_* / ghost_value بدهد؛
   اگر هنوز نداد، به فیلدهای قدیمی (qty / amount_rial / avg_cost_rial) برمی‌گردیم. */
const WH_REP_EPS_QTY=0.0005, WH_REP_TOL_RIAL=1;
function whRepNum(o,keys){
  if(!o) return null;
  for(let i=0;i<keys.length;i++){
    const v=o[keys[i]];
    if(v!=null&&v!==''&&isFinite(Number(v))) return Number(v);
  }
  return null;
}
function whRepFlagOn(o,keys){
  if(!o) return false;
  const fl=(o.flags&&typeof o.flags==='object'&&!Array.isArray(o.flags))?o.flags:null;
  const arr=Array.isArray(o.flags)?o.flags.map(String):[];
  for(let i=0;i<keys.length;i++){
    const k=keys[i];
    if(o[k]===true||o[k]===1||o[k]==='1') return true;
    if(fl&&(fl[k]===true||fl[k]===1)) return true;
    if(arr.indexOf(k)>=0) return true;
  }
  return false;
}
function whRepNormRow(p){
  p=p||{};
  const hasKardex=p.kardex_qty!=null||p.ledger_qty!=null||p.ledger_value_rial!=null||p.source==='kardex';
  const qty=whRepNum(p,['kardex_qty','ledger_qty','qty','stock']);
  const wsQty=whRepNum(p,['ws_qty','warehouse_qty','stock_qty']);
  const value=whRepNum(p,['ledger_value_rial','value_rial','amount_rial','cost_value']);
  let avg=whRepNum(p,['avg_rate_rial','weighted_avg_rate_rial','weighted_avg_unit_rial','avg_cost_rial','unit_cost_rial','cost']);
  if(avg==null&&qty&&Math.abs(qty)>WH_REP_EPS_QTY&&value!=null) avg=Math.round(value/qty);
  let driftQty=whRepNum(p,['drift_qty','stock_drift_qty','drift_qty_vs_ws','drift_ws_ledger_qty']);
  if(driftQty==null&&hasKardex&&wsQty!=null&&qty!=null) driftQty=qty-wsQty;
  let driftVal=whRepNum(p,['drift_value_rial','drift_value','value_diff_rial','header_value_diff_rial','header_diff_rial']);
  if(driftVal==null){
    const hv=whRepNum(p,['header_value_rial']);
    if(hv!=null&&value!=null) driftVal=value-hv;
  }
  const qtyDrift=driftQty!=null&&Math.abs(driftQty)>WH_REP_EPS_QTY;
  const valDrift=driftVal!=null&&Math.abs(driftVal)>WH_REP_TOL_RIAL;
  const drift=whRepFlagOn(p,['drift_any','drift_ws_ledger','drift_ws_vws','layer_drift','header_drift','warehouse_drift','ws_vs_ledger','ws_vs_vws','header_vs_ws','mismatch','has_drift'])||qtyDrift;
  const negQty=whRepFlagOn(p,['negative_qty'])||(qty!=null&&qty<-WH_REP_EPS_QTY);
  const negValFlag=whRepFlagOn(p,['negative_value']);
  const ghost=whRepFlagOn(p,['ghost_value','zero_qty_nonzero_value','zero_qty_value'])
    ||(qty!=null&&Math.abs(qty)<WH_REP_EPS_QTY&&value!=null&&Math.abs(value)>WH_REP_TOL_RIAL);
  const negVal=(negValFlag||(value!=null&&value<-WH_REP_TOL_RIAL))&&!ghost;
  const flags=[];
  if(ghost) flags.push({key:'ghost',level:'bad',label:'مقدار ۰ با ارزش ≠ ۰',title:'موجودی صفر است اما ارزش ریالی کاردکس صفر نیست (مثل WIP یا باقی‌ماندهٔ تعدیل)'});
  if(drift) flags.push({key:'drift',level:'bad',label:'اختلاف با لایهٔ دیگر',title:'جمع کاردکس با موجودی انبار / رنگ‌وسایز نمی‌خواند؛ اختلاف = لایهٔ دیگر − کاردکس (گزارش «تطبیق موجودی»)'});
  if(negQty&&!ghost) flags.push({key:'negqty',level:'warn',label:'موجودی منفی',title:'جمع کاردکس منفی است'});
  if(negVal) flags.push({key:'negval',level:'warn',label:'ارزش منفی',title:'ارزش ریالی کاردکس منفی است (مثل کالای 334 / WIP؛ علت را در کاردکس بررسی کنید)'});
  if(valDrift&&!drift) flags.push({key:'valdrift',level:'warn',label:'ارزش ≠ سرستون',title:'ارزش کاردکس با «موجودی × میانگین سرستون» فرق دارد؛ مبنای گزارش ارزش کاردکس است'});
  return {qty:qty,wsQty:wsQty,value:value,avg:avg,driftQty:driftQty,driftVal:driftVal,drift:drift,ghost:ghost,flags:flags,fromKardex:hasKardex};
}
function whRepFlagsHtml(n){
  if(!n||!n.flags.length) return '<span class="rcn-ok">✓</span>';
  return '<div class="rcn-flags">'+n.flags.map(f=>`<span class="rcn-flag ${f.level==='warn'?'warn':''}" title="${esc(f.title||'')}">${esc(f.label)}</span>`).join('')+'</div>';
}
function whRepDriftHtml(n){
  if(!n) return '<span class="muted">—</span>';
  const parts=[];
  if(n.driftQty!=null&&Math.abs(n.driftQty)>WH_REP_EPS_QTY) parts.push(`<span class="rcn-diff" title="اختلاف تعداد (لایهٔ دیگر − کاردکس)">${fmtQtyFa(n.driftQty)} عدد</span>`);
  if(n.driftVal!=null&&Math.abs(n.driftVal)>WH_REP_TOL_RIAL) parts.push(`<span class="whrep-drift-val" title="اختلاف ارزش کاردکس با «موجودی × میانگین سرستون»">${fmt(n.driftVal)} ر</span>`);
  return parts.length?parts.join('<br>'):'<span class="muted">—</span>';
}
function whRepFlagText(n){ return n&&n.flags.length?n.flags.map(f=>f.label).join(' | '):''; }
async function renderWarehouseReportTab(body){
  const whs=await api('GET','/warehouses')||[];
  body.innerHTML=`
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px;flex-wrap:wrap;gap:8px;align-items:center`)}">
      <select id="whRepWh" data-csp-style="${CSP.style(`padding:7px 10px;border-radius:8px;border:1.5px solid var(--border)`)}">
        <option value="">همه انبارها</option>
        ${whs.filter(w=>w.active!==0).map(w=>`<option value="${w.id}">${esc(w.name)}</option>`).join('')}
      </select>
      <input id="whRepQ" placeholder="جستجو کالا..." data-csp-style="${CSP.style(`padding:7px 10px;border:1.5px solid var(--border);border-radius:8px;min-width:180px`)}">
      <label data-csp-style="${CSP.style(`font-size:12px;display:flex;align-items:center;gap:4px`)}"><input type="checkbox" id="whRepZero"> شامل موجودی صفر</label>
      <label data-csp-style="${CSP.style(`font-size:12px;display:flex;align-items:center;gap:4px`)}"><input type="checkbox" id="whRepFlagged" data-csp-change="${CSP.bind('change',function(){ if(window._whRepLast) loadWarehouseReport(); })}"> فقط ردیف‌های دارای پرچم</label>
      <button class="btn sm" data-csp-click="${CSP.bind('click',function(event){loadWarehouseReport()})}">اعمال فیلتر</button>
      <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){exportWarehouseReportExcel()})}">خروجی اکسل</button>
    </div>
    <div id="whRepBody"><div class="muted">انبار را انتخاب یا فیلتر را اعمال کنید…</div></div>`;
  loadWarehouseReport();
}
async function loadWarehouseReport(){
  const box=el('whRepBody'); if(!box) return;
  box.innerHTML='<div class="muted">در حال بارگذاری...</div>';
  const wh=el('whRepWh')?.value||'';
  const q=el('whRepQ')?.value||'';
  const zero=el('whRepZero')?.checked?'1':'0';
  const qs=['include_zero='+zero];
  if(wh) qs.push('warehouse_id='+encodeURIComponent(wh));
  if(q) qs.push('q='+encodeURIComponent(q));
  const data=await api('GET','/warehouses/stock/report?'+qs.join('&'))||{rows:[]};
  window._whRepLast=data;
  const onlyFlagged=!!el('whRepFlagged')?.checked;
  let flagTotal=0, ghostTotal=0, driftTotal=0;
  const blocks=(data.rows||[]).map(r=>{
    const all=(r.products||[]).map(p=>({p:p,n:whRepNormRow(p)}));
    all.forEach(x=>{ if(x.n.flags.length) flagTotal++; if(x.n.ghost) ghostTotal++; if(x.n.drift) driftTotal++; });
    const rows=onlyFlagged?all.filter(x=>x.n.flags.length):all;
    // جمع کل از Σ کاردکس (اگر سرور نداد: از جمع ردیف‌ها)
    const sumQty=whRepNum(r,['kardex_total_qty','ledger_total_qty','total_qty']);
    const sumVal=whRepNum(r,['ledger_total_value_rial','total_value_rial','total_amount_rial']);
    let wQty=0,wVal=0;
    all.forEach(x=>{ if(x.n.qty!=null&&x.n.qty>0&&x.n.value!=null){ wQty+=x.n.qty; wVal+=x.n.value; } });
    const srvAvg=whRepNum(r,['avg_rate_rial','weighted_avg_rate_rial']);
    const whAvg=srvAvg!=null?srvAvg:(wQty>0?Math.round(wVal/wQty):(r.avg_unit_cost_rial||0));
    const flagCnt=all.filter(x=>x.n.flags.length).length;
    return `<div class="panel" data-csp-style="${CSP.style(`margin-bottom:14px`)}"><div class="panel-head"><h4>${esc(r.warehouse_name)} <span class="muted mono">${esc(r.warehouse_code||'')}</span></h4>
      <span class="muted" data-csp-style="${CSP.style(`font-size:12px`)}">${fmt(r.product_count)} کالا · موجودی (کاردکس) ${fmtQtyFa(sumQty!=null?sumQty:r.total_qty)} · ارزش ریالی (کاردکس) ${fmt(sumVal!=null?sumVal:(r.total_amount_rial||0))} · میانگین موزون ${fmt(whAvg)}${flagCnt?` · <b class="whrep-flag-count">${fmt(flagCnt)} پرچم</b>`:''}</span></div>
      <div class="panel-body"><div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
        <th>کد</th><th>نام</th><th>گروه</th><th data-col-kind="qty">موجودی (کاردکس)</th><th data-col-kind="avg">میانگین موزون این انبار</th><th data-col-kind="money">ارزش ریالی (کاردکس)</th><th>اختلاف با لایهٔ دیگر</th><th>پرچم</th><th data-col-kind="avg">قیمت فروش</th><th data-col-kind="money">ارزش فروش</th>
      </tr></thead><tbody>${rows.map(x=>{ const p=x.p, n=x.n; return `<tr class="${n.ghost?'whrep-ghost':(n.drift?'whrep-drift':'')}">
        <td class="mono">${esc(p.code||'-')}</td><td>${esc(p.name)}</td><td class="muted">${esc(p.category||'-')}</td>
        <td class="mono${n.drift?' rcn-diff':''}" data-col-kind="qty">${fmtQtyFa(n.qty||0)}</td>
        <td class="mono" data-col-kind="avg">${fmt(n.avg||0)}</td>
        <td class="mono${n.ghost||(n.value!=null&&n.value<0)?' rcn-diff':''}" data-col-kind="money">${fmt(n.value||0)}</td>
        <td class="mono">${whRepDriftHtml(n)}</td>
        <td>${whRepFlagsHtml(n)}</td>
        <td class="mono" data-col-kind="avg">${fmt(p.unit_price_rial||0)}</td>
        <td class="mono" data-col-kind="money">${fmt(p.sales_value_rial||0)}</td>
      </tr>`; }).join('')||emptyRow(10)}</tbody></table></div></div></div>`;
  }).join('')||'<div class="empty">داده‌ای نیست</div>';
  const srcNote=`<div class="muted whrep-src" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:10px;line-height:1.9`)}">منبع عدد و ارزش: <b>جمع کاردکس (Σ) هر کالا×انبار</b> — «میانگین موزون» = ارزش ریالی ÷ موجودی همان انبار. ردیف قرمز: مقدار صفر با ارزش ≠ ۰ یا اختلاف با لایهٔ دیگر (جزئیات و اصلاح: «تطبیق موجودی»).${flagTotal?` <b class="whrep-flag-count">${fmt(flagTotal)} ردیف پرچم‌دار (${fmt(ghostTotal)} مقدار ۰ با ارزش، ${fmt(driftTotal)} اختلاف لایه)</b>`:''}</div>`;
  box.innerHTML=srcNote+blocks;
  if(typeof enhanceAccTables==='function') enhanceAccTables(box);
}
function exportWarehouseReportExcel(){
  const data=window._whRepLast; if(!data||!data.rows){ showToast('ابتدا گزارش را بارگذاری کنید','error'); return; }
  const flat=[];
  const onlyFlagged=!!el('whRepFlagged')?.checked;
  (data.rows||[]).forEach(r=>{(r.products||[]).forEach(p=>{
    const n=whRepNormRow(p);
    if(onlyFlagged&&!n.flags.length) return;
    flat.push({
      'انبار': r.warehouse_name, 'کد انبار': r.warehouse_code||'',
      'کد کالا': p.code||'', 'نام کالا': p.name||'', 'گروه': p.category||'',
      'موجودی (کاردکس)': n.qty||0, 'میانگین موزون انبار (ریال)': n.avg||0,
      'ارزش ریالی (کاردکس)': n.value||0,
      'اختلاف تعداد با لایهٔ دیگر': n.driftQty==null?'':n.driftQty,
      'اختلاف ارزش (ریال)': n.driftVal==null?'':n.driftVal,
      'پرچم': whRepFlagText(n),
      'قیمت فروش (ریال)': p.unit_price_rial||0,
      'ارزش فروش': p.sales_value_rial||0,
    });
  });});
  if(!flat.length){ showToast('ردیفی برای خروجی نیست','error'); return; }
  // Client-side CSV (Excel-compatible) without new deps
  const keys=Object.keys(flat[0]);
  const lines=[keys.join(',')].concat(flat.map(row=>keys.map(k=>{
    const v=row[k]==null?'':String(row[k]);
    return /[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v;
  }).join(',')));
  const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='warehouse-report.csv'; a.click();
  URL.revokeObjectURL(a.href);
  showToast('خروجی اکسل/CSV آماده شد');
}
