/* ============================================================
   CASH OPS — unified receive (settlements) + pay (outgoing) tab
============================================================ */
/** فیلتر بازهٔ مشترک حسابداری روی فیلد تاریخ جلالی YYYY/MM/DD */
function inAccDateRange(dateStr){
  const d=String(dateStr||'').trim();
  if(!d) return !(accDateFrom||accDateTo);
  if(accDateFrom && d < accDateFrom) return false;
  if(accDateTo && d > accDateTo) return false;
  return true;
}
async function renderCashOpsTab(body, dq){
  const softGet=async (path)=>{
    try{ return await api('GET', path); }
    catch(e){
      if(e && (e.status===403 || e.code==='E_FORBIDDEN')) return null;
      throw e;
    }
  };
  const rows=await softGet('/accounting/settlements'+dq);
  if(rows==null){
    body.innerHTML='<div class="empty">دسترسی مشاهدهٔ دریافت/پرداخت را ندارید. در دسترسی‌های کاربر، مشاهدهٔ «عملیات دریافت و پرداخت» و تب حسابداری را فعال کنید.</div>';
    return;
  }
  const pendingRepPay=await softGet('/reps/payments/pending')||[];
  if(!CACHE.banks) CACHE.banks=await softGet('/banks')||[];
  if(!CACHE.cashBoxes) CACHE.cashBoxes=await softGet('/cash-boxes')||[];
  if(!CACHE.checkCategories){
    try{ CACHE.checkCategories=await softGet('/check-categories')||[]; }
    catch(_){ CACHE.checkCategories=[]; }
  }
  // Companion lists must not 403-kill the whole screen when only acc_settlements is granted.
  const [supPay,incPay,expPay,voucherPay,voucherRecv]=await Promise.all([
    softGet('/purchases/payments/list'),
    softGet('/accounting/incentive-payments'),
    softGet('/expenses'),
    softGet('/accounting/cash-ops/outgoing'),
    softGet('/accounting/cash-ops/incoming-extra')
  ]);
  // پرداخت‌های خروجی API بازه ندارند — همان فیلتر از/تا نوار بالا روی تاریخ سند
  const payRows=[
    ...(Array.isArray(supPay)?supPay:[]).map(r=>({...r,kind:'supplier',target:r.supplier_name||'-'})),
    ...(Array.isArray(incPay)?incPay:[]).map(r=>({...r,kind:'incentive',target:r.rep_name||'-'})),
    ...(Array.isArray(expPay)?expPay:[]).map(r=>({...r,kind:'expense',target:r.title||(r.category==='sales'?'هزینه توزیع و فروش':'هزینه عمومی و اداری')})),
    ...(Array.isArray(voucherPay)?voucherPay:[])
  ].filter(r=>inAccDateRange(r.date)).sort((a,b)=>(b.created_at||0)-(a.created_at||0));
  const recvRows=[
    ...(Array.isArray(rows)?rows:[]).map(r=>({...r,kind:'settlement'})),
    ...(Array.isArray(voucherRecv)?voucherRecv:[])
  ].filter(r=>inAccDateRange(r.date)).sort((a,b)=>(b.created_at||0)-(a.created_at||0));
  window._cashOpsIndex={};
  recvRows.forEach(r=>{ window._cashOpsIndex[(r.kind||'settlement')+':'+r.id]=r; });
  payRows.forEach(r=>{ window._cashOpsIndex[r.kind+':'+r.id]=r; });
  const kindLabel={supplier:'🚚 تأمین‌کننده',incentive:'🎯 انگیزه فروش',expense:'🧾 هزینه عمومی',person:'👤 شخص',account:'📒 حساب'};
  const recvKindLabel={settlement:'👤 مشتری',person_receipt:'🧑 شخص',account_receipt:'📒 حساب'};
  const payLabel=p=>p==='cheque'?'🧾 چک':(p==='bank'||p==='bank_transfer')?'🏦 بانکی':'💵 نقد';
  // دریافت شخص/حساب هنوز amend درجا ندارند — فقط ابطال. پرداخت شخص/حساب مداد دارند.
  const recvNoEdit=new Set(['person_receipt','account_receipt']);
  body.innerHTML=`
    ${(pendingRepPay||[]).length?`<div class="panel" data-csp-style="${CSP.style(`margin-bottom:16px;border-color:#fde68a`)}">
      <div class="panel-head"><h4>⏳ دریافت‌های میدانی در انتظار تأیید (${pendingRepPay.length})</h4></div>
      <div class="panel-body tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
        <th>تاریخ</th><th>نماینده</th><th>مشتری</th><th>نوع</th><th data-col-kind="money">مبلغ</th><th>رسید</th><th>عملیات</th>
      </tr></thead><tbody>${pendingRepPay.map(p=>`<tr>
        <td class="mono">${escDate(p.date)}</td><td>${esc(p.rep_name)}</td>
        <td>${esc(p.cust_biz||'-')}${p.cust_owner?`<br><span class="muted">${esc(p.cust_owner)}</span>`:''}</td>
        <td>${p.pay_type==='cheque'?'🧾 چک':p.pay_type==='bank_transfer'?'🏦 واریز':'💵 نقد'}</td>
        <td class="mono" data-col-kind="money">${fmt(p.amount)}</td>
        <td>${repReceiptBtn(p.receipt_url)}</td>
        <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
          <button class="btn sm green" data-csp-click="${CSP.bind('click',function(event){approveRepPayment((p.id))})}">✅ تأیید</button>
          <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){rejectRepPayment((p.id))})}">❌ رد</button>
        </td>
      </tr>`).join('')}</tbody></table></div>
    </div>`:''}
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px;flex-wrap:wrap;gap:8px`)}">
      <button class="btn green" data-csp-click="${CSP.bind('click',function(event){receiptOpChooser()})}">➕ ثبت دریافت</button>
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){paymentOpChooser()})}">➕ ثبت پرداخت (خروجی)</button>
    </div>
    <h4 data-csp-style="${CSP.style(`margin:0 0 8px`)}">💵 دریافت‌ها</h4>
    <div class="tbl-wrap" data-csp-style="${CSP.style(`margin-bottom:20px`)}"><table class="tbl"><thead><tr>
      <th>تاریخ</th><th>سند مرجع</th><th>نوع</th><th>طرف</th><th>فاکتور</th><th data-col-kind="money">مبلغ ${moneyColLabel()}</th><th>نوع</th><th>گروه قسط</th><th>چک</th><th>یادداشت</th><th>ثبت‌کننده</th><th class="no-sort">عملیات</th>
    </tr></thead><tbody>${recvRows.map(r=>`<tr>
      <td class="mono">${escDate(r.date)}</td>
      <td>${refDocCell(r.ref_doc_no,r.ref_doc_type)}</td>
      <td>${recvKindLabel[r.kind]||'👤 مشتری'}</td>
      <td>${esc(r.cust_biz||r.target||'-')}</td>
      <td class="mono">${r.invoice_num?esc(r.invoice_num):'-'}</td>
      <td class="mono" data-col-kind="money" data-csp-style="${CSP.style(`color:var(--green);font-weight:700`)}">${fmt(r.amount)}</td>
      <td>${r.pay_type==='cheque'?'🧾 چک':(r.pay_type==='bank'||r.pay_type==='bank_transfer')?'🏦 بانکی':'💵 نقد'}</td>
      <td class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">${r.installment_group?esc(r.installment_group):'-'}</td>
      <td class="muted" data-csp-style="${CSP.style(`font-size:12px`)}">${r.pay_type==='cheque'?(esc(r.cheque_bank||'')+' | '+esc(r.cheque_sayadi||'')):'-'}</td>
      <td class="muted">${esc(r.note||'-')}</td>
      <td class="muted">${esc(r.recorder_name||r.recorder||'-')}</td>
      <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
        ${recvNoEdit.has(r.kind)?'':`<button class="btn sm ghost" title="ویرایش سند" data-csp-click="${CSP.bind('click',function(event){editCashDoc(`${String((r.kind)||'settlement')}`,(r.id))})}">✏️</button>`}
        <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){const k=`${String((r.kind) ?? '')}`;if(k==='person_receipt'||k==='account_receipt')deletePaymentOp(k,(r.id));else deleteSettlement((r.id));})}">🗑️</button>
      </td>
    </tr>`).join('')||emptyRow(11)}</tbody></table></div>
    <h4 data-csp-style="${CSP.style(`margin:0 0 8px`)}">💸 پرداخت‌ها (خروجی)</h4>
    <div class="tbl-wrap"><table class="tbl"><thead><tr>
      <th>تاریخ</th><th>سند مرجع</th><th>نوع</th><th>به/بابت</th><th data-col-kind="money">مبلغ ${moneyColLabel()}</th><th>نوع پرداخت</th><th>یادداشت</th><th>ثبت‌کننده</th><th class="no-sort">عملیات</th>
    </tr></thead><tbody>${payRows.map(r=>`<tr>
      <td class="mono">${escDate(r.date)}</td>
      <td>${refDocCell(r.ref_doc_no,r.ref_doc_type)}</td>
      <td>${kindLabel[r.kind]||esc(r.kind)}</td>
      <td>${esc(r.target)}</td>
      <td class="mono" data-col-kind="money" data-csp-style="${CSP.style(`color:var(--red);font-weight:700`)}">${fmt(r.amount)}</td>
      <td>${payLabel(r.pay_type)}</td>
      <td class="muted">${esc(r.note||'-')}</td>
      <td class="muted">${esc(r.recorder||'-')}</td>
      <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
        <button class="btn sm ghost" title="ویرایش سند" data-csp-click="${CSP.bind('click',function(event){editCashDoc(`${String((r.kind) ?? '')}`,(r.id))})}">✏️</button>
        <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deletePaymentOp(`${String((r.kind) ?? '')}`,(r.id))})}">🗑️</button>
      </td>
    </tr>`).join('')||emptyRow(8)}</tbody></table></div>`;
}

/* ============================================================
   PAYMENT OPERATIONS (عملیات پرداخت) — unified view of every outgoing
   payment: supplier payments, sales-incentive payments, and general expense
   payments. Receiving side (customer settlements) lives in acc-settlements.
============================================================ */
async function renderPaymentOpsTab(body){
  if(!CACHE.banks) CACHE.banks=await api('GET','/banks')||[];
  if(!CACHE.cashBoxes) CACHE.cashBoxes=await api('GET','/cash-boxes')||[];
  if(!CACHE.checkCategories) CACHE.checkCategories=await api('GET','/check-categories')||[];
  const softGet=async (path)=>{
    try{ return await api('GET', path); }
    catch(e){
      if(e && (e.status===403 || e.code==='E_FORBIDDEN')) return null;
      throw e;
    }
  };
  const [supPay,incPay,expPay,voucherPay]=await Promise.all([
    softGet('/purchases/payments/list'),
    softGet('/accounting/incentive-payments'),
    softGet('/expenses'),
    softGet('/accounting/cash-ops/outgoing')
  ]);
  const rows=[
    ...(Array.isArray(supPay)?supPay:[]).map(r=>({...r,kind:'supplier',target:r.supplier_name||'-'})),
    ...(Array.isArray(incPay)?incPay:[]).map(r=>({...r,kind:'incentive',target:r.rep_name||'-'})),
    ...(Array.isArray(expPay)?expPay:[]).map(r=>({...r,kind:'expense',target:r.title||(r.category==='sales'?'هزینه توزیع و فروش':'هزینه عمومی و اداری')})),
    ...(Array.isArray(voucherPay)?voucherPay:[])
  ].sort((a,b)=>(b.created_at||0)-(a.created_at||0));
  window._cashOpsIndex=window._cashOpsIndex||{};
  rows.forEach(r=>{ window._cashOpsIndex[r.kind+':'+r.id]=r; });
  const kindLabel={supplier:'🚚 تأمین‌کننده',incentive:'🎯 انگیزه فروش',expense:'🧾 هزینه عمومی',person:'👤 شخص',account:'📒 حساب'};
  const payLabel=p=>p==='cheque'?'🧾 چک':(p==='bank'||p==='bank_transfer')?'🏦 بانکی':'💵 نقد';
  body.innerHTML=`
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px`)}"><button class="btn" data-csp-click="${CSP.bind('click',function(event){paymentOpChooser()})}">➕ پرداخت جدید</button></div>
    <div class="tbl-wrap"><table class="tbl"><thead><tr>
      <th>تاریخ</th><th>نوع</th><th>به/بابت</th><th>مبلغ (ریال)</th><th>نوع پرداخت</th><th>یادداشت</th><th>ثبت‌کننده</th><th>عملیات</th>
    </tr></thead><tbody>${rows.map(r=>`<tr>
      <td class="mono">${escDate(r.date)}</td>
      <td>${kindLabel[r.kind]||esc(r.kind)}</td>
      <td>${esc(r.target)}</td>
      <td class="mono" data-csp-style="${CSP.style(`color:var(--red);font-weight:700`)}">${fmt(r.amount)}</td>
      <td>${payLabel(r.pay_type)}</td>
      <td class="muted">${esc(r.note||'-')}</td>
      <td class="muted">${esc(r.recorder||'-')}</td>
      <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
        <button class="btn sm ghost" title="ویرایش سند" data-csp-click="${CSP.bind('click',function(event){editCashDoc(`${String((r.kind) ?? '')}`,(r.id))})}">✏️</button>
        <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deletePaymentOp(`${String((r.kind) ?? '')}`,(r.id))})}">🗑️</button>
      </td>
    </tr>`).join('')||emptyRow(8)}</tbody>
    <tfoot><tr data-csp-style="${CSP.style(`border-top:2px solid var(--border);background:var(--purple-light);font-weight:700`)}">
      <td colspan="3">جمع (${fmt(rows.length)} پرداخت)</td>
      <td class="mono" data-csp-style="${CSP.style(`color:var(--red);font-weight:800`)}">${fmt(rows.reduce((a,r)=>a+(r.amount||0),0))}</td>
      <td colspan="4"></td>
    </tr></tfoot></table></div>`;
}
function coaAllAccounts(){
  return coaDepthOf(CACHE.chartOfAccounts||[]);
}
function coaSearchKey(s){
  return toEnDigits(String(s==null?'':s))
    .replace(/\u200c/g,'')
    .replace(/[يى]/g,'ی')
    .replace(/ك/g,'ک')
    .replace(/ة/g,'ه')
    .replace(/[أإآ]/g,'ا')
    .replace(/\s+/g,' ')
    .trim()
    .toLowerCase();
}
function coaSearchRank(account, term){
  const code=coaSearchKey(account.code);
  const name=coaSearchKey(account.name);
  if(!term) return 4;
  if(code===term) return 0;
  if(code.startsWith(term)) return 1;
  if(name.startsWith(term)) return 2;
  if(name.split(' ').some(w=>w.startsWith(term))) return 3;
  return 4;
}
function expenseCodingAccount(a){
  if(!a || a.is_active===0) return false;
  // parent+'01' هم معین واقعی است (610301 سوشال مدیا) هم پوستهٔ کنترل (210101).
  // پوستهٔ کنترل نوع هزینه نیست و همین پایین رد می‌شود. حذف الگو، معین اول هر کل را از جستجو می‌انداخت.
  const t=String(a.type||'').toLowerCase();
  const code=String(a.code||'');
  if(t==='expense'||t==='cogs') return true;
  return code.startsWith('5')||code.startsWith('6');
}
function coaAcctHtml(prefix, help, opts){
  const any=!!(opts&&opts.any);
  const optional=!!(opts&&opts.optional);
  const scope=(opts&&opts.scope)||'';
  const label=scope==='expense'
    ? 'حساب هزینه (هر سطح کدینگ)'
    : (any?'حساب (هر سطح کدینگ)':'حساب برگ (قابل ثبت)');
  const tip=help||(any
    ?'هر حساب فعال: گروه، کل، معین یا تفصیلی. مبلغ روی خود همان کد سند می‌شود.'
    :'فقط حساب بدون فرزند فعال');
  return `<div class="fg full coa-combo"><label id="${prefix}-account-label" for="${prefix}-account-search">${label}${optional?'':' *'} ${hlp(tip)}</label>
    <input type="hidden" id="${prefix}-account-code" value="">
    <input type="text" id="${prefix}-account-search" class="search" role="combobox" autocomplete="off" spellcheck="false"
      placeholder="جستجوی حساب: کد یا نام..." aria-autocomplete="list" aria-expanded="false"
      aria-controls="${prefix}-acct-drop" aria-labelledby="${prefix}-account-label"
      data-coa-any="${any?'1':'0'}" data-coa-scope="${esc(scope)}"
      data-csp-input="${CSP.bind('input',function(event){coaAcctShow(`${String((prefix) ?? '')}`,this.value)})}"
      data-csp-focus="${CSP.bind('focus',function(event){coaAcctShow(`${String((prefix) ?? '')}`,this.value)})}"
      data-csp-keydown="${CSP.bind('keydown',function(event){coaAcctKey(`${String((prefix) ?? '')}`,event)})}"
      data-csp-blur="${CSP.bind('blur',function(event){setTimeout(()=>{const d=el(`${String((prefix) ?? '')}-acct-drop`);if(d)d.style.display='none';const i=el(`${String((prefix) ?? '')}-account-search`);if(i)i.setAttribute('aria-expanded','false')},200)})}">
    <div id="${prefix}-acct-drop" class="coa-acct-drop" role="listbox" data-csp-style="${CSP.style(`display:none;position:fixed;width:360px;max-height:280px`)}"></div>
    <div id="${prefix}-acct-hint" class="coa-acct-hint"></div>
  </div>`;
}
function coaAcctShow(prefix, q){
  const drop=el(prefix+'-acct-drop'), inp=el(prefix+'-account-search'); if(!drop||!inp) return;
  const any=inp.getAttribute('data-coa-any')==='1';
  const scope=inp.getAttribute('data-coa-scope')||'';
  const hid=el(prefix+'-account-code');
  const picked=hid&&hid.value?(CACHE.chartOfAccounts||[]).find(x=>x.code===hid.value):null;
  const pickedLabel=picked?picked.code+' — '+picked.name:'';
  const editing=!pickedLabel || String(q||'')!==pickedLabel;
  if(hid && editing) hid.value='';
  const term=coaSearchKey(editing?q:(picked?picked.code:''));
  const depthLabel={0:'گروه',1:'کل',2:'معین',3:'تفصیلی'};
  const all=coaAllAccounts();
  let list=any?all.slice():all.filter(a=>vcCoaIsLeaf(a.code));
  if(scope==='expense') list=list.filter(expenseCodingAccount);
  if(!(CACHE.chartOfAccounts||[]).length){
    drop.style.display='block';
    drop.innerHTML='<div class="coa-acct-empty" role="status">کدینگ بارگذاری نشده</div>';
    inp.setAttribute('aria-expanded','true');
    return;
  }
  if(term){
    const words=term.split(/\s+/).filter(Boolean);
    list=list.filter(a=>{
      const hay=coaSearchKey((a.code||'')+' '+(a.name||''));
      return words.every(w=>hay.includes(w));
    });
    list.sort((a,b)=>coaSearchRank(a,term)-coaSearchRank(b,term) || String(a.code).localeCompare(String(b.code),'en'));
  }else{
    list.sort((a,b)=>String(a.code).localeCompare(String(b.code),'en'));
  }
  const shown=list.slice(0,80);
  const more=list.length-shown.length;
  const rect=inp.getBoundingClientRect();
  const width=Math.max(220, Math.min(rect.width, window.innerWidth-16));
  const left=Math.max(8, Math.min(rect.left, window.innerWidth-width-8));
  drop.style.top=(rect.bottom+4)+'px';
  drop.style.left=left+'px';
  drop.style.width=width+'px';
  drop.style.display='block';
  drop.style.zIndex='9999';
  inp.setAttribute('aria-expanded','true');
  const rows=shown.map((a,i)=>{
    const hasChild=(CACHE.chartOfAccounts||[]).some(x=>x.parent_code===a.code);
    const lvl=depthLabel[Math.min(a._depth||0,3)]||'حساب';
    const badge=hasChild&&any?lvl+' · سرفصل':lvl;
    return `<div id="${prefix}-opt-${i}" class="coa-acct-row${i===0?' is-active':''}${hasChild?' is-parent':''}" role="option" data-code="${esc(a.code)}" aria-selected="${i===0?'true':'false'}"
      data-csp-mousedown="${CSP.bind('mousedown',function(event){event.preventDefault();coaAcctPick((prefix),(a.code))})}">
      <span class="coa-acct-main"><span class="coa-acct-name">${esc(a.name)}</span><span class="coa-acct-code">${esc(a.code)}</span></span>
      <span class="coa-acct-lvl">${esc(badge)}</span>
    </div>`;
  }).join('');
  const tail=more>0?`<div class="coa-acct-empty">۸۰ حساب اول از ${fmt(list.length)}. برای بقیه دقیق‌تر بنویسید.</div>`:'';
  drop.innerHTML=rows?rows+tail:'<div class="coa-acct-empty" role="status">حسابی با این عبارت نیست</div>';
  const hint=el(prefix+'-acct-hint');
  if(hint && editing) hint.textContent='';
}
function coaAcctKey(prefix, event){
  const drop=el(prefix+'-acct-drop'), inp=el(prefix+'-account-search');
  if(!drop||!inp) return;
  const open=drop.style.display!=='none' && drop.innerHTML;
  if(!open){
    if(event.key==='ArrowDown'){ event.preventDefault(); coaAcctShow(prefix, inp.value); }
    return;
  }
  const rows=[...drop.querySelectorAll('.coa-acct-row')];
  if(event.key==='Escape'){
    event.preventDefault();
    drop.style.display='none';
    inp.setAttribute('aria-expanded','false');
    return;
  }
  if(!rows.length) return;
  let i=rows.findIndex(r=>r.classList.contains('is-active'));
  if(event.key==='ArrowDown'){ event.preventDefault(); i=Math.min(rows.length-1, (i<0?0:i+1)); }
  else if(event.key==='ArrowUp'){ event.preventDefault(); i=Math.max(0, (i<0?0:i-1)); }
  else if(event.key==='Enter'){
    event.preventDefault();
    const row=rows[i>=0?i:0];
    if(row) coaAcctPick(prefix, row.getAttribute('data-code'));
    return;
  }else return;
  rows.forEach((r,n)=>{
    r.classList.toggle('is-active', n===i);
    r.setAttribute('aria-selected', n===i?'true':'false');
  });
  if(inp && rows[i]) inp.setAttribute('aria-activedescendant', rows[i].id||'');
  rows[i]?.scrollIntoView({block:'nearest'});
}
function coaAcctPick(prefix, code){
  const a=(CACHE.chartOfAccounts||[]).find(x=>x.code===code);
  const hid=el(prefix+'-account-code'), inp=el(prefix+'-account-search');
  if(hid) hid.value=a?code:'';
  if(inp&&a){
    inp.value=a.code+' — '+a.name;
    inp.setAttribute('aria-expanded','false');
  }
  const drop=el(prefix+'-acct-drop'); if(drop) drop.style.display='none';
  const hint=el(prefix+'-acct-hint');
  if(!hint) return;
  if(!a){ hint.textContent=''; return; }
  const hasChild=(CACHE.chartOfAccounts||[]).some(x=>x.parent_code===code);
  const depthLabel={0:'گروه',1:'کل',2:'معین',3:'تفصیلی'};
  const row=coaAllAccounts().find(x=>x.code===code);
  const lvl=depthLabel[Math.min(row?row._depth:0,3)]||'حساب';
  hint.textContent=hasChild
    ? (lvl+' — مبلغ روی خود کد '+a.code+' ثبت می‌شود و بین زیرحساب‌ها تقسیم نمی‌شود.')
    : (lvl+' — '+a.code+' — '+a.name);
}
