function exportStatement(format){
  if(!stmtCustId){ showToast('ابتدا یک مشتری انتخاب کنید','error'); return; }
  const q=stmtQuery();
  const path='/accounting/statement/'+stmtCustId+'/export'+(q?q+'&':'?')+'format='+format;
  if(format==='pdf'){ openHtmlAuth('/api'+path); return; }
  downloadAuth(path, 'statement-'+stmtCustId+'.'+(format==='csv'?'csv':'xlsx'));
}

async function sendStatementImage(){
  if(!stmtCustId){ showToast('ابتدا مشتری انتخاب کنید','error'); return; }
  if(typeof html2canvas==='undefined'){ showToast('کتابخانه تولید تصویر بارگذاری نشده','error'); return; }
  if(!el('stmtBody')?.querySelector('.panel')){ showToast('ابتدا صورت‌حساب را نمایش دهید','error'); return; }
  let recipients=[];
  try{ recipients=await api('GET','/messages/users')||[]; }catch(e){}
  const opts=recipients.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('');
  const broadcast=ME.role==='admin'?'<option value="">📢 همه کاربران</option>':'';
  const custName=(CACHE.customers.find(c=>String(c.id)===String(stmtCustId))||{}).biz||'';
  openModal(`
    <div class="modal-head"><h3>📤 ارسال صورت‌حساب به پیام‌رسان</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg full"><label>گیرنده</label><select id="si-to">${broadcast}${opts}</select></div>
      <div class="fg full"><label>توضیح (اختیاری)</label><textarea id="si-body" placeholder="متن همراه تصویر...">صورت‌حساب ${esc(custName)}</textarea></div>
    </div></div>
    <div class="modal-foot"><button class="btn green" data-csp-click="${CSP.bind('click',function(event){doSendStatementImage()})}">📤 ارسال</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
}

async function doSendStatementImage(){
  const to=el('si-to')?.value||'', body=el('si-body')?.value||'';
  const target=el('stmtBody')?.querySelector('.panel');
  if(!target){ showToast('صورت‌حساب یافت نشد','error'); return; }
  showToast('در حال تولید تصویر...');
  try{
    const canvas=await CSP.capture(target,{backgroundColor:'#ffffff',scale:2,useCORS:true});
    canvas.toBlob(async blob=>{
      if(!blob){ showToast('خطا در تولید تصویر','error'); return; }
      const fd=new FormData();
      fd.append('image',blob,'statement.png');
      if(to) fd.append('to_id',to);
      fd.append('body',body);
      try{
        await api('POST','/messages/with-image',fd,true);
        closeModal(); showToast('صورت‌حساب به پیام‌رسان ارسال شد');
        if(typeof refreshMsgBadge==='function') refreshMsgBadge();
      }catch(e){ showToast('خطا در ارسال','error'); }
    },'image/png');
  }catch(e){ showToast('خطا در تولید تصویر','error'); }
}

// Open an authenticated HTML page (e.g. printable PDF) in a new tab
async function openHtmlAuth(url){
  const token=localStorage.getItem('crm_token');
  try{
    const r=await fetch(url,{headers:{'Authorization':'Bearer '+token}});
    if(!r.ok){ showToast('خطا در دریافت','error'); return; }
    if(!await CSP.openVerifiedServerDocument(r)) showToast('مرورگر پنجره را مسدود کرد','error');
  }catch(e){ showToast('خطا','error'); }
}

async function deleteProductImage(imageId, productId, filename){
  if(!confirm('این تصویر حذف شود؟')) return;
  try{
    if(imageId){
      await api('DELETE','/products/images/'+imageId);
    }else if(productId){
      // Basename only; omit body when empty so server clears products.image.
      let fn = filename == null ? '' : String(filename).trim();
      if(fn){
        fn = fn.replace(/^.*[\\/]/, ''); // strip accidental URL/path prefix
        if(fn === '${safe}' || fn.includes('${')) fn = '';
      }
      const body = fn ? { filename: fn } : {};
      await api('DELETE','/products/'+productId+'/images/primary', body);
    }else{
      throw new Error('شناسه تصویر یا محصول نامعتبر است');
    }
    showToast('حذف شد');
    if(productId) prodModal(productId);
  }catch(e){
    showToast((e&&e.message)||'خطا در حذف تصویر','error');
  }
}
async function approveInvoice(id){
  if(!confirm('این فاکتور تأیید و در محاسبه انگیزه فروش لحاظ شود؟')) return;
  try{
    const r = await api('POST','/accounting/invoices/'+id+'/approve',{});
    showToast('فاکتور با موفقیت تأیید شد');
    try{
      const blob=await captureInvoicePrintImage(id);
      if(blob){
        const fd=new FormData(); fd.append('image',blob,'invoice.png');
        await api('POST','/accounting/invoices/'+id+'/rubika',fd,true);
      }
    }catch(_){}
    if(r?.rubika?.ok) showToast('ارسال به روبیکا انجام شد');
    if(ROUTES[CURRENT_PAGE]) ROUTES[CURRENT_PAGE]();
  }catch(e){}
}

