let _selectedRepId = null;
function repDateQuery(){
  const q=[];
  if(accDateFrom) q.push('from='+encodeURIComponent(accDateFrom));
  if(accDateTo) q.push('to='+encodeURIComponent(accDateTo));
  return q.length?'?'+q.join('&'):'';
}
