/* ============================================================
   MESSAGES
============================================================ */
/* Telegram-style chat (spec 1.0.9 §3). "Real-time" is simulated with a
   lightweight 5s poll — the stack (embedded SQLite, offline device builds)
   has no WebSocket infrastructure and polling keeps sync semantics intact. */
let TG={threads:[],peer:null,peerName:'',peerRole:'',msgs:[],poll:null,q:'',sending:false};
function stopMsgPoll(){ if(TG.poll){ clearInterval(TG.poll); TG.poll=null; } }
const TG_AV_COLORS=['#e17076','#7bc862','#65aadd','#a695e7','#ee7aae','#6ec9cb','#faa774','#8d9aa8'];
function tgAvatar(name,pid){
  if(pid==='broadcast') return `<span class="tg-av" data-csp-style="${CSP.style(`background:#f5a623`)}">📢</span>`;
  if(pid==='self') return `<span class="tg-av" data-csp-style="${CSP.style(`background:#65aadd`)}">📌</span>`;
  let h=0; const s=String(name||'?'); for(let i=0;i<s.length;i++) h=(h*31+s.charCodeAt(i))>>>0;
  return `<span class="tg-av" data-csp-style="${CSP.style(`background:${TG_AV_COLORS[h%TG_AV_COLORS.length]}`)}">${esc(s.trim().charAt(0)||'?')}</span>`;
}
function tgTime(ts){ return new Date(ts*1000).toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'}); }
function tgDay(ts){ return new Date(ts*1000).toLocaleDateString('fa-IR',{day:'numeric',month:'long',year:'numeric'}); }
function tgListTime(ts){
  const d=new Date(ts*1000), now=new Date();
  return d.toDateString()===now.toDateString() ? tgTime(ts) : d.toLocaleDateString('fa-IR',{day:'numeric',month:'short'});
}
function tgTicks(m){
  return `<span class="tg-ticks ${m.is_read?'read':''}">${m.is_read?'✓✓':'✓'}</span>`;
}
ROUTES.messages = async function(){
  stopMsgPoll();
  el('view').innerHTML=`
    <div class="tg" id="tgRoot">
      <div class="tg-side">
        <div class="tg-side-head">
          <input id="msgSearchInput" placeholder="جستجو..." value="${esc(TG.q)}" data-csp-input="${CSP.bind('input',function(event){TG.q=this.value;debounceMsg()})}">
          <button class="tg-new" title="گفتگوی جدید" data-csp-click="${CSP.bind('click',function(event){tgNewChat()})}">✏️</button>
        </div>
        <div class="tg-list" id="tgList"><div class="muted" data-csp-style="${CSP.style(`padding:20px;text-align:center`)}">در حال بارگذاری...</div></div>
      </div>
      <div class="tg-chat" id="tgChat">
        <div class="tg-empty"><span data-csp-style="${CSP.style(`font-size:44px`)}">💬</span><span>برای شروع، یک گفتگو را انتخاب کنید</span></div>
      </div>
    </div>`;
  await tgLoadThreads();
  // Desktop: auto-open latest conversation; mobile keeps the list in view
  if(window.innerWidth>900 && !TG.peer && TG.threads.length) tgOpen(TG.threads[0].peer_id, TG.threads[0].peer_name, TG.threads[0].peer_role);
  else if(TG.peer) tgOpen(TG.peer, TG.peerName, TG.peerRole);
  TG.poll=setInterval(async()=>{
    if(CURRENT_PAGE!=='messages'){ stopMsgPoll(); return; }
    await tgLoadThreads(true);
    if(TG.peer) await tgRefreshThread(true);
    refreshMsgBadge();
  }, 5000);
};
async function tgLoadThreads(silent){
  try{ TG.threads=await api('GET','/messages/threads')||[]; }catch(e){ if(!silent) showToast('خطا در دریافت گفتگوها','error'); return; }
  tgRenderThreads();
}
function tgRenderThreads(){
  const box=el('tgList'); if(!box) return;
  let list=TG.threads;
  if(TG.q){ const q=TG.q.toLowerCase(); list=list.filter(t=>(t.peer_name||'').toLowerCase().includes(q)||(t.last_body||'').toLowerCase().includes(q)); }
  box.innerHTML=list.map(t=>`
    <div class="tg-item ${String(TG.peer)===String(t.peer_id)?'active':''}" data-csp-click="${CSP.bind('click',function(event){tgOpen(`${String((t.peer_id) ?? '')}`,(t.peer_name||'?'),(t.peer_role||''))})}">
      ${tgAvatar(t.peer_name,t.peer_id)}
      <div class="tg-i-main">
        <div class="tg-i-top">
          <span class="tg-i-name">${esc(t.peer_name)}</span>
          <span class="tg-i-time">${t.last_from_me?tgTicks({is_read:t.last_read}):''} ${tgListTime(t.last_at)}</span>
        </div>
        <div class="tg-i-bot">
          <span class="tg-i-snip">${t.last_image?'🖼️ تصویر ':''}${esc((t.last_body||'').slice(0,60))}</span>
          ${t.unread?`<span class="tg-i-badge">${fmt(t.unread)}</span>`:''}
        </div>
      </div>
    </div>`).join('') || `<div class="empty" data-csp-style="${CSP.style(`padding:30px;text-align:center`)}">📭 گفتگویی نیست<br><br><button class="btn sm" data-csp-click="${CSP.bind('click',function(event){tgNewChat()})}">✏️ شروع گفتگو</button></div>`;
}
async function tgOpen(peer, name, role){
  TG.peer=peer; TG.peerName=name; TG.peerRole=role||'';
  el('tgRoot')?.classList.add('chat-open');
  const chat=el('tgChat'); if(!chat) return;
  const canSend = peer!=='broadcast' && peer!=='self' ? true : (peer==='broadcast' && ME.role==='admin');
  chat.innerHTML=`
    <div class="tg-head">
      <button class="tg-back" data-csp-click="${CSP.bind('click',function(event){tgBack()})}">→</button>
      ${tgAvatar(name,peer)}
      <div data-csp-style="${CSP.style(`min-width:0`)}">
        <div data-csp-style="${CSP.style(`font-weight:700;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis`)}">${esc(name)}</div>
        <div class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">${peer==='broadcast'?'اطلاعیه‌های عمومی':peer==='self'?'اعلان‌های سیستمی شما':(role?esc(roleLabel(role)):'')}</div>
      </div>
    </div>
    <div class="tg-body" id="tgBody"><div class="muted" data-csp-style="${CSP.style(`margin:auto`)}">در حال بارگذاری...</div></div>
    ${canSend?`
    <div class="tg-compose">
      <button class="tg-iconbtn tg-attach" title="ارسال تصویر" data-csp-click="${CSP.bind('click',function(event){el('tgFile').click()})}">📎</button>
      <input type="file" id="tgFile" accept="image/*" data-csp-style="${CSP.style(`display:none`)}" data-csp-change="${CSP.bind('change',function(event){tgAttach(this)})}">
      <textarea id="tgInput" rows="1" placeholder="پیام..." data-csp-keydown="${CSP.bind('keydown',function(event){tgKey(event)})}" data-csp-input="${CSP.bind('input',function(event){this.style.height='auto';this.style.height=Math.min(this.scrollHeight,110)+'px'})}"></textarea>
      <button class="tg-iconbtn tg-send" data-csp-click="${CSP.bind('click',function(event){tgSend()})}" title="ارسال">➤</button>
    </div>`:`<div data-csp-style="${CSP.style(`padding:12px;text-align:center;font-size:12px;color:var(--muted);background:var(--card);border-top:1px solid var(--border)`)}">این گفتگو فقط‌خواندنی است</div>`}`;
  tgRenderThreads();
  await tgRefreshThread();
  api('POST','/messages/thread/'+peer+'/read').then(()=>{ refreshMsgBadge(); tgLoadThreads(true); }).catch(()=>{});
}
async function tgRefreshThread(silent){
  try{
    const msgs=await api('GET','/messages/thread/'+TG.peer)||[];
    const changed = msgs.length!==TG.msgs.length || (msgs.length && TG.msgs.length && (msgs[msgs.length-1].id!==TG.msgs[TG.msgs.length-1].id || msgs[msgs.length-1].is_read!==TG.msgs[TG.msgs.length-1].is_read));
    // Re-render also when read-state of older messages flips (ticks turn blue)
    const readSig=msgs.map(m=>m.is_read).join(''), oldSig=TG.msgs.map(m=>m.is_read).join('');
    TG.msgs=msgs;
    if(!silent || changed || readSig!==oldSig) tgRenderMsgs(!silent);
    if(silent && changed){
      tgRenderMsgs(false);
      api('POST','/messages/thread/'+TG.peer+'/read').catch(()=>{});
    }
  }catch(e){ if(!silent) showToast('خطا در دریافت پیام‌ها','error'); }
}
function tgRenderMsgs(forceScroll){
  const body=el('tgBody'); if(!body) return;
  const nearBottom = body.scrollHeight - body.scrollTop - body.clientHeight < 120;
  const prevTop = body.scrollTop, prevH = body.scrollHeight;
  const canDelete = m => ME.role==='admin' || m.from_id===ME.id;
  let lastDay='';
  body.innerHTML=TG.msgs.map(m=>{
    const day=tgDay(m.created_at);
    const sep=day!==lastDay?`<div class="tg-date">${day}</div>`:''; lastDay=day;
    const showSender = TG.peer==='broadcast' && !m.mine;
    return sep+`
    <div class="tg-row ${m.mine?'me':''}">
      <div class="tg-bub">
        ${canDelete(m)?`<button class="tg-del" title="حذف پیام" data-csp-click="${CSP.bind('click',function(event){tgDelete((m.id))})}">×</button>`:''}
        ${showSender?`<div class="tg-sender">${esc(m.from_name||'سیستم')}</div>`:''}
        ${m.image_url?`<button type="button" class="tg-private-image" title="نمایش تصویر" data-csp-click="${CSP.bind('click',function(event){showImgPreview(m.image_url)})}">🖼️</button>`:''}
        ${esc(m.body||'')}
        <div class="tg-meta">${m.mine?tgTicks(m):''} <span>${tgTime(m.created_at)}</span></div>
      </div>
    </div>`;
  }).join('') || `<div class="tg-empty"><span data-csp-style="${CSP.style(`font-size:36px`)}">🕊️</span><span>هنوز پیامی رد و بدل نشده</span></div>`;
  if(forceScroll || nearBottom) body.scrollTop=body.scrollHeight;
  else if(prevH) body.scrollTop=prevTop+(body.scrollHeight-prevH);
}
function tgKey(e){
  if(e.key==='Enter' && !e.shiftKey){ e.preventDefault(); tgSend(); }
}
async function tgSend(){
  if(TG.sending) return;
  const inp=el('tgInput'); const body=(inp?.value||'').trim();
  if(!body || !TG.peer) return;
  const to_id = TG.peer==='broadcast' ? null : +TG.peer;
  TG.sending=true;
  try{
    await api('POST','/messages',{to_id,body});
    if(inp){ inp.value=''; inp.style.height='auto'; }
    await tgRefreshThread(); tgLoadThreads(true);
  }catch(e){}
  TG.sending=false;
  el('tgInput')?.focus();
}
async function tgAttach(input){
  const f=input.files?.[0]; input.value='';
  if(!f || !TG.peer || TG.peer==='self') return;
  const fd=new FormData();
  if(TG.peer!=='broadcast') fd.append('to_id',TG.peer);
  fd.append('body','');
  fd.append('image',f);
  try{
    await api('POST','/messages/with-image',fd,true);
    await tgRefreshThread(); tgLoadThreads(true);
    showToast('تصویر ارسال شد');
  }catch(e){}
}
async function tgDelete(id){
  if(!confirm('این پیام حذف شود؟')) return;
  try{
    await api('DELETE','/messages/'+id);
    TG.msgs=TG.msgs.filter(m=>m.id!==id);
    tgRenderMsgs(false); tgLoadThreads(true);
  }catch(e){}
}
function tgBack(){
  TG.peer=null;
  el('tgRoot')?.classList.remove('chat-open');
  const chat=el('tgChat');
  if(chat) chat.innerHTML=`<div class="tg-empty"><span data-csp-style="${CSP.style(`font-size:44px`)}">💬</span><span>برای شروع، یک گفتگو را انتخاب کنید</span></div>`;
  tgRenderThreads();
}
async function tgNewChat(){
  let recipients;
  try{ recipients=await api('GET','/messages/users')||[]; }catch(e){ recipients=[]; }
  openModal(`
    <div class="modal-head"><h3>✏️ گفتگوی جدید</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body">
      ${ME.role==='admin'?`<div class="tg-item" data-csp-style="${CSP.style(`border:1px solid var(--border);border-radius:10px;margin-bottom:8px`)}" data-csp-click="${CSP.bind('click',function(event){closeModal();tgOpen('broadcast','📢 اطلاعیه‌ها','')})}">
        ${tgAvatar('','broadcast')}<div class="tg-i-main"><div class="tg-i-name">📢 اطلاعیه به همه</div><div class="tg-i-snip">ارسال پیام همگانی به تمام کاربران</div></div>
      </div>`:''}
      ${recipients.map(u=>`
      <div class="tg-item" data-csp-style="${CSP.style(`border:1px solid var(--border);border-radius:10px;margin-bottom:8px`)}" data-csp-click="${CSP.bind('click',function(event){closeModal();tgOpen(`${String((u.id) ?? '')}`,(u.name),(u.role||''))})}">
        ${tgAvatar(u.name,u.id)}<div class="tg-i-main"><div class="tg-i-name">${esc(u.name)}</div><div class="tg-i-snip">${esc(roleLabel(u.role))}</div></div>
      </div>`).join('')||'<div class="empty">کاربری یافت نشد</div>'}
    </div>
    <div class="modal-foot"><button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">بستن</button></div>`);
}
async function markVisibleRead(){ setTimeout(async()=>{ await api('POST','/messages/read-all'); refreshMsgBadge(); }, 800); }
async function refreshMsgBadge(){
  try{
    const r=await api('GET','/messages/unread-count', null, false, true);
    const b=el('msgBadge'); if(!b)return;
    if(r.count>0){ b.textContent=fmt(r.count); b.classList.remove('hide'); }
    else b.classList.add('hide');
  }catch(e){}
}
async function ensureUsersForMsg(){}
async function refreshRemBadge(){
  try{
    const rows=await api('GET','/reminders/due', null, false, true)||[];
    const b=el('remBadge'); if(!b)return;
    if(rows.length>0){ b.textContent=rows.length; b.classList.remove('hide'); }
    else b.classList.add('hide');
  }catch(e){}
}

/* ============================================================
   REMINDERS
============================================================ */
let remFilter = {q:'', done:'0'};
ROUTES.reminders = async function(){
  if(!_remindersFetched){ CACHE.reminders = await api('GET','/reminders')||[]; _remindersFetched=true; }
  const v=el('view');
  v.innerHTML=`
    <div class="toolbar">
      <input class="search" id="remSearch" placeholder="جستجوی یادآور..." value="${esc(remFilter.q)}">
      <select id="remDone">
        <option value="0" ${remFilter.done==='0'?'selected':''}>فعال</option>
        <option value="1" ${remFilter.done==='1'?'selected':''}>انجام‌شده</option>
        <option value="" ${remFilter.done===''?'selected':''}>همه</option>
      </select>
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){remModal()})}">➕ یادآور جدید</button>
    </div>
    <div class="panel"><div class="panel-body" id="remList"></div></div>`;
  el('remSearch').addEventListener('input',e=>{remFilter.q=e.target.value;debounceRem();});
  el('remDone').addEventListener('change',e=>{remFilter.done=e.target.value;renderRemList();});
  renderRemList();
};
function renderRemList(){
  const body=el('remList'); if(!body) return;
  let rows=(CACHE.reminders||[]).slice();
  if(remFilter.q){ const q=remFilter.q.toLowerCase(); rows=rows.filter(r=>(r.title+' '+(r.body||'')+' '+(r.cust_biz||'')).toLowerCase().includes(q)); }
  if(remFilter.done==='0') rows=rows.filter(r=>!r.done);
  else if(remFilter.done==='1') rows=rows.filter(r=>r.done);
  const today=todayJalali();
  body.innerHTML=rows.length?rows.map(r=>{
    const overdue=!r.done && r.remind_at && r.remind_at<today;
    const isAdmin=ME.role==='admin';
    return `<div class="msg ${overdue?'unread':''}" data-csp-style="${CSP.style(`${r.done?'opacity:.55':''}`)}">
      <div class="mh">
        <span>${overdue?'🔴':'🔔'} <b>${esc(r.title)}</b>${r.cust_biz?' — '+esc(r.cust_biz):''}</span>
        <span data-csp-style="${CSP.style(`display:flex;gap:6px;align-items:center`)}">
          <span class="mono">${escDate(r.remind_at)}</span>
          ${isAdmin&&r.user_name?`<span class="muted">${esc(r.user_name)}</span>`:''}
          ${!r.done?`<button class="btn sm green" data-csp-click="${CSP.bind('click',function(event){remDone((r.id))})}">✔ انجام شد</button>`:`<span class="tag" data-csp-style="${CSP.style(`background:#d1fae5;color:#065f46`)}">✔ انجام</span>`}
          <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){remModal((r.id))})}">✏️</button>
          <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){remDelete((r.id))})}">🗑️</button>
        </span>
      </div>
      ${r.body?`<div class="mb">${esc(r.body)}</div>`:''}
    </div>`;
  }).join(''):'<div class="empty">یادآوری وجود ندارد</div>';
}
function remModal(id){
  const r=id?(CACHE.reminders||[]).find(x=>x.id===id)||{}:{};
  openModal(`
    <div class="modal-head"><h3>${id?'ویرایش یادآور':'یادآور جدید'}</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg full"><label>عنوان *</label><input id="rem-title" value="${esc(r.title||'')}"></div>
      <div class="fg"><label>مشتری مرتبط</label>${custSelect('rem-cust', r.cust_id, true)}</div>
      <div class="fg"><label>تاریخ یادآوری *</label><input id="rem-date" data-jdate value="${esc(r.remind_at||'')}"></div>
      <div class="fg full"><label>توضیحات</label><textarea id="rem-body">${esc(r.body||'')}</textarea></div>
    </div></div>
    <div class="modal-foot">
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){saveRem((id||'null'))})}">💾 ذخیره</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button>
    </div>`);
  attachDatepickers(el('modalRoot'));
}
async function saveRem(id){
  const title=el('rem-title').value.trim();
  if(!title){showToast('عنوان الزامی است','error');return;}
  const data={title,body:el('rem-body').value,remind_at:el('rem-date').value,cust_id:el('rem-cust').value||null};
  try{
    if(id) await api('PUT','/reminders/'+id,data); else await api('POST','/reminders',data);
    CACHE.reminders=await api('GET','/reminders')||[];
    closeModal(); renderRemList(); showToast('ذخیره شد'); refreshRemBadge();
  }catch(e){showToast('خطا','error');}
}
async function remDone(id){
  await api('PATCH','/reminders/'+id+'/done',{});
  CACHE.reminders=await api('GET','/reminders')||[];
  renderRemList(); refreshRemBadge(); showToast('یادآور انجام شد');
}
async function remDelete(id){
  if(!confirm('این یادآور حذف شود؟')) return;
  await api('DELETE','/reminders/'+id);
  CACHE.reminders=(CACHE.reminders||[]).filter(r=>r.id!==id);
  renderRemList(); refreshRemBadge(); showToast('حذف شد');
}

